CREATE OR REPLACE FUNCTION private.capture_merchant_lifecycle_events_internal(p_snapshot_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_previous_snapshot text;
  v_snapshot_exists boolean;
  v_counts jsonb;
  v_total integer;
begin
  select exists (
    select 1 from public.merchants where snapshot_id = p_snapshot_id
  ) into v_snapshot_exists;

  if not v_snapshot_exists then
    raise exception 'snapshot_not_found';
  end if;

  select snapshot_id
  into v_previous_snapshot
  from public.merchants
  where snapshot_id <> p_snapshot_id
  order by uploaded_at desc
  limit 1;

  if v_previous_snapshot is null then
    return jsonb_build_object(
      'snapshot_id', p_snapshot_id,
      'previous_snapshot_id', null,
      'baseline', true,
      'created', 0,
      'by_type', '{}'::jsonb
    );
  end if;

  insert into public.merchant_lifecycle_events (
    snapshot_id, previous_snapshot_id, store_id, store_name, phone,
    event_type, to_value, shipment_delta, wallet_delta
  )
  select
    p_snapshot_id, v_previous_snapshot, c.store_id, c.store_name, c.phone,
    'registered', c.status,
    coalesce(c.shipment_count, 0),
    round(coalesce(c.wallet_balance, 0)::numeric, 2)
  from public.merchants c
  left join public.merchants p
    on p.snapshot_id = v_previous_snapshot
   and p.store_id = c.store_id
  where c.snapshot_id = p_snapshot_id
    and p.id is null
  on conflict (snapshot_id, store_id, event_type) do nothing;

  insert into public.merchant_lifecycle_events (
    snapshot_id, previous_snapshot_id, store_id, store_name, phone,
    event_type, from_value, to_value, shipment_delta, wallet_delta
  )
  select
    p_snapshot_id,
    v_previous_snapshot,
    c.store_id,
    c.store_name,
    c.phone,
    e.event_type,
    e.from_value,
    e.to_value,
    coalesce(c.shipment_count, 0) - coalesce(p.shipment_count, 0),
    round((coalesce(c.wallet_balance, 0) - coalesce(p.wallet_balance, 0))::numeric, 2)
  from public.merchants c
  join public.merchants p
    on p.snapshot_id = v_previous_snapshot
   and p.store_id = c.store_id
  cross join lateral (
    values
      ('profile_completed'::text, p.profile_status, c.profile_status,
        coalesce(p.profile_status, '') <> 'مكتمل' and c.profile_status = 'مكتمل'),
      ('verified', p.verification_status, c.verification_status,
        coalesce(p.verification_status, '') <> 'موثق' and c.verification_status = 'موثق'),
      ('integration_connected', p.integration_type, c.integration_type,
        p.integration_type is null and c.integration_type is not null),
      ('integration_changed', p.integration_type, c.integration_type,
        p.integration_type is not null and c.integration_type is not null
          and p.integration_type is distinct from c.integration_type),
      ('wallet_topped', p.last_topup_at::text, c.last_topup_at::text,
        c.last_topup_at is not null
          and (p.last_topup_at is null or c.last_topup_at > p.last_topup_at)),
      ('first_shipment', coalesce(p.shipment_count, 0)::text, coalesce(c.shipment_count, 0)::text,
        coalesce(p.shipment_count, 0) = 0 and coalesce(c.shipment_count, 0) > 0),
      ('shipping_resumed', p.last_shipment_at::text, c.last_shipment_at::text,
        coalesce(c.shipment_count, 0) > coalesce(p.shipment_count, 0)
          and p.last_shipment_at is not null and c.last_shipment_at is not null
          and p.last_shipment_at < p.uploaded_at - interval '60 days'),
      ('deactivated', p.status, c.status,
        p.status = 'نشط' and c.status = 'غير نشط'),
      ('reactivated', p.status, c.status,
        p.status = 'غير نشط' and c.status = 'نشط')
  ) as e(event_type, from_value, to_value, changed)
  where c.snapshot_id = p_snapshot_id
    and e.changed
  on conflict (snapshot_id, store_id, event_type) do nothing;

  select
    count(*)::int,
    coalesce(jsonb_object_agg(event_type, event_count), '{}'::jsonb)
  into v_total, v_counts
  from (
    select event_type, count(*)::int as event_count
    from public.merchant_lifecycle_events
    where snapshot_id = p_snapshot_id
    group by event_type
  ) s;

  return jsonb_build_object(
    'snapshot_id', p_snapshot_id,
    'previous_snapshot_id', v_previous_snapshot,
    'baseline', false,
    'created', coalesce(v_total, 0),
    'by_type', coalesce(v_counts, '{}'::jsonb)
  );
end;
$function$;
CREATE OR REPLACE FUNCTION private.customer_growth_action_queue(p_limit integer DEFAULT 400, p_owner text DEFAULT NULL::text, p_journey text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if (select auth.uid()) is null
     or not public.app_has_any_permission(array[
       'collections.view', 'sales.view', 'overview.view', 'crm.view'
     ]) then
    raise exception 'not_allowed';
  end if;

  return (
    with actions as (
      select *
      from public.customer_engagement_next_actions(
        greatest(1, least(coalesce(p_limit, 400), 1000)), p_owner, p_journey
      )
    ), latest_outcome as (
      select distinct on (public.norm_sa_phone(outcome.phone), outcome.reason_code)
        public.norm_sa_phone(outcome.phone) as phone,
        outcome.reason_code,
        outcome.sales_stage,
        outcome.next_action_at,
        outcome.recorded_at
      from public.customer_growth_outcomes outcome
      order by public.norm_sa_phone(outcome.phone), outcome.reason_code, outcome.recorded_at desc
    )
    select coalesce(
      jsonb_agg(
        to_jsonb(queued_action) || jsonb_build_object(
          'reason', case queued_action.reason_code
            when 'hot_reply' then U&'\0648\0635\0644 \0631\062f \0628\0627\0647\062a\0645\0627\0645 \0648\064a\062d\062a\0627\062c \0645\062a\0627\0628\0639\0629 \0628\0634\0631\064a\0629'
            when 'sla' then U&'\0645\062a\0627\0628\0639\0629 \062a\062c\0627\0648\0632\062a \0645\0648\0639\062f\0647\0627 \0623\0648 \0623\0635\0628\062d\062a \0631\0627\0643\062f\0629'
            when 'reply' then U&'\0631\062f \0639\0644\0649 \0627\0644\062d\0645\0644\0629 \0648\0644\0645 \062a\062a\0645 \0645\062a\0627\0628\0639\062a\0647'
            when 'wallet_neg' then U&'\0645\062d\0641\0638\0629 \0627\0644\062f\0641\0639 \0627\0644\0645\0633\0628\0642 \0633\0627\0644\0628\0629'
            when 'debt' then U&'\0639\0644\0649 \0627\0644\0639\0645\064a\0644 \0630\0645\0629 \0645\0641\062a\0648\062d\0629'
            when 'new_ready' then U&'\0627\0644\0639\0645\064a\0644 \062c\0627\0647\0632 \0648\0644\0645 \064a\0646\0641\0630 \0623\0648\0644 \0634\062d\0646\0629'
            when 'new_registered' then U&'\0645\0633\062c\0644 \062d\062f\064a\062b\0627 \0648\0644\0645 \064a\0628\062f\0623 \0627\0644\062a\062c\0647\064a\0632 \0623\0648 \0627\0644\0634\062d\0646'
            when 'stopped_recent' then U&'\062a\0648\0642\0641 \062d\062f\064a\062b\0627 \0639\0646 \0627\0644\0634\062d\0646'
            when 'stopped_long' then U&'\0639\0645\064a\0644 \0639\0627\0644\064a \0627\0644\0642\064a\0645\0629 \0645\062a\0648\0642\0641 \0639\0646 \0627\0644\0634\062d\0646'
            else U&'\062d\0627\0644\0629 \0639\0645\064a\0644 \062a\062d\062a\0627\062c \0645\062a\0627\0628\0639\0629'
          end,
          'action', case queued_action.reason_code
            when 'hot_reply' then U&'\062a\0627\0628\0639 \0631\062f \0627\0644\0639\0645\064a\0644 \0627\0644\0622\0646'
            when 'reply' then U&'\062a\0627\0628\0639 \0631\062f \0627\0644\0639\0645\064a\0644 \0627\0644\0622\0646'
            when 'sla' then U&'\0646\0641\0630 \0645\062a\0627\0628\0639\0629 \0627\0644\0645\0648\0638\0641 \0627\0644\0622\0646'
            when 'wallet_neg' then U&'\062d\0635\0644 \0631\0635\064a\062f \0627\0644\0645\062d\0641\0638\0629'
            when 'debt' then U&'\062a\0627\0628\0639 \0627\0644\062a\062d\0635\064a\0644 \062d\0633\0628 \0643\0634\0641 \0627\0644\0639\0645\064a\0644'
            when 'new_ready' then U&'\0633\0627\0639\062f\0647 \0639\0644\0649 \062a\0646\0641\064a\0630 \0623\0648\0644 \0634\062d\0646\0629'
            when 'new_registered' then U&'\0633\0627\0639\062f\0647 \0639\0644\0649 \0625\0643\0645\0627\0644 \0627\0644\0628\064a\0627\0646\0627\062a \0648\0631\0628\0637 \0627\0644\0645\062a\062c\0631'
            when 'stopped_recent' then U&'\0627\0641\0647\0645 \0633\0628\0628 \0627\0644\062a\0648\0642\0641 \0648\0623\0639\062f \062a\0646\0634\064a\0637\0647'
            when 'stopped_long' then U&'\0631\0627\062c\0639 \0633\0628\0628 \0627\0644\0641\0642\062f \062b\0645 \0646\0641\0630 \0645\062d\0627\0648\0644\0629 \0627\0633\062a\0639\0627\062f\0629'
            else U&'\0631\0627\062c\0639 \062d\0627\0644\0629 \0627\0644\0639\0645\064a\0644 \0648\062d\062f\062f \0627\0644\0625\062c\0631\0627\0621 \0627\0644\062a\0627\0644\064a'
          end,
          'guard_reason', case queued_action.guard_code
            when 'ready' then U&'\062c\0627\0647\0632 \0644\0644\0645\0631\0627\062c\0639\0629'
            when 'invalid_phone' then U&'\0631\0642\0645 \0627\0644\0647\0627\062a\0641 \063a\064a\0631 \0635\0627\0644\062d'
            when 'blocked' then U&'\0627\0644\0631\0642\0645 \0641\064a \0642\0627\0626\0645\0629 \0627\0644\062d\0638\0631'
            when 'human_followup' then U&'\0645\062a\0627\0628\0639\0629 \0628\0634\0631\064a\0629 \0648\0644\064a\0633\062a \0631\0633\0627\0644\0629 \0642\0627\0644\0628 \062c\062f\064a\062f\0629'
            when 'human_call' then U&'\0641\0631\0635\0629 \0639\0627\0644\064a\0629 \0627\0644\0642\064a\0645\0629 \0648\062a\062d\062a\0627\062c \0627\062a\0635\0627\0644\0627 \0623\0648\0644\0627'
            when 'owner_followup' then U&'\062a\0648\062c\062f \0645\062a\0627\0628\0639\0629 \0645\0648\0638\0641 \0623\0648 \062a\0648\0627\0635\0644 \062d\062f\064a\062b'
            when 'recent_campaign' then U&'\0623\0631\0633\0644\062a \0644\0647 \062d\0645\0644\0629 \062e\0644\0627\0644 \0622\062e\0631 7 \0623\064a\0627\0645'
            when 'recent_call' then U&'\062c\0631\0649 \0627\062a\0635\0627\0644 \0639\0628\0631 \0647\0627\062a\0641 \062e\0644\0627\0644 \0622\062e\0631 3 \0623\064a\0627\0645'
            when 'stale_source' then U&'\0644\0642\0637\0629 \0627\0644\0645\062a\0627\062c\0631 \0623\0642\062f\0645 \0645\0646 72 \0633\0627\0639\0629'
            else U&'\062a\062d\062a\0627\062c \0645\0631\0627\062c\0639\0629'
          end
        )
        order by queued_action.priority desc, queued_action.amount desc nulls last
      ),
      '[]'::jsonb
    )
    from actions queued_action
    left join latest_outcome outcome
      on outcome.phone = public.norm_sa_phone(queued_action.phone)
     and outcome.reason_code = queued_action.reason_code
    where outcome.phone is null
       or (
         outcome.sales_stage not in ('won', 'lost')
         and (outcome.next_action_at is null or outcome.next_action_at <= now())
       )
       or outcome.recorded_at < now() - interval '90 days'
  );
end;
$function$;
comment on function "private"."customer_growth_action_queue"(p_limit integer, p_owner text, p_journey text) is 'Protected customer action queue with transport-safe Arabic labels; never sends messages.';
CREATE OR REPLACE FUNCTION private.customer_growth_operating_snapshot(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_days integer := greatest(7, least(coalesce(p_days, 30), 180));
begin
  if (select auth.uid()) is null
     or not public.app_has_any_permission(array[
       'collections.view', 'sales.view', 'overview.view', 'crm.view', 'receivables.view'
     ]) then
    raise exception 'not_allowed';
  end if;

  return (
    with latest_snapshot as (
      select m.snapshot_id, max(m.uploaded_at) as uploaded_at
      from public.merchants m
      group by m.snapshot_id
      order by max(m.uploaded_at) desc
      limit 1
    ), base as (
      select
        m.*,
        public.norm_sa_phone(m.phone) as normalized_phone,
        case
          when coalesce(m.shipment_count, 0) = 0
               and (
                 m.integration_type is not null
                 or coalesce(m.wallet_balance, 0) > 0.5
                 or m.profile_status = 'مكتمل'
                 or m.verification_status = 'موثق'
               ) then 'ready_first_shipment'
          when coalesce(m.shipment_count, 0) = 0 then 'registered'
          when m.last_shipment_at >= now() - interval '30 days' then 'active'
          when m.last_shipment_at >= now() - interval '60 days' then 'at_risk'
          else 'stopped'
        end as lifecycle_stage
      from public.merchants m
      where m.snapshot_id = (select snapshot_id from latest_snapshot)
    ), scoped_phones as (
      select distinct normalized_phone as phone
      from base
      where normalized_phone is not null
    ), linked_stores as (
      select distinct b.store_id
      from base b
      join public.customer_merchant_links link on link.store_id = b.store_id
      join public.customer_ar ar on ar.contact_name = link.customer_name
    ), open_work as (
      select f.*
      from public.retargeting_followups f
      join scoped_phones p on p.phone = public.norm_sa_phone(f.phone)
      where coalesce(f.sales_stage, 'new') not in ('won', 'lost', 'disqualified')
    ), growth_work as (
      select distinct on (public.norm_sa_phone(outcome.phone), outcome.reason_code)
        outcome.*
      from public.customer_growth_outcomes outcome
      join scoped_phones p on p.phone = public.norm_sa_phone(outcome.phone)
      order by public.norm_sa_phone(outcome.phone), outcome.reason_code, outcome.recorded_at desc
    ), period_events as (
      select e.*
      from public.merchant_lifecycle_events e
      where e.observed_at >= now() - make_interval(days => v_days)
    ), touches as (
      select
        public.norm_sa_phone(a.entity_ref) as phone,
        max(a.occurred_at) as last_touch_at
      from public.crm_activities a
      where a.entity_type = 'platform_merchant'
        and a.occurred_at >= now() - make_interval(days => v_days)
        and public.norm_sa_phone(a.entity_ref) is not null
      group by public.norm_sa_phone(a.entity_ref)
    ), payment_rows as (
      select distinct t.phone, payment.zoho_id, payment.amount
      from touches t
      join base b on b.normalized_phone = t.phone
      join public.customer_merchant_links link on link.store_id = b.store_id
      join public.zoho_payments payment on payment.customer_name = link.customer_name
      where payment.date >= t.last_touch_at::date
        and payment.date <= current_date
    ), shipment_after_touch as (
      select distinct t.phone
      from touches t
      join period_events event
        on public.norm_sa_phone(event.phone) = t.phone
       and event.event_type in ('first_shipment', 'shipping_resumed', 'reactivated')
       and event.observed_at >= t.last_touch_at
    ), new_cohort as (
      select *
      from base
      where created_at_platform >= now() - make_interval(days => v_days)
    )
    select jsonb_build_object(
      'period_days', v_days,
      'source_snapshot', jsonb_build_object(
        'id', (select snapshot_id from latest_snapshot),
        'uploaded_at', (select uploaded_at from latest_snapshot)
      ),
      'identity', jsonb_build_object(
        'stores', (select count(*) from base),
        'valid_phone', (select count(*) from base where normalized_phone is not null),
        'linked_to_zoho', (select count(*) from linked_stores),
        'unlinked_to_zoho', (
          select count(*) from base b
          where not exists (select 1 from linked_stores linked where linked.store_id = b.store_id)
        ),
        'multi_store_accounts', (
          select count(*) from (
            select normalized_phone
            from base
            where normalized_phone is not null
            group by normalized_phone
            having count(*) > 1
          ) grouped
        ),
        'coverage_pct', (
          select case when count(*) = 0 then 0
            else round(100.0 * count(*) filter (
              where normalized_phone is not null
                and exists (select 1 from linked_stores linked where linked.store_id = base.store_id)
            ) / count(*), 1)
          end
          from base
        )
      ),
      'lifecycle', jsonb_build_object(
        'registered', (select count(*) from base where lifecycle_stage = 'registered'),
        'ready_first_shipment', (select count(*) from base where lifecycle_stage = 'ready_first_shipment'),
        'active', (select count(*) from base where lifecycle_stage = 'active'),
        'at_risk', (select count(*) from base where lifecycle_stage = 'at_risk'),
        'stopped', (select count(*) from base where lifecycle_stage = 'stopped'),
        'reactivated_period', (
          select count(distinct coalesce(public.norm_sa_phone(phone), 'store:' || store_id))
          from period_events where event_type in ('reactivated', 'shipping_resumed')
        )
      ),
      'execution', jsonb_build_object(
        'open', (select count(*) from open_work),
        'assigned', (select count(*) from open_work where owner_id is not null),
        'unassigned', (select count(*) from open_work where owner_id is null),
        'overdue', (select count(*) from open_work where next_action_at < now()),
        'missing_next_action', (select count(*) from open_work where next_action_at is null),
        'touched_period', (select count(*) from touches),
        'won_period', (
          select count(*) from public.retargeting_followups f
          join scoped_phones p on p.phone = public.norm_sa_phone(f.phone)
          where f.won_at >= now() - make_interval(days => v_days)
        ),
        'lost_period', (
          select count(*) from public.retargeting_followups f
          join scoped_phones p on p.phone = public.norm_sa_phone(f.phone)
          where f.lost_at >= now() - make_interval(days => v_days)
        ),
        'outcomes_recorded', (
          select count(*) from public.customer_growth_outcomes outcome
          join scoped_phones p on p.phone = public.norm_sa_phone(outcome.phone)
          where outcome.recorded_at >= now() - make_interval(days => v_days)
        ),
        'scheduled_growth_followups', (
          select count(*) from growth_work
          where sales_stage not in ('won', 'lost') and next_action_at > now()
        )
      ),
      'outcomes', jsonb_build_object(
        'new_accounts', (select count(*) from new_cohort),
        'new_accounts_shipped', (select count(*) from new_cohort where coalesce(shipment_count, 0) > 0),
        'activation_rate_pct', (
          select case when count(*) = 0 then 0
            else round(100.0 * count(*) filter (where coalesce(shipment_count, 0) > 0) / count(*), 1)
          end
          from new_cohort
        ),
        'first_shipments', (
          select count(distinct coalesce(public.norm_sa_phone(phone), 'store:' || store_id))
          from period_events where event_type = 'first_shipment'
        ),
        'shipping_after_touch', (select count(*) from shipment_after_touch),
        'customers_paid_after_touch', (select count(distinct phone) from payment_rows),
        'paid_after_touch', (select coalesce(round(sum(amount)::numeric, 2), 0) from payment_rows)
      ),
      'sending', jsonb_build_object(
        'enabled', false,
        'mode', 'review_only'
      )
    )
  );
end;
$function$;
comment on function "private"."customer_growth_operating_snapshot"(p_days integer) is 'Read-only growth operating snapshot. Uses objective Lamha lifecycle events and labels post-touch outcomes without claiming causality.';
CREATE OR REPLACE FUNCTION private.customer_growth_profile(p_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_phone text := public.norm_sa_phone(p_phone);
begin
  if (select auth.uid()) is null
     or not public.app_has_any_permission(array[
       'collections.view', 'sales.view', 'overview.view', 'crm.view', 'receivables.view'
     ]) then
    raise exception 'not_allowed';
  end if;
  if v_phone is null then raise exception 'invalid_phone'; end if;

  return (
    with latest_snapshot as (
      select m.snapshot_id
      from public.merchants m
      group by m.snapshot_id
      order by max(m.uploaded_at) desc
      limit 1
    ), stores as (
      select m.*
      from public.merchants m
      where m.snapshot_id = (select snapshot_id from latest_snapshot)
        and public.norm_sa_phone(m.phone) = v_phone
    ), linked_customers as (
      select distinct link.customer_name
      from stores s
      join public.customer_merchant_links link on link.store_id = s.store_id
    ), finance as (
      select
        coalesce(sum(ar.total_due), 0)::numeric as total_due,
        coalesce(sum(ar.collectible_due), 0)::numeric as collectible_due,
        coalesce(sum(ar.opening_due), 0)::numeric as opening_due,
        coalesce(sum(ar.open_invoices), 0)::bigint as open_invoices
      from public.customer_ar ar
      join linked_customers linked on linked.customer_name = ar.contact_name
    ), followup as (
      select f.*, profile.name as owner_name
      from public.retargeting_followups f
      left join public.profiles profile on profile.id = f.owner_id
      where public.norm_sa_phone(f.phone) = v_phone
      order by f.updated_at desc
      limit 1
    ), last_touch as (
      select max(a.occurred_at) as occurred_at
      from public.crm_activities a
      where a.entity_type = 'platform_merchant'
        and public.norm_sa_phone(a.entity_ref) = v_phone
    ), payment_rows as (
      select distinct payment.zoho_id, payment.amount
      from linked_customers linked
      join public.zoho_payments payment on payment.customer_name = linked.customer_name
      where (select occurred_at from last_touch) is not null
        and payment.date >= (select occurred_at::date from last_touch)
    ), lifecycle as (
      select event.*
      from public.merchant_lifecycle_events event
      where public.norm_sa_phone(event.phone) = v_phone
         or event.store_id in (select store_id from stores)
      order by event.observed_at desc
      limit 20
    ), activities as (
      select activity.*, profile.name as owner_name
      from public.crm_activities activity
      left join public.profiles profile on profile.id = activity.owner_id
      where activity.entity_type = 'platform_merchant'
        and public.norm_sa_phone(activity.entity_ref) = v_phone
      order by activity.occurred_at desc
      limit 20
    ), outcomes as (
      select outcome.*, profile.name as owner_name
      from public.customer_growth_outcomes outcome
      left join public.profiles profile on profile.id = outcome.owner_id
      where public.norm_sa_phone(outcome.phone) = v_phone
      order by outcome.recorded_at desc
      limit 20
    )
    select jsonb_build_object(
      'customer_key', 'phone:' || v_phone,
      'phone', v_phone,
      'name', coalesce((select store_name from stores order by shipment_count desc nulls last limit 1), v_phone),
      'stage', case
        when exists (select 1 from stores where coalesce(shipment_count, 0) > 0 and last_shipment_at >= now() - interval '30 days') then 'active'
        when exists (select 1 from stores where coalesce(shipment_count, 0) > 0 and last_shipment_at >= now() - interval '60 days') then 'at_risk'
        when exists (select 1 from stores where coalesce(shipment_count, 0) > 0) then 'stopped'
        when exists (select 1 from stores where integration_type is not null or coalesce(wallet_balance, 0) > 0.5 or profile_status = 'مكتمل' or verification_status = 'موثق') then 'ready_first_shipment'
        else 'registered'
      end,
      'identity', jsonb_build_object(
        'stores', coalesce((select jsonb_agg(jsonb_build_object(
          'store_id', store_id, 'store_name', store_name, 'status', status,
          'shipments', shipment_count, 'last_shipment_at', last_shipment_at,
          'wallet', wallet_balance, 'billing_type', billing_type,
          'integration_type', integration_type
        ) order by shipment_count desc nulls last) from stores), '[]'::jsonb),
        'zoho_customers', coalesce((select jsonb_agg(jsonb_build_object(
          'name', ar.contact_name, 'zoho_id', ar.zoho_id, 'balance_status', ar.balance_integrity_status
        ) order by ar.contact_name) from public.customer_ar ar
          join linked_customers linked on linked.customer_name = ar.contact_name), '[]'::jsonb)
      ),
      'finance', (select jsonb_build_object(
        'total_due', round(total_due, 2), 'collectible_due', round(collectible_due, 2),
        'opening_due', round(opening_due, 2), 'open_invoices', open_invoices
      ) from finance),
      'followup', coalesce((select jsonb_build_object(
        'status', status, 'sales_stage', sales_stage, 'owner_id', owner_id,
        'owner_name', owner_name, 'next_action_at', next_action_at,
        'next_action_type', next_action_type, 'last_touch_at', last_touch_at,
        'contact_attempts', contact_attempts, 'notes', notes
      ) from followup), '{}'::jsonb),
      'impact_after_last_touch', jsonb_build_object(
        'last_touch_at', (select occurred_at from last_touch),
        'paid_amount', (select coalesce(round(sum(amount)::numeric, 2), 0) from payment_rows),
        'shipment_events', (select count(*) from lifecycle where event_type in ('first_shipment', 'shipping_resumed', 'reactivated') and observed_at >= (select occurred_at from last_touch))
      ),
      'lifecycle', coalesce((select jsonb_agg(to_jsonb(event)) from lifecycle event), '[]'::jsonb),
      'activities', coalesce((select jsonb_agg(to_jsonb(activity)) from activities activity), '[]'::jsonb),
      'outcomes', coalesce((select jsonb_agg(to_jsonb(outcome)) from outcomes outcome), '[]'::jsonb)
    )
  );
end;
$function$;
comment on function "private"."customer_growth_profile"(p_phone text) is 'Unified growth profile joining Lamha stores, Zoho customer links, finance, ownership, activities and objective lifecycle events.';
CREATE OR REPLACE FUNCTION private.record_customer_growth_outcome(p_phone text, p_reason_code text, p_outcome text, p_next timestamp with time zone DEFAULT NULL::timestamp with time zone, p_activity_type text DEFAULT 'call'::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_phone text := public.norm_sa_phone(p_phone);
  v_stage text;
  v_existing public.retargeting_followups%rowtype;
  v_financial_hold boolean := false;
  v_owner uuid;
begin
  if v_uid is null then raise exception 'not_allowed'; end if;
  if p_reason_code in ('wallet_neg', 'debt') then
    if not public.app_has_any_permission(array['collections.update_stage']) then
      raise exception 'not_allowed';
    end if;
  elsif not public.app_has_any_permission(array['sales.manage']) then
    raise exception 'not_allowed';
  end if;

  if v_phone is null then raise exception 'invalid_phone'; end if;
  if p_outcome not in (
    'contacted', 'interested', 'no_answer', 'needs_followup',
    'returned', 'converted', 'not_interested', 'price_issue'
  ) then raise exception 'invalid_outcome'; end if;
  if p_activity_type not in ('note', 'call', 'whatsapp', 'meeting', 'email') then
    raise exception 'invalid_activity_type';
  end if;

  v_stage := case
    when p_outcome in ('returned', 'converted') then 'won'
    when p_outcome = 'not_interested' then 'lost'
    when p_outcome = 'interested' then 'qualified'
    when p_outcome in ('no_answer', 'needs_followup') then 'nurture'
    else 'contacted'
  end;

  if v_stage not in ('won', 'lost') and p_next is null then
    raise exception 'next_action_required';
  end if;
  if v_stage = 'lost' and nullif(btrim(coalesce(p_note, '')), '') is null then
    raise exception 'loss_reason_required';
  end if;

  select * into v_existing
  from public.retargeting_followups
  where public.norm_sa_phone(phone) = v_phone
  order by updated_at desc
  limit 1
  for update;

  if found and v_existing.owner_id is not null and v_existing.owner_id <> v_uid
     and not public.crm_can_see_all() and not public.crm_has_permission('crm.assign') then
    raise exception 'not_allowed';
  end if;

  select exists (
    select 1 from public.v_platform_commercial_routing routing
    where routing.phone = v_phone and routing.financial_hold
  ) into v_financial_hold;
  v_owner := coalesce(v_existing.owner_id, v_uid);

  insert into public.customer_growth_outcomes (
    phone, reason_code, outcome, sales_stage, activity_type,
    next_action_at, note, owner_id, recorded_by
  ) values (
    v_phone, p_reason_code, p_outcome, v_stage, p_activity_type,
    case when v_stage in ('won', 'lost') then null else p_next end,
    nullif(btrim(p_note), ''), v_owner, v_uid
  );

  if not v_financial_hold then
    insert into public.retargeting_followups (
    phone, status, sales_stage, owner_id, next_action_at, next_action_type,
    notes, last_touch_at, first_contact_at, contact_attempts,
    loss_reason, lost_at, won_at, updated_by, updated_at
  ) values (
    v_phone, p_outcome, v_stage, v_owner,
    case when v_stage in ('won', 'lost') then null else p_next end,
    case when p_activity_type in ('call', 'whatsapp', 'meeting', 'email') then p_activity_type else 'other' end,
    nullif(btrim(p_note), ''), now(), now(), 1,
    case when v_stage = 'lost' then nullif(btrim(p_note), '') end,
    case when v_stage = 'lost' then now() end,
    case when v_stage = 'won' then now() end,
    v_uid, now()
  )
  on conflict (phone) do update set
    status = excluded.status,
    sales_stage = excluded.sales_stage,
    owner_id = coalesce(public.retargeting_followups.owner_id, excluded.owner_id),
    next_action_at = excluded.next_action_at,
    next_action_type = excluded.next_action_type,
    notes = coalesce(excluded.notes, public.retargeting_followups.notes),
    last_touch_at = now(),
    first_contact_at = coalesce(public.retargeting_followups.first_contact_at, now()),
    contact_attempts = public.retargeting_followups.contact_attempts + 1,
    loss_reason = case when excluded.sales_stage = 'lost' then excluded.loss_reason else null end,
    lost_at = case when excluded.sales_stage = 'lost' then coalesce(public.retargeting_followups.lost_at, now()) else null end,
    won_at = case when excluded.sales_stage = 'won' then coalesce(public.retargeting_followups.won_at, now()) else null end,
    updated_by = v_uid,
    updated_at = now();

    if p_outcome is distinct from coalesce(v_existing.status, 'new') then
      insert into public.retargeting_status_log(phone, old_status, new_status, changed_by)
      values (v_phone, v_existing.status, p_outcome, v_uid);
    end if;
  end if;

  insert into public.crm_activities (
    entity_type, entity_ref, kind, disposition, summary, body,
    channel_ref, occurred_at, owner_id, created_by
  ) values (
    'platform_merchant', v_phone,
    case when p_reason_code in ('wallet_neg', 'debt') then 'collections_' else 'sales_' end || p_activity_type,
    p_outcome,
    'نتيجة من مهام العملاء: ' || coalesce(p_reason_code, 'general'),
    nullif(btrim(p_note), ''), p_reason_code, now(),
    v_owner, v_uid
  );

  return jsonb_build_object(
    'phone', v_phone, 'outcome', p_outcome, 'sales_stage', v_stage,
    'next_action_at', case when v_stage in ('won', 'lost') then null else p_next end,
    'recorded_at', now(), 'financial_hold_preserved', v_financial_hold,
    'sending_triggered', false
  );
end;
$function$;
comment on function "private"."record_customer_growth_outcome"(p_phone text, p_reason_code text, p_outcome text, p_next timestamp with time zone, p_activity_type text, p_note text) is 'Records a reviewed customer outcome, owner, SLA and CRM activity. It never sends a WhatsApp message or starts a campaign.';
CREATE OR REPLACE FUNCTION public._test_alloc_guard()
 RETURNS TABLE(scenario text, result text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_pay int; v_op uuid; v_op2 uuid; v_amt numeric; v_carrier text; v_msg text;
begin
  select id, amount, carrier_id into v_pay, v_amt, v_carrier from payments order by id limit 1;
  select id into v_op  from carrier_operations where carrier_id = v_carrier limit 1;
  select id into v_op2 from carrier_operations where carrier_id <> v_carrier limit 1;

  begin
    insert into payment_allocations (payment_id, operation_id, amount) values (v_pay, v_op, v_amt * 10);
    scenario := 'تجاوز مبلغ الدفعة'; result := '❌ مرّ (الحارس فشل)'; return next;
  exception when others then
    get stacked diagnostics v_msg = MESSAGE_TEXT;
    scenario := 'تجاوز مبلغ الدفعة'; result := '✅ رُفض: ' || v_msg; return next;
  end;

  begin
    insert into payment_allocations (payment_id, operation_id, amount) values (v_pay, v_op2, 1);
    scenario := 'ناقل مختلف'; result := '❌ مرّ (الحارس فشل)'; return next;
  exception when others then
    get stacked diagnostics v_msg = MESSAGE_TEXT;
    scenario := 'ناقل مختلف'; result := '✅ رُفض: ' || v_msg; return next;
  end;

  begin
    insert into payment_allocations (payment_id, operation_id, amount) values (v_pay, v_op, -5);
    scenario := 'مبلغ سالب'; result := '❌ مرّ (الحارس فشل)'; return next;
  exception when others then
    scenario := 'مبلغ سالب'; result := '✅ رُفض'; return next;
  end;
  return;
end$function$;
CREATE OR REPLACE FUNCTION public.ap_aging_by_carrier()
 RETURNS TABLE(carrier_id text, current_amt numeric, d31_60 numeric, d61_90 numeric, d90_plus numeric, total_open numeric, oldest_at date)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH open_ops AS (
    SELECT
      carrier_id,
      doc_date,
      (amount_dr - amount_cr) AS net,
      (current_date - doc_date) AS age_days
    FROM carrier_operations
    WHERE status IS DISTINCT FROM 'paid'
      AND doc_date IS NOT NULL
  )
  SELECT
    carrier_id,
    coalesce(SUM(net) FILTER (WHERE age_days <= 30), 0)::numeric                          AS current_amt,
    coalesce(SUM(net) FILTER (WHERE age_days BETWEEN 31 AND 60), 0)::numeric              AS d31_60,
    coalesce(SUM(net) FILTER (WHERE age_days BETWEEN 61 AND 90), 0)::numeric              AS d61_90,
    coalesce(SUM(net) FILTER (WHERE age_days > 90), 0)::numeric                           AS d90_plus,
    coalesce(SUM(net), 0)::numeric                                                        AS total_open,
    MIN(doc_date)                                                                          AS oldest_at
  FROM open_ops
  GROUP BY carrier_id
  HAVING SUM(net) > 0.5
  ORDER BY total_open DESC;
$function$;
CREATE OR REPLACE FUNCTION public.app_has_any_permission(p_keys text[])
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(
    (select p.role = 'admin'
         or exists (
           select 1 from unnest(coalesce(p_keys, array[]::text[])) k
           where coalesce((p.permissions ->> k)::boolean, false)
         )
       from public.profiles p
      where p.id = auth.uid()),
    false
  );
$function$;
CREATE OR REPLACE FUNCTION public.approve_hudhud_lead_candidate(p_candidate_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  c public.hudhud_lead_candidates%rowtype;
  lead_id uuid;
begin
  if auth.uid() is null or not public.hudhud_can_review_leads() then
    raise exception 'not_authorized';
  end if;

  select * into c from public.hudhud_lead_candidates where id = p_candidate_id for update;
  if not found then raise exception 'candidate_not_found'; end if;
  if c.crm_lead_id is not null then return c.crm_lead_id; end if;

  if c.phone_normalized is not null then
    select id into lead_id from public.crm_leads
    where phone_normalized = c.phone_normalized
    order by created_at desc limit 1;
  end if;

  if lead_id is null then
    insert into public.crm_leads (
      name, name_en, phone, phone_normalized, email, city, category, address,
      website, social_links, notes, source, snapshot_id, status, lead_kind,
      source_channel, campaign_meta, created_by
    ) values (
      c.name_ar, c.name_en, c.phone, c.phone_normalized, c.email, c.city_ar,
      c.category_ar, concat_ws('، ', c.district_ar, c.city_ar), c.website_url,
      jsonb_strip_nulls(jsonb_build_object('instagram',c.instagram_url,'x',c.x_url,'snapchat',c.snapchat_url,'tiktok',c.tiktok_url)),
      nullif(trim(p_notes),''), 'hudhud_places', 'hudhud_' || c.hudhud_place_id,
      'new', 'cold', 'hudhud_places',
      jsonb_build_object('hudhud_candidate_id',c.id,'ecommerce_score',c.ecommerce_score,'evidence',c.qualification_evidence),
      auth.uid()
    ) returning id into lead_id;
  end if;

  update public.hudhud_lead_candidates set
    review_status = 'approved', review_notes = nullif(trim(p_notes),''),
    reviewed_by = auth.uid(), reviewed_at = now(), crm_lead_id = lead_id, updated_at = now()
  where id = c.id;
  return lead_id;
end;
$function$;
CREATE OR REPLACE FUNCTION public.approved_writeoffs_by_customer()
 RETURNS TABLE(customer_name text, total_written_off numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT customer_name, SUM(amount)::numeric
  FROM bad_debt_writeoffs
  WHERE status = 'approved'
  GROUP BY customer_name;
$function$;
CREATE OR REPLACE FUNCTION public.ar_aging_trend(p_months integer DEFAULT 6)
 RETURNS json
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select coalesce(
    json_agg(row_to_json(t) order by t.period),
    '[]'::json
  )
  from (
    select s.period, s.b0_30, s.b31_60, s.b61_90, s.b90p, s.total, s.captured_at
    from public.ar_aging_snapshots s
    order by s.period desc
    limit greatest(2, least(coalesce(p_months, 6), 24))
  ) t;
$function$;
CREATE OR REPLACE FUNCTION public.assign_collection_tasks(p_task_ids uuid[], p_assignee uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_ids uuid[];
  v_updated integer := 0;
begin
  if v_uid is null or not public.crm_has_permission('collections.assign') then
    raise exception 'not_allowed';
  end if;

  if coalesce(cardinality(p_task_ids), 0) = 0 then
    raise exception 'task_ids_required';
  end if;

  if cardinality(p_task_ids) > 500 then
    raise exception 'too_many_tasks';
  end if;

  if p_assignee is not null and not exists (
    select 1
    from public.profiles profile
    where profile.id = p_assignee
      and profile.role <> 'admin'
      and coalesce((profile.permissions ->> 'collections.view')::boolean, false)
      and coalesce((profile.permissions ->> 'collections.update_stage')::boolean, false)
  ) then
    raise exception 'assignee_not_eligible';
  end if;

  select array_agg(distinct task.id order by task.id)
  into v_ids
  from public.collection_tasks task
  where task.id = any(p_task_ids)
    and task.stage in ('todo', 'contacted', 'promised', 'snoozed');

  if coalesce(cardinality(v_ids), 0) = 0 then
    raise exception 'no_open_tasks';
  end if;

  update public.collection_tasks task
  set assigned_to = p_assignee,
      updated_at = now()
  where task.id = any(v_ids);
  get diagnostics v_updated = row_count;

  insert into public.collection_task_assignment_batches (
    task_ids, task_count, assignee_id, assigned_by
  ) values (
    v_ids, v_updated, p_assignee, v_uid
  );

  return jsonb_build_object(
    'updated', v_updated,
    'assignee_id', p_assignee,
    'unassigned', p_assignee is null
  );
end;
$function$;
CREATE OR REPLACE FUNCTION public.assign_platform_sales_accounts(p_phones text[], p_owner uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_requested integer;
  v_assigned integer;
  v_reassigned integer;
  v_batch uuid;
  v_phones text[];
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if not public.crm_has_permission('crm.assign') then raise exception 'not_allowed'; end if;
  if p_owner is null then raise exception 'assignee_required'; end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_owner
      and p.role <> 'admin'
      and coalesce((p.permissions ->> 'sales.view')::boolean, false)
      and coalesce((p.permissions ->> 'sales.manage')::boolean, false)
  ) then
    raise exception 'assignee_not_sales_operator';
  end if;

  select array_agg(phone order by phone), count(*)
  into v_phones, v_requested
  from (
    select distinct btrim(raw_phone) as phone
    from unnest(coalesce(p_phones, array[]::text[])) raw_phone
    where nullif(btrim(raw_phone), '') is not null
  ) selected;

  if coalesce(v_requested, 0) = 0 then raise exception 'no_accounts_selected'; end if;
  if v_requested > 5000 then raise exception 'bulk_limit_5000'; end if;

  -- Only accounts that are still eligible for the platform-sales workspace
  -- can be assigned. Financially held customers remain outside this workflow.
  select array_agg(selected.phone order by selected.phone), count(*)
  into v_phones, v_assigned
  from unnest(v_phones) selected(phone)
  join public.v_platform_commercial_routing routing on routing.phone = selected.phone
  where routing.sales_eligible;

  if coalesce(v_assigned, 0) = 0 then raise exception 'no_eligible_accounts'; end if;
  if v_assigned <> v_requested then raise exception 'selection_changed_refresh_required'; end if;

  select count(*) into v_reassigned
  from public.retargeting_followups followup
  where followup.phone = any(v_phones)
    and followup.owner_id is not null
    and followup.owner_id is distinct from p_owner;

  insert into public.retargeting_followups (
    phone, status, owner_id, updated_by, updated_at
  )
  select phone, 'new', p_owner, v_uid, now()
  from unnest(v_phones) selected(phone)
  on conflict (phone) do update set
    owner_id = excluded.owner_id,
    updated_by = excluded.updated_by,
    updated_at = excluded.updated_at;

  insert into public.platform_sales_assignment_batches (
    assignee_id, assigned_by, requested_count, assigned_count,
    reassigned_count, phones
  ) values (
    p_owner, v_uid, v_requested, v_assigned, v_reassigned, v_phones
  ) returning id into v_batch;

  return jsonb_build_object(
    'batch_id', v_batch,
    'requested_count', v_requested,
    'assigned_count', v_assigned,
    'reassigned_count', v_reassigned,
    'assignee_id', p_owner
  );
end;
$function$;
CREATE OR REPLACE FUNCTION public.assistant_readonly_sql(q text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE result jsonb; clean text;
BEGIN
  clean := btrim(q);
  IF clean !~* '^(select|with)\s' THEN
    RAISE EXCEPTION 'يُسمح فقط باستعلامات SELECT';
  END IF;
  -- جملة واحدة: لا فاصلة منقوطة في المنتصف
  IF clean ~ ';\s*\S' THEN
    RAISE EXCEPTION 'جملة SELECT واحدة فقط';
  END IF;
  -- كلمات الكتابة/DDL محظورة (حدود كلمات)
  IF clean ~* '\m(insert|update|delete|drop|alter|create|grant|revoke|truncate|copy|merge|comment|vacuum|reindex|call|do|set)\M' THEN
    RAISE EXCEPTION 'كلمة محظورة في الاستعلام';
  END IF;
  -- منع دوال الكتابة الخفية
  IF clean ~* '\m(pg_read_file|pg_ls_dir|dblink|pg_sleep|lo_import|lo_export)\M' THEN
    RAISE EXCEPTION 'دالة محظورة';
  END IF;
  -- طبقة القاعدة: لو أي شيء فلت، الكتابة تفشل
  SET LOCAL transaction_read_only = on;
  EXECUTE format(
    'SELECT coalesce(jsonb_agg(t), ''[]''::jsonb) FROM (%s) t',
    regexp_replace(clean, '\s*;\s*$', '')
  ) INTO result;
  -- حدّ السلامة: لا نرجّع أكثر من 500 صف
  IF jsonb_array_length(result) > 500 THEN
    result := (SELECT jsonb_agg(e) FROM (SELECT e FROM jsonb_array_elements(result) e LIMIT 500) s);
  END IF;
  RETURN result;
END; $function$;
CREATE OR REPLACE FUNCTION public.autolink_balances_by_exact_name()
 RETURNS TABLE(linked_count integer, store_ids text[])
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_linked_ids text[];
  v_snaps uuid[];
  v_todo  int;
BEGIN
  -- أحدث كشف لكل مصدر — الباقي تاريخ لا يُعرَض ولا يُربَط
  SELECT array_agg(id) INTO v_snaps FROM (
    SELECT DISTINCT ON (source) id FROM store_balance_snapshots
    ORDER BY source, uploaded_at DESC
  ) s;
  IF v_snaps IS NULL THEN
    RETURN QUERY SELECT 0, ARRAY[]::text[]; RETURN;
  END IF;

  -- خروج مبكر: لا شيء غير مرتبط → لا تخطيط ولا cross join
  SELECT count(*) INTO v_todo FROM store_balances
  WHERE store_id IS NULL AND snapshot_id = ANY(v_snaps);
  IF v_todo = 0 THEN
    RETURN QUERY SELECT 0, ARRAY[]::text[]; RETURN;
  END IF;

  WITH latest_merchants AS (
    SELECT snapshot_id FROM merchants ORDER BY uploaded_at DESC LIMIT 1
  ),
  merchant_lookup AS (
    SELECT DISTINCT ON (m.store_id) m.store_id, m.store_name
    FROM merchants m JOIN latest_merchants lm ON m.snapshot_id = lm.snapshot_id
    WHERE m.store_name IS NOT NULL AND LENGTH(TRIM(m.store_name)) >= 3
  ),
  todo AS (
    SELECT id, raw_name FROM store_balances
    WHERE store_id IS NULL AND snapshot_id = ANY(v_snaps)
  ),
  candidates AS (
    SELECT t.id AS sb_id, ml.store_id, ml.store_name,
      ROW_NUMBER() OVER (PARTITION BY t.id ORDER BY LENGTH(ml.store_name) DESC, ml.store_id) AS rn
    FROM todo t
    CROSS JOIN merchant_lookup ml
    WHERE TRIM(t.raw_name) = TRIM(ml.store_name)
       OR t.raw_name  ILIKE '%' || ml.store_name || '%'
       OR ml.store_name ILIKE '%' || t.raw_name  || '%'
  ),
  best AS (SELECT sb_id, store_id FROM candidates WHERE rn = 1),
  updated AS (
    UPDATE store_balances sb
    SET store_id = b.store_id, match_method = 'link-segment-backfill', match_confidence = 0.95
    FROM best b WHERE sb.id = b.sb_id AND sb.store_id IS NULL
    RETURNING sb.store_id
  )
  SELECT ARRAY_AGG(DISTINCT store_id) INTO v_linked_ids FROM updated;

  RETURN QUERY SELECT
    COALESCE(ARRAY_LENGTH(v_linked_ids, 1), 0), COALESCE(v_linked_ids, ARRAY[]::text[]);
END;
$function$;
comment on function "public"."autolink_balances_by_exact_name"() is 'Backfills store_balances.store_id for unmatched rows whose raw_name exact-matches OR contains/is-contained-in a merchant.store_name. Picks the longest (most specific) merchant when multiple match. v2: substring matching.';
CREATE OR REPLACE FUNCTION public.balance_reconciliation()
 RETURNS TABLE(store_id text, store_name text, internal_balance numeric, zoho_balance numeric, receivables_balance numeric, max_diff numeric, internal_raw_name text, zoho_raw_name text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH
  latest_internal AS (
    SELECT id FROM store_balance_snapshots WHERE source='internal' ORDER BY uploaded_at DESC LIMIT 1
  ),
  latest_receivables AS (SELECT snapshot_id FROM customer_receivables ORDER BY uploaded_at DESC LIMIT 1),
  latest_merchants AS (SELECT snapshot_id FROM merchants ORDER BY uploaded_at DESC LIMIT 1),
  internal_rows AS (
    SELECT sb.store_id, MIN(sb.raw_name) AS raw_name, SUM(sb.balance) AS balance
    FROM store_balances sb JOIN latest_internal li ON sb.snapshot_id = li.id
    GROUP BY sb.store_id
  ),
  merchant_norm AS (
    SELECT m.store_id, normalize_arabic_name(m.store_name) AS norm
    FROM merchants m JOIN latest_merchants lm ON m.snapshot_id = lm.snapshot_id
  ),
  -- ✅ زوهو الحي = الذمّة الكاملة من `customer_ar` (فواتير مفتوحة + رصيد افتتاحي)
  zoho_live AS (
    SELECT contact_name AS customer_name, total_due AS bal
    FROM customer_ar WHERE total_due > 0.5
  ),
  zoho_rows AS (
    SELECT t.store_id, MIN(t.customer_name) AS raw_name, SUM(t.bal) AS balance
    FROM (
      SELECT z.customer_name, z.bal,
        COALESCE(l.store_id,
          (SELECT mn.store_id FROM merchant_norm mn
           WHERE mn.norm = normalize_arabic_name(z.customer_name) LIMIT 1)) AS store_id
      FROM zoho_live z
      LEFT JOIN customer_merchant_links l
        ON l.customer_name = z.customer_name AND l.store_id IS NOT NULL
    ) t
    WHERE t.store_id IS NOT NULL
    GROUP BY t.store_id
  ),
  receivables_rows AS (
    SELECT cml.store_id, SUM(cr.balance_amount)::numeric AS balance
    FROM customer_receivables cr
    JOIN latest_receivables lr ON cr.snapshot_id = lr.snapshot_id
    JOIN customer_merchant_links cml ON cml.customer_name = cr.customer_name
    WHERE cml.store_id IS NOT NULL AND NOT coalesce(cr.is_summary, false)
    GROUP BY cml.store_id
  ),
  merchant_names AS (
    SELECT m.store_id, m.store_name FROM merchants m JOIN latest_merchants lm ON m.snapshot_id = lm.snapshot_id
  ),
  all_stores AS (
    SELECT store_id FROM internal_rows WHERE store_id IS NOT NULL
    UNION SELECT store_id FROM zoho_rows WHERE store_id IS NOT NULL
    UNION SELECT store_id FROM receivables_rows
  )
  SELECT a.store_id, mn.store_name,
    -(coalesce(i.balance, 0)) AS internal_balance,
    coalesce(z.balance, 0)    AS zoho_balance,
    coalesce(r.balance, 0)    AS receivables_balance,
    GREATEST(
      abs(-(coalesce(i.balance, 0)) - coalesce(z.balance, 0)),
      abs(-(coalesce(i.balance, 0)) - coalesce(r.balance, 0)),
      abs(coalesce(z.balance, 0)    - coalesce(r.balance, 0))
    )::numeric AS max_diff,
    i.raw_name AS internal_raw_name, z.raw_name AS zoho_raw_name
  FROM all_stores a
  LEFT JOIN internal_rows     i  ON i.store_id = a.store_id
  LEFT JOIN zoho_rows         z  ON z.store_id = a.store_id
  LEFT JOIN receivables_rows  r  ON r.store_id = a.store_id
  LEFT JOIN merchant_names    mn ON mn.store_id = a.store_id
  ORDER BY max_diff DESC;
$function$;
CREATE OR REPLACE FUNCTION public.bulk_match_customers(p_names text[], p_threshold numeric DEFAULT 0.78)
 RETURNS TABLE(customer_name text, store_id text, store_name text, confidence numeric, method text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with latest_snapshot as (
    select snapshot_id
    from public.merchants
    order by uploaded_at desc
    limit 1
  ),
  segs as (
    select
      n as customer_name,
      public.normalize_arabic_name(seg) as nseg
    from unnest(p_names) as n
    cross join lateral regexp_split_to_table(n, '[-|]') as seg
    where length(public.normalize_arabic_name(seg)) >= 2
  ),
  candidates as (
    select
      s.customer_name,
      s.nseg,
      m.store_id,
      m.store_name,
      public.normalize_arabic_name(m.store_name) as nname
    from segs s
    cross join lateral (
      select store_id, store_name
      from public.merchants m
      where m.snapshot_id = (select snapshot_id from latest_snapshot)
        and public.normalize_arabic_name(m.store_name) % s.nseg
      order by similarity(public.normalize_arabic_name(m.store_name), s.nseg) desc
      limit 8
    ) as m
  ),
  scored as (
    select
      c.customer_name,
      c.store_id,
      c.store_name,
      case
        when c.nseg = c.nname then 1.0
        when length(c.nseg) >= 3 and (
          c.nseg like '%' || c.nname || '%'
          or c.nname like '%' || c.nseg || '%'
        ) then least(length(c.nseg), length(c.nname))::numeric
             / greatest(length(c.nseg), length(c.nname))::numeric
        else similarity(c.nseg, c.nname)::numeric
      end as confidence,
      case when c.nseg = c.nname then 'auto-exact' else 'auto-fuzzy' end as method
    from candidates c
  ),
  per_store as (
    select
      customer_name,
      store_id,
      max(store_name) as store_name,
      max(confidence) as confidence,
      case when bool_or(method = 'auto-exact') then 'auto-exact' else 'auto-fuzzy' end as method
    from scored
    group by customer_name, store_id
  ),
  ranked as (
    select
      p.*,
      row_number() over (
        partition by customer_name
        order by confidence desc, (method = 'auto-exact') desc, store_id
      ) as candidate_rank,
      lead(confidence) over (
        partition by customer_name
        order by confidence desc, (method = 'auto-exact') desc, store_id
      ) as runner_up_confidence
    from per_store p
  )
  select
    customer_name,
    store_id,
    store_name,
    round(confidence, 2),
    method
  from ranked
  where candidate_rank = 1
    and confidence >= p_threshold
    -- Equal or near-equal store candidates are ambiguous. Five percentage
    -- points is deliberately conservative because this mapping drives money
    -- collection, suspension and activation decisions.
    and (runner_up_confidence is null or confidence - runner_up_confidence >= 0.05);
$function$;
CREATE OR REPLACE FUNCTION public.campaign_blocklist_report()
 RETURNS TABLE(phone text, name text, reason text, added_at timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select phone, name, reason, added_at
  from public.campaign_phone_blocklist order by added_at desc;
$function$;
CREATE OR REPLACE FUNCTION public.campaign_hour_stats(p_days integer DEFAULT 90)
 RETURNS TABLE(hour integer, sent bigint, read_pct numeric, reply_pct numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select extract(hour from sent_at at time zone 'Asia/Riyadh')::int,
    count(*),
    round(100.0*count(*) filter (where read_at is not null)/nullif(count(*),0),1),
    round(100.0*count(*) filter (where replied_at is not null and coalesce(reply_is_auto,false)=false)/nullif(count(*),0),1)
  from whatsapp_campaign_sends
  where sent_at > now() - make_interval(days => greatest(p_days,1))
  group by 1 having count(*) >= 20 order by 1;
$function$;
CREATE OR REPLACE FUNCTION public.campaign_recipient_context(p_phones text[])
 RETURNS TABLE(phone text, store_name text, store_count integer, shipments integer, last_shipment timestamp with time zone, wallet numeric, billing_type text, store_status text, zoho_due numeric, zoho_open_count bigint, zoho_last_invoice date, zoho_last_payment date)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
with latest as (select snapshot_id from merchants order by uploaded_at desc nulls last limit 1),
ph as (
  select distinct norm_sa_phone(p) as phone from unnest(p_phones) p
  where p is not null and length(norm_sa_phone(p)) >= 11
),
m as (
  select norm_sa_phone(mm.phone) as phone,
         mm.store_id, mm.store_name, mm.shipment_count, mm.last_shipment_at,
         mm.wallet_balance, mm.billing_type, mm.status,
         count(*) over (partition by norm_sa_phone(mm.phone))::int as store_count
  from merchants mm join latest l on mm.snapshot_id = l.snapshot_id
  where norm_sa_phone(mm.phone) in (select phone from ph)
),
custs as (
  select m.phone, m.store_id, cml.customer_name
  from m join customer_merchant_links cml on cml.store_id = m.store_id
),
zi as (
  select c.phone, c.store_id,
         sum(ar.total_due) as due,
         (select count(*) from zoho_invoices z2 where z2.customer_name = c.customer_name and z2.balance > 0.5) as cnt,
         (select max(z3.date) from zoho_invoices z3 where z3.customer_name = c.customer_name) as last_inv
  from custs c join customer_ar ar on ar.contact_name = c.customer_name
  group by c.phone, c.store_id, c.customer_name
),
zp as (
  select c.phone, c.store_id, max(p.date) as last_pay
  from custs c join zoho_payments p on p.customer_name = c.customer_name
  group by c.phone, c.store_id
)
select m.phone, m.store_name, m.store_count,
       m.shipment_count, m.last_shipment_at,
       m.wallet_balance, m.billing_type, m.status,
       coalesce(zi.due, 0), coalesce(zi.cnt, 0), zi.last_inv, zp.last_pay
from m
left join zi on zi.phone = m.phone and zi.store_id = m.store_id
left join zp on zp.phone = m.phone and zp.store_id = m.store_id
order by m.phone, m.shipment_count desc;
$function$;
CREATE OR REPLACE FUNCTION public.campaign_template_stats(p_days integer DEFAULT 90)
 RETURNS TABLE(template text, sent bigint, delivered_pct numeric, read_pct numeric, reply_pct numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(nullif(template_name,''),'(بلا قالب)'),
    count(*),
    round(100.0*count(*) filter (where delivered_at is not null)/nullif(count(*),0),1),
    round(100.0*count(*) filter (where read_at is not null)/nullif(count(*),0),1),
    round(100.0*count(*) filter (where replied_at is not null and coalesce(reply_is_auto,false)=false)/nullif(count(*),0),1)
  from whatsapp_campaign_sends
  where sent_at > now() - make_interval(days => greatest(p_days,1))
  group by 1 having count(*) >= 20 order by 2 desc;
$function$;
CREATE OR REPLACE FUNCTION public.canon_lead_category(c text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case
    when head is null then null
    when head ~ 'تسويق|حلول إلكتروني|تصميم|طباعة|تصوير|لوجست|إدار|خدمات الأعمال|دراسات|استشار|برمج|تقني|موقع' then 'خدمات الأعمال'
    when head ~ 'مستلزمات المرأة|كوافير|تجميل|عناية|عطور|صحة|لياقة|الجمال' then 'الجمال والصحة'
    when head ~ 'مطبخ|مخبوز|قهوة|مشروب|أطعم|اطعم|طعام|حلوي|بن|تمر' then 'أطعمة ومشروبات'
    when head ~ 'إلكترون|الكترون|اكسسوار|جوال|كمبيوتر|تقنية' then 'إلكترونيات'
    when head ~ 'أثاث|اثاث|ديكور|منزل|مفروش' then 'المنزل'
    when head ~ 'حرف|يدوي|هدايا|هديه|متسوق|ورد|زهور' then 'هدايا'
    when head ~ 'مناسبات|حفل|تنسيق|فعاليات' then 'حفلات'
    when head ~ 'أكاديمي|اكاديمي|تعليم|دورات|تدريب|مدرس' then 'التعليم'
    when head ~ 'عقار' then 'العقارات'
    when head ~ 'سيارات|سياره|مركبات' then 'السيارات'
    when head ~ 'أزياء|ازياء|ملابس|موضة|عباي|أحذية|حقائب' then 'أزياء'
    when head ~ 'أطفال|اطفال|مواليد|ألعاب|العاب' then 'أطفال وألعاب'
    when head in ('أخرى','اخرى') then 'أخرى'
    else head
  end
  from (select nullif(btrim(regexp_replace(split_part(regexp_replace(coalesce(c,''),'[—–-]','—','g'),'—',1),'\s+',' ','g')),'') as head) s;
$function$;
CREATE OR REPLACE FUNCTION public.capture_ar_aging_snapshot()
 RETURNS json
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with clock as (
    select (now() at time zone 'Asia/Riyadh')::date as as_of
  ),
  inv as (
    select
      coalesce(sum(i.balance) filter (where (c.as_of - i.date)::int <= 30), 0) b0,
      coalesce(sum(i.balance) filter (where (c.as_of - i.date)::int between 31 and 60), 0) b1,
      coalesce(sum(i.balance) filter (where (c.as_of - i.date)::int between 61 and 90), 0) b2,
      coalesce(sum(i.balance) filter (where (c.as_of - i.date)::int > 90), 0) b3
    from public.zoho_invoices i
    cross join clock c
    where i.balance > 0.5
  ),
  opening as (
    select coalesce(sum(ar.opening_due), 0) op
    from public.customer_ar ar
    where ar.opening_due > 0.5
  ),
  agg as (
    select b0, b1, b2, b3 + op b3, b0 + b1 + b2 + b3 + op tot
    from inv, opening
  ),
  up as (
    insert into public.ar_aging_snapshots
      (period, b0_30, b31_60, b61_90, b90p, total, captured_at)
    select
      to_char(c.as_of, 'YYYY-MM'),
      round(a.b0::numeric, 2),
      round(a.b1::numeric, 2),
      round(a.b2::numeric, 2),
      round(a.b3::numeric, 2),
      round(a.tot::numeric, 2),
      now()
    from agg a
    cross join clock c
    on conflict (period) do update set
      b0_30 = excluded.b0_30,
      b31_60 = excluded.b31_60,
      b61_90 = excluded.b61_90,
      b90p = excluded.b90p,
      total = excluded.total,
      captured_at = excluded.captured_at
    returning *
  )
  select row_to_json(up) from up;
$function$;
CREATE OR REPLACE FUNCTION public.capture_merchant_lifecycle_events(p_snapshot_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if (select auth.uid()) is null
     or not public.crm_has_permission('merchants.upload') then
    raise exception 'not_allowed';
  end if;

  return private.capture_merchant_lifecycle_events_internal(p_snapshot_id);
end;
$function$;
CREATE OR REPLACE FUNCTION public.capture_retargeting_summary()
 RETURNS json
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_snap   text;
  v_date   date;
  v_stats  jsonb;
  v_prev   jsonb;
  v_prev_snap text;
begin
  select snapshot_id, snapshot_date into v_snap, v_date
  from public.merchants order by uploaded_at desc limit 1;
  if v_snap is null then
    return json_build_object('current', null, 'previous', null);
  end if;
  v_stats := (public.crm_retargeting_summary() -> 'stats');
  insert into public.retargeting_snapshot_summary(snapshot_id, snapshot_date, stats, captured_at)
    values (v_snap, v_date, v_stats, now())
  on conflict (snapshot_id) do update set stats = excluded.stats, snapshot_date = excluded.snapshot_date, captured_at = now();
  select stats, snapshot_id into v_prev, v_prev_snap
  from public.retargeting_snapshot_summary
  where snapshot_id <> v_snap
  order by captured_at desc limit 1;
  return json_build_object(
    'current', v_stats, 'current_snapshot', v_snap, 'current_date', v_date,
    'previous', v_prev, 'previous_snapshot', v_prev_snap
  );
end;
$function$;
CREATE OR REPLACE FUNCTION public.carrier_cod_net_balances()
 RETURNS TABLE(carrier_id text, net numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT
    carrier_id,
    coalesce(SUM(
      CASE direction
        WHEN 'out' THEN  amount
        WHEN 'in'  THEN -amount
        ELSE 0
      END
    ), 0)::numeric AS net
  FROM cod_settlement
  GROUP BY carrier_id;
$function$;
CREATE OR REPLACE FUNCTION public.carrier_health_kpis()
 RETURNS TABLE(carrier_id text, audits_count integer, audits_approved integer, drift_total numeric, total_billed_sum numeric, drift_pct numeric, mismatch_total integer, shipments_total integer, mismatch_pct numeric, first_pass_rate numeric, avg_approval_hours numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH approved AS (
    SELECT * FROM audits WHERE approved_at IS NOT NULL
  ),
  per_carrier AS (
    SELECT
      a.carrier_id,
      COUNT(*)::int                                                 AS audits_count_all,
      COUNT(*) FILTER (WHERE approved_at IS NOT NULL)::int          AS audits_approved,
      coalesce(SUM(drift_pre_tax) FILTER (WHERE approved_at IS NOT NULL), 0)::numeric AS drift_total,
      coalesce(SUM(total_billed)  FILTER (WHERE approved_at IS NOT NULL), 0)::numeric AS total_billed_sum,
      coalesce(SUM(mismatch_count) FILTER (WHERE approved_at IS NOT NULL), 0)::int    AS mismatch_total,
      coalesce(SUM(row_count)      FILTER (WHERE approved_at IS NOT NULL), 0)::int    AS shipments_total,
      -- first_pass = approved && never had rejected_at populated
      COUNT(*) FILTER (WHERE approved_at IS NOT NULL AND rejected_at IS NULL)::int    AS first_pass_count,
      -- avg approval lag in hours
      AVG(EXTRACT(EPOCH FROM (approved_at - created_at)) / 3600.0)
        FILTER (WHERE approved_at IS NOT NULL)                                        AS avg_approval_hours
    FROM audits a
    GROUP BY a.carrier_id
  )
  SELECT
    carrier_id,
    audits_count_all                                                      AS audits_count,
    audits_approved,
    drift_total,
    total_billed_sum,
    CASE WHEN total_billed_sum > 0
         THEN (abs(drift_total) / total_billed_sum * 100)::numeric(6,2)
         ELSE 0::numeric(6,2)
    END                                                                   AS drift_pct,
    mismatch_total,
    shipments_total,
    CASE WHEN shipments_total > 0
         THEN (mismatch_total::numeric / shipments_total * 100)::numeric(6,2)
         ELSE 0::numeric(6,2)
    END                                                                   AS mismatch_pct,
    CASE WHEN audits_approved > 0
         THEN (first_pass_count::numeric / audits_approved * 100)::numeric(5,1)
         ELSE 100::numeric(5,1)
    END                                                                   AS first_pass_rate,
    coalesce(avg_approval_hours, 0)::numeric(8,2)                         AS avg_approval_hours
  FROM per_carrier
  ORDER BY drift_pct DESC, mismatch_pct DESC;
$function$;
CREATE OR REPLACE FUNCTION public.carrier_internal_balances()
 RETURNS TABLE(carrier_id text, carrier_name text, internal_balance numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select co.carrier_id, c.name,
         sum(co.amount_dr - co.amount_cr)::numeric
  from carrier_operations co
  left join carriers c on c.id = co.carrier_id
  where co.status is distinct from 'paid'
  group by co.carrier_id, c.name;
$function$;
CREATE OR REPLACE FUNCTION public.carrier_open_balance(p_carrier_id text)
 RETURNS TABLE(balance numeric, paid numeric, pending integer, disputed integer, reviewing integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT
    coalesce(SUM((amount_dr - amount_cr)) FILTER (WHERE status IS DISTINCT FROM 'paid'), 0)::numeric AS balance,
    coalesce(SUM((amount_dr - amount_cr)) FILTER (WHERE status = 'paid'),                0)::numeric AS paid,
    coalesce(COUNT(*) FILTER (WHERE status = 'pending'),   0)::int                                   AS pending,
    coalesce(COUNT(*) FILTER (WHERE status = 'disputed'),  0)::int                                   AS disputed,
    coalesce(COUNT(*) FILTER (WHERE status = 'reviewing'), 0)::int                                   AS reviewing
  FROM carrier_operations
  WHERE carrier_id = p_carrier_id;
$function$;
CREATE OR REPLACE FUNCTION public.carrier_open_balances_all()
 RETURNS TABLE(carrier_id text, balance numeric, paid numeric, pending integer, disputed integer, reviewing integer)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select
    o.carrier_id,
    coalesce(sum(o.amount_dr - o.amount_cr) filter (where o.status is distinct from 'paid'), 0)::numeric as balance,
    coalesce(sum(o.amount_dr - o.amount_cr) filter (where o.status = 'paid'), 0)::numeric as paid,
    count(*) filter (where o.status = 'pending')::integer as pending,
    count(*) filter (where o.status = 'disputed')::integer as disputed,
    count(*) filter (where o.status = 'reviewing')::integer as reviewing
  from public.carrier_operations o
  group by o.carrier_id;
$function$;
CREATE OR REPLACE FUNCTION public.carrier_recent_remittance_avg(p_batches integer DEFAULT 3)
 RETURNS TABLE(carrier_id text, avg_amount numeric, last_amount numeric, last_at timestamp with time zone, batch_count integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH batches AS (
    SELECT
      carrier_id,
      upload_id,
      SUM(amount) AS batch_total,
      MAX(coalesce(created_at, upload_date::timestamptz)) AS batch_at,
      ROW_NUMBER() OVER (
        PARTITION BY carrier_id
        ORDER BY MAX(coalesce(created_at, upload_date::timestamptz)) DESC
      ) AS rn
    FROM cod_settlement
    WHERE direction = 'in' AND upload_id IS NOT NULL
    GROUP BY carrier_id, upload_id
  ),
  recent AS (
    SELECT * FROM batches WHERE rn <= p_batches
  )
  SELECT
    carrier_id,
    AVG(batch_total)::numeric                              AS avg_amount,
    (ARRAY_AGG(batch_total ORDER BY batch_at DESC))[1]    AS last_amount,
    MAX(batch_at)                                          AS last_at,
    COUNT(*)::int                                          AS batch_count
  FROM recent
  GROUP BY carrier_id;
$function$;
CREATE OR REPLACE FUNCTION public.carrier_spend_concentration(p_period text DEFAULT NULL::text)
 RETURNS TABLE(carrier_id text, period text, spend numeric, share_pct numeric, audits_count integer, rank_order integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH p AS (
    SELECT coalesce(p_period, to_char(now(), 'YYYY-MM')) AS period
  ),
  per_carrier AS (
    SELECT
      c.carrier_id,
      SUM(c.amount_dr)::numeric AS spend,
      COUNT(DISTINCT c.audit_id) FILTER (WHERE c.audit_id IS NOT NULL)::int AS audits_count
    FROM carrier_operations c, p
    WHERE to_char(c.doc_date, 'YYYY-MM') = p.period
    GROUP BY c.carrier_id
  ),
  total AS (SELECT NULLIF(SUM(spend), 0) AS s FROM per_carrier)
  SELECT
    pc.carrier_id,
    p.period,
    pc.spend,
    coalesce((pc.spend / total.s * 100)::numeric(6,2), 0) AS share_pct,
    pc.audits_count,
    ROW_NUMBER() OVER (ORDER BY pc.spend DESC)::int AS rank_order
  FROM per_carrier pc CROSS JOIN p, total
  ORDER BY pc.spend DESC;
$function$;
CREATE OR REPLACE FUNCTION public.carrier_zoho_financial_dossier(p_carrier_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_vendor_id text;
  v_cod_expected numeric := 0;
  v_cod_received numeric := 0;
  v_treasury_balance numeric := 0;
  v_out jsonb;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if not (
    public.crm_has_permission('carriers.view')
    and public.crm_has_permission('zoho.view')
  ) then raise exception 'not_allowed'; end if;

  select zoho_vendor_id into v_vendor_id
  from public.carrier_zoho_vendor_links where carrier_id = p_carrier_id;

  select
    coalesce(sum(amount) filter (where direction = 'out'), 0),
    coalesce(sum(amount) filter (where direction = 'in'), 0)
  into v_cod_expected, v_cod_received
  from public.cod_settlement where carrier_id = p_carrier_id;

  select coalesce(sum(abs(coalesce(a.current_balance, 0))), 0)
  into v_treasury_balance
  from public.zoho_financial_account_links l
  join public.zoho_chart_accounts a on a.zoho_id = l.zoho_account_id
  where l.carrier_id = p_carrier_id and l.link_kind = 'cod_treasury';

  select jsonb_build_object(
    'carrier_id', p_carrier_id,
    'linked', v_vendor_id is not null,
    'vendor', (
      select jsonb_build_object(
        'zoho_id', c.zoho_id,
        'name', c.contact_name,
        'status', c.status,
        'gross_payable', coalesce(c.outstanding_payable, 0),
        'credits', coalesce(c.unused_credits_payable, 0),
        'net_payable', round((coalesce(c.outstanding_payable, 0) - coalesce(c.unused_credits_payable, 0))::numeric, 2),
        'synced_at', c.synced_at
      ) from public.zoho_contacts c where c.zoho_id = v_vendor_id
    ),
    'bills', jsonb_build_object(
      'count', count(*),
      'open_count', count(*) filter (where b.balance > 0.5),
      'total', coalesce(round(sum(b.total)::numeric, 2), 0),
      'open_balance', coalesce(round((sum(b.balance) filter (where b.balance > 0.5))::numeric, 2), 0),
      'overdue_count', count(*) filter (where b.balance > 0.5 and b.due_date < current_date),
      'overdue_balance', coalesce(round((sum(b.balance) filter (where b.balance > 0.5 and b.due_date < current_date))::numeric, 2), 0),
      'oldest_due_date', min(b.due_date) filter (where b.balance > 0.5)
    ),
    'payments', (
      select jsonb_build_object(
        'count', count(*),
        'total', coalesce(round(sum(p.amount)::numeric, 2), 0),
        'last_date', max(p.date),
        'last_amount', (array_agg(p.amount order by p.date desc nulls last, p.zoho_id desc))[1]
      ) from public.zoho_vendor_payments p where p.vendor_id = v_vendor_id
    ),
    'vendor_credits', (
      select jsonb_build_object(
        'count', count(*),
        'open_balance', coalesce(round((sum(vc.balance) filter (where vc.balance > 0.5))::numeric, 2), 0)
      ) from public.zoho_vendor_credits vc where vc.vendor_id = v_vendor_id
    ),
    'cod', jsonb_build_object(
      'expected', round(v_cod_expected, 2),
      'received', round(v_cod_received, 2),
      'outstanding', round(v_cod_expected - v_cod_received, 2),
      'treasury_balance', round(v_treasury_balance, 2),
      'treasury_gap', round((v_cod_expected - v_cod_received) - v_treasury_balance, 2)
    ),
    'treasuries', coalesce((
      select jsonb_agg(jsonb_build_object(
        'zoho_id', a.zoho_id,
        'name', a.account_name,
        'code', a.account_code,
        'balance', a.current_balance,
        'currency', a.currency_code,
        'synced_at', a.synced_at
      ) order by a.account_name)
      from public.zoho_financial_account_links l
      join public.zoho_chart_accounts a on a.zoho_id = l.zoho_account_id
      where l.carrier_id = p_carrier_id and l.link_kind = 'cod_treasury'
    ), '[]'::jsonb),
    'recent_activity', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.activity_date desc nulls last, x.id desc)
      from (
        select 'bill'::text kind, b.zoho_id id, b.date activity_date,
          b.bill_number reference, b.total amount, b.balance balance, b.status
        from public.zoho_bills b where b.vendor_id = v_vendor_id
        union all
        select 'payment', p.zoho_id, p.date, p.reference_number,
          p.amount, 0::numeric, coalesce(p.mode, 'paid')
        from public.zoho_vendor_payments p where p.vendor_id = v_vendor_id
        union all
        select 'credit', vc.zoho_id, vc.date, vc.credit_number,
          vc.total, vc.balance, vc.status
        from public.zoho_vendor_credits vc where vc.vendor_id = v_vendor_id
        order by activity_date desc nulls last, id desc
        limit 30
      ) x
    ), '[]'::jsonb),
    'generated_at', now()
  ) into v_out
  from public.zoho_bills b
  where b.vendor_id = v_vendor_id;

  return v_out;
end;
$function$;
comment on function "public"."carrier_zoho_financial_dossier"(p_carrier_id text) is 'Unified read model: Zoho vendor position, bills, payments, credits, COD and linked treasury balances.';
CREATE OR REPLACE FUNCTION public.claim_platform_sales_opportunity(p_phone text, p_next timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_followup public.retargeting_followups%rowtype;
  v_inserted boolean := false;
  v_claimed boolean := false;
begin
  if v_uid is null then
    raise exception 'not_authenticated';
  end if;

  if not (
    public.crm_has_permission('sales.view')
    or public.crm_has_permission('crm.view')
  ) then
    raise exception 'not_allowed';
  end if;

  if p_phone is null or btrim(p_phone) = '' then
    raise exception 'phone_required';
  end if;

  if not exists (
    select 1
    from public.v_platform_commercial_routing routing
    where routing.phone = btrim(p_phone)
      and routing.sales_eligible
  ) then
    raise exception 'not_sales_eligible';
  end if;

  insert into public.retargeting_followups (
    phone,
    status,
    sales_stage,
    owner_id,
    next_action_at,
    next_action_type,
    updated_by,
    updated_at
  )
  values (
    btrim(p_phone),
    'needs_followup',
    'new',
    v_uid,
    coalesce(p_next, now()),
    'call',
    v_uid,
    now()
  )
  on conflict (phone) do nothing
  returning *
  into v_followup;

  v_inserted := found;
  v_claimed := v_inserted;

  if not v_inserted then
    select *
    into v_followup
    from public.retargeting_followups
    where phone = btrim(p_phone)
    for update;

    if v_followup.owner_id is not null
       and v_followup.owner_id is distinct from v_uid then
      raise exception 'already_claimed';
    end if;

    update public.retargeting_followups
    set
      owner_id = v_uid,
      status = case
        when owner_id is null then 'needs_followup'
        else status
      end,
      next_action_at = coalesce(next_action_at, p_next, now()),
      next_action_type = coalesce(next_action_type, 'call'),
      updated_by = v_uid,
      updated_at = now()
    where phone = btrim(p_phone)
    returning *
    into v_followup;

    v_claimed := true;
  end if;

  if v_claimed then
    insert into public.crm_activities (
      entity_type,
      entity_ref,
      kind,
      disposition,
      summary,
      occurred_at,
      owner_id,
      created_by
    )
    values (
      'platform_merchant',
      btrim(p_phone),
      'sales_claim',
      'needs_followup',
      'أُضيفت الفرصة إلى قائمة اليوم',
      now(),
      v_uid,
      v_uid
    );
  end if;

  return to_jsonb(v_followup);
end;
$function$;
comment on function "public"."claim_platform_sales_opportunity"(p_phone text, p_next timestamp with time zone) is 'Atomically assigns an eligible platform opportunity to the caller and schedules it in today''s queue.';
CREATE OR REPLACE FUNCTION public.classify_bank_transaction(p_transaction_id uuid, p_classification_type text, p_entity_type text DEFAULT NULL::text, p_entity_id text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS bank_transactions
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_row public.bank_transactions;
begin
  if not public.crm_has_permission('bank.reconcile') then
    raise exception 'not_allowed:bank.reconcile';
  end if;
  if nullif(btrim(coalesce(p_classification_type,'')), '') is null then
    raise exception 'classification_type_required';
  end if;
  if (p_entity_type is null) <> (p_entity_id is null) then
    raise exception 'match_requires_entity_type_and_id';
  end if;

  update public.bank_transaction_matches
     set status='revoked'
   where bank_transaction_id=p_transaction_id and status='approved';

  update public.bank_transactions
     set classification_status=case when p_entity_type is not null then 'matched' else 'classified' end,
         classification_type=btrim(p_classification_type),
         matched_entity_type=nullif(btrim(coalesce(p_entity_type,'')),''),
         matched_entity_id=nullif(btrim(coalesce(p_entity_id,'')),''),
         matched_at=case when p_entity_type is not null then now() else null end,
         classified_by=auth.uid(),
         classification_note=nullif(btrim(coalesce(p_note,'')),''),
         updated_at=now()
   where id=p_transaction_id
   returning * into v_row;
  if not found then raise exception 'bank_transaction_not_found'; end if;

  if p_entity_type is not null then
    insert into public.bank_transaction_matches(
      bank_transaction_id,entity_type,entity_id,amount,confidence,status,source,approved_by,approved_at,note
    ) values (
      p_transaction_id,btrim(p_entity_type),btrim(p_entity_id),greatest(v_row.debit,v_row.credit),1,'approved','manual',auth.uid(),now(),nullif(btrim(coalesce(p_note,'')),'')
    );
  end if;
  return v_row;
end;
$function$;
CREATE OR REPLACE FUNCTION public.clear_bank_transaction_classification(p_transaction_id uuid)
 RETURNS bank_transactions
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_row public.bank_transactions;
begin
  if not public.crm_has_permission('bank.reconcile') then
    raise exception 'not_allowed:bank.reconcile';
  end if;
  update public.bank_transaction_matches set status='revoked'
   where bank_transaction_id=p_transaction_id and status='approved';
  update public.bank_transactions
     set classification_status='unclassified', classification_type=null,
         matched_entity_type=null, matched_entity_id=null, matched_at=null,
         classified_by=null, classification_note=null, updated_at=now()
   where id=p_transaction_id returning * into v_row;
  if not found then raise exception 'bank_transaction_not_found'; end if;
  return v_row;
end;
$function$;
CREATE OR REPLACE FUNCTION public.cod_action_touch_updated()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END;
$function$;
CREATE OR REPLACE FUNCTION public.cod_cash_cycle()
 RETURNS TABLE(carrier_id text, matched_count integer, avg_days numeric, out_d0_15 numeric, out_d16_30 numeric, out_d31_60 numeric, out_over60 numeric, out_count integer, out_total numeric, oldest_days integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH per_awb AS (
    SELECT carrier_id, awb,
      min(upload_date) FILTER (WHERE direction='out') AS out_date,
      min(upload_date) FILTER (WHERE direction='in')  AS in_date,
      sum(amount)      FILTER (WHERE direction='out') AS out_amount
    FROM cod_settlement
    GROUP BY carrier_id, awb
  )
  SELECT
    carrier_id,
    count(*) FILTER (WHERE in_date IS NOT NULL AND out_date IS NOT NULL)::int,
    round(avg(in_date - out_date) FILTER (WHERE in_date IS NOT NULL AND out_date IS NOT NULL)::numeric, 1),
    coalesce(sum(out_amount) FILTER (WHERE in_date IS NULL AND current_date - out_date <= 15), 0)::numeric,
    coalesce(sum(out_amount) FILTER (WHERE in_date IS NULL AND current_date - out_date BETWEEN 16 AND 30), 0)::numeric,
    coalesce(sum(out_amount) FILTER (WHERE in_date IS NULL AND current_date - out_date BETWEEN 31 AND 60), 0)::numeric,
    coalesce(sum(out_amount) FILTER (WHERE in_date IS NULL AND current_date - out_date > 60), 0)::numeric,
    count(*) FILTER (WHERE in_date IS NULL AND out_date IS NOT NULL)::int,
    coalesce(sum(out_amount) FILTER (WHERE in_date IS NULL), 0)::numeric,
    coalesce(max(current_date - out_date) FILTER (WHERE in_date IS NULL), 0)::int
  FROM per_awb
  WHERE out_date IS NOT NULL
  GROUP BY carrier_id;
$function$;
CREATE OR REPLACE FUNCTION public.collection_assignment_candidates()
 RETURNS TABLE(user_id uuid, employee_name text, employee_email text, open_tasks bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if auth.uid() is null or not public.crm_has_permission('collections.assign') then
    raise exception 'not_allowed';
  end if;

  return query
  select
    profile.id,
    profile.name,
    profile.email,
    count(task.id) filter (
      where task.stage in ('todo', 'contacted', 'promised', 'snoozed')
    ) as open_tasks
  from public.profiles profile
  left join public.collection_tasks task on task.assigned_to = profile.id
  where profile.role <> 'admin'
    and coalesce((profile.permissions ->> 'collections.view')::boolean, false)
    and coalesce((profile.permissions ->> 'collections.update_stage')::boolean, false)
  group by profile.id, profile.name, profile.email
  order by count(task.id) filter (
    where task.stage in ('todo', 'contacted', 'promised', 'snoozed')
  ), profile.name nulls last, profile.email;
end;
$function$;
CREATE OR REPLACE FUNCTION public.collection_can_see_all()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ select public.crm_has_permission('collections.view_all') $function$;
CREATE OR REPLACE FUNCTION public.collection_record_promise(p_task_id uuid, p_amount numeric, p_date date, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=(select auth.uid());v_task public.collection_tasks%rowtype;v_debt numeric;
begin
  if v_uid is null or not public.crm_has_permission('collections.record_promise') then raise exception 'not_allowed';end if;
  if p_amount is null or p_amount<=0 or p_date is null then raise exception 'invalid_promise';end if;
  select * into v_task from public.collection_tasks where id=p_task_id for update;
  if not found then raise exception 'task_not_found';end if;
  if v_task.assigned_to is distinct from v_uid and not public.collection_can_see_all() then raise exception 'not_owner';end if;
  select coalesce(collectible_due,0) into v_debt from public.customer_ar where contact_name=v_task.customer_name;
  v_debt:=coalesce(v_debt,v_task.debt_at_creation,0);
  if p_amount>v_debt+0.5 then raise exception 'promise_exceeds_collectible';end if;
  update public.collection_tasks set stage='promised',promise_amount=round(p_amount,2),promise_date=p_date,
    promise_status='pending',promised_at=now(),promise_baseline_debt=round(v_debt,2),
    promise_paid_amount=0,promise_verified_at=now(),honored_amount=null,
    notes=coalesce(nullif(btrim(p_notes),''),notes),updated_at=now()
  where id=p_task_id returning * into v_task;
  return to_jsonb(v_task);
end;
$function$;
CREATE OR REPLACE FUNCTION public.collection_team_performance(p_period date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_start date := date_trunc(
    'month',
    coalesce(p_period, (now() at time zone 'Asia/Riyadh')::date)
  )::date;
  v_end date := (v_start + interval '1 month')::date;
  v_today date := (now() at time zone 'Asia/Riyadh')::date;
  v_result jsonb;
begin
  if (select auth.uid()) is null
     or not public.crm_has_permission('collections.view_all') then
    raise exception 'not_allowed';
  end if;

  with promise_base as (
    select
      t.id,
      t.assigned_to,
      t.customer_name,
      t.promised_at,
      t.promise_date,
      greatest(coalesce(t.promise_amount, 0), 0)::numeric as promise_amount
    from public.collection_tasks t
    where t.promised_at is not null
      and coalesce(t.promise_amount, 0) > 0.5
  ),
  bound_payments as (
    select
      p.zoho_id,
      p.date,
      p.amount,
      chosen.task_id
    from public.zoho_payments p
    join lateral (
      select pb.id as task_id
      from promise_base pb
      where pb.customer_name = p.customer_name
        and pb.promised_at::date <= p.date
      order by pb.promised_at desc, pb.id desc
      limit 1
    ) chosen on true
    where p.amount > 0
      and p.date < v_end
  ),
  promise_progress as (
    select
      pb.id,
      pb.assigned_to,
      pb.promised_at,
      pb.promise_date,
      pb.promise_amount,
      coalesce(sum(bp.amount) filter (where bp.date < v_start), 0)::numeric as prior_paid,
      coalesce(sum(bp.amount) filter (where bp.date >= v_start and bp.date < v_end), 0)::numeric as period_paid,
      coalesce(sum(bp.amount), 0)::numeric as paid_to_period_end
    from promise_base pb
    left join bound_payments bp on bp.task_id = pb.id
    group by pb.id, pb.assigned_to, pb.promised_at, pb.promise_date, pb.promise_amount
  ),
  promise_metrics as (
    select
      pp.assigned_to,
      count(*) filter (
        where pp.promised_at >= v_start
          and pp.promised_at < v_end
      )::int as promises_made,
      count(*) filter (
        where pp.promise_date >= v_start
          and pp.promise_date < v_end
      )::int as promises_due,
      count(*) filter (
        where pp.promise_date >= v_start
          and pp.promise_date < v_end
          and pp.paid_to_period_end >= greatest(pp.promise_amount - 0.5, 0)
      )::int as promises_kept,
      count(*) filter (
        where pp.promise_date >= v_start
          and pp.promise_date < least(v_end, v_today + 1)
          and pp.paid_to_period_end < greatest(pp.promise_amount - 0.5, 0)
      )::int as promises_broken,
      coalesce(sum(
        least(
          pp.period_paid,
          greatest(pp.promise_amount - pp.prior_paid, 0)
        )
      ), 0)::numeric as verified_collected,
      coalesce(sum(
        case
          when pp.period_paid > 0
            or (pp.promise_date >= v_start and pp.promise_date < v_end)
          then greatest(pp.promise_amount - pp.prior_paid, 0)
          else 0
        end
      ), 0)::numeric as eligible_promise_amount
    from promise_progress pp
    group by pp.assigned_to
  ),
  open_portfolio as (
    select
      x.assigned_to,
      count(*)::int as open_tasks,
      coalesce(sum(coalesce(ar.total_due, x.debt_at_creation)), 0)::numeric as open_debt,
      round(avg(greatest(v_today - x.created_at::date, 0)))::int as avg_open_age_days,
      count(*) filter (
        where x.stage = 'promised'
          and x.promise_date < v_today
      )::int as overdue_promises
    from (
      select distinct on (t.assigned_to, t.customer_name)
        t.assigned_to,
        t.customer_name,
        t.stage,
        t.promise_date,
        t.debt_at_creation,
        t.created_at,
        t.updated_at
      from public.collection_tasks t
      where t.stage in ('todo', 'contacted', 'promised', 'snoozed')
      order by t.assigned_to, t.customer_name, t.updated_at desc
    ) x
    left join public.customer_ar ar on ar.contact_name = x.customer_name
    group by x.assigned_to
  ),
  task_metrics as (
    select
      t.assigned_to,
      count(*) filter (
        where t.done_at >= v_start
          and t.done_at < v_end
      )::int as completed_in_period
    from public.collection_tasks t
    group by t.assigned_to
  ),
  collector_pool as (
    select p.id as collector_id, p.name as collector_name, false as is_unassigned
    from public.profiles p
    where p.role <> 'admin'
      and coalesce((p.permissions ->> 'collections.update_stage')::boolean, false)
    union
    select distinct p.id, p.name, false
    from public.collection_tasks t
    join public.profiles p on p.id = t.assigned_to
    union
    select null::uuid, 'غير مسند'::text, true
    where exists (
      select 1 from public.collection_tasks t
      where t.assigned_to is null
    )
  ),
  rows as (
    select
      cp.collector_id,
      cp.collector_name,
      cp.is_unassigned,
      coalesce(op.open_tasks, 0)::int as open_tasks,
      round(coalesce(op.open_debt, 0), 2) as open_debt,
      coalesce(op.avg_open_age_days, 0)::int as avg_open_age_days,
      coalesce(tm.completed_in_period, 0)::int as completed_in_period,
      coalesce(pm.promises_made, 0)::int as promises_made,
      coalesce(pm.promises_due, 0)::int as promises_due,
      coalesce(pm.promises_kept, 0)::int as promises_kept,
      coalesce(pm.promises_broken, 0)::int as promises_broken,
      coalesce(op.overdue_promises, 0)::int as overdue_promises,
      round(coalesce(pm.verified_collected, 0), 2) as verified_collected,
      case
        when coalesce(pm.eligible_promise_amount, 0) <= 0.5 then 0
        else round(
          least(
            100,
            (pm.verified_collected / nullif(pm.eligible_promise_amount, 0)) * 100
          ),
          1
        )
      end as promise_fulfillment_pct
    from collector_pool cp
    left join open_portfolio op
      on op.assigned_to is not distinct from cp.collector_id
    left join task_metrics tm
      on tm.assigned_to is not distinct from cp.collector_id
    left join promise_metrics pm
      on pm.assigned_to is not distinct from cp.collector_id
  ),
  summary as (
    select
      coalesce(sum(r.open_tasks), 0)::int as open_tasks,
      round(coalesce(sum(r.open_debt), 0), 2) as open_debt,
      coalesce(sum(r.completed_in_period), 0)::int as completed_in_period,
      coalesce(sum(r.promises_made), 0)::int as promises_made,
      coalesce(sum(r.promises_due), 0)::int as promises_due,
      coalesce(sum(r.promises_kept), 0)::int as promises_kept,
      coalesce(sum(r.promises_broken), 0)::int as promises_broken,
      coalesce(sum(r.overdue_promises), 0)::int as overdue_promises,
      round(coalesce(sum(r.verified_collected), 0), 2) as verified_collected,
      case
        when coalesce(sum(pm.eligible_promise_amount), 0) <= 0.5 then 0
        else round(
          least(
            100,
            (
              coalesce(sum(pm.verified_collected), 0)
              / nullif(sum(pm.eligible_promise_amount), 0)
            ) * 100
          ),
          1
        )
      end as promise_fulfillment_pct
    from rows r
    left join promise_metrics pm
      on pm.assigned_to is not distinct from r.collector_id
  )
  select jsonb_build_object(
    'period', to_char(v_start, 'YYYY-MM'),
    'period_start', v_start,
    'period_end', v_end - 1,
    'generated_at', now(),
    'summary', (
      select jsonb_build_object(
        'open_tasks', s.open_tasks,
        'open_debt', s.open_debt,
        'completed_in_period', s.completed_in_period,
        'promises_made', s.promises_made,
        'promises_due', s.promises_due,
        'promises_kept', s.promises_kept,
        'promises_broken', s.promises_broken,
        'overdue_promises', s.overdue_promises,
        'verified_collected', s.verified_collected,
        'promise_fulfillment_pct', s.promise_fulfillment_pct
      )
      from summary s
    ),
    'rows', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'collector_id', r.collector_id,
          'collector_name', r.collector_name,
          'is_unassigned', r.is_unassigned,
          'open_tasks', r.open_tasks,
          'open_debt', r.open_debt,
          'avg_open_age_days', r.avg_open_age_days,
          'completed_in_period', r.completed_in_period,
          'promises_made', r.promises_made,
          'promises_due', r.promises_due,
          'promises_kept', r.promises_kept,
          'promises_broken', r.promises_broken,
          'overdue_promises', r.overdue_promises,
          'verified_collected', r.verified_collected,
          'promise_fulfillment_pct', r.promise_fulfillment_pct
        )
        order by r.is_unassigned, r.verified_collected desc, r.collector_name
      )
      from rows r
    ), '[]'::jsonb)
  )
  into v_result;

  return v_result;
end;
$function$;
CREATE OR REPLACE FUNCTION public.collection_work_readiness_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_result jsonb;
begin
  if v_uid is null then
    raise exception 'not_authenticated';
  end if;

  if not (
    public.crm_has_permission('overview.view')
    or public.crm_has_permission('system.manage_employees')
  ) then
    raise exception 'not_allowed';
  end if;

  with latest_snapshot as (
    select m.snapshot_id
    from public.merchants m
    order by m.uploaded_at desc
    limit 1
  ), merchant_context as (
    select
      link.customer_name,
      bool_or(coalesce(merchant.billing_type, '') = 'دفع مسبق') as prepaid
    from public.customer_merchant_links link
    join public.merchants merchant
      on merchant.store_id = link.store_id
     and merchant.snapshot_id = (select snapshot_id from latest_snapshot)
    group by link.customer_name
  ), debtors as (
    select
      ar.contact_name as customer_name,
      ar.collectible_due as debt,
      greatest(coalesce(age.days_outstanding, 0), 0) as days_outstanding,
      coalesce(context.prepaid, false) as prepaid
    from public.customer_ar ar
    left join merchant_context context on context.customer_name = ar.contact_name
    left join lateral (
      select max(line.age_days) as days_outstanding
      from public.customer_collectible_lines line
      where line.contact_name = ar.contact_name
        and line.collectible_amount > 0.005
    ) age on true
    where ar.collectible_due > 0.5
  ), candidates as (
    select debtor.*
    from debtors debtor
    where debtor.prepaid
       or debtor.debt > 10000
       or debtor.days_outstanding > 30
  ), open_tasks as (
    select
      task.customer_name,
      bool_or(task.assigned_to is not null) as has_assignee
    from public.collection_tasks task
    where task.stage in ('todo', 'contacted', 'promised', 'snoozed')
      and task.done_at is null
    group by task.customer_name
  ), totals as (
    select
      (select count(*) from debtors)::int as debtors,
      coalesce((select sum(debt) from debtors), 0)::numeric as total_debt,
      (select count(*) from candidates)::int as candidates,
      coalesce((select sum(debt) from candidates), 0)::numeric as candidate_debt,
      (select count(*) from candidates candidate
        where exists (
          select 1 from open_tasks task
          where task.customer_name = candidate.customer_name
        ))::int as covered,
      (select count(*) from candidates candidate
        where not exists (
          select 1 from open_tasks task
          where task.customer_name = candidate.customer_name
        ))::int as missing_tasks,
      coalesce((select sum(candidate.debt) from candidates candidate
        where not exists (
          select 1 from open_tasks task
          where task.customer_name = candidate.customer_name
        )), 0)::numeric as missing_task_debt,
      (select count(*) from candidates candidate
        join open_tasks task on task.customer_name = candidate.customer_name
        where task.has_assignee)::int as assigned,
      (select count(*) from candidates candidate
        join open_tasks task on task.customer_name = candidate.customer_name
        where not task.has_assignee)::int as unassigned,
      coalesce((select sum(candidate.debt) from candidates candidate
        join open_tasks task on task.customer_name = candidate.customer_name
        where not task.has_assignee), 0)::numeric as unassigned_debt
  )
  select jsonb_build_object(
    'checked_at', now(),
    'debtors', totals.debtors,
    'total_debt', round(totals.total_debt, 2),
    'collection_candidates', totals.candidates,
    'candidate_debt', round(totals.candidate_debt, 2),
    'covered_collection_tasks', totals.covered,
    'missing_collection_tasks', totals.missing_tasks,
    'missing_collection_debt', round(totals.missing_task_debt, 2),
    'assigned_collection_customers', totals.assigned,
    'unassigned_collection_customers', totals.unassigned,
    'unassigned_collection_debt', round(totals.unassigned_debt, 2)
  )
  into v_result
  from totals;

  return v_result;
end;
$function$;
comment on function "public"."collection_work_readiness_snapshot"() is 'Read-only coverage of collectible customers by open and explicitly assigned collection tasks.';
CREATE OR REPLACE FUNCTION public.company_operating_pulse()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_sales_visible boolean;
  v_sales_all boolean;
  v_collections_visible boolean;
  v_collections_all boolean;
  v_support_visible boolean;
  v_sales jsonb;
  v_collections jsonb;
  v_support jsonb;
begin
  if v_uid is null then
    raise exception 'not_authenticated';
  end if;

  if not public.crm_has_permission('overview.view') then
    raise exception 'not_allowed';
  end if;

  v_sales_visible := public.crm_has_permission('sales.view')
    or public.crm_has_permission('crm.view');
  v_sales_all := v_sales_visible and public.crm_can_see_all();
  v_collections_visible := public.crm_has_permission('collections.view');
  v_collections_all := v_collections_visible
    and public.crm_has_permission('collections.view_all');
  v_support_visible := public.crm_has_permission('support.view');

  if v_sales_visible then
    with
    routing as materialized (
      select
        source.phone,
        source.sales_eligible,
        source.financial_hold,
        source.hot_live_new,
        source.hot_live_topped,
        source.recent_stop,
        source.wallet_stranded,
        source.live_inactive,
        source.direct_live,
        source.total_shipments
      from public.v_platform_commercial_routing source
    ),
    opportunity_pool as (
      select count(*)::integer as total
      from routing
      left join public.retargeting_followups followup
        on followup.phone = routing.phone
      where followup.phone is null
        and routing.sales_eligible
        and (
          routing.hot_live_new
          or routing.hot_live_topped
          or routing.recent_stop
          or routing.wallet_stranded
          or routing.live_inactive
          or (routing.direct_live and routing.total_shipments = 0)
        )
    ),
    followups as (
      select
        followup.phone,
        followup.owner_id,
        followup.next_action_at,
        followup.last_touch_at,
        routing.financial_hold
      from public.retargeting_followups followup
      left join routing
        on routing.phone = followup.phone
      where coalesce(followup.sales_stage, 'new')
        not in ('won', 'lost', 'disqualified')
        and (v_sales_all or followup.owner_id = v_uid)
    ),
    leads as (
      select
        lead.id,
        lead.owner_id,
        lead.lead_kind,
        lead.status,
        lead.next_action_at,
        lead.first_attempt_at,
        lead.first_response_due_at
      from public.crm_leads lead
      where lead.status not in ('converted', 'activated', 'lost', 'existing_customer')
        and (
          lead.lead_kind = 'inbound'
          or lead.next_action_at is not null
          or lead.first_attempt_at is not null
          or lead.last_touch_at is not null
        )
        and (v_sales_all or lead.owner_id = v_uid)
    ),
    metrics as (
      select
        (select total from opportunity_pool) as opportunity_total,
        (select count(*)::integer from followups) as followup_total,
        (select count(*)::integer from leads) as lead_total,
        (select count(*)::integer from followups
          where next_action_at <= now() + interval '12 hours') as followup_due,
        (select count(*)::integer from leads
          where next_action_at <= now() + interval '12 hours'
             or (lead_kind = 'inbound' and status = 'new')) as lead_due,
        (select count(*)::integer from followups
          where next_action_at < now()) as followup_overdue,
        (select count(*)::integer from leads
          where next_action_at < now()) as lead_overdue,
        (select count(*)::integer from leads
          where lead_kind = 'inbound'
            and first_attempt_at is null
            and first_response_due_at < now()) as inbound_sla_breached,
        (select count(*)::integer from public.crm_leads lead
          where v_sales_all
            and lead.lead_kind = 'inbound'
            and lead.owner_id is null
            and lead.status not in ('converted', 'activated', 'lost', 'existing_customer'))
          as inbound_unassigned,
        (select count(*)::integer from followups
          where last_touch_at is not null and next_action_at is null)
          +
        (select count(*)::integer from leads
          where first_attempt_at is not null and next_action_at is null)
          as without_next_action,
        (select count(*)::integer from followups where financial_hold)
          as financial_hold_conflicts
    )
    select jsonb_build_object(
      'visible', true,
      'scope', case when v_sales_all then 'team' else 'mine' end,
      'today', least(opportunity_total, 12) + followup_due + lead_due,
      'backlog', opportunity_total + followup_total + lead_total,
      'overdue', followup_overdue + lead_overdue + inbound_sla_breached,
      'unassigned', inbound_unassigned,
      'without_next_action', without_next_action,
      'financial_hold_conflicts', financial_hold_conflicts,
      'platform_opportunities', opportunity_total,
      'followups', followup_total,
      'leads', lead_total
    ) into v_sales
    from metrics;
  end if;

  if v_collections_visible then
    with ranked as (
      select
        task.*,
        row_number() over (
          partition by task.customer_name
          order by case task.stage
            when 'promised' then 4
            when 'contacted' then 3
            when 'snoozed' then 2
            else 1
          end desc, task.created_at desc
        ) as customer_rank
      from public.collection_tasks task
      where task.stage in ('todo', 'contacted', 'promised', 'snoozed')
        and (v_collections_all or task.assigned_to = v_uid)
    ),
    active as (
      select ranked.*
      from ranked
      where customer_rank = 1
    ),
    metrics as (
      select
        count(*)::integer as open_count,
        coalesce(round(sum(coalesce(ar.total_due, active.debt_at_creation, 0))::numeric, 2), 0)
          as open_amount,
        count(*) filter (
          where active.stage = 'promised'
            and active.promise_date < (now() at time zone 'Asia/Riyadh')::date
        )::integer as promise_overdue,
        count(*) filter (
          where active.stage = 'promised'
            and active.promise_date = (now() at time zone 'Asia/Riyadh')::date
        )::integer as promise_today,
        count(*) filter (
          where active.stage = 'snoozed'
            and active.snooze_until <= now()
        )::integer as snooze_expired,
        count(*) filter (where active.assigned_to is null)::integer as unassigned
      from active
      left join public.customer_ar ar
        on ar.contact_name = active.customer_name
    )
    select jsonb_build_object(
      'visible', true,
      'scope', case when v_collections_all then 'team' else 'mine' end,
      'today', least(open_count, 25),
      'backlog', greatest(open_count - 25, 0),
      'open', open_count,
      'open_amount', open_amount,
      'promise_overdue', promise_overdue,
      'promise_today', promise_today,
      'snooze_expired', snooze_expired,
      'unassigned', unassigned
    ) into v_collections
    from metrics;
  end if;

  if v_support_visible then
    with active as (
      select ticket.*
      from public.support_tickets ticket
      where ticket.status in ('open', 'in_progress', 'waiting_customer')
    ),
    metrics as (
      select
        count(*)::integer as open_count,
        count(*) filter (
          where priority = 'urgent'
             or assigned_to is null
             or next_followup_at is null
             or next_followup_at <= now() + interval '24 hours'
        )::integer as today_count,
        count(*) filter (where next_followup_at < now())::integer as overdue,
        count(*) filter (where assigned_to is null)::integer as unassigned,
        count(*) filter (where next_followup_at is null)::integer as without_followup,
        count(*) filter (where priority = 'urgent')::integer as urgent,
        count(*) filter (where created_at < now() - interval '3 days')::integer as stale_3d
      from active
    )
    select jsonb_build_object(
      'visible', true,
      'scope', 'team',
      'today', today_count,
      'backlog', greatest(open_count - today_count, 0),
      'open', open_count,
      'overdue', overdue,
      'unassigned', unassigned,
      'without_followup', without_followup,
      'urgent', urgent,
      'stale_3d', stale_3d
    ) into v_support
    from metrics;
  end if;

  return jsonb_build_object(
    'generated_at', now(),
    'sales', v_sales,
    'collections', v_collections,
    'support', v_support
  );
end;
$function$;
comment on function "public"."company_operating_pulse"() is 'Read-only executive pulse over the existing sales, collections and support work sources; creates no parallel task system.';
CREATE OR REPLACE FUNCTION public.configure_integration_health_agent(p_enabled boolean, p_interval_minutes integer, p_zoho_minutes integer, p_hatif_minutes integer, p_platform_hours integer)
 RETURNS work_agents
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'cron', 'pg_temp'
AS $function$
declare
  a public.work_agents;
  j bigint;
  expr text;
  cadence text;
begin
  if not exists (
    select 1 from public.profiles p
    where p.id = (select auth.uid())
      and (p.role = 'admin' or coalesce((p.permissions ->> 'agents.manage')::boolean, false))
  ) then
    raise exception 'forbidden';
  end if;

  if p_interval_minutes not in (15, 30, 60, 360)
     or p_zoho_minutes not between 15 and 1440
     or p_hatif_minutes not between 5 and 1440
     or p_platform_hours not between 1 and 720 then
    raise exception 'invalid_agent_configuration';
  end if;

  expr := case p_interval_minutes
    when 15 then '5,20,35,50 * * * *'
    when 30 then '5,35 * * * *'
    when 60 then '5 * * * *'
    else '5 */6 * * *'
  end;
  cadence := case p_interval_minutes
    when 60 then 'كل ساعة'
    when 360 then 'كل 6 ساعات'
    else format('كل %s دقيقة', p_interval_minutes)
  end;

  update public.work_agents
  set status = case when p_enabled then 'active' else 'paused' end,
      cadence_label = cadence,
      cron_expression = expr,
      config = coalesce(config, '{}'::jsonb) || jsonb_build_object(
        'interval_minutes', p_interval_minutes,
        'zoho_max_age_minutes', p_zoho_minutes,
        'hatif_max_age_minutes', p_hatif_minutes,
        'platform_max_age_hours', p_platform_hours,
        'auto_repair', false
      ),
      next_run_at = case when p_enabled then now() + make_interval(mins => p_interval_minutes) else null end,
      updated_at = now()
  where agent_key = 'integration_health'
  returning * into a;

  select jobid into j from cron.job where jobname = 'work-agent-integration-health';
  if j is not null then
    perform cron.alter_job(j, schedule => expr, active => p_enabled);
  end if;
  return a;
end
$function$;
CREATE OR REPLACE FUNCTION public.configure_management_report_agent(p_enabled boolean, p_hour integer, p_minute integer)
 RETURNS work_agents
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'cron', 'pg_temp'
AS $function$
declare a public.work_agents;j bigint;expr text;utc_hour integer;next_local timestamp;
begin
  if not exists(select 1 from profiles p where p.id=(select auth.uid()) and (p.role='admin' or coalesce((p.permissions->>'agents.manage')::boolean,false))) then raise exception 'forbidden';end if;
  if p_hour not between 0 and 23 or p_minute not between 0 and 59 then raise exception 'invalid_agent_configuration';end if;
  utc_hour:=p_hour-3;if utc_hour<0 then utc_hour:=utc_hour+24;end if;expr:=format('%s %s * * *',p_minute,utc_hour);
  next_local:=date_trunc('day',now() at time zone 'Asia/Riyadh')+make_interval(hours=>p_hour,mins=>p_minute);if next_local<=now() at time zone 'Asia/Riyadh' then next_local:=next_local+interval '1 day';end if;
  update work_agents set status=case when p_enabled then 'active' else 'paused' end,cadence_label=format('يوميًا، %s:%s بتوقيت السعودية',lpad((case when p_hour%12=0 then 12 else p_hour%12 end)::text,2,'0'),lpad(p_minute::text,2,'0')),cron_expression=expr,
    config=coalesce(config,'{}')||jsonb_build_object('hour',p_hour,'minute',p_minute,'delivery','in_app'),next_run_at=case when p_enabled then next_local at time zone 'Asia/Riyadh' else null end,updated_at=now()
  where agent_key='management_daily_report' returning * into a;
  select jobid into j from cron.job where jobname='work-agent-management-daily';if j is not null then perform cron.alter_job(j,schedule=>expr,active=>p_enabled);end if;return a;
end $function$;
CREATE OR REPLACE FUNCTION public.configure_overdue_sadad_agent(p_enabled boolean, p_day_of_week integer, p_hour integer, p_minute integer, p_min_days integer, p_min_balance numeric, p_max_recipients integer)
 RETURNS work_agents
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'cron', 'pg_temp'
AS $function$
declare
  a public.work_agents;
  j bigint;
  utc_hour integer;
  expr text;
  next_local timestamp;
begin
  if not exists (
    select 1 from public.profiles p where p.id=(select auth.uid())
      and (p.role='admin' or coalesce((p.permissions->>'agents.manage')::boolean,false))
  ) then raise exception 'forbidden'; end if;
  if p_day_of_week not between 0 and 6 or p_hour not between 0 and 23 or p_minute not between 0 and 59
     or p_min_days not between 1 and 3650 or p_min_balance < 0 or p_max_recipients not between 1 and 2000
  then raise exception 'invalid_agent_configuration'; end if;

  utc_hour := p_hour - 3;
  if utc_hour < 0 then utc_hour := utc_hour + 24; p_day_of_week := (p_day_of_week + 6) % 7; end if;
  expr := format('%s %s * * %s',p_minute,utc_hour,p_day_of_week);
  next_local := date_trunc('day', now() at time zone 'Asia/Riyadh')
    + ((p_day_of_week - extract(dow from now() at time zone 'Asia/Riyadh')::integer + 7) % 7) * interval '1 day'
    + make_interval(hours=>p_hour,mins=>p_minute);
  if next_local <= now() at time zone 'Asia/Riyadh' then next_local := next_local + interval '7 days'; end if;

  update public.work_agents set
    status=case when p_enabled then 'active' else 'paused' end,
    cadence_label=format('كل %s، %s:%s بتوقيت السعودية',
      (array['أحد','اثنين','ثلاثاء','أربعاء','خميس','جمعة','سبت'])[p_day_of_week+1],
      lpad(((case when p_hour%12=0 then 12 else p_hour%12 end))::text,2,'0'),lpad(p_minute::text,2,'0')),
    cron_expression=expr,
    config=coalesce(config,'{}'::jsonb)||jsonb_build_object('day_of_week',p_day_of_week,'hour',p_hour,'minute',p_minute,
      'min_overdue_days',p_min_days,'min_balance',p_min_balance,'max_recipients',p_max_recipients,
      'template_name','sadad','template_language','ar','one_message_per_phone',true,'exclude_opening_balances',true),
    next_run_at=case when p_enabled then next_local at time zone 'Asia/Riyadh' else null end,
    updated_at=now()
  where agent_key='overdue_sadad' returning * into a;

  select jobid into j from cron.job where jobname='work-agent-overdue-sadad';
  if j is not null then perform cron.alter_job(j,schedule=>expr,active=>p_enabled); end if;
  return a;
end $function$;
CREATE OR REPLACE FUNCTION public.configure_zatca_work_agent(p_enabled boolean, p_hour integer, p_minute integer, p_max_invoices integer)
 RETURNS work_agents
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'cron', 'pg_temp'
AS $function$
declare a public.work_agents; j bigint; expr text; utc_hour integer; next_local timestamp;
begin
  if not exists(select 1 from public.profiles p where p.id=(select auth.uid())
    and (p.role='admin' or coalesce((p.permissions->>'agents.manage')::boolean,false))) then raise exception 'forbidden'; end if;
  if p_hour not between 0 and 23 or p_minute not between 0 and 59 or p_max_invoices not between 1 and 500 then
    raise exception 'invalid_agent_configuration';
  end if;
  utc_hour:=p_hour-3; if utc_hour<0 then utc_hour:=utc_hour+24; end if;
  expr:=format('%s %s * * *',p_minute,utc_hour);
  next_local:=date_trunc('day',now() at time zone 'Asia/Riyadh')+make_interval(hours=>p_hour,mins=>p_minute);
  if next_local<=now() at time zone 'Asia/Riyadh' then next_local:=next_local+interval '1 day'; end if;
  update public.work_agents set status=case when p_enabled then 'active' else 'paused' end,
    cadence_label=format('يوميًا، %s:%s بتوقيت السعودية',lpad((case when p_hour%12=0 then 12 else p_hour%12 end)::text,2,'0'),lpad(p_minute::text,2,'0')),
    cron_expression=expr, config=coalesce(config,'{}'::jsonb)||jsonb_build_object('hour',p_hour,'minute',p_minute,'max_invoices',p_max_invoices,'exclude_opening_balances',true,'live_check_before_push',true),
    next_run_at=case when p_enabled then next_local at time zone 'Asia/Riyadh' else null end,updated_at=now()
  where agent_key='zatca_nightly' returning * into a;
  select jobid into j from cron.job where jobname='zatca-auto-push-2345-riyadh';
  if j is not null then perform cron.alter_job(j,schedule=>expr,active=>p_enabled); end if;
  return a;
end $function$;
CREATE OR REPLACE FUNCTION public.credit_stop_list(p_limit numeric DEFAULT 10000, p_overdue integer DEFAULT 30)
 RETURNS json
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with latest_merch as (select snapshot_id from merchants order by uploaded_at desc limit 1),
  merch as (
    select store_id,store_name,phone,billing_type,status,wallet_balance,normalize_arabic_name(store_name) norm
    from merchants where snapshot_id=(select snapshot_id from latest_merch)
  ), links as (select customer_name,store_id from customer_merchant_links where store_id is not null),
  line_agg as (
    select contact_name,
      coalesce(sum(collectible_amount) filter(where age_days>p_overdue),0) overdue_amount,
      max(age_days) oldest_days,
      count(*) filter(where line_kind='invoice' and collectible_amount>0.5)::int inv_cnt
    from customer_collectible_lines where collectible_amount>0.005 group by contact_name
  ), per_cust as (
    select ar.contact_name customer_name,round(ar.collectible_due,2) total_open,
      round(coalesce(a.overdue_amount,0),2) overdue_amount,coalesce(a.oldest_days,0) oldest_days,coalesce(a.inv_cnt,0) inv_cnt
    from customer_ar ar left join line_agg a on a.contact_name=ar.contact_name where ar.collectible_due>0.5
  ), breached as (select * from per_cust where total_open>p_limit or oldest_days>p_overdue),
  joined as (
    select distinct on (b.customer_name) b.customer_name,b.total_open,b.overdue_amount,b.oldest_days,b.inv_cnt,
      m.store_id,m.store_name,m.phone,m.billing_type,m.status,round(coalesce(m.wallet_balance,0),2) wallet,
      (m.status='نشط') active,
      case when b.total_open>p_limit and b.oldest_days>p_overdue then 'both'
           when b.total_open>p_limit then 'over_limit' else 'overdue' end reason
    from breached b left join links l on l.customer_name=b.customer_name
    left join merch m on m.store_id=l.store_id or (l.store_id is null and m.norm=normalize_arabic_name(b.customer_name))
    order by b.customer_name,(l.store_id is not null) desc
  ), filtered as (select * from joined where coalesce(billing_type,'')<>'دفع مسبق')
  select json_build_object(
    'limit',p_limit,'overdue_days',p_overdue,
    'summary',(select json_build_object('count',count(*),'total',round(coalesce(sum(total_open),0),2),
      'active_count',count(*) filter(where active),'active_total',round(coalesce(sum(total_open) filter(where active),0),2)) from filtered),
    'rows',(select coalesce(json_agg(json_build_object(
      'customer_name',customer_name,'store_name',store_name,'store_id',store_id,'phone',phone,
      'billing_type',billing_type,'status',status,'active',active,'wallet',wallet,
      'total_open',total_open,'overdue_amount',overdue_amount,'oldest_days',oldest_days,
      'inv_cnt',inv_cnt,'reason',reason
    ) order by active desc,total_open desc),'[]') from filtered)
  );
$function$;
CREATE OR REPLACE FUNCTION public.crm_board_stats()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
with
  params as (
    select now() - interval '7 days' as week_ago
  ),
  lead_by_owner as (
    select
      l.owner_id,
      count(*)::bigint as assigned_leads,
      count(*) filter (where l.status not in ('converted', 'lost', 'existing_customer'))::bigint as open_leads,
      count(*) filter (where l.matched_store_id is not null or l.status = 'existing_customer')::bigint as existing_customers
    from public.crm_leads l
    group by l.owner_id
  ),
  activity_by_owner as (
    select a.owner_id, count(*)::bigint as touches_this_week
    from public.crm_activities a, params p
    where a.occurred_at >= p.week_ago
      and a.kind in ('call', 'whatsapp', 'note', 'visit', 'meeting')
    group by a.owner_id
  ),
  task_by_owner as (
    select
      t.assigned_to as owner_id,
      count(*) filter (where t.status = 'open')::bigint as tasks_open,
      count(*) filter (
        where t.status = 'done'
          and t.completed_at >= (select week_ago from params)
      )::bigint as tasks_done_this_week
    from public.crm_tasks t
    group by t.assigned_to
  ),
  deal_by_owner as (
    select
      d.owner_id,
      count(*) filter (where d.status = 'open')::bigint as deals_open,
      count(*) filter (where d.status = 'won')::bigint as deals_won,
      coalesce(sum(d.value) filter (where d.status = 'won'), 0)::numeric as won_value
    from public.crm_deals d
    group by d.owner_id
  ),
  owner_ids as (
    select owner_id from lead_by_owner
    union select owner_id from activity_by_owner
    union select owner_id from task_by_owner
    union select owner_id from deal_by_owner
  ),
  owner_rows as (
    select
      o.owner_id,
      coalesce(l.assigned_leads, 0) as assigned_leads,
      coalesce(l.open_leads, 0) as open_leads,
      coalesce(l.existing_customers, 0) as existing_customers,
      coalesce(a.touches_this_week, 0) as touches_this_week,
      coalesce(t.tasks_open, 0) as tasks_open,
      coalesce(t.tasks_done_this_week, 0) as tasks_done_this_week,
      coalesce(d.deals_open, 0) as deals_open,
      coalesce(d.deals_won, 0) as deals_won,
      coalesce(d.won_value, 0) as won_value
    from owner_ids o
    left join lead_by_owner l on l.owner_id is not distinct from o.owner_id
    left join activity_by_owner a on a.owner_id is not distinct from o.owner_id
    left join task_by_owner t on t.owner_id is not distinct from o.owner_id
    left join deal_by_owner d on d.owner_id is not distinct from o.owner_id
  ),
  lead_total as (
    select
      count(*)::bigint as total,
      count(*) filter (where status not in ('converted', 'lost', 'existing_customer'))::bigint as open_count,
      count(*) filter (where matched_store_id is not null or status = 'existing_customer')::bigint as existing_count,
      count(*) filter (where duplicate_count > 1)::bigint as duplicate_count
    from public.crm_leads
  ),
  activity_total as (
    select count(*)::bigint as touches
    from public.crm_activities a, params p
    where a.occurred_at >= p.week_ago
      and a.kind in ('call', 'whatsapp', 'note', 'visit', 'meeting')
  ),
  promise_total as (
    select
      count(*) filter (where promise_status = 'open')::bigint as open_count,
      count(*) filter (where promise_status = 'kept')::bigint as kept_count,
      count(*) filter (where promise_status = 'broken')::bigint as broken_count
    from public.crm_activities
    where kind = 'promise'
  ),
  deal_total as (
    select
      count(*) filter (where status = 'open')::bigint as open_count,
      coalesce(sum(value) filter (where status = 'open'), 0)::numeric as pipeline_value,
      coalesce(sum(value) filter (where status = 'won'), 0)::numeric as won_value
    from public.crm_deals
  )
select jsonb_build_object(
  'touchesThisWeek', (select touches from activity_total),
  'promisesOpen', (select open_count from promise_total),
  'promisesKept', (select kept_count from promise_total),
  'promisesBroken', (select broken_count from promise_total),
  'dealsOpenCount', (select open_count from deal_total),
  'pipelineValue', (select pipeline_value from deal_total),
  'wonValue', (select won_value from deal_total),
  'leadsTotal', (select total from lead_total),
  'leadsOpen', (select open_count from lead_total),
  'leadsExistingCustomers', (select existing_count from lead_total),
  'leadsDuplicateRows', (select duplicate_count from lead_total),
  'byOwner', coalesce((
    select jsonb_agg(
      jsonb_build_object(
        'ownerId', owner_id,
        'assignedLeads', assigned_leads,
        'openLeads', open_leads,
        'existingCustomers', existing_customers,
        'touchesThisWeek', touches_this_week,
        'tasksOpen', tasks_open,
        'tasksDoneThisWeek', tasks_done_this_week,
        'dealsOpen', deals_open,
        'dealsWon', deals_won,
        'wonValue', won_value
      ) order by touches_this_week desc, open_leads desc
    )
    from owner_rows
  ), '[]'::jsonb)
);
$function$;
CREATE OR REPLACE FUNCTION public.crm_can_see_all()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from profiles
    where id = auth.uid()
      and (role = 'admin' or coalesce((permissions->>'crm.view_all')::boolean, false))
  );
$function$;
CREATE OR REPLACE FUNCTION public.crm_close_lead(p_lead_id uuid, p_won boolean, p_reason text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_customer_name text DEFAULT NULL::text, p_store_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_lead public.crm_leads%rowtype;
  v_stage_id uuid;
  v_status text := case when p_won then 'converted' else 'lost' end;
begin
  if v_uid is null or not (
    case when p_won then public.crm_has_permission('crm.convert_lead')
         else public.crm_has_permission('crm.change_status') end
  ) then raise exception 'not_allowed'; end if;
  if not p_won and nullif(btrim(coalesce(p_reason,'')), '') is null then
    raise exception 'loss_reason_required';
  end if;

  select * into v_lead from public.crm_leads where id = p_lead_id for update;
  if not found then raise exception 'lead_not_found'; end if;
  if v_lead.owner_id is distinct from v_uid and not public.crm_can_see_all() then
    raise exception 'not_allowed';
  end if;
  if v_lead.status = v_status then return to_jsonb(v_lead); end if;
  if v_lead.status in ('converted','activated','lost') then raise exception 'lead_already_closed'; end if;

  update public.crm_leads set
    status = v_status,
    next_action_at = null,
    loss_reason = case when p_won then null else btrim(p_reason) end,
    loss_notes = case when p_won then null else nullif(btrim(coalesce(p_notes,'')), '') end,
    converted_at = case when p_won then now() else converted_at end,
    won_at = case when p_won then now() else won_at end,
    converted_customer = case when p_won then coalesce(nullif(btrim(coalesce(p_customer_name,'')), ''), name) else converted_customer end,
    converted_store_id = case when p_won then coalesce(p_store_id, matched_store_id) else converted_store_id end,
    converted_by = case when p_won then v_uid else converted_by end,
    status_changed_at = now(),
    updated_at = now()
  where id = p_lead_id
  returning * into v_lead;

  select id into v_stage_id from public.crm_stages where key = case when p_won then 'won' else 'lost' end;

  update public.crm_deals set
    stage_id = v_stage_id,
    status = case when p_won then 'won' else 'lost' end,
    lost_reason = case when p_won then null else btrim(p_reason) end,
    closed_at = now(),
    updated_at = now()
  where entity_type = 'lead' and entity_ref = p_lead_id::text and status = 'open';

  if not found then
    insert into public.crm_deals(
      title, entity_type, entity_ref, stage_id, value, owner_id, status,
      lost_reason, closed_at, created_by
    ) values (
      'صفقة — ' || v_lead.name, 'lead', p_lead_id::text, v_stage_id, 0,
      coalesce(v_lead.owner_id, v_uid), case when p_won then 'won' else 'lost' end,
      case when p_won then null else btrim(p_reason) end, now(), v_uid
    );
  end if;

  update public.crm_tasks
  set status = 'cancelled', updated_at = now()
  where entity_type = 'lead' and entity_ref = p_lead_id::text and status = 'open';

  insert into public.crm_activities(
    entity_type, entity_ref, kind, disposition, summary, body, occurred_at, owner_id, created_by
  ) values (
    'lead', p_lead_id::text, case when p_won then 'conversion' else 'lost' end,
    case when p_won then 'won' else p_reason end,
    case when p_won then 'أُغلقت الصفقة رابحة' else 'أُغلقت الفرصة: ' || p_reason end,
    nullif(btrim(coalesce(p_notes,'')), ''), now(), v_lead.owner_id, v_uid
  );

  return to_jsonb(v_lead);
end;
$function$;
CREATE OR REPLACE FUNCTION public.crm_find_existing_leads(p_phones text[])
 RETURNS TABLE(phone_normalized text, name_normalized text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if (select auth.uid()) is null or not public.crm_has_permission('crm.upload_leads') then
    raise exception 'not_allowed';
  end if;
  return query
    select l.phone_normalized, l.name_normalized
    from public.crm_leads l
    where l.phone_normalized = any(coalesce(p_phones, '{}'::text[]));
end;
$function$;
CREATE OR REPLACE FUNCTION public.crm_has_permission(p_key text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select exists (
    select 1 from public.profiles p
    where p.id = (select auth.uid())
      and (
        p.role = 'admin'
        or coalesce((p.permissions ->> p_key)::boolean, false)
      )
  );
$function$;
CREATE OR REPLACE FUNCTION public.crm_leads_dashboard_meta()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with counts as (
    select
      count(*)::int total,
      count(*) filter (where status = 'new')::int new_count,
      count(*) filter (where lead_kind = 'inbound' and status = 'new')::int inbound_new,
      count(*) filter (where lead_kind = 'inbound' and owner_id is null
        and status not in ('converted','activated','lost','existing_customer'))::int inbound_unassigned,
      count(*) filter (where lead_kind = 'inbound' and first_response_due_at < now()
        and first_attempt_at is null and status not in ('converted','activated','lost','existing_customer'))::int overdue_sla,
      count(*) filter (where matched_store_id is not null or status = 'existing_customer')::int existing_customers,
      count(*) filter (where coalesce(duplicate_count, 1) > 1)::int duplicate_rows,
      count(*) filter (where owner_id is null)::int unassigned,
      count(*) filter (where status in ('converted','activated'))::int converted
    from public.crm_leads
  ),
  cat as (
    with recursive t as (
      (select category c from public.crm_leads where category is not null order by category limit 1)
      union all
      select (select category from public.crm_leads where category > t.c and category is not null order by category limit 1)
      from t where t.c is not null
    )
    select coalesce(jsonb_agg(c order by c), '[]'::jsonb) items from t where nullif(c,'') is not null
  ),
  plat as (
    with recursive t as (
      (select platform c from public.crm_leads where platform is not null order by platform limit 1)
      union all
      select (select platform from public.crm_leads where platform > t.c and platform is not null order by platform limit 1)
      from t where t.c is not null
    )
    select coalesce(jsonb_agg(c order by c), '[]'::jsonb) items from t where nullif(c,'') is not null
  ),
  stat as (
    with recursive t as (
      (select status c from public.crm_leads where status is not null order by status limit 1)
      union all
      select (select status from public.crm_leads where status > t.c and status is not null order by status limit 1)
      from t where t.c is not null
    )
    select coalesce(jsonb_agg(c order by c), '[]'::jsonb) items from t where nullif(c,'') is not null
  )
  select jsonb_build_object(
    'stats', jsonb_build_object(
      'total', counts.total,
      'newCount', counts.new_count,
      'inboundNew', counts.inbound_new,
      'inboundUnassigned', counts.inbound_unassigned,
      'overdueSla', counts.overdue_sla,
      'existingCustomers', counts.existing_customers,
      'duplicateRows', counts.duplicate_rows,
      'unassigned', counts.unassigned,
      'converted', counts.converted
    ),
    'options', jsonb_build_object(
      'categories', cat.items, 'platforms', plat.items, 'statuses', stat.items
    )
  )
  from counts, cat, plat, stat;
$function$;
CREATE OR REPLACE FUNCTION public.crm_log_lead_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_type text;
begin
  if tg_op = 'INSERT' then
    insert into public.crm_lead_history(
      lead_id, event_type, to_status, disposition, next_action_at, owner_id, changed_by, details
    ) values (
      new.id, 'created', new.status, new.last_disposition, new.next_action_at,
      new.owner_id, coalesce((select auth.uid()), new.created_by),
      jsonb_build_object('source', new.source, 'channel', new.source_channel, 'campaign', new.campaign_name)
    );
    return new;
  end if;

  if old.owner_id is distinct from new.owner_id then v_type := 'assigned';
  elsif old.status is distinct from new.status then v_type := 'stage_changed';
  elsif old.last_disposition is distinct from new.last_disposition then v_type := 'outcome_recorded';
  elsif old.next_action_at is distinct from new.next_action_at then v_type := 'next_action_changed';
  else return new;
  end if;

  insert into public.crm_lead_history(
    lead_id, event_type, from_status, to_status, disposition, next_action_at,
    owner_id, changed_by, details
  ) values (
    new.id, v_type, old.status, new.status, new.last_disposition, new.next_action_at,
    new.owner_id, (select auth.uid()),
    jsonb_build_object('old_owner', old.owner_id, 'old_next_action_at', old.next_action_at)
  );
  return new;
end;
$function$;
CREATE OR REPLACE FUNCTION public.crm_record_lead_outcome(p_lead_id uuid, p_disposition text, p_status text, p_next_action timestamp with time zone DEFAULT NULL::timestamp with time zone, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_lead public.crm_leads%rowtype;
  v_stage_id uuid;
  v_connected boolean;
begin
  if v_uid is null or not public.crm_has_permission('crm.change_status') then
    raise exception 'not_allowed';
  end if;
  if p_disposition is null or p_disposition not in ('answered','interested','callback','no_answer','busy','wrong_number','not_interested') then
    raise exception 'invalid_disposition';
  end if;
  if p_status is null or p_status not in ('new','attempting','contacted','qualified','proposal','negotiation','nurture','lost') then
    raise exception 'invalid_status';
  end if;
  if p_status = 'lost' then
    raise exception 'use_close_lead_for_loss';
  end if;
  if p_status not in ('new') and p_next_action is null then
    raise exception 'next_action_required';
  end if;

  select * into v_lead from public.crm_leads where id = p_lead_id for update;
  if not found then raise exception 'lead_not_found'; end if;
  if v_lead.owner_id is distinct from v_uid and not public.crm_can_see_all() then
    raise exception 'not_allowed';
  end if;
  if v_lead.status in ('converted','activated','lost','existing_customer') then
    raise exception 'lead_closed';
  end if;

  v_connected := p_disposition in ('answered','interested','callback','not_interested');
  update public.crm_leads set
    status = p_status,
    last_disposition = p_disposition,
    contact_attempts = contact_attempts + 1,
    first_attempt_at = coalesce(first_attempt_at, now()),
    first_connected_at = case when v_connected then coalesce(first_connected_at, now()) else first_connected_at end,
    last_touch_at = now(),
    next_action_at = p_next_action,
    status_changed_at = case when status is distinct from p_status then now() else status_changed_at end,
    notes = case when nullif(btrim(coalesce(p_notes,'')), '') is null then notes
                 else concat_ws(E'\n', nullif(notes,''), '[' || to_char(now(), 'YYYY-MM-DD HH24:MI') || '] ' || btrim(p_notes)) end,
    updated_at = now()
  where id = p_lead_id
  returning * into v_lead;

  insert into public.crm_activities(
    entity_type, entity_ref, kind, disposition, summary, body, occurred_at, owner_id, created_by
  ) values (
    'lead', p_lead_id::text, 'call', p_disposition,
    'نتيجة التواصل: ' || p_disposition, nullif(btrim(coalesce(p_notes,'')), ''),
    now(), v_lead.owner_id, v_uid
  );

  update public.crm_tasks
  set status = 'cancelled', updated_at = now()
  where entity_type = 'lead' and entity_ref = p_lead_id::text and status = 'open';

  if p_next_action is not null then
    insert into public.crm_tasks(
      entity_type, entity_ref, title, kind, due_at, status, priority, assigned_to, created_by
    ) values (
      'lead', p_lead_id::text, 'متابعة: ' || v_lead.name, 'sales_followup',
      p_next_action, 'open',
      case when p_next_action < now() + interval '24 hours' then 'high' else 'normal' end,
      coalesce(v_lead.owner_id, v_uid), v_uid
    );
  end if;

  if p_status in ('qualified','proposal','negotiation') then
    select id into v_stage_id from public.crm_stages
    where key = case p_status when 'qualified' then 'qualified' when 'proposal' then 'proposal' else 'negotiation' end;

    insert into public.crm_deals(
      title, entity_type, entity_ref, stage_id, value, owner_id, status, created_by
    ) values (
      'صفقة — ' || v_lead.name, 'lead', p_lead_id::text, v_stage_id, 0,
      coalesce(v_lead.owner_id, v_uid), 'open', v_uid
    )
    on conflict (entity_ref) where entity_type = 'lead' and status = 'open'
    do update set stage_id = excluded.stage_id, owner_id = excluded.owner_id, updated_at = now();
  end if;

  return to_jsonb(v_lead);
end;
$function$;
CREATE OR REPLACE FUNCTION public.crm_retargeting_campaign_stats()
 RETURNS json
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with fu as (
    select f.phone, f.status, f.owner_id, f.last_touch_at, v.segment, v.total_shipments
    from public.retargeting_followups f
    join public.v_crm_retargeting v on v.phone = f.phone
  ),
  funnel as (
    select
      (select count(*) from public.v_crm_retargeting) as universe,
      count(*) as worked,
      count(*) filter (where last_touch_at is not null) as contacted,
      count(*) filter (where status = 'interested') as interested,
      count(*) filter (where status = 'returned') as returned,
      count(*) filter (where status in ('not_interested','competitor','closed_business')) as lost,
      count(*) filter (where status in ('price_issue','support_issue','integration_issue')) as blocked
    from fu
  )
  select json_build_object(
    'funnel', (select row_to_json(funnel) from funnel),
    'by_status', (select coalesce(json_object_agg(status, c), '{}') from (select status, count(*) c from fu group by status) s),
    'by_owner', (select coalesce(json_agg(o), '[]') from (
       select coalesce(pr.name, '—') as name,
         count(*)::int worked,
         count(*) filter (where fu.last_touch_at is not null)::int contacted,
         count(*) filter (where fu.status = 'interested')::int interested,
         count(*) filter (where fu.status = 'returned')::int returned
       from fu left join public.profiles pr on pr.id = fu.owner_id
       where fu.owner_id is not null
       group by pr.name order by returned desc, worked desc
    ) o),
    'by_segment', (select coalesce(json_agg(s), '[]') from (
       select segment,
         count(*)::int worked,
         count(*) filter (where status = 'returned')::int returned,
         count(*) filter (where status = 'interested')::int interested
       from fu group by segment order by returned desc, worked desc
    ) s)
  );
$function$;
CREATE OR REPLACE FUNCTION public.crm_retargeting_followup_stats()
 RETURNS json
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with base as (
    select v.phone, coalesce(fu.status,'new') status, fu.owner_id, fu.next_action_at
    from public.v_crm_retargeting v
    left join public.retargeting_followups fu on fu.phone = v.phone
  )
  select json_build_object(
    'by_status', (select coalesce(json_object_agg(status, c),'{}') from (select status, count(*) c from base group by status) s),
    'assigned',   (select count(*) from base where owner_id is not null),
    'due_today',  (select count(*) from base where next_action_at is not null and next_action_at::date <= current_date),
    'returned',   (select count(*) from base where status = 'returned')
  );
$function$;
CREATE OR REPLACE FUNCTION public.crm_retargeting_leads(p_segment text DEFAULT NULL::text, p_priority text DEFAULT NULL::text, p_integration text DEFAULT NULL::text, p_billing text DEFAULT NULL::text, p_has_balance boolean DEFAULT NULL::boolean, p_q text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_owner uuid DEFAULT NULL::uuid, p_unassigned boolean DEFAULT NULL::boolean, p_include_excluded boolean DEFAULT false, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_campaign text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with lc as (
    select phone, max(sent_at) as last_at
    from whatsapp_campaign_sends where phone is not null group by phone
  ),
  f as (
    select v.*, coalesce(fu.status,'new') as fu_status, fu.owner_id as fu_owner,
      pr.name as owner_name, fu.next_action_at, fu.notes as fu_notes, fu.last_touch_at,
      lc.last_at as last_campaign_at
    from public.v_crm_retargeting v
    left join public.retargeting_followups fu on fu.phone = v.phone
    left join public.profiles pr on pr.id = fu.owner_id
    left join lc on lc.phone = norm_sa_phone(v.phone)
    where (p_segment is null or v.segment = p_segment)
      and (p_priority is null or coalesce(v.priority,'none') = p_priority)
      and (p_integration is null or coalesce(v.integration_type,'none') = p_integration)
      and (p_billing is null or v.billing_type = p_billing)
      and (p_has_balance is null or (p_has_balance and v.wallet > 0.5) or (not p_has_balance))
      and (p_q is null or btrim(p_q) = '' or v.primary_store ilike '%'||p_q||'%' or v.phone ilike '%'||p_q||'%')
      and (p_status is null or coalesce(fu.status,'new') = p_status)
      and (p_owner is null or fu.owner_id = p_owner)
      and (p_unassigned is null or (p_unassigned and fu.owner_id is null) or (not p_unassigned))
      and (p_include_excluded or p_status in ('blacklist','test')
           or coalesce(fu.status,'new') not in ('blacklist','test'))
      -- فلتر آخر حملة
      and (p_campaign is null or p_campaign = ''
        or (p_campaign = 'none'     and lc.last_at is null)
        or (p_campaign = 'within7'  and lc.last_at >= now() - interval '7 days')
        or (p_campaign = 'within30' and lc.last_at >= now() - interval '30 days')
        or (p_campaign = 'older30'  and lc.last_at is not null and lc.last_at < now() - interval '30 days'))
  )
  select json_build_object(
    'count', (select count(*) from f),
    'rows', (select coalesce(json_agg(r), '[]') from (
      select phone, primary_store, store_names, store_count, total_shipments, last_shipment,
             days_since_last, wallet, last_topup, created_at, integration_type, billing_type,
             profile_done, verified, segment, priority, channel, high_value,
             fu_status, fu_owner, owner_name, next_action_at, fu_notes, last_touch_at, last_campaign_at
      from f
      order by case coalesce(priority,'none')
                 when 'A' then 1 when 'B' then 2 when 'C' then 3 when 'D' then 4 when 'FIN' then 5 else 6 end,
               total_shipments desc
      limit greatest(1, least(p_limit, 200)) offset greatest(0, p_offset)
    ) r)
  );
$function$;
CREATE OR REPLACE FUNCTION public.crm_retargeting_reactivations()
 RETURNS json
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with snaps as (
    select snapshot_id, snapshot_date, row_number() over (order by uploaded_at desc) rn
    from (select snapshot_id, min(snapshot_date) snapshot_date, max(uploaded_at) uploaded_at
          from public.merchants group by snapshot_id) x
  ),
  latest as (select snapshot_id, snapshot_date from snaps where rn = 1),
  prev   as (select snapshot_id, snapshot_date from snaps where rn = 2),
  cur as (select phone, sum(coalesce(shipment_count,0)) sh from public.merchants
          where snapshot_id = (select snapshot_id from latest) and phone is not null and btrim(phone) <> '' group by phone),
  old as (select phone, sum(coalesce(shipment_count,0)) sh from public.merchants
          where snapshot_id = (select snapshot_id from prev) group by phone),
  delta as (
    select c.phone, (c.sh - coalesce(o.sh,0)) as gained
    from cur c left join old o on o.phone = c.phone
  ),
  fu as (select phone from public.retargeting_followups)
  select json_build_object(
    'has_previous', (select count(*) from prev) > 0,
    'previous_date', (select snapshot_date from prev),
    'current_date',  (select snapshot_date from latest),
    'all_reactivated', (select count(*) from delta where gained > 0),
    'all_shipments_generated', (select coalesce(sum(gained),0)::bigint from delta where gained > 0),
    'worked_reactivated', (select count(*) from delta d join fu on fu.phone = d.phone where d.gained > 0),
    'worked_shipments_generated', (select coalesce(sum(d.gained),0)::bigint from delta d join fu on fu.phone = d.phone where d.gained > 0),
    'worked_total', (select count(*) from fu)
  );
$function$;
CREATE OR REPLACE FUNCTION public.crm_retargeting_status_changes(p_limit integer DEFAULT 50)
 RETURNS json
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(json_agg(r), '[]') from (
    select l.phone, l.old_status, l.new_status, l.changed_at,
           coalesce(pr.name, '—') as changed_by_name,
           v.primary_store
    from public.retargeting_status_log l
    left join public.profiles pr on pr.id = l.changed_by
    left join public.v_crm_retargeting v on v.phone = l.phone
    order by l.changed_at desc
    limit greatest(1, least(p_limit, 200))
  ) r;
$function$;
CREATE OR REPLACE FUNCTION public.crm_retargeting_summary()
 RETURNS json
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with v as (select * from public.v_crm_retargeting),
  base as (
    select
      (select count(*) from public.merchants
        where snapshot_id = (select snapshot_id from public.merchants order by uploaded_at desc limit 1)) as total_stores,
      count(*) as unique_customers,
      count(*) filter (where segment = 'active') as active,
      count(*) filter (where segment in ('stopped_recent','stopped_long')) as stopped,
      count(*) filter (where segment in ('registered_no_ship','new_active','linked_no_ship','topped_no_ship')) as never_shipped,
      count(*) filter (where high_value) as high_value,
      count(*) filter (where wallet > 0.5) as with_balance,
      count(*) filter (where segment = 'negative_balance') as negative_balance,
      count(*) filter (where priority = 'A') as prio_a,
      round(coalesce(sum(wallet) filter (where wallet > 0.5), 0)::numeric, 2) as balance_total,
      coalesce(sum(total_shipments), 0) as total_shipments
    from v
  )
  select json_build_object(
    'stats', (select row_to_json(base) from base),
    'segments',     (select coalesce(json_object_agg(segment, cnt), '{}') from (select segment, count(*) cnt from v group by segment) s),
    'priorities',   (select coalesce(json_object_agg(coalesce(priority,'none'), cnt), '{}') from (select priority, count(*) cnt from v group by priority) p),
    'integrations', (select coalesce(json_object_agg(coalesce(integration_type,'(بلا ربط)'), cnt), '{}') from (select integration_type, count(*) cnt from v group by integration_type) i)
  );
$function$;
CREATE OR REPLACE FUNCTION public.cron_health()
 RETURNS TABLE(job text, label text, schedule text, active boolean, last_effect timestamp with time zone, gap_minutes numeric, max_gap_min integer, status text, detail text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with signals(job, label, last_effect, max_gap_min, detail) as (
    select 'zoho-sync-entities', 'مزامنة زوهو',
           (select max(synced_at) from zoho_invoices), 90, 'آخر فاتورة زوهو مُمرآة'
    union all select 'zoho-vat-refresh', 'ضريبة الربع الجاري',
           (select max(fetched_at) from vat_snapshots), 90, 'آخر تحديث لكاش الضريبة'
    union all select 'zoho-pnl-current-month', 'قائمة الدخل',
           (select max(fetched_at) from pnl_snapshots), 2880, 'آخر لقطة ربح'
    union all select 'hatif-pull-calls', 'سحب المكالمات',
           (select max(synced_at) from hatif_call_log), 120, 'آخر مكالمة مسحوبة من هاتف'
    union all select 'hatif-tag-sync', 'وسم المحادثات',
           (select max(applied_at) from hatif_conversation_tags), 720,
           'آخر تغيير وسم (لا يتحرّك في الساعات الهادئة — سلوك سليم)'
    union all select 'hatif-resolve-contacts', 'أرقام جهات هاتف',
           (select max(synced_at) from hatif_contact_phones), 1440, 'آخر رقم جهة تم حلّه'
    union all select 'hatif-contacts-sync', 'مزامنة جهات الاتصال',
           (select max(synced_at) from hatif_contact_sync), 480, 'آخر جهة اتصال مُزامَنة'
    union all select 'hatif-contacts-audit', 'تدقيق جهات هاتف (المجهولون)',
           (select max(last_seen) from hatif_unknown_contacts), 2880,
           'آخر مسح كامل لجهات هاتف — يملأ «فرص هاتف»'
  ),
  queues(job, label, last_effect, max_gap_min, detail) as (
    select 'campaign-runner', 'مشغّل الحملات',
           (select max(processed_at) from campaign_queue), null::integer,
           case when (select count(*) from campaign_queue
                      where status in ('pending','sending') and scheduled_at < now() - interval '30 minutes') > 0
                then (select count(*)::text from campaign_queue
                      where status in ('pending','sending') and scheduled_at < now() - interval '30 minutes')
                     || ' صف حملة عالق (حان وقته ولم يُرسَل)'
                else 'لا طابور عالق' end
    union all
    select 'ivr-runner', 'مشغّل المكالمات الآلية', null::timestamptz, null::integer,
           case when (select count(*) from ivr_queue
                      where status = 'pending' and run_at < now() - interval '30 minutes') > 0
                then (select count(*)::text from ivr_queue
                      where status = 'pending' and run_at < now() - interval '30 minutes')
                     || ' مكالمة عالقة'
                else 'لا طابور عالق' end
    union all
    select 'hatif-retag-runner', 'إعادة الوسم الحدثي', null::timestamptz, null::integer,
           case when (select count(*) from hatif_retag_dirty
                      where queued_at < now() - interval '30 minutes') > 0
                then (select count(*)::text from hatif_retag_dirty
                      where queued_at < now() - interval '30 minutes')
                     || ' رقم ينتظر إعادة وسم'
                else 'لا متأثّرين معلّقين' end
  ),
  all_signals as (select * from signals union all select * from queues)
  select s.job, s.label, coalesce(j.schedule,'—'), coalesce(j.active,false), s.last_effect,
    case when s.last_effect is null then null
         else round(extract(epoch from (now() - s.last_effect))/60.0, 1) end,
    s.max_gap_min,
    case
      when not coalesce(j.active,false) then 'معطّلة'
      when s.max_gap_min is null and s.detail like 'لا %' then 'سليمة'
      when s.max_gap_min is null then 'متأخّرة'
      when s.last_effect is null then 'بلا أثر'
      when extract(epoch from (now() - s.last_effect))/60.0 > s.max_gap_min then 'متأخّرة'
      else 'سليمة' end,
    s.detail
  from all_signals s left join cron.job j on j.jobname = s.job
  order by case
      when not coalesce(j.active,false) then 3
      when s.last_effect is null then 0
      when s.max_gap_min is not null
           and extract(epoch from (now() - s.last_effect))/60.0 > s.max_gap_min then 0
      when s.max_gap_min is null and s.detail not like 'لا %' then 0
      else 2 end, s.label;
$function$;
CREATE OR REPLACE FUNCTION public.customer_activation_command_center(p_days integer DEFAULT 5, p_target integer DEFAULT 500, p_limit integer DEFAULT 24)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_days integer := greatest(1, least(coalesce(p_days, 5), 30));
  v_target integer := greatest(1, least(coalesce(p_target, 500), 100000));
  v_limit integer := greatest(2, least(coalesce(p_limit, 24), 60));
  v_current jsonb;
  v_movement jsonb;
  v_execution jsonb;
  v_outcomes jsonb;
  v_trend jsonb;
  v_sync jsonb;
  v_active integer;
  v_gap integer;
  v_exited integer;
begin
  if (select auth.uid()) is null
     or not (
       public.crm_has_permission('sales.view')
       or public.crm_has_permission('merchants.view')
       or public.crm_has_permission('crm.view')
     ) then
    raise exception 'not_allowed';
  end if;

  select jsonb_build_object(
    'total_customers', count(*)::int,
    'total_stores', coalesce(sum(store_count), 0)::int,
    'active', count(*) filter (
      where last_shipment >= now() - make_interval(days => v_days)
    )::int,
    'active_30d', count(*) filter (
      where last_shipment >= now() - interval '30 days'
    )::int,
    'active_sales_eligible', count(*) filter (
      where last_shipment >= now() - make_interval(days => v_days)
        and sales_eligible
    )::int,
    'active_financial_hold', count(*) filter (
      where last_shipment >= now() - make_interval(days => v_days)
        and financial_hold
    )::int,
    'prepaid_active', count(*) filter (
      where last_shipment >= now() - make_interval(days => v_days)
        and billing_type = 'دفع مسبق'
    )::int,
    'postpaid_active', count(*) filter (
      where last_shipment >= now() - make_interval(days => v_days)
        and billing_type = 'دفع لاحق'
    )::int,
    'target', v_target,
    'days', v_days
  )
  into v_current
  from public.v_platform_commercial_routing;

  v_active := coalesce((v_current->>'active')::int, 0);
  v_gap := greatest(0, v_target - v_active);

  with snapshot_meta as (
    select snapshot_id, min(snapshot_date) as snapshot_date, max(uploaded_at) as uploaded_at
    from public.merchants
    group by snapshot_id
  ), latest as (
    select * from snapshot_meta order by uploaded_at desc limit 1
  ), previous as (
    select meta.*
    from snapshot_meta meta, latest current_snapshot
    where meta.snapshot_id <> current_snapshot.snapshot_id
    order by
      (meta.uploaded_at <= current_snapshot.uploaded_at - interval '7 days') desc,
      case when meta.uploaded_at <= current_snapshot.uploaded_at - interval '7 days'
        then meta.uploaded_at end desc nulls last,
      meta.uploaded_at desc
    limit 1
  ), current_customers as (
    select m.phone, max(m.last_shipment_at) as last_shipment
    from public.merchants m join latest l on l.snapshot_id = m.snapshot_id
    where m.phone is not null and btrim(m.phone) <> ''
    group by m.phone
  ), previous_customers as (
    select m.phone, max(m.last_shipment_at) as last_shipment
    from public.merchants m join previous p on p.snapshot_id = m.snapshot_id
    where m.phone is not null and btrim(m.phone) <> ''
    group by m.phone
  ), current_active as (
    select c.phone from current_customers c, latest l
    where c.last_shipment >= l.uploaded_at - make_interval(days => v_days)
  ), previous_active as (
    select c.phone from previous_customers c, previous p
    where c.last_shipment >= p.uploaded_at - make_interval(days => v_days)
  )
  select jsonb_build_object(
    'has_previous', exists (select 1 from previous),
    'current_date', (select snapshot_date from latest),
    'previous_date', (select snapshot_date from previous),
    'current_active', (select count(*)::int from current_active),
    'previous_active', (select count(*)::int from previous_active),
    'entered', (
      select count(*)::int from current_active c
      where not exists (select 1 from previous_active p where p.phone = c.phone)
    ),
    'exited', (
      select count(*)::int from previous_active p
      where not exists (select 1 from current_active c where c.phone = p.phone)
    )
  )
  into v_movement;

  v_exited := coalesce((v_movement->>'exited')::int, 0);
  v_current := v_current || jsonb_build_object(
    'gap', v_gap,
    'progress_pct', round(least(100, (v_active::numeric / v_target) * 100), 1),
    'required_weekly_entrants', greatest(0, ceil(v_gap::numeric / 4)::int + v_exited)
  );
  v_movement := v_movement || jsonb_build_object(
    'net', coalesce((v_movement->>'entered')::int, 0) - v_exited
  );

  select jsonb_build_object(
    'actionable', count(*) filter (
      where route.sales_eligible
        and route.commercial_signal in (
          'hot_live_new', 'hot_live_topped', 'recent_stop', 'wallet_stranded',
          'live_inactive', 'live_no_first_shipment', 'recovery'
        )
    )::int,
    'hot_live', count(*) filter (
      where route.sales_eligible and (route.hot_live_new or route.hot_live_topped)
    )::int,
    'recent_stop', count(*) filter (
      where route.sales_eligible and route.recent_stop
    )::int,
    'wallet_stranded', count(*) filter (
      where route.sales_eligible and route.wallet_stranded
    )::int,
    'live_inactive', count(*) filter (
      where route.sales_eligible and route.live_inactive
    )::int,
    'financial_hold', count(*) filter (where route.financial_hold)::int,
    'unassigned', count(*) filter (
      where route.sales_eligible
        and route.commercial_signal in (
          'hot_live_new', 'hot_live_topped', 'recent_stop', 'wallet_stranded',
          'live_inactive', 'live_no_first_shipment', 'recovery'
        )
        and followup.owner_id is null
    )::int,
    'never_contacted', count(*) filter (
      where route.sales_eligible
        and route.commercial_signal in (
          'hot_live_new', 'hot_live_topped', 'recent_stop', 'wallet_stranded',
          'live_inactive', 'live_no_first_shipment', 'recovery'
        )
        and followup.first_contact_at is null
    )::int,
    'overdue', count(*) filter (
      where followup.next_action_at < now()
        and coalesce(followup.sales_stage, 'new') not in ('won', 'lost', 'disqualified')
    )::int,
    'contacted_no_next', count(*) filter (
      where followup.first_contact_at is not null
        and followup.next_action_at is null
        and coalesce(followup.sales_stage, 'new') not in ('won', 'lost', 'disqualified')
    )::int,
    'scheduled', count(*) filter (
      where followup.next_action_at >= now()
        and coalesce(followup.sales_stage, 'new') not in ('won', 'lost', 'disqualified')
    )::int
  )
  into v_execution
  from public.v_platform_commercial_routing route
  left join public.retargeting_followups followup on followup.phone = route.phone;

  select jsonb_build_object(
    'objective', count(distinct coalesce(nullif(event.phone, ''), 'store:' || event.store_id))::int,
    'first_shipments', count(distinct coalesce(nullif(event.phone, ''), 'store:' || event.store_id))
      filter (where event.event_type = 'first_shipment')::int,
    'resumed', count(distinct coalesce(nullif(event.phone, ''), 'store:' || event.store_id))
      filter (where event.event_type = 'shipping_resumed')::int,
    'attributed_after_contact', count(distinct event.phone) filter (
      where event.phone is not null
        and followup.first_contact_at is not null
        and followup.first_contact_at <= event.observed_at
    )::int,
    'marked_won', count(distinct event.phone) filter (
      where event.phone is not null and followup.won_at is not null
    )::int
  )
  into v_outcomes
  from public.merchant_lifecycle_events event
  left join public.retargeting_followups followup on followup.phone = event.phone
  where event.observed_at >= now() - interval '30 days'
    and event.event_type in ('first_shipment', 'shipping_resumed');

  with snaps as (
    select snapshot_id, min(snapshot_date) as snapshot_date, max(uploaded_at) as uploaded_at
    from public.merchants
    group by snapshot_id
    order by max(uploaded_at) desc
    limit v_limit
  ), customer_rows as (
    select
      snap.snapshot_id,
      snap.snapshot_date,
      snap.uploaded_at,
      merchant.phone,
      count(*)::int as stores,
      max(merchant.last_shipment_at) as last_shipment,
      bool_or(merchant.billing_type = 'دفع مسبق') as prepaid,
      bool_or(merchant.billing_type = 'دفع لاحق') as postpaid
    from snaps snap
    join public.merchants merchant on merchant.snapshot_id = snap.snapshot_id
    where merchant.phone is not null and btrim(merchant.phone) <> ''
    group by snap.snapshot_id, snap.snapshot_date, snap.uploaded_at, merchant.phone
  ), points as (
    select
      snapshot_id,
      snapshot_date,
      uploaded_at,
      count(*)::int as total_customers,
      sum(stores)::int as total_stores,
      count(*) filter (
        where last_shipment >= uploaded_at - make_interval(days => v_days)
      )::int as active,
      count(*) filter (
        where last_shipment >= uploaded_at - interval '30 days'
      )::int as active_30d,
      count(*) filter (
        where last_shipment >= uploaded_at - make_interval(days => v_days) and prepaid
      )::int as prepaid_active,
      count(*) filter (
        where last_shipment >= uploaded_at - make_interval(days => v_days) and postpaid
      )::int as postpaid_active
    from customer_rows
    group by snapshot_id, snapshot_date, uploaded_at
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'snapshot_id', point.snapshot_id,
    'snapshot_date', point.snapshot_date,
    'uploaded_at', point.uploaded_at,
    'total_customers', point.total_customers,
    'total_stores', point.total_stores,
    'active', point.active,
    'active_30d', point.active_30d,
    'prepaid_active', point.prepaid_active,
    'postpaid_active', point.postpaid_active
  ) order by point.uploaded_at), '[]'::jsonb)
  into v_trend
  from points point;

  with latest_snapshot as (
    select snapshot_id, max(uploaded_at) as uploaded_at
    from public.merchants
    group by snapshot_id
    order by max(uploaded_at) desc
    limit 1
  ), latest_webhook as (
    select * from public.platform_snapshot_receipts
    order by received_at desc
    limit 1
  )
  select jsonb_build_object(
    'snapshot_id', snapshot.snapshot_id,
    'uploaded_at', snapshot.uploaded_at,
    'age_minutes', greatest(0, floor(extract(epoch from (now() - snapshot.uploaded_at)) / 60))::int,
    'source', case when receipt.snapshot_id = snapshot.snapshot_id then 'webhook' else 'excel' end,
    'last_webhook_at', receipt.received_at,
    'last_webhook_rows', receipt.row_count
  )
  into v_sync
  from latest_snapshot snapshot
  left join latest_webhook receipt on true;

  return jsonb_build_object(
    'current', coalesce(v_current, '{}'::jsonb),
    'movement', coalesce(v_movement, '{}'::jsonb),
    'execution', coalesce(v_execution, '{}'::jsonb),
    'outcomes_30d', coalesce(v_outcomes, '{}'::jsonb),
    'trend', coalesce(v_trend, '[]'::jsonb),
    'sync', coalesce(v_sync, '{}'::jsonb)
  );
end;
$function$;
CREATE OR REPLACE FUNCTION public.customer_balance_recon_zoho()
 RETURNS TABLE(anchor text, store_id text, store_name text, phone text, billing_type text, platform_status text, wallet_balance numeric, zoho_balance numeric, zoho_open_cnt integer, zoho_oldest date, zoho_names text[], internal_balance numeric, internal_names text[], diff numeric, recon_status text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with latest_settle as (
    select id from store_balance_snapshots
    where source = 'internal' order by uploaded_at desc limit 1
  ),
  latest_merch as (select snapshot_id from merchants order by uploaded_at desc limit 1),
  merch as (
    select m.store_id, m.store_name, m.phone, m.billing_type, m.status,
           coalesce(m.wallet_balance,0) wallet,
           normalize_arabic_name(m.store_name) norm
    from merchants m where m.snapshot_id = (select snapshot_id from latest_merch)
  ),
  links as (select customer_name, l.store_id from customer_merchant_links l where l.store_id is not null),
  -- ✅ زوهو: **إجمالي الذمّة** من customer_ar (يشمل الرصيد الافتتاحي)
  --    وعدد الفواتير/أقدمها يبقيان للعرض فقط.
  zoho_raw as (
    select ar.contact_name as customer_name,
           ar.total_due    as bal,
           ar.open_invoices::int as cnt,
           ar.oldest_invoice_date as oldest
    from customer_ar ar
    where ar.total_due > 0.5 and ar.contact_name is not null
  ),
  zoho_anch as (
    select z.*,
      coalesce(l.store_id,
        (select m.store_id from merch m where m.norm = normalize_arabic_name(z.customer_name) limit 1),
        'n:' || normalize_arabic_name(z.customer_name)) anchor
    from zoho_raw z left join links l on l.customer_name = z.customer_name
  ),
  zoho_g as (
    select anchor, sum(bal) bal, sum(cnt)::int cnt, min(oldest) oldest,
           array_agg(customer_name order by bal desc) names
    from zoho_anch group by anchor
  ),
  int_raw as (
    select sb.raw_name as customer_name, sb.store_id as sid0, -sum(sb.balance) bal
    from store_balances sb
    where sb.snapshot_id = (select id from latest_settle)
    group by sb.raw_name, sb.store_id
    having abs(sum(sb.balance)) > 0.5
  ),
  int_anch as (
    select i.customer_name, i.bal,
      coalesce(i.sid0, l.store_id,
        (select m.store_id from merch m where m.norm = normalize_arabic_name(i.customer_name) limit 1),
        'n:' || normalize_arabic_name(i.customer_name)) anchor
    from int_raw i left join links l on l.customer_name = i.customer_name
  ),
  int_g as (
    select anchor, sum(bal) bal, array_agg(customer_name order by bal desc) names
    from int_anch group by anchor
  ),
  joined as (
    select coalesce(z.anchor, i.anchor) anchor,
      case when coalesce(z.anchor, i.anchor) like 'n:%' then null else coalesce(z.anchor, i.anchor) end sid,
      coalesce(z.bal, 0) zbal, coalesce(z.cnt, 0) zcnt, z.oldest, z.names znames,
      coalesce(i.bal, 0) ibal, i.names inames
    from zoho_g z full outer join int_g i on z.anchor = i.anchor
  )
  select j.anchor, j.sid, m.store_name, m.phone, m.billing_type, m.status, m.wallet,
    round(j.zbal::numeric, 2), j.zcnt, j.oldest, coalesce(j.znames, '{}'),
    round(j.ibal::numeric, 2), coalesce(j.inames, '{}'),
    round((j.ibal - j.zbal)::numeric, 2),
    case
      when abs(j.ibal - j.zbal) <= 1           then 'matched'
      when j.zbal <= 0.5 and abs(j.ibal) > 0.5 then 'internal_only'
      when j.zbal > 0.5 and abs(j.ibal) <= 0.5 then 'zoho_only'
      else 'needs_investigation'
    end
  from joined j
  left join merch m on m.store_id = j.sid
  order by abs(j.ibal - j.zbal) desc;
$function$;
CREATE OR REPLACE FUNCTION public.customer_collection_campaign_buckets()
 RETURNS json
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with bucketed as materialized (
    select
      l.contact_id::text as zoho_id,
      l.contact_name,
      coalesce(sum(l.collectible_amount) filter (
        where l.line_kind = 'invoice' and l.age_days between 1 and 15
      ), 0) as inv_1_15,
      coalesce(sum(l.collectible_amount) filter (
        where l.line_kind = 'invoice' and l.age_days between 16 and 30
      ), 0) as inv_16_30,
      coalesce(sum(l.collectible_amount) filter (
        where l.line_kind = 'invoice' and l.age_days between 31 and 60
      ), 0) as inv_31_60,
      coalesce(sum(l.collectible_amount) filter (
        where l.line_kind = 'invoice' and l.age_days between 61 and 90
      ), 0) as inv_61_90,
      coalesce(sum(l.collectible_amount) filter (
        where l.line_kind = 'invoice' and l.age_days > 90
      ), 0) as inv_90p,
      coalesce(sum(l.collectible_amount) filter (
        where l.line_kind = 'opening_balance'
      ), 0) as opening_balance
    from public.customer_collectible_lines l
    where l.collectible_amount > 0.005
    group by l.contact_id, l.contact_name
  ), eligible as materialized (
    select *
    from bucketed b
    where b.inv_1_15 + b.inv_16_30 + b.inv_31_60
        + b.inv_61_90 + b.inv_90p + b.opening_balance > 0.005
  )
  select json_build_object(
    'aging', json_build_object(
      'inv_1_15', coalesce(round(sum(e.inv_1_15)::numeric, 2), 0),
      'inv_16_30', coalesce(round(sum(e.inv_16_30)::numeric, 2), 0),
      'inv_31_60', coalesce(round(sum(e.inv_31_60)::numeric, 2), 0),
      'inv_61_90', coalesce(round(sum(e.inv_61_90)::numeric, 2), 0),
      'inv_90p', coalesce(round(sum(e.inv_90p)::numeric, 2), 0),
      'opening_balance', coalesce(round(sum(e.opening_balance)::numeric, 2), 0)
    ),
    'customers', coalesce(json_agg(json_build_object(
      'zoho_id', e.zoho_id,
      'name', e.contact_name,
      'inv_1_15', round(e.inv_1_15::numeric, 2),
      'inv_16_30', round(e.inv_16_30::numeric, 2),
      'inv_31_60', round(e.inv_31_60::numeric, 2),
      'inv_61_90', round(e.inv_61_90::numeric, 2),
      'inv_90p', round(e.inv_90p::numeric, 2),
      'opening_balance', round(e.opening_balance::numeric, 2)
    ) order by (
      e.inv_1_15 + e.inv_16_30 + e.inv_31_60
      + e.inv_61_90 + e.inv_90p + e.opening_balance
    ) desc), '[]'::json)
  )
  from eligible e;
$function$;
comment on function "public"."customer_collection_campaign_buckets"() is 'Read-only, invoice-only overdue campaign buckets plus a separate unpaid opening-balance bucket.';
CREATE OR REPLACE FUNCTION public.customer_comm_timeline(p_phone text)
 RETURNS TABLE(kind text, occurred_at timestamp with time zone, title text, detail text, status text, recording_url text, sentiment integer, ai_summary jsonb, agent_id text, reply_body text, conversation_id text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with ph as (select norm_sa_phone(p_phone) as phone)
  select 'campaign', w.sent_at,
         coalesce(nullif(w.campaign_name,''), 'حملة واتساب'), w.template_name,
         case when w.replied_at is not null and coalesce(w.reply_is_auto,false)=false then 'replied'
              when w.read_at is not null then 'read'
              when w.delivered_at is not null then 'delivered'
              when w.status = 'failed' then 'failed' else 'sent' end,
         null::text, null::int, null::jsonb, w.sent_by::text,
         case when coalesce(w.reply_is_auto,false)=false then w.reply_body else null end,
         w.conversation_id
  from whatsapp_campaign_sends w, ph where w.phone = ph.phone
  union all
  select 'ivr', coalesce(iv.initiated_at, iv.created_at),
         coalesce('IVR: '||nullif(iv.script_key,''), 'IVR'),
         case when iv.pressed_digit is not null then 'digit '||iv.pressed_digit
              when iv.result is not null then iv.result else iv.status end,
         iv.result, cl.recording_url, cl.sentiment, cl.ai_summary, iv.initiated_by::text, null, null::text
  from ivr_calls iv cross join ph
  left join hatif_call_log cl on cl.id = iv.voxa_call_id
  where iv.phone = ph.phone
  union all
  select 'voice_call', call_row.creation_time,
         case when call_row.call_type = 1 then 'مكالمة واردة'
              else 'مكالمة صادرة' end
           || case when nullif(btrim(call_row.user_name), '') is not null
                   then ' — ' || call_row.user_name else '' end,
         case when call_row.pickup_time is not null then 'تم الرد'
              else 'لم يُردّ' end
           || case when coalesce(call_row.talk_seconds, 0) > 0
                   then ' · ' || call_row.talk_seconds::text || ' ثانية' else '' end,
         case when call_row.pickup_time is not null then 'answered' else 'not_answered' end,
         call_row.recording_url, call_row.sentiment, call_row.ai_summary,
         call_row.user_id, null::text, null::text
  from hatif_call_log call_row cross join ph
  where call_row.contact_phone = ph.phone
    and not exists (
      select 1 from ivr_calls iv where iv.voxa_call_id = call_row.id
    )
  union all
  select 'handled', e.received_at, 'handled', null, null,
         null::text, null::int, null::jsonb, e.assigned_user_id, null, e.conversation_id
  from hatif_events e cross join ph
  where e.event_type = 'AssignedUserIdChanged' and e.assigned_user_id is not null
    and (
      exists (select 1 from whatsapp_campaign_sends w where (w.conversation_id = e.conversation_id or w.contact_id = e.contact_id) and w.phone = ph.phone)
      or exists (select 1 from hatif_contact_phones cp where cp.contact_id = e.contact_id and norm_sa_phone(cp.phone) = ph.phone)
      or exists (select 1 from hatif_contact_sync cs where cs.contact_id = e.contact_id and norm_sa_phone(cs.phone) = ph.phone)
    )
  order by 2 desc;
$function$;
CREATE OR REPLACE FUNCTION public.customer_debt_concentration(p_limit integer DEFAULT 10)
 RETURNS TABLE(customer_name text, debt numeric, invoice_count integer, share_pct numeric, rank_order integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with per_customer as (
    select ar.contact_name as customer_name,
           ar.total_due::numeric   as debt,
           ar.open_invoices::int   as invoice_count
    from customer_ar ar where ar.total_due > 0.5
  ),
  total as (select nullif(sum(debt), 0) as s from per_customer)
  select pc.customer_name, pc.debt, pc.invoice_count,
    coalesce((pc.debt / total.s * 100)::numeric(6,2), 0) as share_pct,
    row_number() over (order by pc.debt desc)::int as rank_order
  from per_customer pc, total
  order by pc.debt desc
  limit p_limit;
$function$;
CREATE OR REPLACE FUNCTION public.customer_engagement_next_actions(p_limit integer DEFAULT 400, p_owner text DEFAULT NULL::text, p_journey text DEFAULT NULL::text)
 RETURNS TABLE(phone text, name text, store_id text, owner_id text, reason_code text, journey text, reason text, action text, priority integer, amount numeric, followup_status text, last_touch timestamp with time zone, recommended_channel text, recommended_template_key text, send_eligible boolean, guard_code text, guard_reason text, last_campaign_at timestamp with time zone, last_call_at timestamp with time zone, source_snapshot_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with
  access_guard as (
    select public.app_has_any_permission(array[
      'collections.view', 'sales.view', 'overview.view', 'crm.view'
    ]) as allowed
  ),
  latest_snapshot as (
    select snapshot_id, max(uploaded_at) as uploaded_at
    from public.merchants
    group by snapshot_id
    order by max(uploaded_at) desc
    limit 1
  ),
  merchant_primary as (
    select distinct on (public.norm_sa_phone(m.phone))
      public.norm_sa_phone(m.phone) as phone,
      m.store_id,
      m.store_name
    from public.merchants m
    where m.snapshot_id = (select snapshot_id from latest_snapshot)
      and public.norm_sa_phone(m.phone) is not null
    order by public.norm_sa_phone(m.phone), coalesce(m.shipment_count, 0) desc, m.store_id
  ),
  lifecycle as (
    select
      public.norm_sa_phone(v.phone) as phone,
      v.primary_store as name,
      mp.store_id,
      v.total_shipments,
      v.last_shipment,
      v.created_at,
      v.wallet,
      v.segment,
      v.priority as lifecycle_priority,
      v.opportunity_score,
      v.readiness_score,
      v.profile_done,
      v.verified,
      v.integration_type,
      v.days_since_last
    from public.v_crm_retargeting v
    left join merchant_primary mp on mp.phone = public.norm_sa_phone(v.phone)
    where public.norm_sa_phone(v.phone) is not null
  ),
  debt_by_phone as (
    select public.norm_sa_phone(m.phone) as phone, sum(ar.total_due)::numeric as owed
    from public.customer_ar ar
    join public.customer_merchant_links l on l.customer_name = ar.contact_name
    join public.merchants m
      on m.store_id = l.store_id
     and m.snapshot_id = (select snapshot_id from latest_snapshot)
    where ar.total_due > 0.5
      and public.norm_sa_phone(m.phone) is not null
    group by public.norm_sa_phone(m.phone)
  ),
  followups as (
    select public.norm_sa_phone(f.phone) as phone,
      f.status, f.owner_id, f.next_action_at, f.last_touch_at
    from public.retargeting_followups f
    where public.norm_sa_phone(f.phone) is not null
  ),
  last_campaign as (
    select public.norm_sa_phone(w.phone) as phone, max(w.sent_at) as sent_at
    from public.whatsapp_campaign_sends w
    where w.sent_at is not null and public.norm_sa_phone(w.phone) is not null
    group by public.norm_sa_phone(w.phone)
  ),
  last_call as (
    select coalesce(h.contact_phone, public.norm_sa_phone(h.contact_number)) as phone,
           max(h.creation_time) as called_at
    from public.hatif_call_log h
    where coalesce(h.contact_phone, public.norm_sa_phone(h.contact_number)) is not null
    group by coalesce(h.contact_phone, public.norm_sa_phone(h.contact_number))
  ),
  blocked as (
    select distinct public.norm_sa_phone(b.phone) as phone
    from public.campaign_phone_blocklist b
    where public.norm_sa_phone(b.phone) is not null
  ),
  signals as (
    select public.norm_sa_phone(w.phone) as phone,
      coalesce(nullif(w.name, ''), l.name, public.norm_sa_phone(w.phone)) as name,
      l.store_id,
      'hot_reply'::text as reason_code, 'reply'::text as journey,
      (case public.reply_intent(w.reply_body)
        when 'wants_call' then 'Ø±Ø¯Ù‘ ÙŠØ·Ù„Ø¨ Ø§ØªØµØ§Ù„Ø§Ù‹: '
        when 'price' then 'Ø±Ø¯Ù‘ Ø¨Ø§Ø¹ØªØ±Ø§Ø¶ Ø³Ø¹Ø±: '
        else 'Ø±Ø¯Ù‘ Ø¨Ø§Ù‡ØªÙ…Ø§Ù…: '
       end) || left(coalesce(w.reply_body, ''), 45) as reason,
      (case public.reply_intent(w.reply_body)
        when 'wants_call' then 'Ø§ØªØµÙ„ Ø¨Ù‡ Ø§Ù„Ø¢Ù†'
        when 'price' then 'Ø±Ø§Ø¬Ø¹ Ø§Ø¹ØªØ±Ø§Ø¶ Ø§Ù„Ø³Ø¹Ø± Ù…Ø¹Ù‡'
        else 'ØªØ§Ø¨Ø¹ Ø§Ù„Ø±Ø¯ Ø§Ù„Ø¢Ù†'
       end) as action,
      108 as priority, null::numeric as amount
    from public.whatsapp_campaign_sends w
    left join lifecycle l on l.phone = public.norm_sa_phone(w.phone)
    where w.replied_at > now() - interval '14 days'
      and coalesce(w.reply_is_auto, false) = false
      and public.reply_intent(w.reply_body) in ('interested', 'wants_call', 'price')

    union all
    select f.phone, coalesce(l.name, f.phone), l.store_id,
      'sla', 'team_followup',
      case when f.next_action_at is not null and f.next_action_at < now()
        then 'Ù…ØªØ§Ø¨Ø¹Ø© ØªØ¬Ø§ÙˆØ²Øª Ù…ÙˆØ¹Ø¯Ù‡Ø§ Ø§Ù„Ù…Ø­Ø¯Ø¯'
        else 'Ù…ØªØ§Ø¨Ø¹Ø© Ø±Ø§ÙƒØ¯Ø© Ù…Ù†Ø° ' || greatest(1, floor(extract(epoch from now() - f.last_touch_at) / 86400))::int || ' ÙŠÙˆÙ…'
      end,
      'Ù†ÙÙ‘Ø° Ù…ØªØ§Ø¨Ø¹Ø© Ø§Ù„Ù…ÙˆØ¸Ù Ø§Ù„Ø¢Ù†', 105, null::numeric
    from followups f
    left join lifecycle l on l.phone = f.phone
    where f.status not in ('converted', 'rejected', 'not_interested', 'blacklist', 'supplier', 'noise', 'test')
      and ((f.next_action_at is not null and f.next_action_at < now())
        or f.last_touch_at < now() - interval '3 days')

    union all
    select public.norm_sa_phone(w.phone), coalesce(nullif(w.name, ''), l.name, public.norm_sa_phone(w.phone)), l.store_id,
      'reply', 'reply', 'Ø±Ø¯Ù‘ Ø¹Ù„Ù‰ Ø§Ù„Ø­Ù…Ù„Ø© ÙˆÙ„Ù… ÙŠÙØªØ§Ø¨ÙŽØ¹', 'ØªØ§Ø¨Ø¹ Ø§Ù„Ø±Ø¯ Ø§Ù„Ø¢Ù†', 100, null::numeric
    from public.whatsapp_campaign_sends w
    left join lifecycle l on l.phone = public.norm_sa_phone(w.phone)
    where w.replied_at > now() - interval '30 days'
      and coalesce(w.reply_is_auto, false) = false
      and coalesce(w.followed_up, false) = false

    union all
    select l.phone, l.name, l.store_id,
      'wallet_neg', 'collections', 'Ù…Ø­ÙØ¸Ø© Ø§Ù„Ø¯ÙØ¹ Ø§Ù„Ù…Ø³Ø¨Ù‚ Ø³Ø§Ù„Ø¨Ø©', 'Ø­ØµÙ‘Ù„ Ø±ØµÙŠØ¯ Ø§Ù„Ù…Ø­ÙØ¸Ø©',
      88, abs(l.wallet)::numeric
    from lifecycle l
    where l.wallet < -0.5

    union all
    select l.phone, l.name, l.store_id,
      'debt', 'collections', 'Ø¹Ù„Ù‰ Ø§Ù„Ø¹Ù…ÙŠÙ„ Ø°Ù…Ø© Ù…ÙØªÙˆØ­Ø©', 'ØªØ§Ø¨Ø¹ Ø§Ù„ØªØ­ØµÙŠÙ„ Ø­Ø³Ø¨ ÙƒØ´Ù Ø§Ù„Ø¹Ù…ÙŠÙ„',
      82, d.owed
    from lifecycle l
    join debt_by_phone d on d.phone = l.phone
    where d.owed > 0.5

    union all
    select l.phone, l.name, l.store_id,
      'new_ready', 'new_customer',
      case
        when l.segment = 'topped_no_ship' then 'Ø´Ø­Ù† Ø§Ù„Ù…Ø­ÙØ¸Ø© ÙˆÙ„Ù… ÙŠÙ†ÙØ° Ø£ÙˆÙ„ Ø´Ø­Ù†Ø©'
        when l.integration_type is not null then 'Ø§Ù„Ø±Ø¨Ø· Ø¬Ø§Ù‡Ø² ÙˆÙ„Ù… ÙŠÙ†ÙØ° Ø£ÙˆÙ„ Ø´Ø­Ù†Ø©'
        else 'Ø¨ÙŠØ§Ù†Ø§ØªÙ‡ Ø¬Ø§Ù‡Ø²Ø© ÙˆÙ„Ù… ÙŠÙ†ÙØ° Ø£ÙˆÙ„ Ø´Ø­Ù†Ø©'
      end,
      'Ø³Ø§Ø¹Ø¯Ù‡ Ø¹Ù„Ù‰ ØªÙ†ÙÙŠØ° Ø£ÙˆÙ„ Ø´Ø­Ù†Ø©', 78 + least(9, coalesce(l.opportunity_score, 0) / 10), null::numeric
    from lifecycle l
    left join followups f on f.phone = l.phone
    where l.total_shipments = 0
      and l.segment in ('topped_no_ship', 'linked_no_ship', 'new_active')
      and l.created_at >= current_date - 90
      and coalesce(f.status, '') not in ('converted', 'rejected', 'not_interested', 'blacklist', 'supplier', 'noise', 'test')

    union all
    select l.phone, l.name, l.store_id,
      'new_registered', 'new_customer', 'Ù…Ø³Ø¬Ù„ Ø­Ø¯ÙŠØ«Ù‹Ø§ ÙˆÙ„Ù… ÙŠØ¨Ø¯Ø£ Ø§Ù„ØªØ¬Ù‡ÙŠØ² Ø£Ùˆ Ø§Ù„Ø´Ø­Ù†',
      case
        when not coalesce(l.profile_done, false) then 'Ø£Ø±Ø³Ù„ ØªØ±Ø­ÙŠØ¨Ù‹Ø§ ÙˆØ³Ø§Ø¹Ø¯Ù‡ Ø¹Ù„Ù‰ Ø¥ÙƒÙ…Ø§Ù„ Ø§Ù„Ø¨ÙŠØ§Ù†Ø§Øª'
        when not coalesce(l.verified, false) then 'Ø³Ø§Ø¹Ø¯Ù‡ Ø¹Ù„Ù‰ Ø¥ÙƒÙ…Ø§Ù„ Ø§Ù„ØªÙˆØ«ÙŠÙ‚'
        else 'Ø³Ø§Ø¹Ø¯Ù‡ Ø¹Ù„Ù‰ Ø±Ø¨Ø· Ø§Ù„Ù…ØªØ¬Ø±'
      end,
      74 + least(7, coalesce(l.readiness_score, 0) / 15), null::numeric
    from lifecycle l
    left join followups f on f.phone = l.phone
    where l.total_shipments = 0
      and l.segment = 'registered_no_ship'
      and l.created_at >= current_date - 14
      and coalesce(f.status, '') not in ('converted', 'rejected', 'not_interested', 'blacklist', 'supplier', 'noise', 'test')

    union all
    select l.phone, l.name, l.store_id,
      'stopped_recent', 'stopped_customer',
      'ØªÙˆÙ‚Ù Ø¹Ù† Ø§Ù„Ø´Ø­Ù† Ù…Ù†Ø° ' || coalesce(l.days_since_last, 0) || ' ÙŠÙˆÙ…',
      'Ø§ÙÙ‡Ù… Ø³Ø¨Ø¨ Ø§Ù„ØªÙˆÙ‚Ù ÙˆØ£Ø¹Ø¯ ØªÙ†Ø´ÙŠØ·Ù‡', 70 + least(8, coalesce(l.opportunity_score, 0) / 15), null::numeric
    from lifecycle l
    left join followups f on f.phone = l.phone
    where l.segment = 'stopped_recent'
      and l.days_since_last between 7 and 60
      and coalesce(f.status, '') not in ('converted', 'rejected', 'not_interested', 'blacklist', 'supplier', 'noise', 'test')

    union all
    select l.phone, l.name, l.store_id,
      'stopped_long', 'stopped_customer',
      'Ù…ØªÙˆÙ‚Ù Ø¹Ø§Ù„ÙŠ Ø§Ù„Ù‚ÙŠÙ…Ø© Ù…Ù†Ø° ' || coalesce(l.days_since_last, 0) || ' ÙŠÙˆÙ…',
      'Ø±Ø§Ø¬Ø¹ Ø³Ø¨Ø¨ Ø§Ù„ÙÙ‚Ø¯ Ø«Ù… Ù†ÙÙ‘Ø° Ù…Ø­Ø§ÙˆÙ„Ø© Ø§Ø³ØªØ¹Ø§Ø¯Ø©', 58 + least(8, coalesce(l.opportunity_score, 0) / 15), null::numeric
    from lifecycle l
    left join followups f on f.phone = l.phone
    where l.segment = 'stopped_long'
      and l.days_since_last between 61 and 180
      and l.lifecycle_priority in ('A', 'B')
      and coalesce(f.status, '') not in ('converted', 'rejected', 'not_interested', 'blacklist', 'supplier', 'noise', 'test')
  ),
  ranked as (
    select s.*,
      row_number() over (partition by s.phone order by s.priority desc, s.amount desc nulls last) as rn
    from signals s
    where s.phone is not null and s.phone <> ''
  ),
  contextual as (
    select r.*, f.owner_id::text, f.status as followup_status, f.last_touch_at,
      f.next_action_at, lc.sent_at as last_campaign_at, ll.called_at as last_call_at,
      (select uploaded_at from latest_snapshot) as source_snapshot_at,
      (b.phone is not null) as is_blocked
    from ranked r
    left join followups f on f.phone = r.phone
    left join last_campaign lc on lc.phone = r.phone
    left join last_call ll on ll.phone = r.phone
    left join blocked b on b.phone = r.phone
    where r.rn = 1
  ),
  guarded as (
    select c.*,
      case
        when c.phone !~ '^9665[0-9]{8}$' then 'invalid_phone'
        when c.is_blocked then 'blocked'
        when c.reason_code in ('hot_reply', 'reply', 'sla') then 'human_followup'
        when c.reason_code = 'stopped_long' then 'human_call'
        when c.next_action_at > now() or c.last_touch_at > now() - interval '3 days' then 'owner_followup'
        when c.last_campaign_at > now() - interval '7 days' then 'recent_campaign'
        when c.last_call_at > now() - interval '3 days' then 'recent_call'
        when c.journey in ('new_customer', 'stopped_customer')
          and c.source_snapshot_at < now() - interval '72 hours' then 'stale_source'
        else 'ready'
      end as guard_code
    from contextual c
  )
  select
    g.phone, g.name, g.store_id, g.owner_id, g.reason_code, g.journey,
    g.reason, g.action, g.priority, g.amount, g.followup_status, g.last_touch_at,
    case
      when g.reason_code in ('hot_reply', 'reply', 'sla') then 'call'
      when g.reason_code in ('wallet_neg', 'debt') then 'whatsapp_collections'
      when g.reason_code in ('stopped_long') then 'call'
      else 'whatsapp'
    end as recommended_channel,
    case
      when g.reason_code in ('wallet_neg', 'debt') then 'collections_reminder'
      when g.reason_code = 'new_registered' then 'welcome_activation'
      when g.reason_code = 'new_ready' then 'first_shipment'
      when g.reason_code in ('stopped_recent', 'stopped_long') then 'reactivation'
      else null
    end as recommended_template_key,
    (g.guard_code = 'ready') as send_eligible,
    g.guard_code,
    case g.guard_code
      when 'ready' then 'Ø¬Ø§Ù‡Ø² Ù„Ù„Ù…Ø±Ø§Ø¬Ø¹Ø© ÙˆØ§Ù„Ø¥Ø±Ø³Ø§Ù„'
      when 'invalid_phone' then 'Ø±Ù‚Ù… Ø§Ù„Ù‡Ø§ØªÙ ØºÙŠØ± ØµØ§Ù„Ø­ Ù„ÙˆØ§ØªØ³Ø§Ø¨'
      when 'blocked' then 'Ø§Ù„Ø±Ù‚Ù… ÙÙŠ Ù‚Ø§Ø¦Ù…Ø© Ø§Ù„Ø­Ø¸Ø±'
      when 'human_followup' then 'Ù‡Ø°Ù‡ Ù…ØªØ§Ø¨Ø¹Ø© Ø¨Ø´Ø±ÙŠØ© ÙˆÙ„ÙŠØ³Øª Ø±Ø³Ø§Ù„Ø© Ù‚Ø§Ù„Ø¨ Ø¬Ø¯ÙŠØ¯Ø©'
      when 'human_call' then 'Ù‡Ø°Ù‡ ÙØ±ØµØ© Ø§Ø³ØªØ¹Ø§Ø¯Ø© Ø¹Ø§Ù„ÙŠØ© Ø§Ù„Ù‚ÙŠÙ…Ø© ÙˆØªØ­ØªØ§Ø¬ Ø§ØªØµØ§Ù„Ù‹Ø§ Ø£ÙˆÙ„Ù‹Ø§'
      when 'owner_followup' then 'ØªÙˆØ¬Ø¯ Ù…ØªØ§Ø¨Ø¹Ø© Ù…ÙˆØ¸Ù Ø£Ùˆ ØªÙˆØ§ØµÙ„ Ø­Ø¯ÙŠØ«'
      when 'recent_campaign' then 'Ø£ÙØ±Ø³Ù„Øª Ù„Ù‡ Ø­Ù…Ù„Ø© Ø®Ù„Ø§Ù„ Ø¢Ø®Ø± 7 Ø£ÙŠØ§Ù…'
      when 'recent_call' then 'Ø¬Ø±Ù‰ Ø§ØªØµØ§Ù„ Ø¹Ø¨Ø± Ù‡Ø§ØªÙ Ø®Ù„Ø§Ù„ Ø¢Ø®Ø± 3 Ø£ÙŠØ§Ù…'
      when 'stale_source' then 'Ù„Ù‚Ø·Ø© Ø§Ù„Ù…ØªØ§Ø¬Ø± Ø£Ù‚Ø¯Ù… Ù…Ù† 72 Ø³Ø§Ø¹Ø©'
      else 'ØªØ­ØªØ§Ø¬ Ù…Ø±Ø§Ø¬Ø¹Ø©'
    end as guard_reason,
    g.last_campaign_at, g.last_call_at, g.source_snapshot_at
  from guarded g
  cross join access_guard a
  where a.allowed
    and (p_owner is null or g.owner_id = p_owner)
    and (p_journey is null or g.journey = p_journey)
  order by g.priority desc, g.amount desc nulls last
  limit greatest(1, least(coalesce(p_limit, 400), 1000));
$function$;
comment on function "public"."customer_engagement_next_actions"(p_limit integer, p_owner text, p_journey text) is 'Review-first customer engagement decisions across Lamha merchants, CRM, finance and Hatif. Never sends automatically.';
