CREATE OR REPLACE FUNCTION public.customer_money_dashboard()
 RETURNS json
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with latest_merch as materialized (
    select snapshot_id from merchants order by uploaded_at desc limit 1
  ),
  merch as materialized (
    select m.store_id, m.store_name, m.phone, normalize_arabic_name(m.store_name) norm,
           m.billing_type, m.status platform_status, m.wallet_balance, m.last_shipment_at
    from merchants m where m.snapshot_id = (select snapshot_id from latest_merch)
  ),
  links as materialized (
    select customer_name, store_id from customer_merchant_links where store_id is not null
  ),
  ar_base as materialized (
    select * from customer_ar
  ),
  collectible_lines as materialized (
    select * from customer_collectible_lines where collectible_amount > 0.005
  ),
  line_agg as materialized (
    select l.contact_name,
      sum(l.collectible_amount) filter (
        where l.line_kind = 'opening_balance' or lower(coalesce(l.status,'')) = 'overdue'
      ) as overdue_amt,
      count(*) filter (where l.line_kind = 'invoice' and l.collectible_amount > 0.5)::int as inv_cnt,
      max(l.age_days) filter (where l.collectible_amount > 0.005) as oldest_days,
      sum(l.collectible_amount) filter (where l.age_days between 0 and 15) as b0_15,
      sum(l.collectible_amount) filter (where l.age_days between 16 and 30) as b16_30,
      sum(l.collectible_amount) filter (where l.age_days between 31 and 60) as b1,
      sum(l.collectible_amount) filter (where l.age_days between 61 and 90) as b2,
      sum(l.collectible_amount) filter (where l.age_days > 90) as b3,
      sum(l.collectible_amount) filter (where l.line_kind = 'opening_balance') as opening_balance
    from collectible_lines l
    group by l.contact_name
  ),
  cust as materialized (
    select ar.contact_name customer_name,
      ar.zoho_id,
      ar.total_due gross_due,
      greatest(coalesce(ar.unused_credits,0),0) unused_credit,
      ar.credit_offset,
      ar.collectible_due owed,
      ar.credit_surplus,
      ar.needs_zoho_settlement,
      coalesce(a.overdue_amt,0) overdue_amt,
      coalesce(a.inv_cnt,0) inv_cnt,
      coalesce(a.oldest_days,0) oldest_days,
      coalesce(a.b0_15,0) b0_15,
      coalesce(a.b16_30,0) b16_30,
      coalesce(a.b1,0) b1, coalesce(a.b2,0) b2, coalesce(a.b3,0) b3,
      coalesce(a.opening_balance,0) opening_balance,
      greatest(coalesce(ar.opening_due,0),0) opening_gross
    from ar_base ar
    left join line_agg a on a.contact_name = ar.contact_name
    where ar.collectible_due > 0.5
  ),
  settlement_base as materialized (
    select ar.contact_name customer_name,
      ar.zoho_id,
      ar.total_due gross_due,
      greatest(coalesce(ar.unused_credits,0),0) unused_credit,
      ar.credit_offset,
      ar.collectible_due,
      ar.credit_surplus,
      greatest(coalesce(ar.opening_due,0),0) opening_gross,
      coalesce(a.opening_balance,0) opening_collectible
    from ar_base ar
    left join line_agg a on a.contact_name = ar.contact_name
    where ar.total_due > 0.5 and ar.credit_offset > 0.005
  ),
  last_pay as materialized (
    select customer_name,max(date) last_date
    from zoho_payments where customer_name is not null group by customer_name
  ),
  last_pay_amt as materialized (
    select p.customer_name,p.date,sum(p.amount) amount
    from zoho_payments p
    join last_pay lp on lp.customer_name=p.customer_name and p.date=lp.last_date
    group by p.customer_name,p.date
  ),
  cust_full as materialized (
    select distinct on (c.customer_name) c.*,lpa.date last_payment_date,lpa.amount last_payment_amount,
      m.store_id,m.phone,m.store_name,m.billing_type,m.platform_status,m.wallet_balance,m.last_shipment_at
    from cust c left join last_pay_amt lpa on lpa.customer_name=c.customer_name
    left join links l on l.customer_name=c.customer_name
    left join merch m on m.store_id=l.store_id or (l.store_id is null and m.norm=normalize_arabic_name(c.customer_name))
    order by c.customer_name,(l.store_id is not null) desc
  ),
  settlement_full as materialized (
    select distinct on (s.customer_name) s.*,m.store_id,m.phone,m.store_name
    from settlement_base s
    left join links l on l.customer_name=s.customer_name
    left join merch m on m.store_id=l.store_id or (l.store_id is null and m.norm=normalize_arabic_name(s.customer_name))
    order by s.customer_name,(l.store_id is not null) desc
  ),
  monthly_col as materialized (
    select to_char(date,'YYYY-MM') ym,sum(amount) amount,count(*)::int cnt
    from zoho_payments
    where date >= current_date-interval '12 months'
    group by 1 order by 1 desc
  )
  select json_build_object(
    'gross_outstanding',(select coalesce(round(sum(total_due)::numeric,2),0) from ar_base where total_due > 0.5),
    'credit_offset',(select coalesce(round(sum(credit_offset)::numeric,2),0) from ar_base where total_due > 0.5),
    'unused_credits',(select coalesce(round(sum(greatest(coalesce(unused_credits,0),0))::numeric,2),0) from ar_base),
    'credit_surplus',(select coalesce(round(sum(credit_surplus)::numeric,2),0) from ar_base),
    'outstanding',(select coalesce(round(sum(owed)::numeric,2),0) from cust),
    'outstanding_cnt',(select count(*) from cust),
    'settlement_count',(select count(*) from settlement_base),
    'settlement_total',(select coalesce(round(sum(credit_offset)::numeric,2),0) from settlement_base),
    'overdue_amt',(select coalesce(round(sum(overdue_amt)::numeric,2),0) from cust),
    'aging',json_build_object(
      'b0_15',(select coalesce(round(sum(b0_15)::numeric,2),0) from cust),
      'b16_30',(select coalesce(round(sum(b16_30)::numeric,2),0) from cust),
      'b0_30',(select coalesce(round(sum(b0_15 + b16_30)::numeric,2),0) from cust),
      'b31_60',(select coalesce(round(sum(b1)::numeric,2),0) from cust),
      'b61_90',(select coalesce(round(sum(b2)::numeric,2),0) from cust),
      'b90p',(select coalesce(round(sum(b3)::numeric,2),0) from cust),
      'opening_balance',(select coalesce(round(sum(opening_balance)::numeric,2),0) from cust),
      'opening_gross',(select coalesce(round(sum(opening_gross)::numeric,2),0) from cust)),
    'collected_this_month',(select coalesce(round(sum(amount)::numeric,2),0) from zoho_payments where date>=date_trunc('month',current_date) and date<date_trunc('month',current_date)+interval '1 month'),
    'collected_prev_month',(select coalesce(round(sum(amount)::numeric,2),0) from zoho_payments where date>=date_trunc('month',current_date)-interval '1 month' and date<date_trunc('month',current_date)),
    'monthly_collected',(select coalesce(json_agg(row_to_json(m)),'[]') from monthly_col m),
    'customers',(select coalesce(json_agg(json_build_object(
      'name',cf.customer_name,'zoho_id',cf.zoho_id,'store_name',cf.store_name,'store_id',cf.store_id,'phone',cf.phone,
      'gross_due',round(cf.gross_due::numeric,2),'unused_credit',round(cf.unused_credit::numeric,2),
      'credit_offset',round(cf.credit_offset::numeric,2),'credit_surplus',round(cf.credit_surplus::numeric,2),
      'needs_zoho_settlement',cf.needs_zoho_settlement,
      'owed',round(cf.owed::numeric,2),'overdue',coalesce(round(cf.overdue_amt::numeric,2),0),
      'inv_cnt',cf.inv_cnt,'oldest_days',cf.oldest_days,
      'b0_15',round(cf.b0_15::numeric,2),'b16_30',round(cf.b16_30::numeric,2),
      'b0',round((cf.b0_15 + cf.b16_30)::numeric,2),
      'b1',round(cf.b1::numeric,2),'b2',round(cf.b2::numeric,2),'b3',round(cf.b3::numeric,2),
      'opening_balance',round(cf.opening_balance::numeric,2),'opening_gross',round(cf.opening_gross::numeric,2),
      'last_payment_date',cf.last_payment_date,'last_payment_amount',coalesce(round(cf.last_payment_amount::numeric,2),0),
      'billing_type',cf.billing_type,'platform_status',cf.platform_status,
      'wallet_balance',round(coalesce(cf.wallet_balance,0)::numeric,2),'last_shipment_at',cf.last_shipment_at
    ) order by cf.owed desc),'[]') from cust_full cf),
    'settlements',(select coalesce(json_agg(json_build_object(
      'name',sf.customer_name,'zoho_id',sf.zoho_id,'store_name',sf.store_name,'store_id',sf.store_id,'phone',sf.phone,
      'gross_due',round(sf.gross_due::numeric,2),'unused_credit',round(sf.unused_credit::numeric,2),
      'credit_offset',round(sf.credit_offset::numeric,2),'collectible_due',round(sf.collectible_due::numeric,2),
      'credit_surplus',round(sf.credit_surplus::numeric,2),
      'opening_gross',round(sf.opening_gross::numeric,2),'opening_collectible',round(sf.opening_collectible::numeric,2),
      'covered_fully',sf.collectible_due <= 0.5
    ) order by sf.credit_offset desc),'[]') from settlement_full sf)
  );
$function$;
CREATE OR REPLACE FUNCTION public.employee_activity_log(p_user uuid, p_kind text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS SETOF user_activity_log
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
begin
  if not is_admin() then raise exception 'admins only'; end if;
  return query
    select * from user_activity_log
    where user_id = p_user and (p_kind is null or kind = p_kind)
    order by created_at desc
    limit least(coalesce(p_limit, 100), 500) offset greatest(coalesce(p_offset, 0), 0);
end $function$;
CREATE OR REPLACE FUNCTION public.employee_activity_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare out jsonb;
begin
  if not is_admin() then raise exception 'admins only'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'user_id', p.id,
    'last_sign_in', u.last_sign_in_at,
    'last_action', la.action, 'last_action_at', la.created_at,
    'last_ip', la.ip, 'last_country', la.country,
    'actions_7d', coalesce(c7.n, 0), 'denied_7d', coalesce(d7.n, 0)
  )), '[]'::jsonb) into out
  from profiles p
  left join auth.users u on u.id = p.id
  left join lateral (
    select action, created_at, ip, country from user_activity_log l
    where l.user_id = p.id order by created_at desc limit 1
  ) la on true
  left join lateral (
    select count(*) n from user_activity_log l
    where l.user_id = p.id and l.created_at > now() - interval '7 days'
  ) c7 on true
  left join lateral (
    select count(*) n from user_activity_log l
    where l.user_id = p.id and l.kind = 'denied' and l.created_at > now() - interval '7 days'
  ) d7 on true;
  return out;
end $function$;
CREATE OR REPLACE FUNCTION public.enforce_bank_transaction_action_permission()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if auth.role() = 'service_role' then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;
  if tg_op = 'INSERT' then
    if not public.crm_has_permission('bank.upload_statement') then raise exception 'not_allowed:bank.upload_statement'; end if;
    return new;
  elsif tg_op = 'DELETE' then
    if not public.crm_has_permission('bank.delete_transaction') then raise exception 'not_allowed:bank.delete_transaction'; end if;
    return old;
  end if;

  if (to_jsonb(new) - 'note' - 'updated_at') = (to_jsonb(old) - 'note' - 'updated_at') then
    if not public.app_has_any_permission(array['bank.edit_note','bank.upload_statement']) then raise exception 'not_allowed:bank.edit_note'; end if;
  elsif (to_jsonb(new) - 'classification_status' - 'classification_type' - 'matched_entity_type'
         - 'matched_entity_id' - 'matched_at' - 'classified_by' - 'classification_note'
         - 'zoho_import_status' - 'zoho_bank_account_id' - 'updated_at')
        = (to_jsonb(old) - 'classification_status' - 'classification_type' - 'matched_entity_type'
         - 'matched_entity_id' - 'matched_at' - 'classified_by' - 'classification_note'
         - 'zoho_import_status' - 'zoho_bank_account_id' - 'updated_at') then
    if not public.crm_has_permission('bank.reconcile') then raise exception 'not_allowed:bank.reconcile'; end if;
  elsif not public.crm_has_permission('bank.upload_statement') then
    raise exception 'not_allowed:bank.upload_statement';
  end if;
  return new;
end;
$function$;
CREATE OR REPLACE FUNCTION public.enforce_carrier_payment_action_permission()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if auth.role() = 'service_role' then return new; end if;
  if new.status is distinct from old.status
     or new.paid_at is distinct from old.paid_at
     or new.payment_ref is distinct from old.payment_ref then
    if not public.crm_has_permission('payments.allocate')
       and not public.crm_has_permission('bank.reconcile') then
      raise exception 'not_allowed:bank.reconcile_or_payments.allocate';
    end if;
  end if;
  return new;
end;
$function$;
CREATE OR REPLACE FUNCTION public.evaluate_hatif_call_commitments()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_updated integer := 0;
begin
  with candidate as (
    select
      commitment.id as commitment_id,
      matched.id as matched_call_id,
      matched.user_id as actual_agent_id,
      matched.user_name as actual_agent_name,
      matched.creation_time as attempted_at,
      matched.pickup_time as answered_at,
      case
        when matched.id is null and now() > commitment.window_end + interval '15 minutes'
          then 'missed'
        when matched.id is null then 'pending'
        when matched.creation_time <= commitment.window_end and matched.pickup_time is not null
          then 'on_time_answered'
        when matched.creation_time <= commitment.window_end
          then 'on_time_no_answer'
        when matched.pickup_time is not null
          then 'late_answered'
        else 'late_no_answer'
      end as next_status,
      case
        when matched.id is null
          or (commitment.expected_agent_id is null and commitment.expected_agent_name is null)
          then null
        when commitment.expected_agent_id is not null and matched.user_id is not null
          then commitment.expected_agent_id = matched.user_id
        when commitment.expected_agent_name is not null and matched.user_name is not null
          then lower(btrim(commitment.expected_agent_name)) = lower(btrim(matched.user_name))
        else null
      end as owner_match
    from public.hatif_call_commitments commitment
    left join lateral (
      select call_row.*
      from public.hatif_call_log call_row
      where call_row.contact_phone = commitment.phone
        and call_row.call_type = 2
        and call_row.id <> commitment.source_call_id
        and call_row.creation_time >= commitment.window_start
        and call_row.creation_time <= least(now(), commitment.window_end + interval '1 day')
      order by
        case
          when call_row.creation_time <= commitment.window_end and call_row.pickup_time is not null then 0
          when call_row.creation_time <= commitment.window_end then 1
          when call_row.pickup_time is not null then 2
          else 3
        end,
        call_row.creation_time asc,
        call_row.id asc
      limit 1
    ) matched on true
    where commitment.status in (
      'pending', 'on_time_no_answer', 'late_no_answer', 'missed'
    )
      and commitment.window_start is not null
      and commitment.window_end is not null
      -- يسمح بتقييم المزامنة التاريخية الحديثة دون مسح كامل السجل كل خمس دقائق.
      and commitment.window_end >= now() - interval '90 days'
  )
  update public.hatif_call_commitments commitment
  set
    status = candidate.next_status,
    matched_call_id = candidate.matched_call_id,
    actual_agent_id = candidate.actual_agent_id,
    actual_agent_name = candidate.actual_agent_name,
    attempted_at = candidate.attempted_at,
    answered_at = candidate.answered_at,
    owner_match = candidate.owner_match,
    evaluated_at = now(),
    updated_at = now()
  from candidate
  where commitment.id = candidate.commitment_id
    and (
      commitment.status is distinct from candidate.next_status
      or commitment.matched_call_id is distinct from candidate.matched_call_id
      or commitment.actual_agent_id is distinct from candidate.actual_agent_id
      or commitment.attempted_at is distinct from candidate.attempted_at
      or commitment.answered_at is distinct from candidate.answered_at
      or commitment.owner_match is distinct from candidate.owner_match
    );

  get diagnostics v_updated = row_count;
  return jsonb_build_object('updated', v_updated, 'evaluated_at', now());
end;
$function$;
comment on function "public"."evaluate_hatif_call_commitments"() is 'يطابق نافذة الاتصال بالمكالمة الصادرة الفعلية من هاتف ويثبت الموظف والتوقيت والرد.';
CREATE OR REPLACE FUNCTION public.forecast_receivables_rollup(p_horizon_days integer DEFAULT 30, p_terms_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
with prepared as (
  select
    (z.date + greatest(0, least(p_terms_days, 365)))::date as expected_date,
    coalesce(z.balance, 0)::numeric as balance
  from public.zoho_invoices z
  where z.balance > 0.5
    and z.date is not null
), buckets as (
  select expected_date, round(sum(balance), 2) as amount
  from prepared
  where expected_date >= current_date
    and expected_date <= current_date + greatest(1, least(p_horizon_days, 120))
  group by expected_date
  order by expected_date
)
select jsonb_build_object(
  'buckets', coalesce((
    select jsonb_agg(jsonb_build_object('date', expected_date, 'amount', amount) order by expected_date)
    from buckets
  ), '[]'::jsonb),
  'withinTotal', coalesce((select round(sum(amount), 2) from buckets), 0),
  'overdue', coalesce((select round(sum(balance), 2) from prepared where expected_date < current_date), 0)
);
$function$;
CREATE OR REPLACE FUNCTION public.global_entity_search(p_term text, p_limit integer DEFAULT 8)
 RETURNS TABLE(entity_kind text, payload jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
with params as (
  select
    btrim(regexp_replace(coalesce(p_term, ''), '[%,]+', ' ', 'g')) as term,
    regexp_replace(coalesce(p_term, ''), '\D', '', 'g') as digits,
    greatest(1, least(coalesce(p_limit, 8), 12)) as lim
), latest_snapshot as (
  select m.snapshot_id
  from public.merchants m
  order by m.uploaded_at desc
  limit 1
), merchant_hits as (
  select
    'merchant'::text as entity_kind,
    jsonb_build_object(
      'store_id', m.store_id,
      'store_name', m.store_name,
      'phone', m.phone,
      'status', m.status,
      'billing_type', m.billing_type,
      'shipment_count', m.shipment_count,
      'last_shipment_at', m.last_shipment_at,
      'wallet_balance', m.wallet_balance
    ) as payload,
    case
      when lower(m.store_name) = lower(p.term) or lower(m.store_id) = lower(p.term) then 0
      when lower(m.store_name) like lower(p.term) || '%' then 1
      else 2
    end as rank_no,
    coalesce(m.shipment_count, 0) as volume
  from public.merchants m
  cross join params p
  where m.snapshot_id = (select snapshot_id from latest_snapshot)
    and length(p.term) >= 2
    and (
      m.store_name ilike '%' || p.term || '%'
      or m.store_id ilike '%' || p.term || '%'
      or (length(p.digits) >= 4 and m.phone ilike '%' || p.digits || '%')
    )
  order by rank_no, volume desc
  limit (select lim from params)
), invoice_hits as (
  select
    'invoice'::text as entity_kind,
    jsonb_build_object(
      'zoho_id', z.zoho_id,
      'invoice_number', z.invoice_number,
      'customer_name', z.customer_name,
      'date', z.date,
      'due_date', z.due_date,
      'status', z.status,
      'total', z.total,
      'balance', z.balance
    ) as payload,
    case
      when lower(z.invoice_number) = lower(p.term) then 0
      when lower(z.invoice_number) like lower(p.term) || '%' then 1
      else 2
    end as rank_no,
    z.date
  from public.zoho_invoices z
  cross join params p
  where length(p.term) >= 2
    and (
      z.invoice_number ilike '%' || p.term || '%'
      or z.customer_name ilike '%' || p.term || '%'
    )
  order by rank_no, z.date desc nulls last
  limit (select lim from params)
)
select m.entity_kind, m.payload from merchant_hits m
union all
select i.entity_kind, i.payload from invoice_hits i;
$function$;
CREATE OR REPLACE FUNCTION public.guard_campaign_queue_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare perms jsonb; rol text;
begin
  if coalesce(auth.role(), '') = 'service_role' then return new; end if;
  select role, permissions into rol, perms from public.profiles where id = auth.uid();
  if rol = 'admin' or coalesce((perms->>'campaigns.send')::boolean, false) then
    return new;
  end if;
  raise exception 'إطلاق الحملات يتطلّب صلاحية campaigns.send';
end$function$;
CREATE OR REPLACE FUNCTION public.guard_closed_period()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_col text := TG_ARGV[0];
  v_date date;
  v_period text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    EXECUTE format('SELECT ($1).%I::date', v_col) USING OLD INTO v_date;
  ELSE
    EXECUTE format('SELECT ($1).%I::date', v_col) USING NEW INTO v_date;
  END IF;

  IF v_date IS NULL THEN
    -- Rows without a date are exempt — pre-existing data shouldn't
    -- be locked. The closing UI surfaces these so the operator can
    -- backfill before closing.
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  IF is_period_closed(v_date) THEN
    v_period := to_char(v_date, 'YYYY-MM');
    RAISE EXCEPTION 'الفترة % مُقفلة — أعد فتحها قبل التعديل', v_period
      USING ERRCODE = 'P0001', HINT = 'افتح /settings/periods وأعد فتح الفترة، ثم أعد المحاولة.';
  END IF;

  IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.guard_ivr_queue_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
