CREATE OR REPLACE FUNCTION public.guard_payment_allocation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_pay_amount numeric; v_offset numeric; v_pay_carrier text;
  v_alloc_total numeric; v_op_carrier text;
begin
  select amount, coalesce(credit_offset, 0), carrier_id
    into v_pay_amount, v_offset, v_pay_carrier
    from payments where id = new.payment_id;
  if v_pay_amount is null then
    raise exception 'الدفعة غير موجودة (payment_id=%)', new.payment_id;
  end if;

  if coalesce(new.amount, 0) <= 0 then
    raise exception 'مبلغ التوزيع يجب أن يكون موجباً';
  end if;

  select carrier_id into v_op_carrier from carrier_operations where id = new.operation_id;
  if v_op_carrier is not null and v_pay_carrier is not null and v_op_carrier <> v_pay_carrier then
    raise exception 'لا يجوز توزيع دفعة ناقل (%) على عملية ناقل آخر (%)', v_pay_carrier, v_op_carrier;
  end if;

  select coalesce(sum(amount), 0) into v_alloc_total
    from payment_allocations
    where payment_id = new.payment_id and (TG_OP = 'INSERT' or id <> new.id);

  if v_alloc_total + new.amount > v_pay_amount + v_offset + 0.01 then
    raise exception 'مجموع التوزيعات (%) يتجاوز الدفعة (%) + المقاصّة (%) — المتبقي %',
      round(v_alloc_total + new.amount, 2), round(v_pay_amount, 2), round(v_offset, 2),
      round(v_pay_amount + v_offset - v_alloc_total, 2);
  end if;

  return new;
end$function$;
CREATE OR REPLACE FUNCTION public.guard_platform_sales_financial_hold()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if exists(
    select 1 from public.v_platform_commercial_routing r
    where r.phone=new.phone and r.financial_hold
  ) then
    if tg_op='UPDATE' and new.sales_stage='disqualified' and new.next_action_at is null then
      return new;
    end if;
    raise exception 'financial_hold';
  end if;
  return new;
end;
$function$;
comment on function "public"."guard_platform_sales_financial_hold"() is 'Prevents sales followups from being inserted or changed while the platform account belongs to collections.';
CREATE OR REPLACE FUNCTION public.guard_profile_authorization_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if auth.role() = 'service_role' or public.is_admin() then
    return new;
  end if;
  if new.role is distinct from old.role
     or new.permissions is distinct from old.permissions then
    raise exception 'not_allowed:profile_authorization_fields';
  end if;
  return new;
end;
$function$;
CREATE OR REPLACE FUNCTION public.guard_profile_privilege_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if (new.role is distinct from old.role
      or new.permissions is distinct from old.permissions) then
    if not (coalesce(auth.role(), '') = 'service_role' or public.is_admin()) then
      raise exception 'تغيير الدور/الصلاحيات مسموح للمدير فقط';
    end if;
  end if;
  return new;
end$function$;
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  INSERT INTO public.profiles (id, email, name)
  VALUES (NEW.id, NEW.email, COALESCE(NEW.raw_user_meta_data->>'name', NEW.email))
  ON CONFLICT DO NOTHING;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.has_money_write()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select public.is_admin() or exists (
    select 1 from public.profiles p, jsonb_each(coalesce(p.permissions, '{}'::jsonb)) kv
    where p.id = auth.uid()
      and kv.value = 'true'::jsonb
      and (kv.key like 'audits.%' or kv.key like 'cod.%' or kv.key like 'bank.%'
        or kv.key like 'carriers.%' or kv.key like 'money.%' or kv.key like 'ledger.%'
        or kv.key like 'reconciliation.%' or kv.key like 'payments.%'
        or kv.key like 'uploads.%' or kv.key like 'internal_exports.%')
      -- مفاتيح القراءة لا تمنح كتابة
      and kv.key not like '%.view'
      and kv.key not like '%.view\_%'
      and kv.key not like '%.export'
      and kv.key not like '%.export\_%'
  );
$function$;
CREATE OR REPLACE FUNCTION public.hatif_agent_activity(p_days integer DEFAULT 30)
 RETURNS TABLE(agent_id text, events bigint, assignments bigint, conversations bigint, contacts bigint, last_at timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select assigned_user_id as agent_id,
         count(*) as events,
         count(*) filter (where event_type = 'AssignedUserIdChanged') as assignments,
         count(distinct conversation_id) as conversations,
         count(distinct contact_id) as contacts,
         max(received_at) as last_at
  from hatif_events
  where assigned_user_id is not null
    and received_at >= now() - make_interval(days => greatest(1, p_days))
  group by assigned_user_id
  order by count(*) desc;
$function$;
CREATE OR REPLACE FUNCTION public.hatif_call_agent_stats(p_days integer DEFAULT 30)
 RETURNS TABLE(user_id text, calls bigint, answered bigint, inbound bigint, outbound bigint, talk_seconds bigint, avg_talk numeric, avg_sentiment numeric, last_call timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select
    user_id,
    count(*)                                                     as calls,
    count(*) filter (where pickup_time is not null)             as answered,
    count(*) filter (where call_type = 1)                       as inbound,
    count(*) filter (where call_type = 2)                       as outbound,
    coalesce(sum(talk_seconds), 0)                              as talk_seconds,
    round(avg(talk_seconds) filter (where talk_seconds > 0), 1) as avg_talk,
    round(avg(sentiment) filter (where sentiment is not null), 2) as avg_sentiment,
    max(creation_time)                                          as last_call
  from hatif_call_log
  where creation_time > now() - make_interval(days => greatest(p_days, 1))
  group by user_id
  order by calls desc;
$function$;
CREATE OR REPLACE FUNCTION public.hatif_call_categories(t text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select array_remove(array[
    case when t ~ 'سعر|أسعار|تكلفة|غالي|أغلى|تنافس|مرتفع.{0,8}(سعر|تكلف)' then 'price' end,
    case when t ~ 'سجل تجاري|سجل التجاري' then 'cr_requirement' end,
    case when t ~ 'تأخر|تأخير|متأخر|لم تصل|ما وصل|توصيل.{0,8}(بطيء|متأخر)|سرعة التوصيل' then 'delivery' end,
    case when t ~ 'مفقود|فقدان|ضاع|ضايع|شحنة.{0,6}مفقود' then 'lost' end,
    case when t ~ 'خدمة العملاء|ما يرد|لا أحد يرد|تجاهل|صعوبة.{0,8}تواصل|لا يوجد دعم' then 'support' end,
    case when t ~ 'رجيع|إرجاع|ارجاع|استرجاع|مرتجع' then 'returns' end,
    case when t ~ 'فاتورة|فواتير|فوترة' then 'billing' end,
    case when t ~ 'ريد بوكس|red box|تفعيل شرك|شركات شحن إضاف|تفعيل.{0,10}شركة' then 'carriers' end,
    case when t ~ 'أغلق|إغلاق|مغلق|توقف النشاط|توقف العمل|أغلقت' then 'closed' end
  ], null);
$function$;
CREATE OR REPLACE FUNCTION public.hatif_call_ops()
 RETURNS TABLE(negative_7d bigint, negative_prev bigint, rising_category text, rising_now bigint, rising_delta bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with neg as (
    select
      count(*) filter (where creation_time > now() - interval '7 days') as n7,
      count(*) filter (where creation_time <= now() - interval '7 days' and creation_time > now() - interval '14 days') as nprev
    from hatif_call_log
    where sentiment <= 2 and talk_seconds > 40
      and ai_summary::text !~ 'رسالة ترحيبية|مركز اتصال|الرجاء اختيار|للاستمرار باللغة'
  ),
  prob as (
    select category, calls, (calls - calls_prev) as delta
    from hatif_call_problems(30)
    where (calls - calls_prev) > 0
    order by (calls - calls_prev) desc, calls desc
    limit 1
  )
  select neg.n7, neg.nprev,
    (select category from prob), (select calls from prob), (select delta from prob)
  from neg;
$function$;
CREATE OR REPLACE FUNCTION public.hatif_call_problems(p_days integer DEFAULT 60)
 RETURNS TABLE(category text, calls bigint, calls_prev bigint, avg_sentiment numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with base as (
    select ai_summary::text as t, sentiment, creation_time
    from hatif_call_log
    where ai_summary is not null and talk_seconds > 40
      and ai_summary::text !~ 'رسالة ترحيبية|مركز اتصال|الرجاء اختيار|للاستمرار باللغة'
      and creation_time > now() - make_interval(days => greatest(p_days,1) * 2)
  ), c as (
    select unnest(hatif_call_categories(t)) as cat, sentiment, creation_time from base
  )
  select cat,
    count(*) filter (where creation_time > now() - make_interval(days => greatest(p_days,1))),
    count(*) filter (where creation_time <= now() - make_interval(days => greatest(p_days,1))),
    round(avg(sentiment) filter (where sentiment is not null), 2)
  from c group by cat
  having count(*) filter (where creation_time > now() - make_interval(days => greatest(p_days,1))) > 0
  order by 2 desc;
$function$;
CREATE OR REPLACE FUNCTION public.hatif_contact_labels()
 RETURNS TABLE(phone text, name text, store_count integer, store_names text[], tags text[], note text, debt numeric, wallet numeric, shipments bigint, days_since_last integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with latest as (select snapshot_id from public.merchants order by uploaded_at desc limit 1),
  debt_by_phone as (
    select phone, sum(bal) as debt from (
      select distinct public.norm_sa_phone(m.phone) as phone, d.customer_name, d.bal
      from (select contact_name customer_name, total_due bal from public.customer_ar where total_due > 0.5) d
      join public.customer_merchant_links cml on cml.customer_name = d.customer_name
      join public.merchants m on m.store_id = cml.store_id and m.snapshot_id = (select snapshot_id from latest)
      where public.norm_sa_phone(m.phone) is not null
    ) x group by phone
  ),
  base as (
    select public.norm_sa_phone(v.phone) as np, v.*
    from public.v_crm_retargeting v
    where public.norm_sa_phone(v.phone) is not null
      and (public.norm_sa_phone(v.phone) ~ '^9665[0-9]{8}$'
        or (left(public.norm_sa_phone(v.phone), 3) <> '966'
            and length(public.norm_sa_phone(v.phone)) between 10 and 15))
  ),
  agg as (
    select b.np, sum(b.total_shipments)::bigint as shipments, round(sum(b.wallet), 2) as wallet,
      sum(b.store_count)::int as store_count, min(b.days_since_last) as days_since_last
    from base b group by b.np
  ),
  names as (
    select b.np, array_agg(distinct sn.name) as store_names
    from base b, lateral unnest(coalesce(b.store_names, array[]::text[])) as sn(name)
    group by b.np
  ),
  dom as (
    select distinct on (np) np, primary_store, segment, billing_type
    from base order by np, total_shipments desc nulls last
  )
  select
    a.np as phone,
    d.primary_store || case when a.store_count > 1 then ' (+' || (a.store_count - 1) || ' متاجر)' else '' end as name,
    a.store_count,
    coalesce(n.store_names, array[]::text[]) as store_names,
    array_remove(array[
      case when a.shipments >= 300 then 'VIP' end,
      case when d.segment = 'active' then 'نشط' end,
      case when d.segment in ('stopped_recent','stopped_long') then 'متوقف' end,
      case when d.segment in ('new_active','registered_no_ship','linked_no_ship') then 'جديد' end,
      case when coalesce(db.debt,0) > 0.5 then 'عليه مديونية' end,
      case when a.wallet < -0.5 then 'رصيد سالب' end,
      case when d.billing_type = 'دفع مسبق' then 'دفع مسبق'
           when d.billing_type = 'دفع لاحق' then 'دفع لاحق' end
    ], null) as tags,
    'المتاجر: ' || array_to_string(coalesce(n.store_names, array[]::text[]), ' · ')
      || ' | شحنات: ' || a.shipments::text
      || case when a.days_since_last is not null then ' | آخر شحنة: ' || a.days_since_last || 'ي' else '' end
      || case when coalesce(db.debt,0) > 0.5 then ' | دين: ' || round(db.debt)::text else '' end
      || case when a.wallet < -0.5 then ' | محفظة: ' || round(a.wallet)::text else '' end as note,
    coalesce(db.debt, 0)::numeric as debt,
    a.wallet, a.shipments, a.days_since_last
  from agg a
  join dom d on d.np = a.np
  left join names n on n.np = a.np
  left join debt_by_phone db on db.phone = a.np;
$function$;
CREATE OR REPLACE FUNCTION public.hatif_contact_profile()
 RETURNS TABLE(phone text, name text, status_val text, class_val text, debt_val text, debt numeric, wallet numeric, store_count integer, shipments bigint, last_shipment_at date, joined_at date, details text, followup_val text, followup_note text, whatsapp_val text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with latest as (select snapshot_id from public.merchants order by uploaded_at desc limit 1),
  store_debt as (
    select distinct on (cml.customer_name) cml.store_id, d.bal
    from (select contact_name customer_name, total_due bal from public.customer_ar where total_due > 0.5) d
    join public.customer_merchant_links cml on cml.customer_name = d.customer_name
    join public.merchants m on m.store_id = cml.store_id and m.snapshot_id = (select snapshot_id from latest)
    order by cml.customer_name, m.shipment_count desc nulls last
  ),
  s as (
    select public.norm_sa_phone(m.phone) as np, m.store_id, m.store_name,
           coalesce(m.shipment_count, 0) as ships, m.last_shipment_at::date as last_ship,
           m.created_at_platform::date as joined, m.status, m.billing_type,
           coalesce(m.wallet_balance, 0) as wal, coalesce(sd.bal, 0) as sdebt
    from public.merchants m
    left join store_debt sd on sd.store_id = m.store_id
    where m.snapshot_id = (select snapshot_id from latest)
      and public.norm_sa_phone(m.phone) is not null
      and (public.norm_sa_phone(m.phone) ~ '^9665[0-9]{8}$'
           or (left(public.norm_sa_phone(m.phone), 3) <> '966'
               and length(public.norm_sa_phone(m.phone)) between 10 and 15))
  ),
  agg as (
    select np, sum(ships)::bigint as shipments, round(sum(wal), 2) as wallet,
      round(sum(sdebt), 2) as debt, count(*)::int as store_count,
      max(last_ship) as last_shipment_at, min(joined) as joined_at,
      bool_or(status = 'نشط') as any_active
    from s group by np
  ),
  dom as (select distinct on (np) np, store_name, billing_type from s order by np, ships desc nulls last),
  det as (
    select np, string_agg(line, ' | ' order by ships desc) as details
    from (
      select np, ships,
        store_name || ' — ' || case when ships = 0 then 'لم يشحن' else ships || ' شحنة' end
        || case when last_ship is not null then ' · آخر شحنة ' || to_char(last_ship, 'YYYY-MM-DD') else '' end
        || case when sdebt > 0.5 then ' · عليه ' || round(sdebt)::text || ' ر.س' else ' · لا مديونية' end
        || case when status is not null and status <> 'نشط' then ' · (' || status || ')' else '' end as line
      from s
    ) x group by np
  ),
  wa as (
    select phone, bool_or(delivered_at is not null or read_at is not null or replied_at is not null) as delivered
    from public.whatsapp_campaign_sends where phone is not null group by phone
  )
  select a.np as phone, d.store_name as name,
    case when a.shipments = 0 then 'جديد' when a.any_active then 'نشط' else 'متوقف' end as status_val,
    case when a.shipments >= 300 then 'VIP' else 'عادي' end as class_val,
    case when a.debt > 0.5 then 'عليه مديونية' else 'سليم' end as debt_val,
    a.debt, a.wallet, a.store_count, a.shipments, a.last_shipment_at, a.joined_at,
    case when a.store_count > 1 then a.store_count || ' متاجر: ' else '' end || t.details as details,
    case fu.status
      when 'needs_followup' then 'متابعة مطلوبة' when 'interested' then 'مهتم'
      when 'converted' then 'تحوّل' when 'returned' then 'تحوّل'
      when 'not_interested' then 'غير مهتم' when 'blacklist' then 'بلاك لست'
      when 'whatsapp_sent' then 'تم التواصل' else null end as followup_val,
    nullif(trim(coalesce(fu.notes, '')
      || case when fu.next_action_at is not null then ' · موعد المتابعة: ' || to_char(fu.next_action_at, 'YYYY-MM-DD') else '' end
      || case when pr.name is not null then ' · المسؤول: ' || pr.name else '' end), '') as followup_note,
    case when wa.delivered then 'نعم' when nw.phone is not null then 'لا' else null end as whatsapp_val
  from agg a
  join dom d on d.np = a.np
  left join det t on t.np = a.np
  left join public.retargeting_followups fu on fu.phone = a.np
  left join public.profiles pr on pr.id = fu.owner_id
  left join wa on wa.phone = a.np
  left join public.v_no_whatsapp nw on nw.phone = a.np;
$function$;
CREATE OR REPLACE FUNCTION public.hatif_lead_names()
 RETURNS TABLE(phone text, name text, platform text, city text, category text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with latest as (select snapshot_id from merchants order by uploaded_at desc limit 1),
  conv as (select distinct phone from whatsapp_campaign_sends where conversation_id is not null),
  merch as (
    select distinct norm_sa_phone(phone) ph
    from merchants where snapshot_id = (select snapshot_id from latest) and phone is not null
  )
  select distinct on (l.whatsapp_normalized)
    l.whatsapp_normalized as phone,
    trim(l.name) as name,
    l.platform, l.city, l.category
  from crm_leads l
  join conv c on c.phone = l.whatsapp_normalized
  where l.whatsapp_normalized is not null
    and coalesce(trim(l.name), '') <> ''
    and l.whatsapp_normalized ~ '^9665[0-9]{8}$'
    and not exists (select 1 from merch m where m.ph = l.whatsapp_normalized)
  order by l.whatsapp_normalized, l.created_at desc nulls last;
$function$;
CREATE OR REPLACE FUNCTION public.hatif_leads_enriched()
 RETURNS TABLE(phone text, contact_id text, hatif_name text, named_manually boolean, phone_kind text, created_at_hatif timestamp with time zone, last_seen timestamp with time zone, lead_id text, lead_name text, platform text, category text, city text, lead_matched boolean, status text, owner_id uuid, note text, next_action_at timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select
    h.phone, h.contact_id, h.name as hatif_name, h.named_manually,
    h.phone_kind, h.created_at_hatif, h.last_seen,
    lm.id::text as lead_id, lm.name as lead_name, lm.platform, lm.category, lm.city,
    (lm.id is not null) as lead_matched,
    f.status, f.owner_id, f.notes as note, f.next_action_at
  from hatif_unknown_contacts h
  cross join lateral (select norm_sa_phone(h.phone) as np) n
  left join lateral (
    select * from (
      select id, name, platform, category, city, updated_at
        from crm_leads where whatsapp_normalized = n.np
      union all
      select id, name, platform, category, city, updated_at
        from crm_leads where phone_normalized = n.np
    ) x
    order by x.updated_at desc nulls last
    limit 1
  ) lm on true
  left join retargeting_followups f on f.phone = h.phone
  order by h.phone;
$function$;
CREATE OR REPLACE FUNCTION public.hatif_phone_tags()
 RETURNS TABLE(phone text, tags text[])
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with latest as (select max(snapshot_id) sid from merchants),
  convs as (select distinct phone from whatsapp_campaign_sends where conversation_id is not null),
  mnorm as (
    select norm_sa_phone(phone) ph, coalesce(shipment_count,0) shipment_count, status,
      last_shipment_at, billing_type, wallet_balance, created_at_platform,
      row_number() over (partition by norm_sa_phone(phone) order by coalesce(shipment_count,0) desc) rn
    from merchants where snapshot_id = (select sid from latest) and phone is not null
  ),
  prim as (select * from mnorm where rn = 1),
  agg  as (select ph, max(shipment_count) max_ship, min(wallet_balance) min_wallet from mnorm group by ph),
  linkph as (
    select distinct norm_sa_phone(m.phone) ph,
           lower(regexp_replace(coalesce(l.customer_name,''),'\s+','','g')) cname
    from customer_merchant_links l
    join merchants m on m.store_id = l.store_id and m.snapshot_id = (select sid from latest)
    where norm_sa_phone(m.phone) is not null
  ),
  ar as (
    select lower(regexp_replace(coalesce(contact_name,''),'\s+','','g')) cname,
           total_due, opening_due, days_oldest
    from customer_ar where total_due > 0.5
  ),
  debt as (select distinct lp.ph from linkph lp join ar on ar.cname = lp.cname),
  overdue as (
    select distinct lp.ph from linkph lp join ar on ar.cname = lp.cname
    where ar.opening_due > 0.5 or ar.days_oldest > 45
  ),
  leadph as (select distinct whatsapp_normalized ph from crm_leads where whatsapp_normalized is not null),
  blk as (select distinct norm_sa_phone(phone) ph from campaign_phone_blocklist where phone is not null)
  select c.phone,
    array_remove(array[
      case when dbt.ph is not null then 'عليه مديونية' end,
      case when od.ph is not null then 'متأخر سداد' end,
      case when ag.min_wallet < -0.5 then 'رصيد سالب' end,
      case when ag.max_ship > 1000 then 'VIP' end,
      case when pr.status = 'نشط' then 'نشط' end,
      case when pr.status = 'غير نشط' and pr.shipment_count > 0 then 'متوقف' end,
      case when pr.shipment_count = 0 and pr.created_at_platform is not null and pr.created_at_platform >= (now() - interval '30 days') then 'جديد' end,
      case when pr.billing_type = 'دفع مسبق' then 'دفع مسبق' end,
      case when pr.billing_type = 'دفع لاحق' then 'دفع لاحق' end,
      case when pr.ph is null and lp.ph is not null then 'عميل محتمل' end,
      case when bl.ph is not null then 'بلاك لست' end
    ], null) as tags
  from convs c
  left join prim pr on pr.ph = c.phone
  left join agg  ag on ag.ph = c.phone
  left join debt dbt on dbt.ph = c.phone
  left join overdue od on od.ph = c.phone
  left join leadph lp on lp.ph = c.phone
  left join blk bl on bl.ph = c.phone
  order by c.phone;
$function$;
CREATE OR REPLACE FUNCTION public.hatif_problem_calls(p_category text, p_days integer DEFAULT 60, p_limit integer DEFAULT 40)
 RETURNS TABLE(id text, user_id text, creation_time timestamp with time zone, talk_seconds integer, sentiment integer, recording_url text, ai_summary jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select id, user_id, creation_time, talk_seconds, sentiment, recording_url, ai_summary
  from hatif_call_log
  where ai_summary is not null and talk_seconds > 40
    and ai_summary::text !~ 'رسالة ترحيبية|مركز اتصال|الرجاء اختيار|للاستمرار باللغة'
    and creation_time > now() - make_interval(days => greatest(p_days,1))
    and p_category = any(hatif_call_categories(ai_summary::text))
  order by creation_time desc
  limit greatest(p_limit,1);
$function$;
CREATE OR REPLACE FUNCTION public.hatif_touched_phones(p_days integer DEFAULT 30)
 RETURNS TABLE(phone text, last_touch timestamp with time zone, human_assigned boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with conv as (
    select conversation_id, contact_id,
           max(received_at) filter (where event_type = 'AssignedUserIdChanged'
                                      and assigned_user_id is not null) assigned_at,
           max(received_at) filter (where event_type = 'StatusChanged'
                                      and status = 2)                   closed_at
    from hatif_events
    where received_at > now() - make_interval(days => greatest(p_days, 1))
    group by conversation_id, contact_id
  ),
  -- المفتوحة فقط: أُسنِدت ولم تُغلق بعد الإسناد
  ev as (
    select conversation_id, contact_id, assigned_at as received_at
    from conv
    where assigned_at is not null
      and (closed_at is null or closed_at <= assigned_at)
  ),
  mapped as (
    select norm_sa_phone(coalesce(w1.phone, w2.phone, cs.phone, cp.phone)) as phone, ev.received_at
    from ev
    left join lateral (select w.phone from whatsapp_campaign_sends w
                       where w.conversation_id = ev.conversation_id and w.phone is not null limit 1) w1 on true
    left join lateral (select w.phone from whatsapp_campaign_sends w
                       where w.contact_id = ev.contact_id and w.phone is not null limit 1) w2 on true
    left join lateral (select cs.phone from hatif_contact_sync cs
                       where cs.contact_id = ev.contact_id and cs.phone is not null limit 1) cs on true
    left join lateral (select cp.phone from hatif_contact_phones cp
                       where cp.contact_id = ev.contact_id and cp.phone is not null limit 1) cp on true
  )
  select phone, max(received_at) as last_touch, true as human_assigned
  from mapped
  where phone is not null and phone <> ''
  group by phone;
$function$;
CREATE OR REPLACE FUNCTION public.hub_rollup()
 RETURNS TABLE(carrier_id text, name text, logo text, color text, contracts jsonb, file_signature jsonb, total_dr numeric, total_cr numeric, open_balance numeric, doc_counts jsonb, pending_audits integer, draft_audits integer, approved_audits integer, webhook_pending integer, webhook_total integer, settlements_count integer, last_activity_at timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH ops AS (
    SELECT
      co.carrier_id,
      coalesce(SUM(co.amount_dr), 0) AS total_dr,
      coalesce(SUM(co.amount_cr), 0) AS total_cr,
      coalesce(SUM(co.amount_dr - co.amount_cr) FILTER (WHERE co.status IS DISTINCT FROM 'paid'), 0) AS open_balance,
      jsonb_build_object(
        'INV',   COUNT(*) FILTER (WHERE upper(coalesce(co.doc_type,'')) = 'INV'),
        'COD',   COUNT(*) FILTER (WHERE upper(coalesce(co.doc_type,'')) = 'COD'),
        'PAY',   COUNT(*) FILTER (WHERE upper(coalesce(co.doc_type,'')) = 'PAY'),
        'ADJ',   COUNT(*) FILTER (WHERE upper(coalesce(co.doc_type,'')) = 'ADJ'),
        'OTHER', COUNT(*) FILTER (WHERE upper(coalesce(co.doc_type,'')) NOT IN ('INV','COD','PAY','ADJ'))
      ) AS doc_counts,
      MAX(coalesce(co.updated_at, co.doc_date::timestamptz)) AS last_at
    FROM carrier_operations co
    GROUP BY co.carrier_id
  ),
  aud AS (
    SELECT a.carrier_id,
      COUNT(*) FILTER (WHERE coalesce(a.review_status,'pending') = 'pending')::int AS pending,
      COUNT(*) FILTER (WHERE a.review_status = 'draft')::int                       AS draft,
      COUNT(*) FILTER (WHERE a.review_status = 'approved')::int                    AS approved,
      MAX(a.created_at) AS last_at
    FROM audits a GROUP BY a.carrier_id
  ),
  wh AS (
    SELECT w.detected_carrier_id AS carrier_id,
      COUNT(*)::int                                                              AS total,
      COUNT(*) FILTER (WHERE w.status IN ('awaiting_assignment','pending'))::int AS pending,
      MAX(w.received_at)                                                         AS last_at
    FROM webhook_events w WHERE w.detected_carrier_id IS NOT NULL GROUP BY w.detected_carrier_id
  ),
  st AS (
    SELECT s.carrier_id, COUNT(*)::int AS cnt,
      MAX(coalesce(s.created_at, s.upload_date::timestamptz)) AS last_at
    FROM cod_settlement s GROUP BY s.carrier_id
  )
  SELECT
    c.id, c.name, c.logo, c.color, c.contracts, c.file_signature,
    coalesce(o.total_dr, 0)::numeric,
    coalesce(o.total_cr, 0)::numeric,
    coalesce(o.open_balance, 0)::numeric,
    coalesce(o.doc_counts, '{"INV":0,"COD":0,"PAY":0,"ADJ":0,"OTHER":0}'::jsonb),
    coalesce(a.pending, 0), coalesce(a.draft, 0), coalesce(a.approved, 0),
    coalesce(w.pending, 0), coalesce(w.total, 0), coalesce(s.cnt, 0),
    GREATEST(o.last_at, a.last_at, w.last_at, s.last_at)
  FROM carriers c
  LEFT JOIN ops o ON o.carrier_id = c.id
  LEFT JOIN aud a ON a.carrier_id = c.id
  LEFT JOIN wh  w ON w.carrier_id = c.id
  LEFT JOIN st  s ON s.carrier_id = c.id
  ORDER BY c.name;
$function$;
CREATE OR REPLACE FUNCTION public.hudhud_can_review_leads()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.profiles p
    where p.id = auth.uid()
      and (
        p.role = 'admin'
        or coalesce((p.permissions->>'sales.external_leads')::boolean, false)
        or coalesce((p.permissions->>'crm.upload_leads')::boolean, false)
      )
  );
$function$;
CREATE OR REPLACE FUNCTION public.ingest_google_campaign_lead(p_external_event_id text, p_payload_hash text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_event public.campaign_lead_inbox%rowtype;
  v_lead public.crm_leads%rowtype;
  v_owner public.profiles%rowtype;
  v_name text := nullif(btrim(coalesce(p_payload->>'name', p_payload->>'Ø§Ù„Ø§Ø³Ù…', '')), '');
  v_phone text := regexp_replace(coalesce(p_payload->>'phone', p_payload->>'Ø§Ù„Ø¬ÙˆØ§Ù„', p_payload->>'Ø±Ù‚Ù… Ø§Ù„Ø¬ÙˆØ§Ù„', ''), '\D', '', 'g');
  v_campaign text := nullif(btrim(coalesce(p_payload->>'campaign_name', p_payload->>'campaign', p_payload->>'Ø§Ø³Ù… Ø§Ù„Ø­Ù…Ù„Ø©', '')), '');
  v_city text := nullif(btrim(coalesce(p_payload->>'city', p_payload->>'Ø§Ù„Ù…Ø¯ÙŠÙ†Ø©', '')), '');
  v_email text := nullif(btrim(coalesce(p_payload->>'email', p_payload->>'Ø§Ù„Ø¨Ø±ÙŠØ¯ Ø§Ù„Ø¥Ù„ÙƒØªØ±ÙˆÙ†ÙŠ', '')), '');
  v_category text := nullif(btrim(coalesce(p_payload->>'category', p_payload->>'activity', p_payload->>'Ø§Ù„Ù†Ø´Ø§Ø·', '')), '');
begin
  if nullif(btrim(coalesce(p_external_event_id, '')), '') is null then
    raise exception 'external_event_id_required';
  end if;
  if v_name is null or v_phone = '' then raise exception 'name_and_phone_required'; end if;
  if left(v_phone, 2) = '00' then v_phone := substr(v_phone, 3); end if;
  if left(v_phone, 3) <> '966' and length(v_phone) = 10 and left(v_phone, 2) = '05' then
    v_phone := '966' || substr(v_phone, 2);
  elsif left(v_phone, 3) <> '966' and length(v_phone) = 9 and left(v_phone, 1) = '5' then
    v_phone := '966' || v_phone;
  end if;
  if v_phone !~ '^9665[0-9]{8}$' then raise exception 'invalid_sa_phone'; end if;

  insert into public.campaign_lead_inbox(source, external_event_id, payload_hash, payload)
  values ('google_sheets', btrim(p_external_event_id), p_payload_hash, p_payload)
  on conflict (source, external_event_id) do nothing
  returning * into v_event;

  if v_event.id is null then
    select * into v_event from public.campaign_lead_inbox
    where source='google_sheets' and external_event_id=btrim(p_external_event_id);
    return jsonb_build_object('ok', true, 'duplicate_event', true, 'inbox_id', v_event.id,
      'lead_id', v_event.lead_id, 'status', v_event.status, 'notification_status', v_event.notification_status);
  end if;

  -- Serialize round-robin selection and assignment.
  perform pg_advisory_xact_lock(hashtext('google_campaign_lead_assignment'));

  select * into v_lead from public.crm_leads
  where phone_normalized = v_phone
    and lead_kind = 'inbound'
    and status not in ('converted','activated','lost','existing_customer')
  order by received_at desc limit 1;

  if v_lead.id is not null then
    update public.campaign_lead_inbox set status='duplicate', lead_id=v_lead.id,
      assigned_to=v_lead.owner_id, notification_status='skipped', processed_at=now()
    where id=v_event.id;
    return jsonb_build_object('ok', true, 'duplicate_lead', true, 'inbox_id', v_event.id,
      'lead_id', v_lead.id, 'assigned_to', v_lead.owner_id);
  end if;

  select p.* into v_owner from public.profiles p
  where p.accepts_campaign_leads = true
    and nullif(btrim(p.lead_notification_phone), '') is not null
    and (p.role='admin' or coalesce((p.permissions->>'sales.external_leads')::boolean,false)
         or coalesce((p.permissions->>'sales.manage')::boolean,false))
  order by p.last_campaign_lead_assigned_at asc nulls first, p.created_at asc
  limit 1;

  insert into public.crm_leads(
    name, name_normalized, phone, phone_normalized, whatsapp, whatsapp_normalized,
    email, city, category, source, source_channel, lead_kind, campaign_name,
    campaign_meta, raw_payload, snapshot_id, status, owner_id, received_at,
    first_response_due_at
  ) values (
    v_name, lower(v_name), v_phone, v_phone, v_phone, v_phone,
    v_email, v_city, v_category, 'google_campaign', 'google_sheets', 'inbound', v_campaign,
    jsonb_strip_nulls(jsonb_build_object(
      'utm_source', p_payload->>'utm_source', 'utm_medium', p_payload->>'utm_medium',
      'utm_campaign', p_payload->>'utm_campaign', 'utm_content', p_payload->>'utm_content',
      'utm_term', p_payload->>'utm_term', 'google_event_id', p_external_event_id,
      'expected_shipments', coalesce(p_payload->>'expected_shipments', p_payload->>'Ø¹Ø¯Ø¯ Ø§Ù„Ø´Ø­Ù†Ø§Øª Ø§Ù„Ù…ØªÙˆÙ‚Ø¹')
    )), p_payload, 'google:' || btrim(p_external_event_id), 'new', v_owner.id, now(), now() + interval '15 minutes'
  ) returning * into v_lead;

  if v_owner.id is not null then
    update public.profiles set last_campaign_lead_assigned_at=now() where id=v_owner.id;
    insert into public.crm_tasks(entity_type, entity_ref, title, kind, due_at, priority, assigned_to)
    values ('lead', v_lead.id::text, 'Ø§Ù„ØªÙˆØ§ØµÙ„ Ø§Ù„Ø£ÙˆÙ„ Ù…Ø¹ Ø¹Ù…ÙŠÙ„ Ø§Ù„Ø­Ù…Ù„Ø©', 'first_contact',
      v_lead.first_response_due_at, 'high', v_owner.id);
  end if;

  update public.campaign_lead_inbox set status='created', lead_id=v_lead.id,
    assigned_to=v_owner.id,
    notification_status=case when v_owner.id is null then 'skipped' else 'pending' end,
    notification_error=case when v_owner.id is null then 'no_eligible_assignee' end,
    processed_at=now()
  where id=v_event.id;

  return jsonb_build_object('ok', true, 'created', true, 'inbox_id', v_event.id,
    'lead_id', v_lead.id, 'assigned_to', v_owner.id,
    'assignee_name', v_owner.name, 'assignee_phone', v_owner.lead_notification_phone,
    'lead_name', v_lead.name, 'lead_phone', v_lead.phone_normalized,
    'campaign_name', v_lead.campaign_name, 'city', v_lead.city, 'category', v_lead.category);
exception when others then
  if v_event.id is not null then
    update public.campaign_lead_inbox set status='failed', notification_status='skipped',
      notification_error=sqlerrm, processed_at=now() where id=v_event.id;
  end if;
  raise;
end;
$function$;
comment on function "public"."ingest_google_campaign_lead"(p_external_event_id text, p_payload_hash text, p_payload jsonb) is 'Idempotent Google campaign intake into internal CRM. Never creates or updates Zoho customers.';
CREATE OR REPLACE FUNCTION public.ingest_platform_merchant_snapshot(p_event_id text, p_snapshot_at timestamp with time zone, p_payload_hash text, p_rows jsonb, p_source text DEFAULT 'platform_webhook'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_existing public.platform_snapshot_receipts%rowtype;
  v_snapshot_id text;
  v_received_at timestamptz := clock_timestamp();
  v_row_count integer;
  v_previous_row_count integer;
  v_inserted integer;
  v_lifecycle jsonb;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'not_allowed';
  end if;

  if p_event_id is null or length(btrim(p_event_id)) < 8 or length(p_event_id) > 160 then
    raise exception 'invalid_event_id';
  end if;
  if p_snapshot_at is null
     or p_snapshot_at < now() - interval '7 days'
     or p_snapshot_at > now() + interval '10 minutes' then
    raise exception 'invalid_snapshot_at';
  end if;
  if p_payload_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid_payload_hash';
  end if;
  if jsonb_typeof(p_rows) <> 'array' then
    raise exception 'rows_must_be_array';
  end if;

  v_row_count := jsonb_array_length(p_rows);
  if v_row_count < 1 or v_row_count > 5000 then
    raise exception 'invalid_row_count';
  end if;

  select count(*)::int
  into v_previous_row_count
  from public.merchants
  where snapshot_id = (
    select snapshot_id from public.merchants order by uploaded_at desc limit 1
  );

  -- حماية من أن تصبح دفعة جزئية هي «أحدث لقطة» فتُسقط العملاء من كل التحليلات.
  if v_previous_row_count >= 100
     and (
       v_row_count < floor(v_previous_row_count * 0.60)
       or v_row_count > ceil(v_previous_row_count * 1.50)
     ) then
    raise exception 'suspicious_row_count_change';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_event_id, 0));

  select * into v_existing
  from public.platform_snapshot_receipts
  where event_id = p_event_id;

  if found then
    if v_existing.payload_hash <> p_payload_hash then
      raise exception 'idempotency_conflict';
    end if;
    return jsonb_build_object(
      'status', 'duplicate',
      'event_id', v_existing.event_id,
      'snapshot_id', v_existing.snapshot_id,
      'row_count', v_existing.row_count,
      'received_at', v_existing.received_at,
      'lifecycle', v_existing.lifecycle
    );
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_rows) item
    where nullif(btrim(item->>'store_id'), '') is null
       or nullif(btrim(item->>'store_name'), '') is null
       or nullif(btrim(item->>'phone'), '') is null
  ) then
    raise exception 'missing_required_merchant_field';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_rows) item
    group by btrim(item->>'store_id')
    having count(*) > 1
  ) then
    raise exception 'duplicate_store_id';
  end if;

  v_snapshot_id := 'api_' || left(
    encode(extensions.digest(convert_to(p_event_id, 'UTF8'), 'sha256'), 'hex'),
    32
  );

  insert into public.platform_snapshot_receipts (
    event_id, payload_hash, snapshot_id, snapshot_at, source, row_count, received_at
  ) values (
    p_event_id, p_payload_hash, v_snapshot_id, p_snapshot_at,
    coalesce(nullif(btrim(p_source), ''), 'platform_webhook'), v_row_count, v_received_at
  );

  insert into public.merchants (
    snapshot_id, snapshot_date, store_id, store_name, phone,
    shipment_count, last_shipment_at, integration_type, billing_type, status,
    created_at_platform, last_topup_at, wallet_balance,
    profile_status, vat_registered, zatca_completed, verification_status,
    uploaded_by, uploaded_at
  )
  select
    v_snapshot_id,
    (p_snapshot_at at time zone 'Asia/Riyadh')::date,
    btrim(row_data.store_id),
    btrim(row_data.store_name),
    btrim(row_data.phone),
    coalesce(row_data.shipment_count, 0),
    row_data.last_shipment_at,
    nullif(btrim(row_data.integration_type), ''),
    nullif(btrim(row_data.billing_type), ''),
    nullif(btrim(row_data.status), ''),
    row_data.created_at_platform,
    row_data.last_topup_at,
    round(coalesce(row_data.wallet_balance, 0)::numeric, 2),
    nullif(btrim(row_data.profile_status), ''),
    coalesce(row_data.vat_registered, false),
    coalesce(row_data.zatca_completed, false),
    nullif(btrim(row_data.verification_status), ''),
    null,
    v_received_at
  from jsonb_to_recordset(p_rows) as row_data(
    store_id text,
    store_name text,
    phone text,
    shipment_count integer,
    last_shipment_at timestamptz,
    integration_type text,
    billing_type text,
    status text,
    created_at_platform timestamptz,
    last_topup_at timestamptz,
    wallet_balance numeric,
    profile_status text,
    vat_registered boolean,
    zatca_completed boolean,
    verification_status text
  );

  get diagnostics v_inserted = row_count;
  if v_inserted <> v_row_count then
    raise exception 'snapshot_row_count_mismatch';
  end if;

  v_lifecycle := private.capture_merchant_lifecycle_events_internal(v_snapshot_id);

  update public.platform_snapshot_receipts
  set lifecycle = v_lifecycle
  where event_id = p_event_id;

  return jsonb_build_object(
    'status', 'accepted',
    'event_id', p_event_id,
    'snapshot_id', v_snapshot_id,
    'row_count', v_inserted,
    'received_at', v_received_at,
    'lifecycle', v_lifecycle
  );
end;
$function$;
CREATE OR REPLACE FUNCTION public.integration_health_snapshot(p_zoho_minutes integer DEFAULT 90, p_hatif_minutes integer DEFAULT 20, p_platform_hours integer DEFAULT 72)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'cron', 'pg_temp'
AS $function$
with cfg as (select * from public.zoho_api_monitor_config where id=true), x as (
  select
    (select max(finished_at) from public.zoho_sync_runs where status='succeeded') zoho_at,
    (select status from public.zoho_sync_runs order by started_at desc limit 1) zoho_last_status,
    (select max(synced_at) from public.hatif_call_log) hatif_at,
    (select max(uploaded_at) from public.merchants) platform_at,
    (select count(*) from public.profiles where accepts_campaign_leads and nullif(btrim(lead_notification_phone),'') is not null) lead_recipients,
    (select count(*) from public.campaign_lead_inbox) lead_events,
    (select max(received_at) from public.campaign_lead_inbox) lead_last_received,
    (select count(*) from public.campaign_lead_inbox where status='failed') lead_failed,
    (select count(*) from public.webhook_events where status='failed' and received_at>=now()-interval '24 hours') webhook_failed,
    (select count(*) from public.webhook_events where status in ('pending','processing') and processed_at is null and received_at<now()-interval '2 hours') webhook_stuck,
    (select count(*) from public.zoho_sync_runs where status='failed' and started_at>=now()-interval '24 hours') zoho_failures,
    (select count(*) from cron.job where active) active_jobs,
    (select count(*) from cron.job where active and jobname in ('zoho-sync-entities','hatif-pull-calls','work-agent-integration-health','zoho-vat-refresh','zatca-auto-push-2345-riyadh')) active_required_jobs,
    (select max(fetched_at) from public.vat_snapshots) vat_at,
    (select coalesce(sum(api_calls),0)::integer from public.zoho_api_daily_usage where usage_date=current_date) api_calls,
    (select coalesce(sum(rate_limited_count),0)::integer from public.zoho_api_daily_usage where usage_date=current_date) api_rate_limited
)
select jsonb_build_object(
  'checked_at',now(),
  'zoho',jsonb_build_object('last_sync',zoho_at,'healthy',zoho_at>=now()-make_interval(mins=>p_zoho_minutes),'max_age_minutes',p_zoho_minutes),
  'hatif',jsonb_build_object('last_sync',hatif_at,'healthy',hatif_at>=now()-make_interval(mins=>p_hatif_minutes),'max_age_minutes',p_hatif_minutes),
  'platform',jsonb_build_object('last_sync',platform_at,'healthy',platform_at>=now()-make_interval(hours=>p_platform_hours),'max_age_hours',p_platform_hours),
  'lead_intake',jsonb_build_object('configured_recipients',lead_recipients,'received_events',lead_events,'last_received',lead_last_received,'failed',lead_failed,'healthy',lead_recipients>0 and lead_failed=0),
  'webhooks',jsonb_build_object('failed_24h',webhook_failed,'stuck',webhook_stuck,'healthy',webhook_failed=0 and webhook_stuck=0),
  'zoho_runs',jsonb_build_object('failed_24h',zoho_failures,'last_status',zoho_last_status,'healthy',zoho_last_status='succeeded'),
  'cron',jsonb_build_object('active_jobs',active_jobs,'required_jobs',5,'active_required_jobs',active_required_jobs,'healthy',active_required_jobs=5),
  'vat',jsonb_build_object('last_refresh',vat_at,'max_age_minutes',cfg.vat_max_age_minutes,'healthy',vat_at>=now()-make_interval(mins=>cfg.vat_max_age_minutes)),
  'zoho_api',jsonb_build_object('calls_today',api_calls,'rate_limited',api_rate_limited,'warning_calls',cfg.warning_calls,'critical_calls',cfg.critical_calls,
    'healthy',api_calls<cfg.warning_calls,'status',case when api_calls>=cfg.critical_calls then 'critical' when api_calls>=cfg.warning_calls then 'warning' else 'healthy' end),
  'issue_count',
    (case when zoho_at is null or zoho_at<now()-make_interval(mins=>p_zoho_minutes) then 1 else 0 end)+
    (case when hatif_at is null or hatif_at<now()-make_interval(mins=>p_hatif_minutes) then 1 else 0 end)+
    (case when platform_at is null or platform_at<now()-make_interval(hours=>p_platform_hours) then 1 else 0 end)+
    (case when lead_recipients=0 or lead_failed>0 then 1 else 0 end)+
    (case when webhook_failed>0 or webhook_stuck>0 then 1 else 0 end)+
    (case when zoho_last_status is distinct from 'succeeded' then 1 else 0 end)+
    (case when active_required_jobs<>5 then 1 else 0 end)+
    (case when vat_at is null or vat_at<now()-make_interval(mins=>cfg.vat_max_age_minutes) then 1 else 0 end)+
    (case when api_calls>=cfg.warning_calls then 1 else 0 end)
)
from x,cfg;
$function$;
CREATE OR REPLACE FUNCTION public.integrity_check()
 RETURNS TABLE(check_key text, item_count integer, total numeric, sample_ids text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH bank_dates AS (
    SELECT substring(txn_date,1,10)::date AS d, debit
    FROM bank_transactions WHERE txn_date ~ '^\d{4}-\d{2}-\d{2}'
  )
  SELECT 'audit_no_ledger', count(*)::int,
    coalesce(sum(a.total_billed + coalesce(a.total_tax,0)),0)::numeric,
    string_agg(a.id, ', ' ORDER BY a.approved_at DESC) FILTER (WHERE true)
  FROM audits a
  WHERE a.review_status='approved'
    AND NOT EXISTS (SELECT 1 FROM carrier_operations op WHERE op.audit_id = a.id)
  UNION ALL
  SELECT 'export_no_file', count(*)::int, 0::numeric,
    string_agg(file_name, ', ' ORDER BY exported_at DESC)
  FROM weight_billing_exports
  WHERE status='exported' AND file_path IS NULL AND exported_at >= '2026-06-12'
  UNION ALL
  SELECT 'weights_wrongly_skipped', count(*)::int, 0::numeric, string_agg(a.id, ', ')
  FROM audits a
  WHERE a.weight_billing_status='skipped' AND a.review_status='approved'
    AND EXISTS (SELECT 1 FROM audit_shipments s
      WHERE s.audit_id=a.id AND s.weight_kg>0 AND coalesce(s.is_cod,false)=false)
  UNION ALL
  SELECT 'cod_not_extracted', count(*)::int, 0::numeric, string_agg(a.id, ', ')
  FROM audits a JOIN carriers c ON c.id=a.carrier_id
  WHERE a.review_status='approved'
    AND c.file_signature->>'file_kind'='audit_with_cod'
    AND NOT EXISTS (SELECT 1 FROM cod_settlement cs WHERE cs.upload_id = 'audit_in_'||a.id)
  UNION ALL
  SELECT 'cod_ledger_double', count(*)::int, coalesce(sum(op.amount_cr),0)::numeric,
    string_agg(op.doc_no, ', ')
  FROM carrier_operations op JOIN carriers c ON c.id=op.carrier_id
  WHERE op.doc_type='COD' AND c.file_signature->>'cod_remit_via_credit_note'='true'
  UNION ALL
  SELECT 'stale_unaudited_rv', count(*)::int, coalesce(sum(op.amount_dr-op.amount_cr),0)::numeric,
    string_agg(op.doc_no, ', ' ORDER BY op.doc_date)
  FROM carrier_operations op
  WHERE op.doc_type='RV' AND op.audit_id IS NULL AND op.status NOT IN ('paid')
    AND op.doc_date < current_date - 45
  UNION ALL
  SELECT 'pay_no_bank_trace', count(*)::int, coalesce(sum(op.amount_cr),0)::numeric,
    string_agg(coalesce(op.doc_no, op.reference_no), ', ' ORDER BY op.doc_date DESC)
  FROM carrier_operations op
  WHERE op.doc_type='PAY'
    AND op.doc_date >= (SELECT min(d) FROM bank_dates)
    AND op.doc_date <= (SELECT max(d) FROM bank_dates)
    AND NOT EXISTS (SELECT 1 FROM bank_dates bt
      WHERE bt.debit BETWEEN op.amount_cr - 0.5 AND op.amount_cr + 0.5
        AND bt.d BETWEEN op.doc_date - 3 AND op.doc_date + 3)
  UNION ALL
  SELECT 'carrier_cod_no_invoice', count(*)::int,
    coalesce(sum(x.cod_in),0)::numeric, string_agg(x.carrier_id, ', ')
  FROM (
    SELECT cs.carrier_id, sum(cs.amount) AS cod_in
    FROM cod_settlement cs
    WHERE cs.direction='in' AND cs.upload_date >= current_date - 60
    GROUP BY cs.carrier_id
    HAVING sum(cs.amount) > 0
      AND NOT EXISTS (SELECT 1 FROM carrier_operations op
        WHERE op.carrier_id = cs.carrier_id AND op.doc_type IN ('INV','RV'))
  ) x
  UNION ALL
  SELECT 'zoho_debt_no_invoices', count(*)::int,
    coalesce(sum(x.gap),0)::numeric, string_agg(x.customer_name, ', ' ORDER BY x.gap DESC)
  FROM (
    SELECT ct.contact_name AS customer_name,
      ct.outstanding_receivable - coalesce((SELECT sum(z.balance) FROM zoho_invoices z
        WHERE z.customer_name = ct.contact_name AND z.balance > 0.5), 0) AS gap
    FROM zoho_contacts ct
    WHERE ct.outstanding_receivable > 1
  ) x
  WHERE x.gap > 1
  UNION ALL
  SELECT 'audit_no_shipments', count(*)::int, 0::numeric,
    string_agg(a.id, ', ' ORDER BY a.approved_at DESC)
  FROM audits a
  WHERE a.review_status='approved' AND coalesce(a.row_count,0) > 0
    AND NOT EXISTS (SELECT 1 FROM audit_shipments s WHERE s.audit_id = a.id)
  UNION ALL
  -- قواعد التنظيف الصارمة (2026-07-22): جهات خارجية وهمية تسلّلت (هاتف
  -- placeholder أو اسم أرقام/سبام/انتحال) — البوابة تمنع الجديد؛ هذا يكشف القديم.
  SELECT 'external_leads_junk', count(*)::int, 0::numeric,
    (SELECT string_agg(name, ', ') FROM (
      SELECT name FROM crm_leads j
      WHERE j.phone_normalized ~ '(\d)\1{5}$' OR j.phone_normalized='966512345678'
         OR j.name ~ '^[0-9٠-٩\s+._\-()]+$'
         OR lower(j.name) ~ '(test|dummy|asdf|xxx|تجربة|تجريبي|وهمي|لا ?يوجد|بلا اسم)'
         OR j.name ~ '(استثمر|عملات رقمية|ارباح يومي|أرباح يومي|رأس مالك|راس مالك|فوركس|forex|تداول الذهب|بيع عملات)'
         OR j.name ~ '(أرامكو|ارامكو|صندوق الاستثمارات العامة)'
         OR length(regexp_replace(coalesce(j.name,''),'\s','','g')) <= 1
      ORDER BY j.id LIMIT 20) t)
  FROM crm_leads cl
  WHERE cl.phone_normalized ~ '(\d)\1{5}$' OR cl.phone_normalized='966512345678'
     OR cl.name ~ '^[0-9٠-٩\s+._\-()]+$'
     OR lower(cl.name) ~ '(test|dummy|asdf|xxx|تجربة|تجريبي|وهمي|لا ?يوجد|بلا اسم)'
     OR cl.name ~ '(استثمر|عملات رقمية|ارباح يومي|أرباح يومي|رأس مالك|راس مالك|فوركس|forex|تداول الذهب|بيع عملات)'
     OR cl.name ~ '(أرامكو|ارامكو|صندوق الاستثمارات العامة)'
     OR length(regexp_replace(coalesce(cl.name,''),'\s','','g')) <= 1
  UNION ALL
  -- دفعات مجموع توزيعها لا يساوي مبلغها (تدقيق خارجي 2026-07-28: صفّان
  -- بفجوة 34,281.30 ر.س كانا صامتين). الحارس يمنع الجديد، وهذا يُظهر القديم.
  SELECT 'payment_allocation_gap', count(*)::int,
    coalesce(sum(abs(x.gap)),0)::numeric,
    string_agg('دفعة #' || x.id::text || ' (' || x.carrier_id || ' — فرق ' || round(x.gap,2)::text || ')', ', ')
  FROM (
    SELECT p.id, p.carrier_id, sum(a.amount) - (p.amount + coalesce(p.credit_offset,0)) AS gap
    FROM payments p JOIN payment_allocations a ON a.payment_id = p.id
    GROUP BY p.id, p.carrier_id, p.amount, p.credit_offset
    HAVING abs(sum(a.amount) - (p.amount + coalesce(p.credit_offset,0))) > 0.5
  ) x
  UNION ALL
  SELECT 'store_link_ghost', count(*)::int, 0::numeric,
    string_agg(g.customer_name || ' → متجر ' || g.cur || ' (صفر شحنة) بدل ' || g.best, ', ')
  FROM (
    WITH latest AS (SELECT snapshot_id FROM merchants ORDER BY uploaded_at DESC LIMIT 1),
    mm AS (SELECT store_id, normalize_arabic_name(store_name) nn, coalesce(shipment_count,0) sc, status
           FROM merchants WHERE snapshot_id=(SELECT snapshot_id FROM latest))
    SELECT l.customer_name, cur.store_id cur, best.store_id best
    FROM customer_merchant_links l
    JOIN mm cur ON cur.store_id = l.store_id AND cur.sc = 0
    JOIN LATERAL (SELECT * FROM mm b WHERE b.nn = cur.nn
                  ORDER BY b.sc DESC, (b.status='نشط') DESC, b.store_id LIMIT 1) best ON true
    WHERE best.store_id <> cur.store_id AND best.sc > 0
  ) g
  UNION ALL
  SELECT 'store_name_collision', count(*)::int, 0::numeric,
    string_agg(c.detail, ', ')
  FROM (
    WITH latest AS (SELECT snapshot_id FROM merchants ORDER BY uploaded_at DESC LIMIT 1)
    SELECT string_agg(store_id || ' «' || store_name || '» ' || coalesce(shipment_count,0) || ' شحنة', ' + '
                      ORDER BY coalesce(shipment_count,0) DESC) detail
    FROM merchants WHERE snapshot_id=(SELECT snapshot_id FROM latest)
      AND normalize_arabic_name(store_name) <> ''
    GROUP BY normalize_arabic_name(store_name)
    HAVING count(*) FILTER (WHERE coalesce(shipment_count,0) > 0) > 1
  ) c;
$function$;
CREATE OR REPLACE FUNCTION public.is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = auth.uid() AND role = 'admin'
  )
$function$;
CREATE OR REPLACE FUNCTION public.is_period_closed(d date)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM period_closes
    WHERE status = 'closed'
      AND period = to_char(d, 'YYYY-MM')
  );
$function$;
CREATE OR REPLACE FUNCTION public.ivr_analytics(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with base as (
    select *,
      (answered_at is not null or coalesce(duration_seconds,0) > 0) as answered,
      (pressed_digit is not null) as pressed,
      (action_taken = 'dnc') as opted_out
    from ivr_calls
    where created_at >= now() - (p_days || ' days')::interval
  ),
  overall as (
    select count(*) total,
      count(*) filter (where answered) answered,
      count(*) filter (where pressed) pressed,
      count(*) filter (where opted_out) opted_out,
      count(*) filter (where not answered) no_answer
    from base
  ),
  by_hour as (
    select extract(hour from (created_at at time zone 'Asia/Riyadh'))::int as hr,
      count(*) total, count(*) filter (where answered) answered
    from base group by 1 order by 1
  ),
  by_script as (
    select coalesce(script_key,'—') script_key, count(*) total,
      count(*) filter (where answered) answered, count(*) filter (where pressed) pressed
    from base group by 1 order by 2 desc
  )
  select jsonb_build_object(
    'overall', (select to_jsonb(o) from overall o),
    'by_hour', coalesce((select jsonb_agg(to_jsonb(h)) from by_hour h), '[]'::jsonb),
    'by_script', coalesce((select jsonb_agg(to_jsonb(s)) from by_script s), '[]'::jsonb)
  );
$function$;
CREATE OR REPLACE FUNCTION public.legal_escalation_dashboard()
 RETURNS json
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with latest_merch as (select snapshot_id from merchants order by uploaded_at desc limit 1),
  merch as (
    select store_id, store_name, phone, billing_type, status, wallet_balance, last_shipment_at,
           normalize_arabic_name(store_name) norm
    from merchants where snapshot_id = (select snapshot_id from latest_merch)
  ),
  links as (select customer_name, store_id from customer_merchant_links where store_id is not null),
  open_inv as (
    select customer_name, balance, (current_date - date)::int as age
    from zoho_invoices where balance > 0.5 and customer_name is not null
  ),
  -- الرصيد الافتتاحي لكل عميل (فرق إجمالي زوهو عن مجموع فواتيره)
  opening as (
    select contact_name as customer_name, opening_due
    from customer_ar where opening_due > 0.5
  ),
  aging as (
    select
      coalesce(sum(balance) filter (where age between 31 and 60), 0) as b31_60,
      coalesce(sum(balance) filter (where age between 61 and 90), 0) as b61_90,
      coalesce(sum(balance) filter (where age > 90), 0)
        + (select coalesce(sum(opening_due),0) from opening)          as b90plus
    from open_inv
  ),
  over90 as (
    select coalesce(o.customer_name, op.customer_name) as customer_name,
      round((coalesce(sum(o.balance) filter (where o.age > 90), 0)
             + coalesce(max(op.opening_due), 0))::numeric, 2)         as amount_90,
      round((coalesce(sum(o.balance), 0)
             + coalesce(max(op.opening_due), 0))::numeric, 2)         as total_open,
      max(o.age)      as oldest_days,
      count(o.*)::int as inv_cnt
    from open_inv o
    full outer join opening op on op.customer_name = o.customer_name
    group by coalesce(o.customer_name, op.customer_name)
    having coalesce(sum(o.balance) filter (where o.age > 90), 0)
           + coalesce(max(op.opening_due), 0) > 0.5
  ),
  over90_full as (
    select ov.*, m.phone, m.store_name
    from over90 ov
    left join links l on l.customer_name = ov.customer_name
    left join merch m on m.store_id = l.store_id
      or (l.store_id is null and m.norm = normalize_arabic_name(ov.customer_name))
  ),
  prepaid_neg as (
    select store_id, store_name, phone, round(wallet_balance::numeric, 2) as wallet, status, last_shipment_at
    from merch where billing_type = 'دفع مسبق' and wallet_balance < -0.5
  )
  select json_build_object(
    'aging', (select json_build_object(
      'b31_60', round(b31_60::numeric, 2), 'b61_90', round(b61_90::numeric, 2), 'b90plus', round(b90plus::numeric, 2),
      'target_31_60', 50000, 'target_61_90', 25000, 'target_90plus', 0) from aging),
    'overdue90', (select coalesce(json_agg(json_build_object(
      'name', customer_name, 'store_name', store_name, 'phone', phone,
      'amount_90', amount_90, 'total_open', total_open, 'oldest_days', oldest_days, 'inv_cnt', inv_cnt
    ) order by amount_90 desc), '[]') from over90_full),
    'prepaid_negative', (select coalesce(json_agg(json_build_object(
      'store_id', store_id, 'store_name', store_name, 'phone', phone,
      'wallet', wallet, 'status', status, 'last_shipment_at', last_shipment_at
    ) order by wallet asc), '[]') from prepaid_neg)
  );
$function$;
CREATE OR REPLACE FUNCTION public.log_period_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status) THEN
    BEGIN
      INSERT INTO activity_log (actor_id, action, entity_type, entity_id, payload)
      VALUES (
        coalesce(NEW.closed_by, NEW.reopened_by),
        CASE WHEN NEW.status = 'closed' THEN 'period.close' ELSE 'period.reopen' END,
        'period',
        NEW.period,
        jsonb_build_object('period', NEW.period, 'status', NEW.status,
                           'note', coalesce(NEW.closed_note, NEW.reopened_note))
      );
    EXCEPTION WHEN undefined_table OR undefined_column THEN
      NULL;
    END;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.log_profile_authorization_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_actor_name text;
  v_actor_email text;
  v_added text[] := array[]::text[];
  v_removed text[] := array[]::text[];
  v_before_count integer := 0;
  v_after_count integer := 0;
begin
  select profile.name, profile.email
    into v_actor_name, v_actor_email
  from public.profiles profile
  where profile.id = v_actor;

  if new.permissions is distinct from old.permissions then
    select coalesce(array_agg(key order by key), array[]::text[])
      into v_added
    from jsonb_object_keys(coalesce(new.permissions, '{}'::jsonb)) as key
    where not (coalesce(old.permissions, '{}'::jsonb) ? key);

    select coalesce(array_agg(key order by key), array[]::text[])
      into v_removed
    from jsonb_object_keys(coalesce(old.permissions, '{}'::jsonb)) as key
    where not (coalesce(new.permissions, '{}'::jsonb) ? key);

    select count(*)::integer into v_before_count
    from jsonb_object_keys(coalesce(old.permissions, '{}'::jsonb));

    select count(*)::integer into v_after_count
    from jsonb_object_keys(coalesce(new.permissions, '{}'::jsonb));

    insert into public.user_activity_log (user_id, kind, action, detail, path)
    values (
      new.id, 'action', 'permissions_changed',
      jsonb_build_object(
        'employee_id', new.id,
        'employee_name', new.name,
        'employee_email', new.email,
        'actor_id', v_actor,
        'actor_name', v_actor_name,
        'actor_email', v_actor_email,
        'added_keys', to_jsonb(v_added),
        'removed_keys', to_jsonb(v_removed),
        'before_count', v_before_count,
        'after_count', v_after_count
      ),
      '/employees'
    );
  end if;

  if new.role is distinct from old.role then
    insert into public.user_activity_log (user_id, kind, action, detail, path)
    values (
      new.id, 'action', 'employee_role_changed',
      jsonb_build_object(
        'employee_id', new.id,
        'employee_name', new.name,
        'employee_email', new.email,
        'actor_id', v_actor,
        'actor_name', v_actor_name,
        'actor_email', v_actor_email,
        'before_role', old.role,
        'after_role', new.role
      ),
      '/employees'
    );
  end if;

  return new;
end;
$function$;
CREATE OR REPLACE FUNCTION public.log_sensitive_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into user_activity_log (user_id, kind, action, detail)
  values (
    auth.uid(),
    'data',
    TG_TABLE_NAME || ':' || lower(TG_OP),
    jsonb_build_object(
      'table', TG_TABLE_NAME, 'op', TG_OP,
      'row_id', coalesce(to_jsonb(case when TG_OP = 'DELETE' then OLD else NEW end)->>'id', '')
    )
  );
  return coalesce(NEW, OLD);
end $function$;
CREATE OR REPLACE FUNCTION public.log_writeoff_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    BEGIN
      INSERT INTO activity_log (actor_id, action, entity_type, entity_id, payload)
      VALUES (NEW.requested_by, 'writeoff.request', 'writeoff', NEW.id::text,
        jsonb_build_object('customer', NEW.customer_name, 'amount', NEW.amount, 'reason', NEW.reason));
    EXCEPTION WHEN OTHERS THEN NULL; END;
  ELSIF TG_OP = 'UPDATE' AND OLD.status <> NEW.status THEN
    BEGIN
      INSERT INTO activity_log (actor_id, action, entity_type, entity_id, payload)
      VALUES (NEW.reviewed_by,
              CASE WHEN NEW.status='approved' THEN 'writeoff.approve' ELSE 'writeoff.reject' END,
              'writeoff', NEW.id::text,
              jsonb_build_object('customer', NEW.customer_name, 'amount', NEW.amount,
                                 'note', NEW.review_note, 'previous', OLD.status));
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.management_daily_snapshot()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with invoice_stats as materialized (
    select
      count(*) filter (where balance > 0.5 and coalesce(due_date, date) < current_date and lower(coalesce(status, '')) not in ('paid', 'void', 'draft')) as overdue_invoices,
      coalesce(sum(balance) filter (where balance > 0.5 and coalesce(due_date, date) < current_date and lower(coalesce(status, '')) not in ('paid', 'void', 'draft')), 0) as overdue_amount,
      max(synced_at) as zoho_last_sync
    from public.zoho_invoices
  ),
  latest_zatca as materialized (
    select coalesce(nullif(run.details->>'failed', '')::integer, 0) as pending, run.summary, run.started_at as checked_at
    from public.work_agent_runs run
    join public.work_agents agent on agent.id = run.agent_id
    where agent.agent_key = 'zatca_nightly' and run.status in ('succeeded', 'partial', 'failed')
    order by run.started_at desc limit 1
  ),
  lead_stats as materialized (
    select
      count(*) filter (where received_at >= date_trunc('day', now() at time zone 'Asia/Riyadh') at time zone 'Asia/Riyadh') as new_leads_today,
      count(*) filter (where owner_id is null and lead_kind = 'inbound' and coalesce(status, 'new') not in ('won', 'lost', 'converted')) as unassigned_leads,
      count(*) filter (where lead_kind = 'cold' and coalesce(status, 'new') = 'new') as cold_lead_pool
    from public.crm_leads
  ),
  task_stats as materialized (
    select count(*) filter (where status not in ('done', 'completed', 'cancelled') and due_at < now()) as overdue_tasks
    from public.crm_tasks
  ),
  agent_stats as materialized (
    select count(*) filter (where status in ('failed', 'partial') and started_at >= now() - interval '24 hours') as agent_failures_24h
    from public.work_agent_runs
  )
  select jsonb_build_object(
    'generated_at', now(),
    'overdue_invoices', invoice_stats.overdue_invoices,
    'overdue_amount', invoice_stats.overdue_amount,
    'zatca_pending', coalesce(latest_zatca.pending, 0),
    'zatca_last_summary', latest_zatca.summary,
    'zatca_last_checked_at', latest_zatca.checked_at,
    'new_leads_today', lead_stats.new_leads_today,
    'unassigned_leads', lead_stats.unassigned_leads,
    'cold_lead_pool', lead_stats.cold_lead_pool,
    'overdue_tasks', task_stats.overdue_tasks,
    'agent_failures_24h', agent_stats.agent_failures_24h,
    'zoho_last_sync', invoice_stats.zoho_last_sync
  )
  from invoice_stats cross join lead_stats cross join task_stats cross join agent_stats left join latest_zatca on true
$function$;
CREATE OR REPLACE FUNCTION public.marketing_assert_plan_tiers(p_plan_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_bad boolean;
  v_target numeric;
begin
  select target_cost_per_order into v_target
  from public.marketing_compensation_plans
  where id = p_plan_id;
  if not found then raise exception 'plan_not_found'; end if;

  select count(*) = 0 into v_bad
  from public.marketing_commission_tiers where plan_id = p_plan_id;
  if v_bad then raise exception 'tiers_required'; end if;

  select exists (
    select 1
    from (
      select from_order, to_order,
             lag(to_order) over (order by from_order) as previous_to,
             row_number() over (order by from_order) as rn,
             count(*) over () as total_rows
      from public.marketing_commission_tiers
      where plan_id = p_plan_id
    ) x
    where (rn = 1 and from_order <> 1)
       or (rn > 1 and (previous_to is null or from_order <> previous_to + 1))
       or (rn < total_rows and to_order is null)
       or (rn = total_rows and to_order is not null)
  ) into v_bad;
  if v_bad then raise exception 'tiers_must_be_contiguous_and_open_ended'; end if;

  select exists (
    select 1
    from (
      select rate_per_order,
             lag(rate_per_order) over (order by from_order) as previous_rate
      from public.marketing_commission_tiers
      where plan_id = p_plan_id
    ) x
    where previous_rate is not null and rate_per_order < previous_rate
  ) into v_bad;
  if v_bad then raise exception 'tiers_must_be_non_decreasing'; end if;

  select rate_per_order >= v_target into v_bad
  from public.marketing_commission_tiers
  where plan_id = p_plan_id
  order by from_order desc
  limit 1;
  if coalesce(v_bad, true) then raise exception 'last_tier_must_be_below_target'; end if;
end;
$function$;
CREATE OR REPLACE FUNCTION public.marketing_break_even_orders(p_plan_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_salary numeric;
  v_target numeric;
  v_margin numeric;
  v_progress numeric := 0;
  v_width integer;
  v_needed integer;
  v_tier record;
begin
  select monthly_salary, target_cost_per_order
    into v_salary, v_target
  from public.marketing_compensation_plans
  where id = p_plan_id;
  if not found then raise exception 'plan_not_found'; end if;

  for v_tier in
    select from_order, to_order, rate_per_order
    from public.marketing_commission_tiers
    where plan_id = p_plan_id
    order by from_order
  loop
    v_margin := v_target - v_tier.rate_per_order;
    if v_tier.to_order is null then
      if v_margin = 0 and v_progress >= v_salary then return v_tier.from_order; end if;
      if v_margin <= 0 then return null; end if;
      v_needed := greatest(1, ceil((v_salary - v_progress) / v_margin)::integer);
      return (v_tier.from_order - 1) + v_needed;
    end if;

    v_width := v_tier.to_order - v_tier.from_order + 1;
    if v_margin = 0 and v_progress >= v_salary then return v_tier.from_order; end if;
    if v_margin > 0 and v_progress + (v_width * v_margin) >= v_salary then
      v_needed := greatest(1, ceil((v_salary - v_progress) / v_margin)::integer);
      return (v_tier.from_order - 1) + v_needed;
    end if;
    v_progress := v_progress + (v_width * v_margin);
  end loop;
  return null;
end;
$function$;
CREATE OR REPLACE FUNCTION public.marketing_close_month(p_marketer_id uuid, p_period date)
 RETURNS TABLE(performance_id uuid, resulting_status text, achieved_break_even boolean, break_even_orders integer, total_cost numeric, effective_cost numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_marketer public.marketing_marketers%rowtype;
  v_perf public.marketing_monthly_performance%rowtype;
  v_plan public.marketing_compensation_plans%rowtype;
  v_commission numeric;
  v_total numeric;
  v_effective numeric;
  v_break_even integer;
  v_success boolean;
  v_next text;
  v_current_month date := date_trunc('month', timezone('Asia/Riyadh', now()))::date;
begin
  if v_uid is null or not public.crm_has_permission('marketers.close_month') then raise exception 'not_allowed'; end if;
  if p_period <> date_trunc('month', p_period)::date then raise exception 'month_required'; end if;
  if p_period >= v_current_month then raise exception 'month_not_finished'; end if;

  select * into v_marketer from public.marketing_marketers where id = p_marketer_id for update;
  if not found then raise exception 'marketer_not_found'; end if;
  select * into v_perf from public.marketing_monthly_performance
    where marketer_id = p_marketer_id and period = p_period for update;
  if not found then raise exception 'orders_not_recorded'; end if;
  if v_perf.close_state = 'closed' then raise exception 'month_already_closed'; end if;
  if exists (
    select 1 from public.marketing_monthly_performance
    where marketer_id = p_marketer_id and period > p_period and close_state = 'closed'
  ) then raise exception 'close_months_in_order'; end if;

  select * into v_plan from public.marketing_compensation_plans
  where marketer_id = p_marketer_id and effective_month <= p_period
  order by effective_month desc limit 1;
  if not found then raise exception 'plan_not_found_for_month'; end if;

  v_commission := round(public.marketing_variable_commission(v_plan.id, v_perf.eligible_orders), 2);
  v_total := round(v_plan.monthly_salary + v_commission, 2);
  v_effective := case when v_perf.eligible_orders > 0 then round(v_total / v_perf.eligible_orders, 4) else null end;
  v_break_even := public.marketing_break_even_orders(v_plan.id);
  v_success := v_break_even is not null and v_perf.eligible_orders >= v_break_even;
  v_next := case
    when v_marketer.lifecycle_status = 'stopped' then 'stopped'
    when v_success and v_marketer.lifecycle_status = 'red' then 'yellow'
    when v_success and v_marketer.lifecycle_status = 'yellow' then 'green'
    when v_success then 'green'
    when v_marketer.lifecycle_status = 'green' then 'yellow'
    when v_marketer.lifecycle_status = 'yellow' then 'red'
    when v_marketer.lifecycle_status = 'red' then 'stopped'
    else v_marketer.lifecycle_status
  end;

  update public.marketing_monthly_performance set
    close_state = 'closed', plan_id = v_plan.id,
    salary_snapshot = v_plan.monthly_salary,
    target_cost_snapshot = v_plan.target_cost_per_order,
    order_target_snapshot = v_plan.monthly_order_target,
    variable_commission_snapshot = v_commission,
    total_cost_snapshot = v_total,
    effective_cost_snapshot = v_effective,
    break_even_orders_snapshot = v_break_even,
    achieved_break_even = v_success,
    resulting_status = v_next,
    closed_by = v_uid, closed_at = now(), updated_at = now()
  where id = v_perf.id;

  update public.marketing_marketers
    set lifecycle_status = v_next, updated_at = now()
  where id = p_marketer_id;

  insert into public.marketing_status_history
    (marketer_id, period, from_status, to_status, achieved_break_even, eligible_orders, break_even_orders, changed_by)
  values
    (p_marketer_id, p_period, v_marketer.lifecycle_status, v_next, v_success, v_perf.eligible_orders, v_break_even, v_uid);

  return query select v_perf.id, v_next, v_success, v_break_even, v_total, v_effective;
end;
$function$;
CREATE OR REPLACE FUNCTION public.marketing_create_marketer(p_name text, p_phone text, p_start_month date, p_monthly_salary numeric, p_target_cost_per_order numeric, p_monthly_order_target integer, p_tiers jsonb, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_marketer uuid;
  v_plan uuid;
begin
  if v_uid is null or not public.crm_has_permission('marketers.manage') then
    raise exception 'not_allowed';
  end if;
  if p_start_month <> date_trunc('month', p_start_month)::date then raise exception 'month_required'; end if;
  if coalesce(jsonb_array_length(p_tiers), 0) = 0 then raise exception 'tiers_required'; end if;

  insert into public.marketing_marketers (name, phone, start_month, notes, created_by)
  values (trim(p_name), nullif(trim(p_phone), ''), p_start_month, nullif(trim(p_notes), ''), v_uid)
  returning id into v_marketer;

  insert into public.marketing_compensation_plans
    (marketer_id, effective_month, monthly_salary, target_cost_per_order, monthly_order_target, created_by)
  values
    (v_marketer, p_start_month, p_monthly_salary, p_target_cost_per_order, p_monthly_order_target, v_uid)
  returning id into v_plan;

  insert into public.marketing_commission_tiers (plan_id, from_order, to_order, rate_per_order)
  select v_plan,
         (x->>'from_order')::integer,
         nullif(x->>'to_order', '')::integer,
         (x->>'rate_per_order')::numeric
  from jsonb_array_elements(p_tiers) x;

  perform public.marketing_assert_plan_tiers(v_plan);
  return v_marketer;
end;
$function$;
CREATE OR REPLACE FUNCTION public.marketing_create_plan(p_marketer_id uuid, p_effective_month date, p_monthly_salary numeric, p_target_cost_per_order numeric, p_monthly_order_target integer, p_tiers jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_plan uuid;
begin
  if v_uid is null or not public.crm_has_permission('marketers.manage') then raise exception 'not_allowed'; end if;
  if p_effective_month <> date_trunc('month', p_effective_month)::date then raise exception 'month_required'; end if;
  if coalesce(jsonb_array_length(p_tiers), 0) = 0 then raise exception 'tiers_required'; end if;
  if not exists (select 1 from public.marketing_marketers where id = p_marketer_id) then raise exception 'marketer_not_found'; end if;

  select id into v_plan
  from public.marketing_compensation_plans
  where marketer_id = p_marketer_id and effective_month = p_effective_month
  for update;

  if v_plan is not null then
    if exists (
      select 1 from public.marketing_monthly_performance
      where plan_id = v_plan and close_state = 'closed'
    ) then raise exception 'plan_month_locked'; end if;
    update public.marketing_compensation_plans set
      monthly_salary = p_monthly_salary,
      target_cost_per_order = p_target_cost_per_order,
      monthly_order_target = p_monthly_order_target
    where id = v_plan;
    delete from public.marketing_commission_tiers where plan_id = v_plan;
  else
    insert into public.marketing_compensation_plans
      (marketer_id, effective_month, monthly_salary, target_cost_per_order, monthly_order_target, created_by)
    values
      (p_marketer_id, p_effective_month, p_monthly_salary, p_target_cost_per_order, p_monthly_order_target, v_uid)
    returning id into v_plan;
  end if;

  insert into public.marketing_commission_tiers (plan_id, from_order, to_order, rate_per_order)
  select v_plan,
         (x->>'from_order')::integer,
         nullif(x->>'to_order', '')::integer,
         (x->>'rate_per_order')::numeric
  from jsonb_array_elements(p_tiers) x;
  perform public.marketing_assert_plan_tiers(v_plan);
  return v_plan;
end;
$function$;
CREATE OR REPLACE FUNCTION public.marketing_save_month(p_marketer_id uuid, p_period date, p_eligible_orders integer, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_id uuid;
begin
  if v_uid is null or not public.crm_has_permission('marketers.record_month') then raise exception 'not_allowed'; end if;
  if p_period <> date_trunc('month', p_period)::date then raise exception 'month_required'; end if;
  if p_eligible_orders < 0 then raise exception 'orders_must_be_positive'; end if;
  if exists (
    select 1 from public.marketing_monthly_performance
    where marketer_id = p_marketer_id and period = p_period and close_state = 'closed'
  ) then raise exception 'month_already_closed'; end if;

  insert into public.marketing_monthly_performance
    (marketer_id, period, eligible_orders, notes, created_by, updated_at)
  values
    (p_marketer_id, p_period, p_eligible_orders, nullif(trim(p_notes), ''), v_uid, now())
  on conflict (marketer_id, period) do update
    set eligible_orders = excluded.eligible_orders,
        notes = excluded.notes,
        updated_at = now()
  returning id into v_id;
  return v_id;
end;
$function$;
CREATE OR REPLACE FUNCTION public.marketing_variable_commission(p_plan_id uuid, p_orders integer)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(sum(
    greatest(
      0,
      least(greatest(coalesce(p_orders, 0), 0), coalesce(t.to_order, greatest(coalesce(p_orders, 0), 0)))
      - t.from_order + 1
    ) * t.rate_per_order
  ), 0)::numeric
  from public.marketing_commission_tiers t
  where t.plan_id = p_plan_id;
$function$;
CREATE OR REPLACE FUNCTION public.merchant_sales_signals()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result jsonb;
begin
  if (select auth.uid()) is null
     or not (
       public.crm_has_permission('sales.view')
       or public.crm_has_permission('merchants.view')
       or public.crm_has_permission('crm.view')
     ) then
    raise exception 'not_allowed';
  end if;

  select jsonb_build_object(
    'summary', (
      select jsonb_build_object(
        'ready_to_activate', count(*) filter (
          where total_shipments = 0
            and profile_done and verified
            and integration_type is not null
            and segment <> 'negative_balance'
        ),
        'topped_no_ship', count(*) filter (where segment = 'topped_no_ship'),
        'new_7d_no_ship', count(*) filter (
          where total_shipments = 0
            and created_at >= current_date - 7
            and segment <> 'negative_balance'
        ),
        'stopped_30d', count(*) filter (
          where segment = 'stopped_recent' and days_since_last <= 30
        ),
        'key_accounts_at_risk', count(*) filter (
          where segment in ('stopped_recent', 'stopped_long')
            and total_shipments >= 1000
        ),
        'compliance_pending', count(*) filter (
          where compliance_pending
            and total_shipments > 0
            and days_since_last <= 30
        ),
        'multi_store_accounts', count(*) filter (where store_count > 1),
        'collections_only', count(*) filter (where segment = 'negative_balance')
      )
      from public.v_crm_retargeting
    ),
    'opportunity_details', (
      select coalesce(jsonb_agg(to_jsonb(d)), '[]'::jsonb)
      from (
        select
          v.phone,
          v.store_count,
          v.store_names,
          v.integration_type,
          v.billing_type,
          v.profile_done,
          v.verified,
          v.vat_reg,
          v.zatca_done,
          v.compliance_pending,
          v.readiness_score,
          v.opportunity_score,
          v.team_route,
          v.next_step
        from public.v_crm_retargeting v
        left join public.retargeting_followups f on f.phone = v.phone
        where f.phone is null
          and (
            v.segment = 'topped_no_ship'
            or v.segment = 'stopped_recent'
            or (v.segment = 'stopped_long' and v.priority = 'A')
            or (
              v.segment in ('new_active', 'linked_no_ship', 'registered_no_ship')
              and v.created_at >= now() - interval '30 days'
            )
          )
        order by v.opportunity_score desc, v.total_shipments desc, v.created_at desc nulls last
        limit 200
      ) d
    ),
    'activation_ready', (
      select coalesce(jsonb_agg(to_jsonb(a) order by a.opportunity_score desc, a.created_at desc), '[]'::jsonb)
      from (
        select
          v.phone,
          v.primary_store as store,
          v.store_count,
          v.store_names,
          v.segment,
          v.priority,
          v.channel,
          v.total_shipments,
          v.wallet,
          v.created_at,
          v.integration_type,
          v.billing_type,
          v.readiness_score,
          v.opportunity_score,
          v.team_route,
          v.next_step
        from public.v_crm_retargeting v
        left join public.retargeting_followups f on f.phone = v.phone
        where f.phone is null
          and v.total_shipments = 0
          and v.profile_done
          and v.verified
          and v.integration_type is not null
          and v.segment <> 'negative_balance'
          and (v.created_at is null or v.created_at < now() - interval '30 days')
        order by v.opportunity_score desc, v.created_at desc nulls last
        limit 15
      ) a
    ),
    'activation_ready_count', (
      select count(*)
      from public.v_crm_retargeting v
      left join public.retargeting_followups f on f.phone = v.phone
      where f.phone is null
        and v.total_shipments = 0
        and v.profile_done
        and v.verified
        and v.integration_type is not null
        and v.segment <> 'negative_balance'
        and (v.created_at is null or v.created_at < now() - interval '30 days')
    )
  )
  into v_result;

  return v_result;
end;
$function$;
CREATE OR REPLACE FUNCTION public.message_open_hours(p_days integer DEFAULT 120)
 RETURNS TABLE(hour integer, opens bigint, replies bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with h as (select generate_series(0,23) as hour)
  select h.hour,
    (select count(*) from whatsapp_campaign_sends w
       where w.read_at is not null and w.read_at > now() - make_interval(days=>greatest(p_days,1))
         and extract(hour from w.read_at at time zone 'Asia/Riyadh')::int = h.hour) as opens,
    (select count(*) from whatsapp_campaign_sends w
       where w.replied_at is not null and coalesce(w.reply_is_auto,false)=false
         and w.replied_at > now() - make_interval(days=>greatest(p_days,1))
         and extract(hour from w.replied_at at time zone 'Asia/Riyadh')::int = h.hour) as replies
  from h order by h.hour;
$function$;
CREATE OR REPLACE FUNCTION public.monthly_financial_snapshot(p_period text DEFAULT NULL::text)
 RETURNS TABLE(period text, carrier_spend_gross numeric, carrier_paid numeric, cod_received numeric, drift_total numeric, audits_approved integer, audits_pending integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH p AS ( SELECT coalesce(p_period, to_char(now(), 'YYYY-MM')) AS period )
  SELECT
    p.period,
    coalesce((SELECT SUM(amount_dr) FROM carrier_operations
              WHERE to_char(doc_date, 'YYYY-MM') = p.period), 0)::numeric AS carrier_spend_gross,
    coalesce((SELECT SUM(amount) FROM payments
              WHERE to_char(paid_at, 'YYYY-MM') = p.period), 0)::numeric AS carrier_paid,
    coalesce((SELECT SUM(amount) FROM cod_settlement
              WHERE direction='in' AND to_char(upload_date, 'YYYY-MM') = p.period), 0)::numeric AS cod_received,
    coalesce((SELECT SUM(drift_pre_tax) FROM audits
              WHERE approved_at IS NOT NULL AND to_char(approved_at::date, 'YYYY-MM') = p.period), 0)::numeric AS drift_total,
    coalesce((SELECT COUNT(*) FROM audits
              WHERE approved_at IS NOT NULL AND to_char(approved_at::date, 'YYYY-MM') = p.period), 0)::int AS audits_approved,
    coalesce((SELECT COUNT(*) FROM audits
              WHERE coalesce(review_status,'pending') = 'pending'), 0)::int AS audits_pending
  FROM p;
$function$;
CREATE OR REPLACE FUNCTION public.months_with_activity()
 RETURNS TABLE(period text, ops_count bigint, cod_count bigint, audits_count bigint, payments_count bigint, total_count bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH all_months AS (
    SELECT to_char(doc_date, 'YYYY-MM') AS period FROM carrier_operations WHERE doc_date IS NOT NULL
    UNION ALL
    SELECT to_char(upload_date, 'YYYY-MM') FROM cod_settlement WHERE upload_date IS NOT NULL
    UNION ALL
    SELECT to_char(created_at::date, 'YYYY-MM') FROM audits
    UNION ALL
    SELECT to_char(paid_at::date, 'YYYY-MM') FROM payments WHERE paid_at IS NOT NULL
  ),
  ops AS (
    SELECT to_char(doc_date, 'YYYY-MM') AS p, COUNT(*) AS c
    FROM carrier_operations WHERE doc_date IS NOT NULL GROUP BY 1
  ),
  cod AS (
    SELECT to_char(upload_date, 'YYYY-MM') AS p, COUNT(*) AS c
    FROM cod_settlement WHERE upload_date IS NOT NULL GROUP BY 1
  ),
  aud AS (
    SELECT to_char(created_at::date, 'YYYY-MM') AS p, COUNT(*) AS c
    FROM audits GROUP BY 1
  ),
  pay AS (
    SELECT to_char(paid_at::date, 'YYYY-MM') AS p, COUNT(*) AS c
    FROM payments WHERE paid_at IS NOT NULL GROUP BY 1
  )
  SELECT
    p.period,
    coalesce(ops.c, 0)::bigint AS ops_count,
    coalesce(cod.c, 0)::bigint AS cod_count,
    coalesce(aud.c, 0)::bigint AS audits_count,
    coalesce(pay.c, 0)::bigint AS payments_count,
    (coalesce(ops.c, 0) + coalesce(cod.c, 0) + coalesce(aud.c, 0) + coalesce(pay.c, 0))::bigint AS total_count
  FROM (SELECT DISTINCT period FROM all_months) p
  LEFT JOIN ops ON ops.p = p.period
  LEFT JOIN cod ON cod.p = p.period
  LEFT JOIN aud ON aud.p = p.period
  LEFT JOIN pay ON pay.p = p.period
  ORDER BY p.period DESC;
$function$;
CREATE OR REPLACE FUNCTION public.morning_brief_management_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_customer jsonb;
  v_finance jsonb;
  v_collections jsonb;
  v_operations jsonb;
  v_sales jsonb;
  v_system jsonb;
begin
  select public.customer_money_dashboard()::jsonb into v_customer;

  with linked as materialized (
    select distinct link.zoho_account_id, link.internal_bank_name
    from public.zoho_financial_account_links link
    where link.source_type = 'bank_account'
      and link.link_kind = 'bank'
  ), latest_statements as materialized (
    select distinct on (summary.bank)
      summary.bank,
      summary.closing_balance,
      summary.period_to
    from public.bank_statement_summaries summary
    join linked on linked.internal_bank_name = summary.bank
    order by summary.bank, summary.period_to desc, summary.created_at desc
  ), bank_totals as materialized (
    select
      count(*)::int as linked_count,
      coalesce(sum(account.book_balance), 0)::numeric as book_balance,
      coalesce(sum(account.uncategorized_count), 0)::int as uncategorized_operations,
      max(account.synced_at) as bank_synced_at
    from linked
    join public.zoho_bank_accounts account
      on account.zoho_id = linked.zoho_account_id
  ), statement_totals as materialized (
    select
      count(*)::int as statement_count,
      coalesce(sum(closing_balance), 0)::numeric as statement_balance,
      max(period_to) as statement_as_of
    from latest_statements
  ), vendor_totals as materialized (
    select
      count(*) filter (where outstanding_payable > 0.5)::int as payable_vendors,
      coalesce(sum(outstanding_payable), 0)::numeric as outstanding_payable,
      coalesce(sum(unused_credits_payable), 0)::numeric as vendor_credits
    from public.zoho_contacts
    where contact_type = 'vendor'
  ), bill_totals as materialized (
    select
      count(*) filter (where balance > 0.5)::int as open_count,
      coalesce(sum(balance) filter (where balance > 0.5), 0)::numeric as open_balance,
      count(*) filter (where balance > 0.5 and due_date < current_date)::int as overdue_count,
      coalesce(sum(balance) filter (where balance > 0.5 and due_date < current_date), 0)::numeric as overdue_balance
    from public.zoho_bills
  )
  select jsonb_build_object(
    'linked_bank_accounts', bank.linked_count,
    'statement_count', statement.statement_count,
    'statement_balance', round(statement.statement_balance, 2),
    'book_balance', round(bank.book_balance, 2),
    'statement_vs_book_difference', round(statement.statement_balance - bank.book_balance, 2),
    'uncategorized_bank_operations', bank.uncategorized_operations,
    'statement_as_of', statement.statement_as_of,
    'bank_synced_at', bank.bank_synced_at,
    'payable_vendors', vendor.payable_vendors,
    'vendor_outstanding', round(vendor.outstanding_payable, 2),
    'vendor_credits', round(vendor.vendor_credits, 2),
    'vendor_net_payable', round(vendor.outstanding_payable - vendor.vendor_credits, 2),
    'open_bills', bills.open_count,
    'open_bills_balance', round(bills.open_balance, 2),
    'overdue_bills', bills.overdue_count,
    'overdue_bills_balance', round(bills.overdue_balance, 2)
  ) into v_finance
  from bank_totals bank
  cross join statement_totals statement
  cross join vendor_totals vendor
  cross join bill_totals bills;

  with latest_snapshot as materialized (
    select snapshot_id from public.merchants order by uploaded_at desc limit 1
  ), merchant_context as materialized (
    select
      link.customer_name,
      bool_or(coalesce(merchant.billing_type, '') = 'دفع مسبق') as prepaid
    from public.customer_merchant_links link
    join public.merchants merchant
      on merchant.store_id = link.store_id
     and merchant.snapshot_id = (select snapshot_id from latest_snapshot)
    group by link.customer_name
  ), debtors as materialized (
    select
      ar.contact_name as customer_name,
      ar.collectible_due as debt,
      greatest(coalesce(age.days_outstanding, 0), 0) as days_outstanding,
      coalesce(context.prepaid, false) as prepaid
    from public.customer_ar ar
    left join merchant_context context on context.customer_name = ar.contact_name
    left join lateral (
      select max(line.age_days) as days_outstanding
      from public.customer_collectible_lines line
      where line.contact_name = ar.contact_name
        and line.collectible_amount > 0.005
    ) age on true
    where ar.collectible_due > 0.5
  ), candidates as materialized (
    select * from debtors
    where prepaid or debt > 10000 or days_outstanding > 30
  ), open_tasks as materialized (
    select
      task.customer_name,
      bool_or(task.assigned_to is not null) as has_assignee
    from public.collection_tasks task
    where task.stage in ('todo', 'contacted', 'promised', 'snoozed')
      and task.done_at is null
    group by task.customer_name
  )
  select jsonb_build_object(
    'open_tasks', (select count(*) from open_tasks),
    'assigned_customers', (select count(*) from open_tasks where has_assignee),
    'unassigned_customers', (select count(*) from open_tasks where not has_assignee),
    'candidates', (select count(*) from candidates),
    'candidate_debt', round(coalesce((select sum(debt) from candidates), 0), 2),
    'missing_tasks', (select count(*) from candidates candidate where not exists (
      select 1 from open_tasks task where task.customer_name = candidate.customer_name
    )),
    'missing_task_debt', round(coalesce((select sum(candidate.debt) from candidates candidate where not exists (
      select 1 from open_tasks task where task.customer_name = candidate.customer_name
    )), 0), 2),
    'promises_due_today', (select count(*) from public.collection_tasks
      where stage = 'promised' and done_at is null and promise_date = current_date),
    'broken_promises', (select count(*) from public.collection_tasks
      where stage = 'promised' and done_at is null and promise_date < current_date)
  ) into v_collections;

  with active_carriers as materialized (
    select c.id, c.name, nullif(c.file_signature ->> 'file_kind', '') as file_kind
    from public.carriers c
    where jsonb_typeof(c.contracts) = 'array'
      and exists (
        select 1 from jsonb_array_elements(c.contracts) contract
        where case
          when coalesce(contract ->> 'startDate', '') ~ '^\d{4}-\d{2}-\d{2}$'
            then (contract ->> 'startDate')::date <= current_date
          else true
        end
        and case
          when coalesce(contract ->> 'endDate', '') ~ '^\d{4}-\d{2}-\d{2}$'
            then (contract ->> 'endDate')::date >= date_trunc('month', current_date)::date
          else true
        end
      )
  ), requirements as materialized (
    select carrier.id, carrier.name, required.task_kind
    from active_carriers carrier
    cross join lateral unnest(
      case carrier.file_kind
        when 'audit_with_cod' then array['invoice']::text[]
        when 'audit_only' then array['invoice']::text[]
        when 'audit_and_cod_separate' then array['invoice', 'cod_remittance']::text[]
        when 'cod_only' then array['cod_remittance']::text[]
        else array['classification']::text[]
      end
    ) required(task_kind)
  ), missing as materialized (
    select requirement.*
    from requirements requirement
    where requirement.task_kind = 'classification'
       or not exists (
        select 1 from public.carrier_task_schedules schedule
        where schedule.carrier_id = requirement.id
          and schedule.task_kind = requirement.task_kind
          and schedule.active
          and schedule.schedule_basis in ('weekday', 'month_days')
          and cardinality(schedule.due_days) > 0
          and (
            (schedule.schedule_basis = 'weekday' and schedule.due_days <@ array[0,1,2,3,4,5,6]::smallint[])
            or (schedule.schedule_basis = 'month_days' and schedule.due_days <@ array(select generate_series(1,31)::smallint))
          )
      )
  )
  select jsonb_build_object(
    'contracted_carriers', (select count(*) from active_carriers),
    'missing_carrier_schedules', (select count(distinct id) from missing),
    'missing_schedule_requirements', (select count(*) from missing),
    'current_month_events', (select count(*) from public.accounting_cycle_events
      where period = date_trunc('month', current_date)::date and status = 'success'),
    'cycle_status', coalesce((select status from public.accounting_cycles
      where period = date_trunc('month', current_date)::date), 'not_started'),
    'closed_cycles', (select count(*) from public.accounting_cycles where status = 'closed')
  ) into v_operations;

  select jsonb_build_object(
    'new_leads_today', count(*) filter (
      where received_at >= date_trunc('day', now() at time zone 'Asia/Riyadh') at time zone 'Asia/Riyadh'
    ),
    'unassigned_inbound_leads', count(*) filter (
      where owner_id is null and lead_kind = 'inbound'
        and coalesce(status, 'new') not in ('won', 'lost', 'converted')
    ),
    'cold_lead_pool', count(*) filter (
      where lead_kind = 'cold' and coalesce(status, 'new') = 'new'
    ),
    'unassigned_followups', (select count(*) from public.retargeting_followups
      where status = 'needs_followup' and owner_id is null),
    'overdue_crm_tasks', (select count(*) from public.crm_tasks
      where status not in ('done', 'completed', 'cancelled') and due_at < now()),
    'unassigned_crm_tasks', (select count(*) from public.crm_tasks
      where status not in ('done', 'completed', 'cancelled') and assigned_to is null)
  ) into v_sales
  from public.crm_leads;

  with latest_zatca as materialized (
    select
      coalesce(nullif(run.details ->> 'failed', '')::int, 0) as pending,
      run.summary,
      run.started_at as checked_at
    from public.work_agent_runs run
    join public.work_agents agent on agent.id = run.agent_id
    where agent.agent_key = 'zatca_nightly'
    order by run.started_at desc
    limit 1
  ), latest_integration as materialized (
    select
      coalesce(nullif(run.failed_count, 0), 0) as issue_count,
      run.summary,
      run.started_at as checked_at
    from public.work_agent_runs run
    join public.work_agents agent on agent.id = run.agent_id
    where agent.agent_key = 'integration_health'
    order by run.started_at desc
    limit 1
  )
  select jsonb_build_object(
    'zatca_pending', coalesce((select pending from latest_zatca), 0),
    'zatca_summary', (select summary from latest_zatca),
    'zatca_checked_at', (select checked_at from latest_zatca),
    'integration_issues', coalesce((select issue_count from latest_integration), 0),
    'integration_summary', (select summary from latest_integration),
    'integration_checked_at', (select checked_at from latest_integration),
    'agent_failures_24h', (select count(*) from public.work_agent_runs
      where status in ('failed', 'partial', 'error') and started_at >= now() - interval '24 hours'),
    'pending_webhooks', (select count(*) from public.webhook_events
      where processed_at is null and audit_id is null and status is distinct from 'failed'),
    'zoho_last_sync', greatest(
      (select max(synced_at) from public.zoho_invoices),
      (select max(synced_at) from public.zoho_payments),
      (select max(synced_at) from public.zoho_bank_accounts)
    ),
    'platform_last_snapshot', (select max(uploaded_at) from public.merchants)
  ) into v_system;

  return jsonb_build_object(
    'generated_at', now(),
    'customer', coalesce(v_customer, '{}'::jsonb),
    'finance', coalesce(v_finance, '{}'::jsonb),
    'collections', coalesce(v_collections, '{}'::jsonb),
    'operations', coalesce(v_operations, '{}'::jsonb),
    'sales', coalesce(v_sales, '{}'::jsonb),
    'system', coalesce(v_system, '{}'::jsonb)
  );
end;
$function$;
comment on function "public"."morning_brief_management_snapshot"() is 'Read-only management snapshot used by the scheduled morning brief Edge Function.';
CREATE OR REPLACE FUNCTION public.next_best_actions(p_limit integer DEFAULT 300, p_owner text DEFAULT NULL::text)
 RETURNS TABLE(phone text, name text, store_id text, owner_id text, reason_code text, reason text, action text, priority integer, amount numeric, followup_status text, last_touch timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with
  latest_snap as (select max(snapshot_date) sd from merchants),
  m as (
    select norm_sa_phone(phone) as phone, store_id, store_name, shipment_count,
           last_shipment_at, billing_type, status, wallet_balance
    from merchants where snapshot_date = (select sd from latest_snap) and norm_sa_phone(phone) is not null
  ),
  debt as (   -- ✅ الذمّة الكاملة
    select l.store_id, sum(ar.total_due) as owed
    from customer_ar ar join customer_merchant_links l on l.customer_name = ar.contact_name
    where ar.total_due > 0.5 group by l.store_id
  ),
  sig as (
    select norm_sa_phone(w.phone) as phone, w.name as name, null::text as store_id,
      'hot_reply' as reason_code,
      (case reply_intent(w.reply_body) when 'wants_call' then 'ردّ يطلب اتصالاً: '
        when 'price' then 'ردّ باعتراض سعر: ' else 'ردّ باهتمام: ' end) || left(w.reply_body, 45) as reason,
      (case reply_intent(w.reply_body) when 'wants_call' then 'اتصل به الآن'
        when 'price' then 'اعرض سعراً/خصماً' else 'تواصل معه الآن' end) as action,
      108 as priority, null::numeric as amount
    from whatsapp_campaign_sends w
    where w.replied_at is not null and coalesce(w.reply_is_auto,false) = false
      and reply_intent(w.reply_body) in ('interested','wants_call','price')
      and w.replied_at > now() - interval '14 days'
    union all
    select f.phone,
      coalesce((select store_name from m where m.phone = f.phone limit 1), f.phone), null::text,
      'sla',
      case when f.next_action_at is not null and f.next_action_at < now() then 'متابعة تجاوزت موعدها المحدد'
           else 'متابعة راكدة — لم تُلمَس منذ '||greatest(1, floor(extract(epoch from now() - f.last_touch_at)/86400))::int||' يوم' end,
      'تابعه الآن', 105, null::numeric
    from retargeting_followups f
    where f.status not in ('converted','rejected','not_interested','blacklist','supplier','noise','test')
      and ((f.next_action_at is not null and f.next_action_at < now()) or f.last_touch_at < now() - interval '3 days')
    union all
    select norm_sa_phone(w.phone), w.name, null::text,
      'reply', 'ردّ على حملتك ولم يُتابَع', 'تابع الردّ', 100, null::numeric
    from whatsapp_campaign_sends w
    where w.replied_at is not null and coalesce(w.reply_is_auto,false) = false
      and coalesce(w.followed_up,false) = false and w.replied_at > now() - interval '30 days'
    union all
    select m.phone, m.store_name, m.store_id, 'wallet_neg', 'محفظته سالبة (دفع مسبق)', 'حصّل رصيد المحفظة', 88, abs(m.wallet_balance)
    from m where m.billing_type = 'دفع مسبق' and coalesce(m.wallet_balance,0) < -0.5
    union all
    select m.phone, m.store_name, m.store_id, 'debt', 'عليه دين مفتوح', 'حصّل الدين', 82, d.owed
    from m join debt d on d.store_id = m.store_id where d.owed > 0.5
    union all
    select m.phone, m.store_name, m.store_id, 'stopped', 'توقّف عن الشحن (كان نشطاً)', 'أعد تنشيطه', 65, null
    from m where m.shipment_count > 0 and m.last_shipment_at between now() - interval '45 days' and now() - interval '7 days'
  ),
  ranked as (
    select s.*, row_number() over (partition by s.phone order by s.priority desc, s.amount desc nulls last) as rn
    from sig s where s.phone is not null and s.phone <> ''
  )
  select r.phone, r.name, r.store_id, f.owner_id::text,
    r.reason_code, r.reason, r.action, r.priority, r.amount, f.status, f.last_touch_at
  from ranked r
  left join retargeting_followups f on f.phone = r.phone
  where r.rn = 1 and (p_owner is null or f.owner_id::text = p_owner)
  order by r.priority desc, r.amount desc nulls last
  limit greatest(p_limit,1);
$function$;
CREATE OR REPLACE FUNCTION public.no_whatsapp_phones()
 RETURNS TABLE(phone text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select phone from public.v_no_whatsapp
  union
  select phone from public.campaign_phone_blocklist
  union
  -- فشل «غير قابل للتسليم» مرتين فأكثر، وبلا أي تسليم/قراءة/ردّ منذ أول فشل
  select s.phone
  from whatsapp_campaign_sends s
  where s.error_reason ilike '%undeliverable%'
  group by s.phone
  having count(*) >= 2
     and not exists (
       select 1 from whatsapp_campaign_sends d
       where d.phone = s.phone
         and (d.delivered_at is not null or d.read_at is not null or d.replied_at is not null)
         and d.sent_at > min(s.sent_at)
     );
$function$;
CREATE OR REPLACE FUNCTION public.no_whatsapp_report()
 RETURNS TABLE(phone text, name text, last_attempt timestamp with time zone, attempts bigint, campaigns text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select phone, name, last_attempt, attempts, campaigns
  from public.v_no_whatsapp order by last_attempt desc;
$function$;
CREATE OR REPLACE FUNCTION public.norm_sa_phone(raw text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare x text;
begin
  x := regexp_replace(coalesce(raw, ''), '\D', '', 'g');
  if x = '' then return null; end if;
  if left(x, 2) = '00' then x := substr(x, 3); end if;
  if left(x, 3) = '966' then
    x := '966' || ltrim(substr(x, 4), '0');
  elsif length(x) = 10 and left(x, 2) = '05' then
    x := '966' || substr(x, 2);
  elsif length(x) = 9 and left(x, 1) = '5' then
    x := '966' || x;
  end if;
  return x;
end $function$;
CREATE OR REPLACE FUNCTION public.normalize_arabic_name(s text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT
    btrim(
      regexp_replace(
        regexp_replace(
          btrim(
            translate(
              lower(coalesce(s, '')),
              'أإآىة' || E'ًٌٍَُِّْٰ',
              'ااايه'
            )
          ),
          '^(?:متجر|شركة|مؤسسة|مؤسسه|شركه|m1|l1)\s+', '', 'i'
        ),
        '[[:space:]\-_|/\\.،,]+', ' ', 'g'
      )
    );
$function$;
CREATE OR REPLACE FUNCTION public.outreach_impact(p_days integer DEFAULT 90)
 RETURNS TABLE(campaign_name text, contacted bigint, replied bigint, paid bigint, collected numeric, conv_rate numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with
  latest_snap as (select max(snapshot_date) sd from merchants),
  pc as (
    select distinct norm_sa_phone(m.phone) as phone, l.customer_name
    from merchants m
    join customer_merchant_links l on l.store_id = m.store_id
    where m.snapshot_date = (select sd from latest_snap) and norm_sa_phone(m.phone) is not null
  ),
  sends as (
    select coalesce(nullif(w.campaign_name,''),'(بلا اسم)') as campaign_name,
           w.phone, min(w.sent_at) as first_sent,
           bool_or(w.replied_at is not null and coalesce(w.reply_is_auto,false)=false) as replied
    from whatsapp_campaign_sends w
    where w.sent_at > now() - make_interval(days => greatest(p_days,1)) and w.phone is not null
    group by 1, 2
  ),
  paid as (
    select s.campaign_name, s.phone, sum(pm.amount) as amt
    from sends s
    join pc on pc.phone = s.phone
    join lateral (
      select distinct zp.zoho_id, zp.amount
      from zoho_payments zp
      where zp.customer_name = pc.customer_name
        and zp.date >= s.first_sent::date
        and zp.date <= (s.first_sent + interval '14 days')::date
    ) pm on true
    group by 1, 2
  )
  select s.campaign_name,
    count(distinct s.phone) as contacted,
    count(distinct s.phone) filter (where s.replied) as replied,
    count(distinct p.phone) as paid,
    coalesce(sum(p.amt), 0) as collected,
    round(100.0 * count(distinct p.phone) / nullif(count(distinct s.phone), 0), 1) as conv_rate
  from sends s
  left join paid p on p.campaign_name = s.campaign_name and p.phone = s.phone
  group by s.campaign_name
  order by collected desc, contacted desc;
$function$;
CREATE OR REPLACE FUNCTION public.platform_commercial_account(p_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v_base jsonb; v_routing jsonb;
begin
  v_base:=public.platform_sales_account(p_phone);
  select to_jsonb(routing) into v_routing from public.v_platform_commercial_routing routing where routing.phone=p_phone limit 1;
  if v_routing is null then raise exception 'account_not_found'; end if;
  return jsonb_set(v_base,'{account}',coalesce(v_base->'account','{}'::jsonb)||v_routing,true);
end;$function$;
CREATE OR REPLACE FUNCTION public.platform_commercial_pipeline_v2(p_bucket text DEFAULT 'hot_live_new'::text, p_work_filter text DEFAULT 'all'::text, p_sort text DEFAULT 'recommended'::text, p_owner uuid DEFAULT NULL::uuid, p_unassigned boolean DEFAULT false, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_see_all boolean;
  v_result jsonb;
begin
  if v_uid is null
     or not (
       public.crm_has_permission('sales.view')
       or public.crm_has_permission('crm.view')
       or public.crm_has_permission('merchants.view')
     ) then
    raise exception 'not_allowed';
  end if;

  v_see_all := public.crm_can_see_all();
  if p_owner is not null and p_owner is distinct from v_uid and not v_see_all then
    raise exception 'not_allowed';
  end if;

  if coalesce(p_bucket, 'all') not in (
    'all', 'hot_live_new', 'recent_stop', 'wallet_stranded', 'live_inactive',
    'new', 'in_progress', 'recontact_due', 'scheduled',
    'active', 'stopped', 'reactivated', 'won', 'lost', 'unscheduled'
  ) then
    raise exception 'invalid_bucket';
  end if;

  if coalesce(p_work_filter, 'all') not in (
    'all', 'action_now', 'never_contacted', 'no_answer', 'due',
    'contacted_no_next', 'scheduled', 'contacted', 'unassigned'
  ) then
    raise exception 'invalid_work_filter';
  end if;

  if coalesce(p_sort, 'recommended') not in (
    'recommended', 'recent_first', 'action_first', 'largest', 'least_contacted'
  ) then
    raise exception 'invalid_sort';
  end if;

  with recent_events as (
    select
      phone,
      bool_or(
        event_type in ('reactivated', 'shipping_resumed')
        and observed_at >= now() - interval '30 days'
      ) as reactivated_30d,
      max(observed_at) filter (
        where event_type in ('reactivated', 'shipping_resumed')
      ) as last_reactivated_at
    from public.merchant_lifecycle_events
    where phone is not null
    group by phone
  ),
  base as (
    select
      routing.*,
      followup.phone is not null as has_followup,
      coalesce(followup.sales_stage, 'new') as sales_stage,
      coalesce(followup.status, 'new') as last_outcome,
      followup.owner_id,
      profile.name as owner_name,
      followup.next_action_at,
      coalesce(followup.next_action_type, 'call') as next_action_type,
      followup.notes,
      followup.last_touch_at,
      followup.first_contact_at,
      coalesce(followup.contact_attempts, 0) as contact_attempts,
      followup.loss_reason,
      followup.lost_at,
      followup.won_at,
      followup.updated_at,
      coalesce(events.reactivated_30d, false) as reactivated_30d,
      events.last_reactivated_at,
      case
        when routing.financial_hold then 'financial_hold'
        when routing.total_shipments = 0 then 'pending_first_shipment'
        when routing.segment = 'active' then 'active'
        when routing.segment in ('stopped_recent', 'stopped_long') then 'stopped'
        else 'unknown'
      end as platform_state
    from public.v_platform_commercial_routing routing
    left join public.retargeting_followups followup
      on followup.phone = routing.phone
    left join public.profiles profile on profile.id = followup.owner_id
    left join recent_events events on events.phone = routing.phone
  ),
  prepared as (
    select
      base.*,
      case
        when next_action_at is not null and next_action_at <= now() then 'due'
        when last_outcome = 'no_answer' then 'no_answer'
        when next_action_at > now() then 'scheduled'
        when contact_attempts = 0 and last_touch_at is null then 'never_contacted'
        when last_touch_at is not null
          and next_action_at is null
          and sales_stage in (
            'new', 'contacted', 'qualified', 'proposal', 'negotiation', 'nurture'
          ) then 'contacted_no_next'
        when last_touch_at is not null or contact_attempts > 0 then 'contacted'
        else 'unassigned'
      end as work_state
    from base
  ),
  ranked as (
    select
      prepared.*,
      case
        when work_state = 'due' then 0
        when work_state = 'no_answer' then 1
        when work_state = 'never_contacted'
          and (
            commercial_signal in ('hot_live_new', 'hot_live_topped')
            or (recent_stop and days_since_last between 6 and 14)
          ) then 2
        when work_state = 'contacted_no_next' then 3
        when work_state = 'never_contacted' then 4
        when work_state = 'scheduled' then 5
        else 6
      end as work_rank
    from prepared
  ),
  scoped_raw as (
    select *
    from ranked
    where (v_see_all or owner_id = v_uid or not has_followup)
      and (p_owner is null or owner_id = p_owner)
      and (not p_unassigned or not has_followup or owner_id is null)
  ),
  sales_scoped as (
    select *
    from scoped_raw
    where sales_eligible
  ),
  searched as (
    select *
    from sales_scoped
    where p_search is null
       or btrim(p_search) = ''
       or phone ilike '%' || btrim(p_search) || '%'
       or primary_store ilike '%' || btrim(p_search) || '%'
       or exists (
         select 1
         from unnest(store_names) store_name
         where store_name ilike '%' || btrim(p_search) || '%'
       )
  ),
  bucketed as (
    select *
    from searched
    where coalesce(p_bucket, 'all') = 'all'
      or (p_bucket = 'hot_live_new' and (hot_live_new or hot_live_topped))
      or (p_bucket = 'recent_stop' and recent_stop)
      or (p_bucket = 'wallet_stranded' and wallet_stranded)
      or (p_bucket = 'live_inactive' and live_inactive)
      or (
        p_bucket = 'new'
        and total_shipments = 0
        and latest_created_at >= current_date - 30
        and sales_stage = 'new'
      )
      or (
        p_bucket = 'in_progress'
        and has_followup
        and sales_stage in (
          'new', 'contacted', 'qualified', 'proposal', 'negotiation', 'nurture'
        )
      )
      or (
        p_bucket = 'recontact_due'
        and has_followup
        and next_action_at is not null
        and next_action_at <= now()
        and sales_stage not in ('won', 'disqualified')
      )
      or (
        p_bucket = 'scheduled'
        and has_followup
        and next_action_at > now()
        and sales_stage not in ('won', 'disqualified')
      )
      or (p_bucket = 'active' and platform_state = 'active')
      or (p_bucket = 'stopped' and platform_state = 'stopped')
      or (p_bucket = 'reactivated' and reactivated_30d)
      or (p_bucket = 'won' and sales_stage = 'won')
      or (p_bucket = 'lost' and sales_stage = 'lost')
      or (
        p_bucket = 'unscheduled'
        and has_followup
        and next_action_at is null
        and sales_stage in (
          'new', 'contacted', 'qualified', 'proposal', 'negotiation', 'nurture'
        )
      )
  ),
  filtered as (
    select *
    from bucketed
    where coalesce(p_work_filter, 'all') = 'all'
      or (p_work_filter = 'action_now' and work_rank <= 3)
      or (
        p_work_filter = 'never_contacted'
        and contact_attempts = 0
        and last_touch_at is null
      )
      or (p_work_filter = 'no_answer' and last_outcome = 'no_answer')
      or (
        p_work_filter = 'due'
        and next_action_at is not null
        and next_action_at <= now()
      )
      or (
        p_work_filter = 'contacted_no_next'
        and last_touch_at is not null
        and next_action_at is null
        and sales_stage in (
          'new', 'contacted', 'qualified', 'proposal', 'negotiation', 'nurture'
        )
      )
      or (p_work_filter = 'scheduled' and next_action_at > now())
      or (
        p_work_filter = 'contacted'
        and (last_touch_at is not null or contact_attempts > 0)
      )
      or (p_work_filter = 'unassigned' and owner_id is null)
  ),
  sequenced as (
    select
      filtered.*,
      row_number() over (
        order by
          case
            when p_sort = 'recent_first'
              or (p_sort = 'recommended' and p_bucket = 'recent_stop')
            then days_since_last
          end asc nulls last,
          case
            when p_sort in ('recommended', 'action_first') then work_rank
          end asc nulls last,
          case when p_sort = 'largest' then total_shipments end desc nulls last,
          case when p_sort = 'least_contacted' then contact_attempts end asc nulls last,
          case when p_sort = 'least_contacted' then last_touch_at end asc nulls first,
          signal_score desc,
          next_action_at asc nulls last,
          updated_at desc nulls last,
          latest_created_at desc nulls last,
          primary_store,
          phone
      ) as result_order
    from filtered
  ),
  ordered as (
    select *
    from sequenced
    order by result_order
    limit greatest(1, least(coalesce(p_limit, 50), 100))
    offset greatest(0, coalesce(p_offset, 0))
  )
  select jsonb_build_object(
    'summary', (
      select jsonb_build_object(
        'total', count(*) filter (where sales_eligible),
        'hot_live_new', count(*) filter (
          where sales_eligible and (hot_live_new or hot_live_topped)
        ),
        'recent_stop', count(*) filter (where sales_eligible and recent_stop),
        'wallet_stranded', count(*) filter (
          where sales_eligible and wallet_stranded
        ),
        'live_inactive', count(*) filter (where sales_eligible and live_inactive),
        'collections_hold', count(*) filter (where financial_hold),
        'held_debt', coalesce(round(sum(debt) filter (where financial_hold), 2), 0),
        'held_negative_wallet', coalesce(
          round(sum(negative_wallet) filter (where financial_hold), 2), 0
        ),
        'manual_trials', count(*) filter (
          where sales_eligible and manual_only and joined_5d and total_shipments = 0
        ),
        'new', count(*) filter (
          where sales_eligible and total_shipments = 0
            and latest_created_at >= current_date - 30 and sales_stage = 'new'
        ),
        'in_progress', count(*) filter (
          where sales_eligible and has_followup
            and sales_stage in ('new', 'contacted', 'qualified', 'proposal', 'negotiation', 'nurture')
        ),
        'recontact_due', count(*) filter (
          where sales_eligible and has_followup and next_action_at is not null
            and next_action_at <= now() and sales_stage not in ('won', 'disqualified')
        ),
        'scheduled', count(*) filter (
          where sales_eligible and has_followup and next_action_at > now()
            and sales_stage not in ('won', 'disqualified')
        ),
        'active', count(*) filter (where sales_eligible and platform_state = 'active'),
        'stopped', count(*) filter (where sales_eligible and platform_state = 'stopped'),
        'reactivated', count(*) filter (where sales_eligible and reactivated_30d),
        'won', count(*) filter (where sales_eligible and sales_stage = 'won'),
        'lost', count(*) filter (where sales_eligible and sales_stage = 'lost'),
        'unscheduled', count(*) filter (
          where sales_eligible and has_followup and next_action_at is null
            and sales_stage in ('new', 'contacted', 'qualified', 'proposal', 'negotiation', 'nurture')
        ),
        'unassigned', count(*) filter (
          where sales_eligible and (not has_followup or owner_id is null)
        )
      )
      from scoped_raw
    ),
    'work_summary', (
      select jsonb_build_object(
        'total', count(*),
        'action_now', count(*) filter (where work_rank <= 3),
        'never_contacted', count(*) filter (
          where contact_attempts = 0 and last_touch_at is null
        ),
        'no_answer', count(*) filter (where last_outcome = 'no_answer'),
        'due', count(*) filter (
          where next_action_at is not null and next_action_at <= now()
        ),
        'contacted_no_next', count(*) filter (
          where last_touch_at is not null and next_action_at is null
            and sales_stage in ('new', 'contacted', 'qualified', 'proposal', 'negotiation', 'nurture')
        ),
        'scheduled', count(*) filter (where next_action_at > now()),
        'contacted', count(*) filter (
          where last_touch_at is not null or contact_attempts > 0
        ),
        'unassigned', count(*) filter (where owner_id is null)
      )
      from bucketed
    ),
    'count', (select count(*) from filtered),
    'rows', coalesce(
      (
        select jsonb_agg(
          to_jsonb(row_data) - 'result_order'
          order by row_data.result_order
        )
        from ordered row_data
      ),
      '[]'::jsonb
    )
  )
  into v_result;

  return v_result;
end;
$function$;
comment on function "public"."platform_commercial_pipeline_v2"(p_bucket text, p_work_filter text, p_sort text, p_owner uuid, p_unassigned boolean, p_search text, p_limit integer, p_offset integer) is 'Platform sales pipeline with server-side work-status facets, filters and deterministic pagination.';
CREATE OR REPLACE FUNCTION public.platform_commercial_pipeline(p_bucket text DEFAULT 'hot_live_new'::text, p_owner uuid DEFAULT NULL::uuid, p_unassigned boolean DEFAULT false, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := (select auth.uid()); v_see_all boolean; v_result jsonb;
begin
  if v_uid is null or not (public.crm_has_permission('sales.view') or public.crm_has_permission('crm.view') or public.crm_has_permission('merchants.view')) then raise exception 'not_allowed'; end if;
  v_see_all := public.crm_can_see_all();
  if p_owner is not null and p_owner is distinct from v_uid and not v_see_all then raise exception 'not_allowed'; end if;
  if coalesce(p_bucket, 'all') not in ('all','hot_live_new','recent_stop','wallet_stranded','live_inactive','new','in_progress','recontact_due','scheduled','active','stopped','reactivated','won','lost','unscheduled') then raise exception 'invalid_bucket'; end if;
  with recent_events as (
    select phone, bool_or(event_type in ('reactivated','shipping_resumed') and observed_at >= now() - interval '30 days') as reactivated_30d,
      max(observed_at) filter (where event_type in ('reactivated','shipping_resumed')) as last_reactivated_at
    from public.merchant_lifecycle_events where phone is not null group by phone
  ), base as (
    select routing.*, followup.phone is not null as has_followup, coalesce(followup.sales_stage,'new') as sales_stage,
      coalesce(followup.status,'new') as last_outcome, followup.owner_id, profile.name as owner_name,
      followup.next_action_at, coalesce(followup.next_action_type,'call') as next_action_type, followup.notes,
      followup.last_touch_at, followup.first_contact_at, coalesce(followup.contact_attempts,0) as contact_attempts,
      followup.loss_reason, followup.lost_at, followup.won_at, followup.updated_at,
      coalesce(events.reactivated_30d,false) as reactivated_30d, events.last_reactivated_at,
      case when routing.financial_hold then 'financial_hold' when routing.total_shipments=0 then 'pending_first_shipment'
        when routing.segment='active' then 'active' when routing.segment in ('stopped_recent','stopped_long') then 'stopped' else 'unknown' end as platform_state
    from public.v_platform_commercial_routing routing left join public.retargeting_followups followup on followup.phone=routing.phone
    left join public.profiles profile on profile.id=followup.owner_id left join recent_events events on events.phone=routing.phone
  ), scoped_raw as (
    select * from base where (v_see_all or owner_id=v_uid or not has_followup) and (p_owner is null or owner_id=p_owner) and (not p_unassigned or not has_followup)
  ), sales_scoped as (select * from scoped_raw where sales_eligible), searched as (
    select * from sales_scoped where p_search is null or btrim(p_search)='' or phone ilike '%'||btrim(p_search)||'%'
      or primary_store ilike '%'||btrim(p_search)||'%' or exists(select 1 from unnest(store_names) store_name where store_name ilike '%'||btrim(p_search)||'%')
  ), filtered as (
    select * from searched where coalesce(p_bucket,'all')='all'
      or (p_bucket='hot_live_new' and (hot_live_new or hot_live_topped)) or (p_bucket='recent_stop' and recent_stop)
      or (p_bucket='wallet_stranded' and wallet_stranded) or (p_bucket='live_inactive' and live_inactive)
      or (p_bucket='new' and total_shipments=0 and latest_created_at>=current_date-30 and sales_stage='new')
      or (p_bucket='in_progress' and has_followup and sales_stage in ('new','contacted','qualified','proposal','negotiation','nurture'))
      or (p_bucket='recontact_due' and has_followup and next_action_at is not null and next_action_at<=now() and sales_stage not in ('won','disqualified'))
      or (p_bucket='scheduled' and has_followup and next_action_at>now() and sales_stage not in ('won','disqualified'))
      or (p_bucket='active' and platform_state='active') or (p_bucket='stopped' and platform_state='stopped')
      or (p_bucket='reactivated' and reactivated_30d) or (p_bucket='won' and sales_stage='won') or (p_bucket='lost' and sales_stage='lost')
      or (p_bucket='unscheduled' and has_followup and next_action_at is null and sales_stage in ('new','contacted','qualified','proposal','negotiation','nurture'))
  ), ordered as (
    select * from filtered order by case when p_bucket = 'recent_stop' then days_since_last end asc nulls last, case when next_action_at is not null and next_action_at<=now() then 0 else 1 end,
      signal_score desc, next_action_at asc nulls last, updated_at desc nulls last, latest_created_at desc nulls last, primary_store
    limit greatest(1,least(coalesce(p_limit,50),100)) offset greatest(0,coalesce(p_offset,0))
  )
  select jsonb_build_object(
    'summary',(select jsonb_build_object(
      'total',count(*) filter(where sales_eligible),
      'hot_live_new',count(*) filter(where sales_eligible and (hot_live_new or hot_live_topped)),
      'recent_stop',count(*) filter(where sales_eligible and recent_stop),
      'wallet_stranded',count(*) filter(where sales_eligible and wallet_stranded),
      'live_inactive',count(*) filter(where sales_eligible and live_inactive),
      'collections_hold',count(*) filter(where financial_hold),
      'held_debt',coalesce(round(sum(debt) filter(where financial_hold),2),0),
      'held_negative_wallet',coalesce(round(sum(negative_wallet) filter(where financial_hold),2),0),
      'manual_trials',count(*) filter(where sales_eligible and manual_only and joined_5d and total_shipments=0),
      'new',count(*) filter(where sales_eligible and total_shipments=0 and latest_created_at>=current_date-30 and sales_stage='new'),
      'in_progress',count(*) filter(where sales_eligible and has_followup and sales_stage in ('new','contacted','qualified','proposal','negotiation','nurture')),
      'recontact_due',count(*) filter(where sales_eligible and has_followup and next_action_at is not null and next_action_at<=now() and sales_stage not in ('won','disqualified')),
      'scheduled',count(*) filter(where sales_eligible and has_followup and next_action_at>now() and sales_stage not in ('won','disqualified')),
      'active',count(*) filter(where sales_eligible and platform_state='active'),
      'stopped',count(*) filter(where sales_eligible and platform_state='stopped'),
      'reactivated',count(*) filter(where sales_eligible and reactivated_30d),
      'won',count(*) filter(where sales_eligible and sales_stage='won'), 'lost',count(*) filter(where sales_eligible and sales_stage='lost'),
      'unscheduled',count(*) filter(where sales_eligible and has_followup and next_action_at is null and sales_stage in ('new','contacted','qualified','proposal','negotiation','nurture')),
      'unassigned',count(*) filter(where sales_eligible and not has_followup)) from scoped_raw),
    'count',(select count(*) from filtered), 'rows',coalesce((select jsonb_agg(to_jsonb(row_data)) from ordered row_data),'[]'::jsonb)) into v_result;
  return v_result;
end;$function$;
comment on function "public"."platform_commercial_pipeline"(p_bucket text, p_owner uuid, p_unassigned boolean, p_search text, p_limit integer, p_offset integer) is 'Platform commercial pipeline. recent_stop is ordered by the fewest days beyond the five-day threshold; all other buckets retain their existing priority.';
CREATE OR REPLACE FUNCTION public.platform_commercial_signals()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_result jsonb;
begin
  if (select auth.uid()) is null or not (public.crm_has_permission('sales.view') or public.crm_has_permission('merchants.view') or public.crm_has_permission('crm.view')) then raise exception 'not_allowed'; end if;
  select jsonb_build_object(
    'summary',(select jsonb_build_object(
      'hot_live_new',count(*) filter(where sales_eligible and (hot_live_new or hot_live_topped)),
      'recent_stop',count(*) filter(where sales_eligible and recent_stop), 'wallet_stranded',count(*) filter(where sales_eligible and wallet_stranded),
      'live_inactive',count(*) filter(where sales_eligible and live_inactive),
      'manual_trials',count(*) filter(where sales_eligible and manual_only and joined_5d and total_shipments=0),
      'collections_only',count(*) filter(where financial_hold),
      'ready_to_activate',count(*) filter(where sales_eligible and total_shipments=0 and profile_done and verified and direct_live),
      'topped_no_ship',count(*) filter(where sales_eligible and segment='topped_no_ship'),
      'new_7d_no_ship',count(*) filter(where sales_eligible and total_shipments=0 and joined_5d),
      'stopped_30d',count(*) filter(where sales_eligible and segment='stopped_recent' and days_since_last<=30),
      'key_accounts_at_risk',count(*) filter(where sales_eligible and segment in ('stopped_recent','stopped_long') and total_shipments>=1000),
      'compliance_pending',count(*) filter(where sales_eligible and compliance_pending and total_shipments>0 and days_since_last<=30),
      'multi_store_accounts',count(*) filter(where sales_eligible and store_count>1)) from public.v_platform_commercial_routing),
    'opportunity_details',(select coalesce(jsonb_agg(to_jsonb(detail)),'[]'::jsonb) from (
      select routing.* from public.v_platform_commercial_routing routing left join public.retargeting_followups followup on followup.phone=routing.phone
      where followup.phone is null and routing.sales_eligible and (routing.hot_live_new or routing.hot_live_topped or routing.recent_stop or routing.wallet_stranded or routing.live_inactive or (routing.direct_live and routing.total_shipments=0))
      order by routing.signal_score desc,routing.total_shipments desc,routing.latest_created_at desc nulls last limit 200) detail),
    'activation_ready',(select coalesce(jsonb_agg(to_jsonb(ready) order by ready.signal_score desc,ready.latest_created_at desc),'[]'::jsonb) from (
      select routing.primary_store as store,routing.* from public.v_platform_commercial_routing routing left join public.retargeting_followups followup on followup.phone=routing.phone
      where followup.phone is null and routing.sales_eligible and routing.total_shipments=0 and routing.profile_done and routing.verified and routing.direct_live
        and (routing.latest_created_at is null or routing.latest_created_at<now()-interval '30 days')
      order by routing.signal_score desc,routing.latest_created_at desc nulls last limit 15) ready),
    'activation_ready_count',(select count(*) from public.v_platform_commercial_routing routing left join public.retargeting_followups followup on followup.phone=routing.phone
      where followup.phone is null and routing.sales_eligible and routing.total_shipments=0 and routing.profile_done and routing.verified and routing.direct_live
        and (routing.latest_created_at is null or routing.latest_created_at<now()-interval '30 days')))
  into v_result; return v_result;
end;$function$;
CREATE OR REPLACE FUNCTION public.platform_sales_account(p_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_owner uuid;
  v_exists boolean;
  v_result jsonb;
begin
  if v_uid is null
     or not (
       public.crm_has_permission('sales.view')
       or public.crm_has_permission('crm.view')
       or public.crm_has_permission('merchants.view')
     ) then
    raise exception 'not_allowed';
  end if;

  select
    f.owner_id,
    v.phone is not null
  into v_owner, v_exists
  from public.v_crm_retargeting v
  left join public.retargeting_followups f on f.phone = v.phone
  where v.phone = p_phone
  limit 1;

  if not coalesce(v_exists, false) then
    raise exception 'account_not_found';
  end if;

  if v_owner is not null
     and v_owner is distinct from v_uid
     and not public.crm_can_see_all() then
    raise exception 'not_allowed';
  end if;

  select jsonb_build_object(
    'account', (
      select to_jsonb(account_row)
      from (
        select
          v.*,
          coalesce(f.sales_stage, 'new') as sales_stage,
          coalesce(f.status, 'new') as last_outcome,
          f.owner_id,
          profile.name as owner_name,
          f.next_action_at,
          coalesce(f.next_action_type, 'call') as next_action_type,
          f.notes,
          f.last_touch_at,
          f.first_contact_at,
          coalesce(f.contact_attempts, 0) as contact_attempts,
          f.loss_reason,
          f.lost_at,
          f.won_at,
          f.updated_at
        from public.v_crm_retargeting v
        left join public.retargeting_followups f on f.phone = v.phone
        left join public.profiles profile on profile.id = f.owner_id
        where v.phone = p_phone
        limit 1
      ) account_row
    ),
    'activities', (
      select coalesce(jsonb_agg(to_jsonb(activity_row) order by activity_row.occurred_at desc), '[]'::jsonb)
      from (
        select
          activity.id,
          activity.kind,
          activity.disposition,
          activity.summary,
          activity.body,
          activity.occurred_at,
          profile.name as created_by_name
        from public.crm_activities activity
        left join public.profiles profile on profile.id = activity.created_by
        where activity.entity_type = 'platform_merchant'
          and activity.entity_ref = p_phone
        order by activity.occurred_at desc
        limit 100
      ) activity_row
    ),
    'lifecycle', (
      select coalesce(jsonb_agg(to_jsonb(lifecycle_row) order by lifecycle_row.observed_at desc), '[]'::jsonb)
      from (
        select
          event_type,
          store_name,
          from_value,
          to_value,
          shipment_delta,
          wallet_delta,
          observed_at
        from public.merchant_lifecycle_events
        where phone = p_phone
        order by observed_at desc
        limit 100
      ) lifecycle_row
    ),
    'status_changes', (
      select coalesce(jsonb_agg(to_jsonb(status_row) order by status_row.changed_at desc), '[]'::jsonb)
      from (
        select
          log.old_status,
          log.new_status,
          log.changed_at,
          profile.name as changed_by_name
        from public.retargeting_status_log log
        left join public.profiles profile on profile.id = log.changed_by
        where log.phone = p_phone
        order by log.changed_at desc
        limit 100
      ) status_row
    )
  )
  into v_result;

  return v_result;
end;
$function$;
comment on function "public"."platform_sales_account"(p_phone text) is 'ملف متجر مبيعات 360: معلومات المنصة + ملاحظات الموظف + دورة الحياة.';
CREATE OR REPLACE FUNCTION public.platform_sales_pipeline(p_bucket text DEFAULT 'new'::text, p_owner uuid DEFAULT NULL::uuid, p_unassigned boolean DEFAULT false, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_see_all boolean;
  v_result jsonb;
begin
  if v_uid is null
     or not (
       public.crm_has_permission('sales.view')
       or public.crm_has_permission('crm.view')
       or public.crm_has_permission('merchants.view')
     ) then
    raise exception 'not_allowed';
  end if;

  v_see_all := public.crm_can_see_all();
  if p_owner is not null and p_owner is distinct from v_uid and not v_see_all then
    raise exception 'not_allowed';
  end if;

  if coalesce(p_bucket, 'all') not in (
    'all', 'new', 'in_progress', 'recontact_due', 'scheduled',
    'active', 'stopped', 'reactivated', 'won', 'lost', 'unscheduled'
  ) then
    raise exception 'invalid_bucket';
  end if;

  with recent_events as (
    select
      phone,
      bool_or(event_type in ('reactivated', 'shipping_resumed')
        and observed_at >= now() - interval '30 days') as reactivated_30d,
      max(observed_at) filter (
        where event_type in ('reactivated', 'shipping_resumed')
      ) as last_reactivated_at
    from public.merchant_lifecycle_events
    where phone is not null
    group by phone
  ),
  base as (
    select
      v.phone,
      v.primary_store,
      v.store_names,
      v.store_count,
      v.total_shipments,
      v.last_shipment,
      v.days_since_last,
      v.wallet,
      v.last_topup,
      v.created_at,
      v.integration_type,
      v.billing_type,
      v.profile_done,
      v.verified,
      v.segment,
      v.priority,
      v.channel,
      v.readiness_score,
      v.opportunity_score,
      v.team_route,
      v.next_step,
      f.phone is not null as has_followup,
      coalesce(f.sales_stage, 'new') as sales_stage,
      coalesce(f.status, 'new') as last_outcome,
      f.owner_id,
      profile.name as owner_name,
      f.next_action_at,
      coalesce(f.next_action_type, 'call') as next_action_type,
      f.notes,
      f.last_touch_at,
      f.first_contact_at,
      coalesce(f.contact_attempts, 0) as contact_attempts,
      f.loss_reason,
      f.lost_at,
      f.won_at,
      f.updated_at,
      coalesce(events.reactivated_30d, false) as reactivated_30d,
      events.last_reactivated_at,
      case
        when v.segment = 'negative_balance' then 'financial_hold'
        when v.total_shipments = 0 then 'pending_first_shipment'
        when v.segment = 'active' then 'active'
        when v.segment in ('stopped_recent', 'stopped_long') then 'stopped'
        else 'unknown'
      end as platform_state
    from public.v_crm_retargeting v
    left join public.retargeting_followups f on f.phone = v.phone
    left join public.profiles profile on profile.id = f.owner_id
    left join recent_events events on events.phone = v.phone
  ),
  scoped as (
    select *
    from base
    where
      (v_see_all or owner_id = v_uid or not has_followup)
      and (p_owner is null or owner_id = p_owner)
      and (not p_unassigned or not has_followup)
  ),
  searched as (
    select *
    from scoped
    where p_search is null
       or btrim(p_search) = ''
       or phone ilike '%' || btrim(p_search) || '%'
       or primary_store ilike '%' || btrim(p_search) || '%'
       or exists (
         select 1
         from unnest(store_names) store_name
         where store_name ilike '%' || btrim(p_search) || '%'
       )
  ),
  filtered as (
    select *
    from searched
    where
      coalesce(p_bucket, 'all') = 'all'
      or (
        p_bucket = 'new'
        and total_shipments = 0
        and created_at >= current_date - 30
        and sales_stage = 'new'
      )
      or (
        p_bucket = 'in_progress'
        and has_followup
        and sales_stage in (
          'new', 'contacted', 'qualified', 'proposal', 'negotiation', 'nurture'
        )
      )
      or (
        p_bucket = 'recontact_due'
        and has_followup
        and next_action_at is not null
        and next_action_at <= now()
        and sales_stage not in ('won', 'disqualified')
      )
      or (
        p_bucket = 'scheduled'
        and has_followup
        and next_action_at > now()
        and sales_stage not in ('won', 'disqualified')
      )
      or (p_bucket = 'active' and platform_state = 'active')
      or (p_bucket = 'stopped' and platform_state = 'stopped')
      or (p_bucket = 'reactivated' and reactivated_30d)
      or (p_bucket = 'won' and sales_stage = 'won')
      or (p_bucket = 'lost' and sales_stage = 'lost')
      or (
        p_bucket = 'unscheduled'
        and has_followup
        and next_action_at is null
        and sales_stage in (
          'new', 'contacted', 'qualified', 'proposal', 'negotiation', 'nurture'
        )
      )
  ),
  ordered as (
    select *
    from filtered
    order by
      case when next_action_at is not null and next_action_at <= now() then 0 else 1 end,
      case
        when p_bucket = 'new' then opportunity_score
        when p_bucket = 'stopped' then least(total_shipments, 2147483647)::integer
        else 0
      end desc,
      next_action_at asc nulls last,
      updated_at desc nulls last,
      created_at desc nulls last,
      primary_store
    limit greatest(1, least(coalesce(p_limit, 50), 100))
    offset greatest(0, coalesce(p_offset, 0))
  )
  select jsonb_build_object(
    'summary', jsonb_build_object(
      'total', count(*),
      'new', count(*) filter (
        where total_shipments = 0
          and created_at >= current_date - 30
          and sales_stage = 'new'
      ),
      'in_progress', count(*) filter (
        where has_followup
          and sales_stage in (
            'new', 'contacted', 'qualified', 'proposal', 'negotiation', 'nurture'
          )
      ),
      'recontact_due', count(*) filter (
        where has_followup
          and next_action_at is not null
          and next_action_at <= now()
          and sales_stage not in ('won', 'disqualified')
      ),
      'scheduled', count(*) filter (
        where has_followup
          and next_action_at > now()
          and sales_stage not in ('won', 'disqualified')
      ),
      'active', count(*) filter (where platform_state = 'active'),
      'stopped', count(*) filter (where platform_state = 'stopped'),
      'reactivated', count(*) filter (where reactivated_30d),
      'won', count(*) filter (where sales_stage = 'won'),
      'lost', count(*) filter (where sales_stage = 'lost'),
      'unscheduled', count(*) filter (
        where has_followup
          and next_action_at is null
          and sales_stage in (
            'new', 'contacted', 'qualified', 'proposal', 'negotiation', 'nurture'
          )
      ),
      'unassigned', count(*) filter (where not has_followup)
    ),
    'count', (select count(*) from filtered),
    'rows', coalesce((select jsonb_agg(to_jsonb(row_data)) from ordered row_data), '[]'::jsonb)
  )
  into v_result
  from scoped;

  return v_result;
end;
$function$;
comment on function "public"."platform_sales_pipeline"(p_bucket text, p_owner uuid, p_unassigned boolean, p_search text, p_limit integer, p_offset integer) is 'مسار مبيعات متاجر المنصة: مرحلة بيع منفصلة عن الحالة التشغيلية، مع عدادات وفلاتر مرقمة.';
CREATE OR REPLACE FUNCTION public.purge_hatif_events()
 RETURNS TABLE(echo_deleted bigint, old_deleted bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_echo bigint; v_old bigint;
begin
  with d as (
    delete from hatif_events
    where received_at < now() - interval '14 days'
      and event_type in ('CustomPropertyChanged','LastEventUpdated',
                         'StatusChanged','TagAdded','TagRemoved')
    returning 1
  ) select count(*) into v_echo from d;

  with d as (
    delete from hatif_events
    where received_at < now() - interval '180 days'
    returning 1
  ) select count(*) into v_old from d;

  return query select v_echo, v_old;
end $function$;
CREATE OR REPLACE FUNCTION public.reconcile_collection_promises_internal()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_updated integer:=0;
begin
  with calc as (
    select t.id,coalesce(ar.collectible_due,0)::numeric current_debt,
      least(
        coalesce((select sum(p.amount) from public.zoho_payments p
          where p.customer_name=t.customer_name and p.date>=coalesce(t.promised_at,t.updated_at)::date),0),
        greatest(coalesce(t.promise_baseline_debt,t.debt_at_creation)-coalesce(ar.collectible_due,0),0)
      )::numeric verified_paid
    from public.collection_tasks t
    left join public.customer_ar ar on ar.contact_name=t.customer_name
    where t.stage='promised' and coalesce(t.promise_status,'pending') in ('pending','partial')
  )
  update public.collection_tasks t set
    promise_paid_amount=round(c.verified_paid,2),promise_verified_at=now(),
    promise_status=case when c.verified_paid>=greatest(coalesce(t.promise_amount,0)-0.5,0) then 'honored'
      when t.promise_date<current_date then 'broken' when c.verified_paid>0.5 then 'partial' else 'pending' end,
    honored_amount=case when c.verified_paid>=greatest(coalesce(t.promise_amount,0)-0.5,0)
      then round(c.verified_paid,2) else t.honored_amount end,
    stage=case when c.current_debt<=0.5 then 'done'
      when c.verified_paid>=greatest(coalesce(t.promise_amount,0)-0.5,0) then 'todo'
      when t.promise_date<current_date then 'contacted' else 'promised' end,
    done_at=case when c.current_debt<=0.5 then now() else t.done_at end,updated_at=now()
  from calc c where c.id=t.id;
  get diagnostics v_updated=row_count;
  return jsonb_build_object('checked',v_updated);
end;
$function$;
CREATE OR REPLACE FUNCTION public.record_customer_growth_outcome(p_phone text, p_reason_code text, p_outcome text, p_next timestamp with time zone DEFAULT NULL::timestamp with time zone, p_activity_type text DEFAULT 'call'::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO ''
AS $function$
  select private.record_customer_growth_outcome(
    p_phone, p_reason_code, p_outcome, p_next, p_activity_type, p_note
  )
$function$;
CREATE OR REPLACE FUNCTION public.record_platform_sales_activity(p_phone text, p_stage text DEFAULT NULL::text, p_outcome text DEFAULT NULL::text, p_activity_type text DEFAULT 'note'::text, p_next timestamp with time zone DEFAULT NULL::timestamp with time zone, p_next_type text DEFAULT 'call'::text, p_note text DEFAULT NULL::text, p_owner uuid DEFAULT NULL::uuid, p_loss_reason text DEFAULT NULL::text, p_touch boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_existing public.retargeting_followups%rowtype;
  v_owner uuid;
  v_stage text;
  v_old_outcome text;
begin
  if v_uid is null or not public.crm_has_permission('sales.manage') then
    raise exception 'not_allowed';
  end if;

  if p_phone is null or btrim(p_phone) = '' then
    raise exception 'phone_required';
  end if;

  if p_activity_type not in ('note', 'call', 'whatsapp', 'meeting', 'email') then
    raise exception 'invalid_activity_type';
  end if;

  if p_stage is not null and p_stage not in (
    'new', 'contacted', 'qualified', 'proposal',
    'negotiation', 'nurture', 'won', 'lost', 'disqualified'
  ) then
    raise exception 'invalid_stage';
  end if;

  if p_next_type is not null
     and p_next_type not in ('call', 'whatsapp', 'meeting', 'email', 'other') then
    raise exception 'invalid_next_action_type';
  end if;

  select *
  into v_existing
  from public.retargeting_followups
  where phone = p_phone
  for update;

  if found
     and v_existing.owner_id is not null
     and v_existing.owner_id is distinct from v_uid
     and not public.crm_can_see_all() then
    raise exception 'not_allowed';
  end if;

  if p_owner is not null
     and p_owner is distinct from v_uid
     and not public.crm_has_permission('crm.assign') then
    raise exception 'assign_not_allowed';
  end if;

  v_owner := coalesce(p_owner, v_existing.owner_id, v_uid);
  v_stage := coalesce(p_stage, v_existing.sales_stage, 'new');
  v_old_outcome := v_existing.status;

  if v_stage = 'lost'
     and nullif(btrim(coalesce(p_loss_reason, v_existing.loss_reason)), '') is null then
    raise exception 'loss_reason_required';
  end if;

  if p_touch
     and v_stage in ('new', 'contacted', 'qualified', 'proposal', 'negotiation', 'nurture')
     and p_next is null then
    raise exception 'next_action_required';
  end if;

  insert into public.retargeting_followups (
    phone,
    status,
    sales_stage,
    owner_id,
    next_action_at,
    next_action_type,
    notes,
    last_touch_at,
    first_contact_at,
    contact_attempts,
    loss_reason,
    lost_at,
    won_at,
    updated_by,
    updated_at
  )
  values (
    p_phone,
    coalesce(p_outcome, 'new'),
    v_stage,
    v_owner,
    p_next,
    coalesce(p_next_type, 'call'),
    nullif(btrim(p_note), ''),
    case when p_touch then now() end,
    case when p_touch then now() end,
    case when p_touch then 1 else 0 end,
    case when v_stage = 'lost' then nullif(btrim(p_loss_reason), '') end,
    case when v_stage = 'lost' then now() end,
    case when v_stage = 'won' then now() end,
    v_uid,
    now()
  )
  on conflict (phone) do update set
    status = coalesce(p_outcome, public.retargeting_followups.status),
    sales_stage = v_stage,
    owner_id = v_owner,
    next_action_at = coalesce(p_next, public.retargeting_followups.next_action_at),
    next_action_type = case
      when p_next is not null then coalesce(p_next_type, 'call')
      else public.retargeting_followups.next_action_type
    end,
    notes = coalesce(nullif(btrim(p_note), ''), public.retargeting_followups.notes),
    last_touch_at = case
      when p_touch then now()
      else public.retargeting_followups.last_touch_at
    end,
    first_contact_at = case
      when p_touch then coalesce(public.retargeting_followups.first_contact_at, now())
      else public.retargeting_followups.first_contact_at
    end,
    contact_attempts = public.retargeting_followups.contact_attempts
      + case when p_touch then 1 else 0 end,
    loss_reason = case
      when v_stage = 'lost' then coalesce(
        nullif(btrim(p_loss_reason), ''),
        public.retargeting_followups.loss_reason
      )
      when v_stage <> 'lost' then null
      else public.retargeting_followups.loss_reason
    end,
    lost_at = case
      when v_stage = 'lost' then coalesce(public.retargeting_followups.lost_at, now())
      when v_stage <> 'lost' then null
      else public.retargeting_followups.lost_at
    end,
    won_at = case
      when v_stage = 'won' then coalesce(public.retargeting_followups.won_at, now())
      when v_stage <> 'won' then null
      else public.retargeting_followups.won_at
    end,
    updated_by = v_uid,
    updated_at = now();

  if p_outcome is not null
     and p_outcome is distinct from coalesce(v_old_outcome, 'new') then
    insert into public.retargeting_status_log (
      phone, old_status, new_status, changed_by
    )
    values (p_phone, v_old_outcome, p_outcome, v_uid);
  end if;

  insert into public.crm_activities (
    entity_type,
    entity_ref,
    kind,
    disposition,
    summary,
    body,
    occurred_at,
    owner_id,
    created_by
  )
  values (
    'platform_merchant',
    p_phone,
    'sales_' || p_activity_type,
    p_outcome,
    case
      when p_stage is not null
        and p_stage is distinct from v_existing.sales_stage
        then 'مرحلة البيع: ' || coalesce(v_existing.sales_stage, 'new') || ' → ' || v_stage
      when p_next is not null
        then 'جُدول الإجراء التالي'
      else 'ملاحظة مبيعات'
    end,
    nullif(btrim(p_note), ''),
    now(),
    v_owner,
    v_uid
  );

  return (
    select to_jsonb(followup)
    from public.retargeting_followups followup
    where followup.phone = p_phone
  );
end;
$function$;
comment on function "public"."record_platform_sales_activity"(p_phone text, p_stage text, p_outcome text, p_activity_type text, p_next timestamp with time zone, p_next_type text, p_note text, p_owner uuid, p_loss_reason text, p_touch boolean) is 'تسجيل تواصل/ملاحظة وجدولة الإجراء التالي ذرياً؛ ردود هاتف لا تستدعيها تلقائياً.';
CREATE OR REPLACE FUNCTION public.refresh_collection_tasks()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_created int := 0;
  v_closed int := 0;
  v_cancelled int := 0;
  v_promises jsonb;
begin
  if v_uid is null or not public.crm_has_permission('collections.regenerate') then
    raise exception 'not_allowed';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('refresh_collection_tasks', 0));
  v_promises := public.reconcile_collection_promises_internal();

  update public.collection_tasks t
  set stage = 'done',
      done_at = now(),
      updated_at = now(),
      notes = concat_ws(
        ' · ',
        nullif(t.notes, ''),
        'أُغلقت تلقائياً: لا يوجد مبلغ مطلوب تحصيله بعد احتساب رصيد زوهو الدائن'
      )
  where t.stage in ('todo', 'contacted', 'promised', 'snoozed')
    and t.trigger <> 'manual'
    and not exists (
      select 1
      from public.customer_ar ar
      where ar.contact_name = t.customer_name
        and ar.collectible_due > 0.5
    );
  get diagnostics v_closed = row_count;

  update public.collection_tasks t
  set stage = 'cancelled',
      updated_at = now(),
      notes = concat_ws(
        ' · ',
        nullif(t.notes, ''),
        'استُبدلت تلقائياً بسبب تحصيل أعلى أولوية'
      )
  from public.v_collection_candidates c
  where c.customer_name = t.customer_name
    and c.trigger is distinct from t.trigger
    and t.stage in ('todo', 'contacted', 'snoozed');
  get diagnostics v_cancelled = row_count;

  with missing as (
    select c.*
    from public.v_collection_candidates c
    where c.trigger is not null
      and not exists (
        select 1
        from public.collection_tasks t
        where t.customer_name = c.customer_name
          and t.stage in ('todo', 'contacted', 'promised', 'snoozed')
      )
  )
  insert into public.collection_tasks (
    customer_name,
    trigger,
    stage,
    debt_at_creation,
    credit_limit,
    days_outstanding,
    assigned_to
  )
  select
    customer_name,
    trigger,
    'todo',
    debt,
    10000,
    days_outstanding,
    null
  from missing
  on conflict do nothing;
  get diagnostics v_created = row_count;

  return jsonb_build_object(
    'created', v_created,
    'closed', v_closed,
    'cancelled', v_cancelled,
    'reassigned', 0,
    'promises', v_promises
  );
end;
$function$;
CREATE OR REPLACE FUNCTION public.reply_intent(t text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case
    when t is null or length(btrim(t)) < 2 then null
    -- ردّاد متجر آلي (حتى لو تأخّر >60ث) → يُتجاهَل
    when t ~ 'شكر.{0,4}(لك )?على تواصلك|شكر.{0,4}لتواصلك|يسعدنا خدمتك|يسعدنا تواصلك|سنرد على رسالتك|سنقوم بالرد|سيتم الرد|في أقرب وقت|المحل مغلق|الطلب (عن طريق |ب)?الموقع|اختار.{0,4}الرقم المناسب|الاسعار.{0,6}الموقع|زيارة الموقع|تفضل.{0,4}(بزيارة|على الموقع)|حياك الله (في|ب)|حياكم الله (في|ب)|(أهلا|اهلا|أهلاً)( وسهلا)?( بك| بكم)? (في|ب)\S|مرحبا بكم? في|عزيز(ي|تي) العميل|استفسارك محل|إستفسارك محل|يرجى إخبارنا|أخبرنا كيف يمكننا|بما يمكننا القيام|تم تغيير رقم|خدمة العملاء|أوقات (العمل|الدوام|الاستقبال)|ساعات العمل|خارج أوقات|رد آلي|الرد الآلي|رسالة (آلية|تلقائية)|تم إرسال هذه الرسالة تلقائ|واتساب الأعمال|whatsapp business' then null
    when t ~ 'اتصال|اتصلوا|كلموني|كلمني|رقمكم|تتصلون|أتصل|اتصلو' then 'wants_call'
    when t ~ 'غالي|مرتفع.{0,8}سعر|أرخص|ارخص|تخفيض|خصم|السعر.{0,8}عالي' then 'price'
    when t ~ 'ما ?بي|ما ?اريد|مو مهتم|مب مهتم|لست مهتم|توقفت|مسكر|مغلق نهائي|لا شكرا|not interested' then 'not_interested'
    when t ~ 'تفاصيل|معلومات|كيف|الاسعار|الأسعار|السعر|الوزن|الشحن|ممكن|كم |وش |ايش|أكثر|اكثر|أبغى|ابغى|أريد|اريد' then 'interested'
    else null
  end;
$function$;
CREATE OR REPLACE FUNCTION public.resolve_snapshot_names(p_names text[], p_threshold numeric DEFAULT 0.78)
 RETURNS TABLE(raw_name text, store_id text, match_method text, match_confidence numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH input AS (SELECT DISTINCT n AS raw_name FROM unnest(p_names) AS n),
  tier1 AS (
    SELECT i.raw_name, l.store_id,
           'link-' || coalesce(l.match_method, 'auto') AS match_method,
           coalesce(l.confidence, 1.0)::numeric        AS match_confidence
    FROM input i
    JOIN LATERAL (
      SELECT store_id, match_method, confidence FROM customer_merchant_links
      WHERE customer_name = i.raw_name AND store_id IS NOT NULL LIMIT 1
    ) l ON true
  ),
  rem1 AS (SELECT raw_name FROM input EXCEPT SELECT raw_name FROM tier1),
  -- Tier 2: تطابق دقيق بعد التطبيع — المتجر يُختار من `merchant_by_name`
  tier2 AS (
    SELECT r.raw_name, m.store_id, 'exact'::text AS match_method, 1.0::numeric AS match_confidence
    FROM rem1 r JOIN merchant_by_name m ON m.nname = normalize_arabic_name(r.raw_name)
  ),
  rem2 AS (SELECT raw_name FROM rem1 EXCEPT SELECT raw_name FROM tier2),
  tier3 AS (
    SELECT r.raw_name, b.store_id, 'fuzzy'::text AS match_method, b.confidence AS match_confidence
    FROM rem2 r
    JOIN bulk_match_customers((SELECT array_agg(raw_name) FROM rem2), p_threshold) b
      ON b.customer_name = r.raw_name
  )
  SELECT raw_name, store_id, match_method, match_confidence FROM tier1
  UNION ALL SELECT raw_name, store_id, match_method, match_confidence FROM tier2
  UNION ALL SELECT raw_name, store_id, match_method, match_confidence FROM tier3
  UNION ALL
  SELECT raw_name, NULL::text, 'unmatched'::text, 0::numeric
  FROM (SELECT raw_name FROM rem2 EXCEPT SELECT raw_name FROM tier3) u;
$function$;
CREATE OR REPLACE FUNCTION public.sales_owner_stats()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'owner_id', f.owner_id,
    'assigned', f.total,
    'worked', f.worked,
    'returned', f.returned,
    'conversion_pct', case when f.worked > 0 then round(f.returned * 100.0 / f.worked, 1) else 0 end,
    'touches_7d', f.touches_7d
  )), '[]'::jsonb)
  from (
    select owner_id,
      count(*) total,
      count(*) filter (where status <> 'new') worked,
      count(*) filter (where status in ('returned','converted')) returned,
      count(*) filter (where last_touch_at > now() - interval '7 days') touches_7d
    from retargeting_followups
    where owner_id is not null
    group by owner_id
  ) f;
$function$;
CREATE OR REPLACE FUNCTION public.sales_today_routed(p_user uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid:=coalesce(p_user,(select auth.uid())); v_base jsonb; v_due jsonb; v_opportunities jsonb; v_opportunity_count integer; v_followups_total integer;
begin
  v_base:=public.sales_today(p_user);
  select coalesce(jsonb_agg(item order by item->>'next_at'),'[]'::jsonb) into v_due
  from jsonb_array_elements(coalesce(v_base->'due_followups','[]'::jsonb)) item
  left join public.v_platform_commercial_routing routing on routing.phone=item->>'phone'
  where routing.phone is null or routing.sales_eligible;
  select coalesce(jsonb_agg(to_jsonb(opportunity) order by opportunity.signal_score desc),'[]'::jsonb) into v_opportunities from (
    select routing.phone,routing.primary_store as store,routing.segment,routing.priority,routing.channel,routing.total_shipments,routing.wallet,
      routing.created_at,routing.last_shipment,routing.days_since_last,routing.store_count,routing.store_names,routing.integration_type,routing.billing_type,
      routing.profile_done,routing.verified,routing.vat_reg,routing.zatca_done,routing.compliance_pending,routing.readiness_score,routing.opportunity_score,
      routing.team_route,routing.next_step,routing.direct_live,routing.integration_class,routing.positive_wallet,routing.negative_wallet,routing.debt,
      routing.commercial_signal,routing.signal_score,routing.signal_reason,routing.assigned_team,routing.hot_live_new,routing.hot_live_topped,
      routing.recent_stop,routing.wallet_stranded,routing.live_inactive
    from public.v_platform_commercial_routing routing left join public.retargeting_followups followup on followup.phone=routing.phone
    where followup.phone is null and routing.sales_eligible and (routing.hot_live_new or routing.hot_live_topped or routing.recent_stop or routing.wallet_stranded or routing.live_inactive or (routing.direct_live and routing.total_shipments=0))
    order by routing.signal_score desc,routing.latest_created_at desc nulls last,routing.total_shipments desc limit 30) opportunity;
  select count(*) into v_opportunity_count from public.v_platform_commercial_routing routing left join public.retargeting_followups followup on followup.phone=routing.phone
    where followup.phone is null and routing.sales_eligible and (routing.hot_live_new or routing.hot_live_topped or routing.recent_stop or routing.wallet_stranded or routing.live_inactive or (routing.direct_live and routing.total_shipments=0));
  select count(*) into v_followups_total from public.retargeting_followups followup left join public.v_platform_commercial_routing routing on routing.phone=followup.phone
    where followup.owner_id=v_user and (routing.phone is null or routing.sales_eligible)
      and followup.status not in ('converted','returned','not_interested','supplier','noise','blacklist','test');
  v_base:=jsonb_set(v_base,'{due_followups}',v_due,true);
  v_base:=jsonb_set(v_base,'{platform_opportunities}',v_opportunities,true);
  v_base:=jsonb_set(v_base,'{platform_opportunity_count}',to_jsonb(v_opportunity_count),true);
  v_base:=jsonb_set(v_base,'{my_followups_total}',to_jsonb(v_followups_total),true);
  return v_base;
end;$function$;
comment on function "public"."sales_today_routed"(p_user uuid) is 'Existing sales_today payload with platform opportunities and followups filtered through commercial team routing.';
CREATE OR REPLACE FUNCTION public.sales_today(p_user uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  u uuid := coalesce(p_user, auth.uid());
  out jsonb;
begin
  if auth.uid() is null then
    raise exception 'not_authenticated';
  end if;

  if u is distinct from auth.uid() and not public.crm_can_see_all() then
    raise exception 'not_allowed';
  end if;

  select jsonb_build_object(
    'due_followups', (
      select coalesce(jsonb_agg(to_jsonb(x) order by x.next_at), '[]'::jsonb)
      from (
        select
          f.phone,
          v.primary_store as store,
          f.status,
          f.next_action_at as next_at,
          f.notes,
          greatest(0, extract(day from now() - f.next_action_at))::int as days_over
        from public.retargeting_followups f
        left join lateral (
          select primary_store
          from public.v_crm_retargeting v
          where v.phone = f.phone
          limit 1
        ) v on true
        where f.owner_id = u
          and f.next_action_at is not null
          and f.next_action_at <= now() + interval '12 hours'
          and f.status not in (
            'converted', 'returned', 'not_interested',
            'supplier', 'noise', 'blacklist', 'test'
          )
        order by f.next_action_at
        limit 30
      ) x
    ),
    'platform_opportunities', (
      select coalesce(jsonb_agg(to_jsonb(x) order by x.rank_order, x.created_at desc nulls last), '[]'::jsonb)
      from (
        select
          v.phone,
          v.primary_store as store,
          v.segment,
          v.priority,
          v.channel,
          v.total_shipments,
          v.wallet,
          v.created_at,
          v.last_shipment,
          v.days_since_last,
          case
            when v.segment = 'topped_no_ship' then 1
            when v.segment in ('new_active', 'linked_no_ship', 'registered_no_ship')
              and v.created_at >= now() - interval '7 days' then 2
            when v.segment = 'stopped_recent' and v.priority = 'A' then 3
            when v.segment = 'stopped_recent' then 4
            when v.segment = 'stopped_long' and v.priority = 'A' then 5
            when v.segment = 'linked_no_ship' then 6
            else 7
          end as rank_order
        from public.v_crm_retargeting v
        left join public.retargeting_followups f on f.phone = v.phone
        where f.phone is null
          and (
            v.segment = 'topped_no_ship'
            or v.segment = 'stopped_recent'
            or (v.segment = 'stopped_long' and v.priority = 'A')
            or (
              v.segment in ('new_active', 'linked_no_ship', 'registered_no_ship')
              and v.created_at >= now() - interval '30 days'
            )
          )
        order by rank_order, v.created_at desc nulls last, v.total_shipments desc
        limit 30
      ) x
    ),
    'platform_opportunity_count', (
      select count(*)
      from public.v_crm_retargeting v
      left join public.retargeting_followups f on f.phone = v.phone
      where f.phone is null
        and (
          v.segment = 'topped_no_ship'
          or v.segment = 'stopped_recent'
          or (v.segment = 'stopped_long' and v.priority = 'A')
          or (
            v.segment in ('new_active', 'linked_no_ship', 'registered_no_ship')
            and v.created_at >= now() - interval '30 days'
          )
        )
    ),
    'lead_actions', (
      select coalesce(jsonb_agg(to_jsonb(x) order by x.next_at), '[]'::jsonb)
      from (
        select
          l.id,
          l.name,
          l.phone_normalized as phone,
          l.status,
          l.last_disposition,
          l.next_action_at as next_at,
          l.campaign_name,
          l.received_at
        from public.crm_leads l
        where l.owner_id = u
          and l.next_action_at is not null
          and l.next_action_at <= now() + interval '12 hours'
          and l.status not in ('converted', 'activated', 'lost', 'existing_customer')
        order by l.next_action_at
        limit 30
      ) x
    ),
    'my_new_leads', (
      select coalesce(jsonb_agg(to_jsonb(x) order by x.received_at desc), '[]'::jsonb)
      from (
        select
          l.id,
          l.name,
          l.phone_normalized as phone,
          l.category,
          l.campaign_name,
          l.received_at,
          l.first_response_due_at
        from public.crm_leads l
        where l.owner_id = u
          and l.lead_kind = 'inbound'
          and l.status = 'new'
        order by l.received_at desc
        limit 30
      ) x
    ),
    'my_new_leads_count', (
      select count(*)
      from public.crm_leads
      where owner_id = u
        and lead_kind = 'inbound'
        and status = 'new'
    ),
    'unassigned_inbound', (
      select case
        when public.crm_has_permission('crm.assign') then
          coalesce(jsonb_agg(to_jsonb(x) order by x.received_at), '[]'::jsonb)
        else '[]'::jsonb
      end
      from (
        select
          l.id,
          l.name,
          l.phone_normalized as phone,
          l.campaign_name,
          l.received_at,
          l.first_response_due_at
        from public.crm_leads l
        where l.owner_id is null
          and l.lead_kind = 'inbound'
          and l.status not in ('converted', 'activated', 'lost', 'existing_customer')
        order by l.received_at
        limit 30
      ) x
    ),
    'my_tasks', (
      select coalesce(jsonb_agg(to_jsonb(x) order by x.due_at), '[]'::jsonb)
      from (
        select t.id, t.title, t.due_at, t.kind, t.entity_ref as entity, t.entity_type
        from public.crm_tasks t
        where t.assigned_to = u
          and t.status = 'open'
          and t.due_at <= now() + interval '24 hours'
          and not (t.entity_type = 'retargeting' and t.kind = 'followup')
        order by t.due_at
        limit 30
      ) x
    ),
    'my_followups_total', (
      select count(*)
      from public.retargeting_followups
      where owner_id = u
        and status not in (
          'converted', 'returned', 'not_interested',
          'supplier', 'noise', 'blacklist', 'test'
        )
    )
  )
  into out;

  return out;
end;
$function$;
comment on function "public"."sales_today"(p_user uuid) is 'Daily sales queue led by platform merchant signals; WhatsApp replies are owned by Hatif and excluded from lead creation.';
CREATE OR REPLACE FUNCTION public.set_carrier_zoho_financial_links(p_carrier_id text, p_zoho_vendor_id text DEFAULT NULL::text, p_treasury_account_id text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_vendor_id text := nullif(btrim(p_zoho_vendor_id), '');
  v_treasury_id text := nullif(btrim(p_treasury_account_id), '');
  v_conflict_carrier text;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if not public.crm_has_permission('zoho.configure') then raise exception 'not_allowed'; end if;
  if not exists (select 1 from public.carriers where id = p_carrier_id) then
    raise exception 'carrier_not_found';
  end if;

  if v_vendor_id is not null and not exists (
    select 1 from public.zoho_contacts
    where zoho_id = v_vendor_id and contact_type = 'vendor'
  ) then
    raise exception 'zoho_vendor_not_found';
  end if;

  if v_treasury_id is not null and not exists (
    select 1 from public.zoho_chart_accounts where zoho_id = v_treasury_id
  ) then
    raise exception 'zoho_treasury_not_found';
  end if;

  select carrier_id into v_conflict_carrier
  from public.zoho_financial_account_links
  where source_type = 'chart_account'
    and zoho_account_id = v_treasury_id
    and link_kind = 'cod_treasury'
    and carrier_id is distinct from p_carrier_id
  limit 1;
  if v_conflict_carrier is not null then
    raise exception 'treasury_already_linked:%', v_conflict_carrier;
  end if;

  if v_vendor_id is null then
    delete from public.carrier_zoho_vendor_links where carrier_id = p_carrier_id;
  else
    insert into public.carrier_zoho_vendor_links (
      carrier_id, zoho_vendor_id, notes, created_by, updated_by
    ) values (
      p_carrier_id, v_vendor_id, nullif(btrim(p_notes), ''), v_uid, v_uid
    )
    on conflict (carrier_id) do update set
      zoho_vendor_id = excluded.zoho_vendor_id,
      notes = excluded.notes,
      updated_by = v_uid,
      updated_at = now();
  end if;

  delete from public.zoho_financial_account_links
  where carrier_id = p_carrier_id and link_kind = 'cod_treasury'
    and (v_treasury_id is null or zoho_account_id <> v_treasury_id);

  if v_treasury_id is not null then
    insert into public.zoho_financial_account_links (
      source_type, zoho_account_id, link_kind, carrier_id,
      notes, created_by, updated_by
    ) values (
      'chart_account', v_treasury_id, 'cod_treasury', p_carrier_id,
      nullif(btrim(p_notes), ''), v_uid, v_uid
    )
    on conflict (source_type, zoho_account_id) do update set
      link_kind = 'cod_treasury',
      carrier_id = p_carrier_id,
      internal_bank_name = null,
      notes = excluded.notes,
      updated_by = v_uid,
      updated_at = now();
  end if;

  return jsonb_build_object(
    'carrier_id', p_carrier_id,
    'zoho_vendor_id', v_vendor_id,
    'treasury_account_id', v_treasury_id,
    'updated_at', now()
  );
end;
$function$;
CREATE OR REPLACE FUNCTION public.set_retargeting_followup(p_phone text, p_status text DEFAULT NULL::text, p_owner uuid DEFAULT NULL::uuid, p_next timestamp with time zone DEFAULT NULL::timestamp with time zone, p_notes text DEFAULT NULL::text, p_touch boolean DEFAULT false)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_old text;
  v_stage text;
begin
  if p_phone is null or btrim(p_phone) = '' then
    raise exception 'phone مطلوب';
  end if;

  select status
  into v_old
  from public.retargeting_followups
  where phone = p_phone;

  v_stage := case
    when p_status in ('converted', 'returned') then 'won'
    when p_status in ('not_interested', 'competitor', 'closed_business') then 'lost'
    when p_status in ('supplier', 'noise', 'blacklist', 'test') then 'disqualified'
    when p_status = 'interested' then 'qualified'
    when p_status in (
      'contacted', 'whatsapp_sent', 'price_issue',
      'support_issue', 'integration_issue', 'finance'
    ) then 'contacted'
    when p_status in ('needs_followup', 'no_answer') then 'nurture'
    when p_status = 'new' then 'new'
  end;

  insert into public.retargeting_followups (
    phone,
    status,
    sales_stage,
    owner_id,
    next_action_at,
    notes,
    last_touch_at,
    first_contact_at,
    contact_attempts,
    updated_by,
    updated_at
  )
  values (
    p_phone,
    coalesce(p_status, 'new'),
    coalesce(v_stage, 'new'),
    p_owner,
    p_next,
    p_notes,
    case when p_touch then now() end,
    case when p_touch then now() end,
    case when p_touch then 1 else 0 end,
    v_uid,
    now()
  )
  on conflict (phone) do update set
    status = coalesce(p_status, public.retargeting_followups.status),
    sales_stage = coalesce(v_stage, public.retargeting_followups.sales_stage),
    owner_id = case
      when p_owner is not null then p_owner
      else public.retargeting_followups.owner_id
    end,
    next_action_at = coalesce(p_next, public.retargeting_followups.next_action_at),
    notes = coalesce(p_notes, public.retargeting_followups.notes),
    last_touch_at = case
      when p_touch then now()
      else public.retargeting_followups.last_touch_at
    end,
    first_contact_at = case
      when p_touch then coalesce(public.retargeting_followups.first_contact_at, now())
      else public.retargeting_followups.first_contact_at
    end,
    contact_attempts = public.retargeting_followups.contact_attempts
      + case when p_touch then 1 else 0 end,
    lost_at = case
      when v_stage = 'lost' then coalesce(public.retargeting_followups.lost_at, now())
      when v_stage is not null and v_stage <> 'lost' then null
      else public.retargeting_followups.lost_at
    end,
    won_at = case
      when v_stage = 'won' then coalesce(public.retargeting_followups.won_at, now())
      when v_stage is not null and v_stage <> 'won' then null
      else public.retargeting_followups.won_at
    end,
    updated_by = v_uid,
    updated_at = now();

  if p_status is not null
     and p_status is distinct from coalesce(v_old, 'new') then
    insert into public.retargeting_status_log (
      phone, old_status, new_status, changed_by
    )
    values (p_phone, v_old, p_status, v_uid);
  end if;

  return (
    select row_to_json(followup)
    from public.retargeting_followups followup
    where followup.phone = p_phone
  );
end;
$function$;
CREATE OR REPLACE FUNCTION public.set_retargeting_followups_bulk(p_phones text[], p_owner uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_touch boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n integer;
begin
  insert into retargeting_followups (phone, owner_id, status, last_touch_at, updated_at, updated_by)
  select ph,
         coalesce(p_owner, null),
         coalesce(p_status, 'new'),
         case when p_touch then now() end,
         now(), auth.uid()
  from unnest(p_phones) ph
  on conflict (phone) do update set
    owner_id     = coalesce(p_owner, retargeting_followups.owner_id),
    status       = coalesce(p_status, retargeting_followups.status),
    last_touch_at = case when p_touch then now() else retargeting_followups.last_touch_at end,
    updated_at   = now(),
    updated_by   = auth.uid();
  get diagnostics n = row_count;
  return n;
end $function$;
CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.sla_breaches()
 RETURNS TABLE(overdue bigint, stale bigint, total bigint, oldest_days integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with a as (
    select next_action_at, last_touch_at from retargeting_followups
    where status not in ('converted','rejected','not_interested','blacklist','supplier','noise','test')
      and ((next_action_at is not null and next_action_at < now()) or last_touch_at < now() - interval '3 days')
  )
  select
    count(*) filter (where next_action_at is not null and next_action_at < now()),
    count(*) filter (where last_touch_at < now() - interval '3 days'),
    count(*),
    coalesce(max(floor(extract(epoch from now() - last_touch_at)/86400))::int, 0)
  from a;
$function$;
CREATE OR REPLACE FUNCTION public.start_hudhud_api_request(p_ip_hash text, p_action text, p_limit integer DEFAULT 60, p_window_seconds integer DEFAULT 60)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id bigint;
begin
  if length(p_ip_hash) <> 64 or p_action not in ('reverse','shortcode','geocode','categories','places','place_detail','directions','matrix') then raise exception 'invalid request metadata'; end if;
  perform pg_advisory_xact_lock(hashtext(p_ip_hash));
  if (select count(*) from public.hudhud_api_events where ip_hash=p_ip_hash and created_at > now() - make_interval(secs => greatest(p_window_seconds,1))) >= greatest(p_limit,1) then return 0; end if;
  insert into public.hudhud_api_events(ip_hash,action) values(p_ip_hash,p_action) returning id into v_id;
  return v_id;
end; $function$;
CREATE OR REPLACE FUNCTION public.store_activation_trend(p_days integer DEFAULT 5, p_limit integer DEFAULT 24)
 RETURNS TABLE(snap_date date, uploaded_at timestamp with time zone, total_stores integer, active_stores integer, active_30d integer, prepaid_active integer, postpaid_active integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with snaps as (
    select snapshot_id, min(uploaded_at) up_at, min(snapshot_date) snap_date, count(*)::int stores
    from merchants group by snapshot_id
    order by min(uploaded_at) desc limit greatest(1, least(p_limit, 60))
  )
  select s.snap_date, s.up_at as uploaded_at, s.stores,
    (select count(*)::int from merchants m where m.snapshot_id = s.snapshot_id
       and m.last_shipment_at >= s.up_at - make_interval(days => p_days)) as active_stores,
    (select count(*)::int from merchants m where m.snapshot_id = s.snapshot_id
       and m.last_shipment_at >= s.up_at - interval '30 days') as active_30d,
    (select count(*)::int from merchants m where m.snapshot_id = s.snapshot_id
       and m.last_shipment_at >= s.up_at - make_interval(days => p_days) and m.billing_type = 'دفع مسبق') as prepaid_active,
    (select count(*)::int from merchants m where m.snapshot_id = s.snapshot_id
       and m.last_shipment_at >= s.up_at - make_interval(days => p_days) and m.billing_type = 'دفع لاحق') as postpaid_active
  from snaps s order by s.up_at asc;
$function$;
CREATE OR REPLACE FUNCTION public.support_assign_ticket(p_ticket uuid, p_assignee uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_new public.support_tickets;
  v_name text;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if not public.crm_has_permission('support.manage') then raise exception 'not_allowed'; end if;

  if p_assignee is not null then
    select name into v_name from public.profiles where id = p_assignee;
    if v_name is null then raise exception 'assignee_not_found'; end if;
  end if;

  update public.support_tickets
  set assigned_to = p_assignee
  where id = p_ticket
  returning * into v_new;
  if not found then raise exception 'ticket_not_found'; end if;

  insert into public.support_ticket_events
    (ticket_id, user_id, kind, note, internal)
  values
    (p_ticket, auth.uid(), 'assign',
     case when p_assignee is null then 'أُلغي الإسناد' else 'أُسندت إلى ' || v_name end,
     true);

  return to_jsonb(v_new);
end;
$function$;
CREATE OR REPLACE FUNCTION public.support_autoclose()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n integer;
begin
  with closed as (
    update support_tickets
    set status = 'closed', resolved_at = coalesce(resolved_at, now())
    where status = 'waiting_customer'
      and updated_at < now() - interval '3 days'
    returning id
  )
  insert into support_ticket_events (ticket_id, kind, old_status, new_status, note, internal)
  select id, 'status', 'waiting_customer', 'closed',
         'أُغلقت تلقائياً — لا رد من العميل خلال 3 أيام', true
  from closed;
  get diagnostics n = row_count;
  return n;
end $function$;
CREATE OR REPLACE FUNCTION public.support_bulk_update(p_tickets uuid[], p_status text DEFAULT NULL::text, p_priority text DEFAULT NULL::text, p_assignee_mode text DEFAULT 'keep'::text, p_assignee uuid DEFAULT NULL::uuid, p_followup_mode text DEFAULT 'keep'::text, p_next timestamp with time zone DEFAULT NULL::timestamp with time zone, p_closure_reason text DEFAULT NULL::text, p_resolution_summary text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_ids uuid[];
  v_requested int;
  v_found int;
  v_updated int;
  v_assignee_name text;
  v_event_kind text := case when p_status is null then 'followup' else 'status' end;
  v_event_note text;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if not public.crm_has_permission('support.manage') then raise exception 'not_allowed'; end if;

  select array_agg(distinct id), count(distinct id)
    into v_ids, v_requested
  from unnest(coalesce(p_tickets, array[]::uuid[])) as selected(id);

  if coalesce(v_requested, 0) = 0 then raise exception 'no_tickets_selected'; end if;
  if v_requested > 200 then raise exception 'bulk_limit_200'; end if;

  if p_status is not null
     and p_status not in ('open', 'in_progress', 'waiting_customer', 'resolved', 'closed') then
    raise exception 'invalid_status';
  end if;
  if p_priority is not null and p_priority not in ('normal', 'high', 'urgent') then
    raise exception 'invalid_priority';
  end if;
  if p_assignee_mode not in ('keep', 'set', 'clear') then raise exception 'invalid_assignee_mode'; end if;
  if p_followup_mode not in ('keep', 'set', 'clear') then raise exception 'invalid_followup_mode'; end if;
  if p_assignee_mode = 'set' and p_assignee is null then raise exception 'assignee_required'; end if;
  if p_followup_mode = 'set' and p_next is null then raise exception 'followup_date_required'; end if;

  if p_status in ('resolved', 'closed') then
    if nullif(btrim(p_closure_reason), '') is null
       or nullif(btrim(p_resolution_summary), '') is null then
      raise exception 'closure_reason_and_resolution_summary_required';
    end if;
  end if;

  if p_status is null and p_priority is null
     and p_assignee_mode = 'keep' and p_followup_mode = 'keep'
     and nullif(btrim(p_note), '') is null then
    raise exception 'no_changes_requested';
  end if;

  if p_assignee_mode = 'set' then
    select name into v_assignee_name
    from public.profiles
    where id = p_assignee;
    if v_assignee_name is null then raise exception 'assignee_not_found'; end if;
  elsif p_assignee_mode = 'clear' then
    v_assignee_name := 'بلا مسؤول';
  end if;

  select count(*) into v_found
  from public.support_tickets
  where id = any(v_ids);
  if v_found <> v_requested then raise exception 'ticket_set_changed'; end if;

  if p_followup_mode = 'set'
     and (
       p_status in ('resolved', 'closed')
       or (
         p_status is null
         and exists (
           select 1 from public.support_tickets
           where id = any(v_ids) and status in ('resolved', 'closed')
         )
       )
     ) then
    raise exception 'closed_ticket_requires_reopen_before_followup';
  end if;

  v_event_note := concat_ws(
    ' · ',
    'تحديث جماعي',
    nullif(btrim(p_note), ''),
    case p_status
      when 'open' then 'الحالة: جديدة'
      when 'in_progress' then 'الحالة: قيد المعالجة'
      when 'waiting_customer' then 'الحالة: بانتظار العميل'
      when 'resolved' then 'الحالة: محلولة'
      when 'closed' then 'الحالة: مغلقة'
    end,
    case p_priority
      when 'normal' then 'الأولوية: عادية'
      when 'high' then 'الأولوية: عالية'
      when 'urgent' then 'الأولوية: عاجلة'
    end,
    case when p_assignee_mode <> 'keep' then 'المسؤول: ' || v_assignee_name end,
    case p_followup_mode
      when 'clear' then 'أُلغي موعد المتابعة'
      when 'set' then 'المتابعة: ' || to_char(p_next at time zone 'Asia/Riyadh', 'YYYY-MM-DD HH24:MI')
    end,
    case when p_status in ('resolved', 'closed') then nullif(btrim(p_resolution_summary), '') end
  );

  with targets as materialized (
    select id, status old_status
    from public.support_tickets
    where id = any(v_ids)
    for update
  ),
  changed as (
    update public.support_tickets t
    set status = coalesce(p_status, t.status),
        priority = coalesce(p_priority, t.priority),
        assigned_to = case p_assignee_mode
          when 'set' then p_assignee
          when 'clear' then null
          else t.assigned_to
        end,
        next_followup_at = case
          when p_status in ('resolved', 'closed') then null
          when p_followup_mode = 'set' then p_next
          when p_followup_mode = 'clear' then null
          else t.next_followup_at
        end,
        last_followup_at = case
          when p_followup_mode <> 'keep' or nullif(btrim(p_note), '') is not null then now()
          else t.last_followup_at
        end,
        closure_reason = case
          when p_status in ('resolved', 'closed') then p_closure_reason
          when p_status is null then t.closure_reason
          else null
        end,
        resolution_summary = case
          when p_status in ('resolved', 'closed') then p_resolution_summary
          when p_status is null then t.resolution_summary
          else null
        end
    from targets old
    where t.id = old.id
    returning t.id, old.old_status, t.status new_status
  )
  insert into public.support_ticket_events
    (ticket_id, user_id, kind, old_status, new_status, note, internal)
  select id, auth.uid(), v_event_kind,
    case when p_status is null then null else old_status end,
    case when p_status is null then null else new_status end,
    v_event_note, true
  from changed;

  get diagnostics v_updated = row_count;
  return jsonb_build_object('updated', v_updated, 'event_kind', v_event_kind);
end;
$function$;
CREATE OR REPLACE FUNCTION public.support_dashboard()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_out jsonb;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if not public.crm_has_permission('support.view') then raise exception 'not_allowed'; end if;

  select jsonb_build_object(
    'by_status', (
      select coalesce(jsonb_object_agg(status, cnt), '{}'::jsonb)
      from (select status, count(*) cnt from public.support_tickets group by status) s
    ),
    'by_priority', (
      select coalesce(jsonb_object_agg(priority, cnt), '{}'::jsonb)
      from (select priority, count(*) cnt from public.support_tickets group by priority) p
    ),
    'by_category', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'category', category, 'total', cnt, 'open', open_cnt
      ) order by cnt desc), '[]'::jsonb)
      from (
        select coalesce(category, 'other') category, count(*) cnt,
          count(*) filter (where status in ('open', 'in_progress', 'waiting_customer')) open_cnt
        from public.support_tickets group by 1
      ) c
    ),
    'by_carrier', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'carrier_id', carrier_id, 'carrier_name', carrier_name,
        'total', cnt, 'open', open_cnt
      ) order by cnt desc), '[]'::jsonb)
      from (
        select carrier_id, coalesce(max(carrier_name), carrier_id, 'بدون شركة') carrier_name,
          count(*) cnt,
          count(*) filter (where status in ('open', 'in_progress', 'waiting_customer')) open_cnt
        from public.support_tickets group by carrier_id
      ) c
    ),
    'by_owner', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'owner_id', owner_id, 'owner_name', owner_name,
        'open', open_cnt, 'overdue', overdue_cnt, 'due_24h', due_24h_cnt,
        'resolved_30d', resolved_30d_cnt, 'avg_resolution_hours', avg_hours
      ) order by overdue_cnt desc, open_cnt desc, owner_name), '[]'::jsonb)
      from (
        select t.assigned_to owner_id, coalesce(max(p.name), 'بلا مسؤول') owner_name,
          count(*) filter (where t.status in ('open', 'in_progress', 'waiting_customer')) open_cnt,
          count(*) filter (
            where t.status in ('open', 'in_progress', 'waiting_customer')
              and t.next_followup_at < now()
          ) overdue_cnt,
          count(*) filter (
            where t.status in ('open', 'in_progress', 'waiting_customer')
              and t.next_followup_at >= now()
              and t.next_followup_at <= now() + interval '24 hours'
          ) due_24h_cnt,
          count(*) filter (where t.resolved_at > now() - interval '30 days') resolved_30d_cnt,
          round((avg(extract(epoch from (t.resolved_at - t.created_at)) / 3600)
            filter (where t.resolved_at is not null))::numeric, 1) avg_hours
        from public.support_tickets t
        left join public.profiles p on p.id = t.assigned_to
        group by t.assigned_to
      ) o
    ),
    'avg_resolution_hours', (
      select round((avg(extract(epoch from (resolved_at - created_at)) / 3600))::numeric, 1)
      from public.support_tickets where resolved_at is not null
    ),
    'created_30d', (select count(*) from public.support_tickets where created_at > now() - interval '30 days'),
    'resolved_30d', (select count(*) from public.support_tickets where resolved_at > now() - interval '30 days')
  ) into v_out;

  return v_out;
end;
$function$;
CREATE OR REPLACE FUNCTION public.support_ticket_admin_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  new.updated_at := now();

  if new.status in ('resolved', 'closed') then
    if nullif(btrim(new.closure_reason), '') is null
       or nullif(btrim(new.resolution_summary), '') is null then
      raise exception 'closure_reason_and_resolution_summary_required';
    end if;
    new.resolved_at := coalesce(new.resolved_at, now());
    new.next_followup_at := null;
  else
    new.resolved_at := null;
    new.closure_reason := null;
    new.resolution_summary := null;
  end if;

  return new;
end;
$function$;
CREATE OR REPLACE FUNCTION public.support_ticket_stats()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_out jsonb;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if not public.crm_has_permission('support.view') then raise exception 'not_allowed'; end if;

  select jsonb_build_object(
    'open', count(*) filter (where status = 'open'),
    'in_progress', count(*) filter (where status = 'in_progress'),
    'waiting', count(*) filter (where status = 'waiting_customer'),
    'stale3d', count(*) filter (
      where status in ('open', 'in_progress', 'waiting_customer')
        and created_at < now() - interval '3 days'
    ),
    'resolved7d', count(*) filter (
      where status in ('resolved', 'closed')
        and coalesce(resolved_at, updated_at) > now() - interval '7 days'
    ),
    'overdue', count(*) filter (
      where status in ('open', 'in_progress', 'waiting_customer')
        and next_followup_at < now()
    ),
    'due_24h', count(*) filter (
      where status in ('open', 'in_progress', 'waiting_customer')
        and next_followup_at >= now()
        and next_followup_at <= now() + interval '24 hours'
    ),
    'unassigned', count(*) filter (
      where status in ('open', 'in_progress', 'waiting_customer')
        and assigned_to is null
    ),
    'without_followup', count(*) filter (
      where status in ('open', 'in_progress', 'waiting_customer')
        and next_followup_at is null
    ),
    'total', count(*)
  ) into v_out
  from public.support_tickets;

  return v_out;
end;
$function$;
CREATE OR REPLACE FUNCTION public.support_update_followup(p_ticket uuid, p_priority text DEFAULT 'normal'::text, p_next timestamp with time zone DEFAULT NULL::timestamp with time zone, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_new public.support_tickets;
  v_event_note text;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if not public.crm_has_permission('support.manage') then raise exception 'not_allowed'; end if;
  if p_priority not in ('normal', 'high', 'urgent') then raise exception 'invalid_priority'; end if;

  update public.support_tickets
  set priority = p_priority,
      next_followup_at = p_next,
      last_followup_at = case when nullif(btrim(p_note), '') is not null then now() else last_followup_at end
  where id = p_ticket
    and status in ('open', 'in_progress', 'waiting_customer')
  returning * into v_new;
  if not found then raise exception 'open_ticket_not_found'; end if;

  v_event_note := concat_ws(
    ' · ',
    nullif(btrim(p_note), ''),
    'الأولوية: ' || case p_priority when 'urgent' then 'عاجلة' when 'high' then 'عالية' else 'عادية' end,
    case when p_next is null then 'بلا موعد قادم' else 'المتابعة: ' || to_char(p_next at time zone 'Asia/Riyadh', 'YYYY-MM-DD HH24:MI') end
  );

  insert into public.support_ticket_events
    (ticket_id, user_id, kind, note, internal)
  values
    (p_ticket, auth.uid(), 'followup', v_event_note, true);

  return to_jsonb(v_new);
end;
$function$;
CREATE OR REPLACE FUNCTION public.support_update_status(p_ticket uuid, p_status text, p_closure_reason text DEFAULT NULL::text, p_resolution_summary text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_old public.support_tickets;
  v_new public.support_tickets;
  v_note text;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if not public.crm_has_permission('support.manage') then raise exception 'not_allowed'; end if;
  if p_status not in ('open', 'in_progress', 'waiting_customer', 'resolved', 'closed') then
    raise exception 'invalid_status';
  end if;

  select * into v_old from public.support_tickets where id = p_ticket for update;
  if not found then raise exception 'ticket_not_found'; end if;

  update public.support_tickets
  set status = p_status,
      closure_reason = case when p_status in ('resolved', 'closed') then p_closure_reason else null end,
      resolution_summary = case when p_status in ('resolved', 'closed') then p_resolution_summary else null end
  where id = p_ticket
  returning * into v_new;

  v_note := coalesce(
    nullif(btrim(p_note), ''),
    case when p_status in ('resolved', 'closed') then nullif(btrim(p_resolution_summary), '') end
  );

  insert into public.support_ticket_events
    (ticket_id, user_id, kind, old_status, new_status, note, internal)
  values
    (p_ticket, auth.uid(), 'status', v_old.status, p_status, v_note, true);

  return to_jsonb(v_new);
end;
$function$;
CREATE OR REPLACE FUNCTION public.team_operational_readiness_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_accounting jsonb;
  v_finance jsonb;
  v_sales jsonb;
begin
  if v_uid is null then
    raise exception 'not_authenticated';
  end if;

  if not (
    public.crm_has_permission('overview.view')
    or public.crm_has_permission('system.manage_employees')
  ) then
    raise exception 'not_allowed';
  end if;

  with active_carriers as (
    select
      c.id,
      c.name,
      nullif(c.file_signature ->> 'file_kind', '') as file_kind
    from public.carriers c
    where jsonb_typeof(c.contracts) = 'array'
      and exists (
        select 1
        from jsonb_array_elements(c.contracts) contract
        where
          case
            when coalesce(contract ->> 'startDate', '') ~ '^\d{4}-\d{2}-\d{2}$'
              then (contract ->> 'startDate')::date <= current_date
            else true
          end
          and case
            when coalesce(contract ->> 'endDate', '') ~ '^\d{4}-\d{2}-\d{2}$'
              then (contract ->> 'endDate')::date >= date_trunc('month', current_date)::date
            else true
          end
      )
  ), requirements as (
    select carrier.id, carrier.name, carrier.file_kind, required.task_kind
    from active_carriers carrier
    cross join lateral unnest(
      case carrier.file_kind
        when 'audit_with_cod' then array['invoice']::text[]
        when 'audit_only' then array['invoice']::text[]
        when 'audit_and_cod_separate' then array['invoice', 'cod_remittance']::text[]
        when 'cod_only' then array['cod_remittance']::text[]
        else array['classification']::text[]
      end
    ) required(task_kind)
  ), missing as (
    select requirement.*
    from requirements requirement
    where requirement.task_kind = 'classification'
       or not exists (
         select 1
         from public.carrier_task_schedules schedule
         where schedule.carrier_id = requirement.id
           and schedule.task_kind = requirement.task_kind
           and schedule.active
           and schedule.schedule_basis in ('weekday', 'month_days')
           and cardinality(schedule.due_days) > 0
           and (
             (schedule.schedule_basis = 'weekday'
               and schedule.due_days <@ array[0,1,2,3,4,5,6]::smallint[])
             or (schedule.schedule_basis = 'month_days'
               and schedule.due_days <@ array(select generate_series(1,31)::smallint))
           )
       )
  ), missing_by_carrier as (
    select
      id,
      max(name) as name,
      jsonb_agg(task_kind order by task_kind) as missing_kinds
    from missing
    group by id
  ), counts as (
    select
      (select count(*) from active_carriers)::int as contracted_carriers,
      (select count(*) from missing)::int as missing_schedules,
      (select count(*) from missing_by_carrier)::int as missing_carriers,
      (select count(*) from public.accounting_cycles where status = 'closed')::int as closed_cycles,
      (select count(*) from public.accounting_cycle_events
        where period = date_trunc('month', current_date)::date)::int as current_month_events
  )
  select jsonb_build_object(
    'status', case
      when counts.missing_schedules > 0 then 'blocked'
      when counts.closed_cycles = 0 then 'pilot'
      else 'ready'
    end,
    'contracted_carriers', counts.contracted_carriers,
    'missing_schedules', counts.missing_schedules,
    'missing_carriers', counts.missing_carriers,
    'closed_cycles', counts.closed_cycles,
    'current_month_events', counts.current_month_events,
    'missing', coalesce((
      select jsonb_agg(jsonb_build_object(
        'carrier_id', row.id,
        'carrier_name', row.name,
        'kinds', row.missing_kinds
      ) order by row.name)
      from missing_by_carrier row
    ), '[]'::jsonb)
  )
  into v_accounting
  from counts;

  with linked as (
    select distinct link.zoho_account_id, link.internal_bank_name
    from public.zoho_financial_account_links link
    where link.source_type = 'bank_account'
      and link.link_kind = 'bank'
  ), latest_statements as (
    select distinct on (summary.bank)
      summary.bank,
      summary.closing_balance,
      summary.period_to
    from public.bank_statement_summaries summary
    order by summary.bank, summary.period_to desc, summary.created_at desc
  ), finance_counts as (
    select
      (select count(*) from public.customer_balance_integrity_issues)::int as integrity_issues,
      (select count(*) from linked)::int as linked_bank_accounts,
      coalesce((
        select sum(coalesce(account.uncategorized_count, 0))
        from linked link
        join public.zoho_bank_accounts account on account.zoho_id = link.zoho_account_id
      ), 0)::int as uncategorized_operations,
      coalesce((select sum(statement.closing_balance) from latest_statements statement), 0)::numeric as statement_balance,
      coalesce((
        select sum(account.book_balance)
        from linked link
        join public.zoho_bank_accounts account on account.zoho_id = link.zoho_account_id
      ), 0)::numeric as book_balance,
      (select max(statement.period_to) from latest_statements statement) as statement_as_of
  )
  select jsonb_build_object(
    'status', case
      when counts.integrity_issues > 0 then 'blocked'
      when counts.uncategorized_operations > 0 or counts.linked_bank_accounts < 2 then 'pilot'
      else 'ready'
    end,
    'customer_integrity_issues', counts.integrity_issues,
    'linked_bank_accounts', counts.linked_bank_accounts,
    'uncategorized_bank_operations', counts.uncategorized_operations,
    'statement_balance', round(counts.statement_balance, 2),
    'book_balance', round(counts.book_balance, 2),
    'statement_vs_book_difference', round(counts.statement_balance - counts.book_balance, 2),
    'statement_as_of', counts.statement_as_of
  )
  into v_finance
  from finance_counts counts;

  with sales_counts as (
    select
      (select count(*) from public.collection_tasks
        where stage = 'todo' and done_at is null and assigned_to is null)::int as unassigned_collections,
      coalesce((select sum(debt_at_creation) from public.collection_tasks
        where stage = 'todo' and done_at is null and assigned_to is null), 0)::numeric as unassigned_collection_debt,
      (select count(*) from public.retargeting_followups
        where status = 'needs_followup' and owner_id is null)::int as unassigned_followups,
      (select count(*) from public.crm_tasks
        where status not in ('done', 'completed', 'cancelled') and assigned_to is null)::int as unassigned_crm_tasks,
      (select count(*) from public.profiles
        where accepts_campaign_leads
          and nullif(btrim(lead_notification_phone), '') is not null)::int as campaign_recipients,
      (select count(*) from public.crm_leads
        where coalesce(lead_kind, 'cold') <> 'cold'
          and status not in ('won', 'lost', 'converted')
          and owner_id is null)::int as unassigned_inbound_leads
  )
  select jsonb_build_object(
    'status', case
      when counts.unassigned_collections > 0
        or counts.unassigned_followups > 0
        or counts.unassigned_crm_tasks > 0
        or counts.unassigned_inbound_leads > 0
        or counts.campaign_recipients = 0 then 'pilot'
      else 'ready'
    end,
    'unassigned_collections', counts.unassigned_collections,
    'unassigned_collection_debt', round(counts.unassigned_collection_debt, 2),
    'unassigned_followups', counts.unassigned_followups,
    'unassigned_crm_tasks', counts.unassigned_crm_tasks,
    'campaign_recipients', counts.campaign_recipients,
    'unassigned_inbound_leads', counts.unassigned_inbound_leads
  )
  into v_sales
  from sales_counts counts;

  return jsonb_build_object(
    'checked_at', now(),
    'accounting', v_accounting,
    'finance', v_finance,
    'sales', v_sales
  );
end;
$function$;
comment on function "public"."team_operational_readiness_snapshot"() is 'Read-only management snapshot for accounting, finance and sales operational readiness.';
CREATE OR REPLACE FUNCTION public.team_staffing_readiness_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_accounting jsonb;
  v_finance jsonb;
  v_sales jsonb;
begin
  if v_uid is null then
    raise exception 'not_authenticated';
  end if;

  if not (
    public.crm_has_permission('overview.view')
    or public.crm_has_permission('system.manage_employees')
  ) then
    raise exception 'not_allowed';
  end if;

  with staff as (
    select id, name, email, coalesce(permissions, '{}'::jsonb) as permissions
    from public.profiles
    where role <> 'admin'
  ), coverage as (
    select
      count(*) filter (where permissions @> '{
        "audits.view": true,
        "audits.create": true,
        "audits.approve": true,
        "internal_exports.view": true,
        "internal_exports.pull": true,
        "uploads.view": true,
        "uploads.upload_file": true,
        "cod.view": true
      }'::jsonb)::int as cycle_operators,
      count(*) filter (where permissions @> '{"system.period_close": true}'::jsonb)::int as cycle_closers
    from staff
  )
  select jsonb_build_object(
    'status', case
      when cycle_operators = 0 then 'blocked'
      when cycle_closers = 0 then 'pilot'
      else 'ready'
    end,
    'cycle_operators', cycle_operators,
    'cycle_closers', cycle_closers
  )
  into v_accounting
  from coverage;

  with staff as (
    select id, name, email, coalesce(permissions, '{}'::jsonb) as permissions
    from public.profiles
    where role <> 'admin'
  ), coverage as (
    select
      count(*) filter (where permissions @> '{
        "zoho.view": true,
        "bank.view": true,
        "reconciliation.view": true,
        "money.pnl": true,
        "reports.view_financial": true
      }'::jsonb)::int as finance_viewers,
      count(*) filter (where permissions @> '{
        "zoho.view": true,
        "bank.view": true,
        "bank.upload_statement": true,
        "bank.reconcile": true,
        "reconciliation.view": true,
        "reconciliation.link": true
      }'::jsonb)::int as finance_operators,
      count(*) filter (where permissions @> '{"reports.view_financial": true}'::jsonb)::int as financial_report_viewers
    from staff
  )
  select jsonb_build_object(
    'status', case
      when finance_viewers = 0 or finance_operators = 0 then 'blocked'
      when financial_report_viewers = 0 then 'pilot'
      else 'ready'
    end,
    'finance_viewers', finance_viewers,
    'finance_operators', finance_operators,
    'financial_report_viewers', financial_report_viewers
  )
  into v_finance
  from coverage;

  with staff as (
    select id, name, email, coalesce(permissions, '{}'::jsonb) as permissions
    from public.profiles
    where role <> 'admin'
  ), coverage as (
    select
      count(*) filter (where permissions @> '{"sales.view": true, "sales.manage": true}'::jsonb)::int as sales_operators,
      count(*) filter (where permissions @> '{"collections.view": true, "collections.update_stage": true}'::jsonb)::int as collection_operators,
      count(*) filter (where permissions @> '{"collections.view_all": true, "collections.assign": true}'::jsonb)::int as collection_supervisors
    from staff
  )
  select jsonb_build_object(
    'status', case
      when sales_operators = 0 or collection_operators = 0 then 'blocked'
      when collection_supervisors = 0 then 'pilot'
      else 'ready'
    end,
    'sales_operators', sales_operators,
    'collection_operators', collection_operators,
    'collection_supervisors', collection_supervisors
  )
  into v_sales
  from coverage;

  return jsonb_build_object(
    'checked_at', now(),
    'accounting', v_accounting,
    'finance', v_finance,
    'sales', v_sales
  );
end;
$function$;
comment on function "public"."team_staffing_readiness_snapshot"() is 'Read-only permission coverage for team cutover; excludes admin accounts.';
