CREATE OR REPLACE FUNCTION public.trg_blocklist_retag()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if public.norm_sa_phone(new.phone) ~ '^9665[0-9]{8}$' then
    insert into public.hatif_retag_dirty (phone, reason)
    values (public.norm_sa_phone(new.phone), 'blocklist')
    on conflict (phone) do update set queued_at = now(), reason = excluded.reason;
  end if;
  return new;
end $function$;
CREATE OR REPLACE FUNCTION public.trg_wcs_retag()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.conversation_id is not null and new.phone ~ '^9665[0-9]{8}$' then
    insert into public.hatif_retag_dirty (phone, reason)
    values (new.phone, 'new_conversation')
    on conflict (phone) do update set queued_at = now(), reason = excluded.reason;
  end if;
  return new;
end $function$;
CREATE OR REPLACE FUNCTION public.trg_zoho_invoice_retag()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare oldbal numeric := case when TG_OP='UPDATE' then coalesce(old.balance,0) else 0 end;
begin
  if coalesce(new.balance,0) <= 0.5 and oldbal <= 0.5 then return new; end if;
  insert into public.hatif_retag_dirty (phone, reason)
  select distinct public.norm_sa_phone(m.phone), 'zoho'
  from public.customer_merchant_links l
  join public.merchants m on m.store_id = l.store_id and m.snapshot_id = (select max(snapshot_id) from public.merchants)
  where l.customer_name = new.customer_name and m.phone is not null
    and public.norm_sa_phone(m.phone) ~ '^9665[0-9]{8}$'
  on conflict (phone) do update set queued_at = now(), reason = excluded.reason;
  return new;
end $function$;
CREATE OR REPLACE FUNCTION public.trigger_tag_sync()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare k text;
begin
  select cron_key into k from public.zoho_auth where id = 1;
  if k is null then return; end if;
  perform net.http_post(
    url := 'https://pubtkfwmznfmffavyzsy.supabase.co/functions/v1/hatif-tag-sync',
    body := '{"limit":120}'::jsonb,
    headers := jsonb_build_object('Content-Type','application/json','X-Cron-Key', k));
end $function$;
CREATE OR REPLACE FUNCTION public.update_employee_permissions(p_employee uuid, p_permissions jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_before jsonb;
  v_after jsonb;
  v_target_name text;
  v_added text[];
  v_removed text[];
  v_before_count integer := 0;
  v_after_count integer := 0;
begin
  if v_actor is null or not public.crm_has_permission('system.manage_permissions') then
    raise exception 'forbidden';
  end if;

  if jsonb_typeof(coalesce(p_permissions, '{}'::jsonb)) <> 'object' then
    raise exception 'permissions_must_be_an_object';
  end if;

  if exists (
    select 1
    from jsonb_each(coalesce(p_permissions, '{}'::jsonb)) item
    where jsonb_typeof(item.value) <> 'boolean'
  ) then
    raise exception 'permission_values_must_be_boolean';
  end if;

  select coalesce(jsonb_object_agg(item.key, true), '{}'::jsonb)
    into v_after
  from jsonb_each(coalesce(p_permissions, '{}'::jsonb)) item
  where item.value = 'true'::jsonb;

  select coalesce(profile.permissions, '{}'::jsonb), profile.name
    into v_before, v_target_name
  from public.profiles profile
  where profile.id = p_employee
    and profile.role <> 'admin'
  for update;

  if not found then
    raise exception 'employee_not_found_or_admin';
  end if;

  select coalesce(array_agg(key order by key), array[]::text[])
    into v_added
  from jsonb_object_keys(v_after) as key
  where not (v_before ? key);

  select coalesce(array_agg(key order by key), array[]::text[])
    into v_removed
  from jsonb_object_keys(v_before) as key
  where not (v_after ? key);

  select count(*)::integer into v_before_count from jsonb_object_keys(v_before);
  select count(*)::integer into v_after_count from jsonb_object_keys(v_after);

  if v_before is distinct from v_after then
    update public.profiles
    set permissions = v_after
    where id = p_employee;
  end if;

  return jsonb_build_object(
    'employee_id', p_employee,
    'employee_name', v_target_name,
    'changed', v_before is distinct from v_after,
    'before_count', v_before_count,
    'after_count', v_after_count,
    'added_keys', to_jsonb(v_added),
    'removed_keys', to_jsonb(v_removed)
  );
end;
$function$;
CREATE OR REPLACE FUNCTION public.update_updated_at()
 RETURNS trigger
