AS $function$
BEGIN NEW.updated_at = NOW(); RETURN NEW; END;
$function$;
CREATE OR REPLACE FUNCTION public.vat_current_quarter()
 RETURNS TABLE(quarter text, period_from date, period_to date, output_tax numeric, input_tax numeric, net_due numeric, output_amount numeric, is_closed boolean, fetched_at timestamp with time zone, days_left integer, prev_net_due numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with cur as (
    select * from vat_snapshots
    where period_from <= current_date and period_to >= current_date
    order by period_from desc limit 1
  ),
  prev as (
    select net_due from vat_snapshots
    where period_to < current_date order by period_to desc limit 1
  )
  select c.quarter, c.period_from, c.period_to,
         c.output_tax, c.input_tax, c.net_due, c.output_amount,
         c.is_closed, c.fetched_at,
         greatest(0, (c.period_to - current_date))::int,
         (select net_due from prev)
  from cur c;
$function$;
CREATE OR REPLACE FUNCTION public.vendor_balance_others()
 RETURNS TABLE(raw_name text, balance numeric, rank_order integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH latest AS (
    SELECT id FROM vendor_balance_snapshots
    ORDER BY uploaded_at DESC LIMIT 1
  )
  SELECT
    vb.raw_name,
    vb.balance::numeric,
    ROW_NUMBER() OVER (ORDER BY abs(vb.balance) DESC)::int AS rank_order
  FROM vendor_balances vb JOIN latest l ON vb.snapshot_id = l.id
  WHERE vb.carrier_id IS NULL
    AND abs(vb.balance) > 0.005
  ORDER BY abs(vb.balance) DESC;
$function$;
CREATE OR REPLACE FUNCTION public.vendor_reconciliation()
 RETURNS TABLE(carrier_id text, carrier_name text, internal_balance numeric, zoho_balance numeric, diff numeric, zoho_raw_names text[])
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH latest_zoho AS (
    SELECT id FROM vendor_balance_snapshots
    ORDER BY uploaded_at DESC LIMIT 1
  ),
  zoho_per_carrier AS (
    SELECT
      vb.carrier_id,
      SUM(vb.balance)::numeric                AS zoho_balance,
      ARRAY_AGG(vb.raw_name ORDER BY abs(vb.balance) DESC) AS raw_names
    FROM vendor_balances vb JOIN latest_zoho lz ON vb.snapshot_id = lz.id
    WHERE vb.carrier_id IS NOT NULL
    GROUP BY vb.carrier_id
  ),
  internal_per_carrier AS (
    SELECT
      carrier_id,
      SUM(amount_dr - amount_cr)::numeric AS internal_balance
    FROM carrier_operations
    WHERE status IS DISTINCT FROM 'paid'
    GROUP BY carrier_id
  ),
  all_ids AS (
    SELECT carrier_id FROM zoho_per_carrier
    UNION
    SELECT carrier_id FROM internal_per_carrier
  )
  SELECT
    a.carrier_id,
    c.name                                      AS carrier_name,
    coalesce(i.internal_balance, 0)::numeric    AS internal_balance,
    coalesce(z.zoho_balance,     0)::numeric    AS zoho_balance,
    (coalesce(z.zoho_balance, 0) - coalesce(i.internal_balance, 0))::numeric AS diff,
    coalesce(z.raw_names, ARRAY[]::text[])      AS zoho_raw_names
  FROM all_ids a
  LEFT JOIN zoho_per_carrier     z  ON z.carrier_id = a.carrier_id
  LEFT JOIN internal_per_carrier i  ON i.carrier_id = a.carrier_id
  LEFT JOIN carriers             c  ON c.id         = a.carrier_id
  ORDER BY abs(coalesce(z.zoho_balance, 0) - coalesce(i.internal_balance, 0)) DESC;
$function$;
CREATE OR REPLACE FUNCTION public.webhook_secret_readiness(p_hours integer DEFAULT 48)
 RETURNS TABLE(total bigint, with_secret bigint, valid_secret bigint, without_secret bigint, pct_ready numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select count(*)::bigint,
         count(*) filter (where had_secret)::bigint,
         count(*) filter (where secret_valid)::bigint,
         count(*) filter (where not had_secret)::bigint,
         case when count(*) = 0 then 0
              else round(100.0 * count(*) filter (where secret_valid) / count(*), 1) end
  from webhook_auth_log
  where received_at >= now() - make_interval(hours => p_hours);
$function$;
CREATE OR REPLACE FUNCTION public.whatsapp_campaign_log(p_phone text DEFAULT NULL::text, p_limit integer DEFAULT 300, p_campaign text DEFAULT NULL::text)
 RETURNS TABLE(id bigint, phone text, name text, template_name text, campaign_name text, campaign_bucket text, amount numeric, status text, sent_at timestamp with time zone, sent_by_name text, delivered_at timestamp with time zone, read_at timestamp with time zone, replied_at timestamp with time zone, reply_body text, error_reason text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select s.id, s.phone, s.name, s.template_name, s.campaign_name, s.campaign_bucket,
         s.amount, s.status, s.sent_at,
         coalesce(pr.name,
           case when s.sent_by = 'admin' then 'مدير' when s.sent_by = 'user' then 'موظف'
                when s.sent_by is null then '—' else s.sent_by end) as sent_by_name,
         s.delivered_at, s.read_at, s.replied_at, s.reply_body, s.error_reason
  from whatsapp_campaign_sends s
  left join profiles pr on pr.id::text = s.sent_by
  where (p_phone is null or s.phone = p_phone)
    and (p_campaign is null
         or coalesce(nullif(trim(s.campaign_name), ''), '(بلا اسم)') = p_campaign)
  order by s.sent_at desc
  limit greatest(1, least(coalesce(p_limit, 300), 1000));
$function$;
CREATE OR REPLACE FUNCTION public.whatsapp_campaign_report()
 RETURNS TABLE(campaign_name text, template_name text, first_sent timestamp with time zone, last_sent timestamp with time zone, targets bigint, delivered bigint, read_count bigint, replied bigint, failed bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(nullif(trim(s.campaign_name), ''), '(بلا اسم)') as campaign_name,
         max(s.template_name) as template_name,
         min(s.sent_at) as first_sent, max(s.sent_at) as last_sent,
         count(*) as targets,
         count(*) filter (where s.delivered_at is not null or s.read_at is not null) as delivered,
         count(*) filter (where s.read_at is not null) as read_count,
         count(*) filter (where s.replied_at is not null) as replied,
         count(*) filter (where s.status = 'Failed' or s.error_reason is not null) as failed
  from whatsapp_campaign_sends s
  group by 1
  order by max(s.sent_at) desc;
$function$;
CREATE OR REPLACE FUNCTION public.whatsapp_campaign_stats(p_campaign text)
 RETURNS TABLE(campaign_name text, template_name text, targets bigint, delivered bigint, read_count bigint, replied bigint, bot_replies bigint, failed bigint, pending bigint, assigned bigint, first_sent timestamp with time zone, last_sent timestamp with time zone, last_event timestamp with time zone, fail_reasons jsonb, recent jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with s as (
    select * from whatsapp_campaign_sends
    where coalesce(nullif(trim(campaign_name), ''), '(بلا اسم)') = p_campaign
  )
  select
    p_campaign,
    (select max(template_name) from s),
    count(*)::bigint,
    count(*) filter (where delivered_at is not null or read_at is not null)::bigint,
    count(*) filter (where read_at is not null)::bigint,
    count(*) filter (where replied_at is not null)::bigint,
    count(*) filter (where reply_is_auto)::bigint,
    count(*) filter (where status = 'Failed' or error_reason is not null)::bigint,
    count(*) filter (where delivered_at is null and read_at is null
                       and coalesce(status,'') <> 'Failed' and error_reason is null)::bigint,
    count(*) filter (where hatif_assigned_at is not null)::bigint,
    min(sent_at), max(sent_at),
    greatest(max(delivered_at), max(read_at), max(replied_at), max(auto_reply_at)),
    coalesce((
      select jsonb_agg(jsonb_build_object('reason', reason, 'n', n) order by n desc)
      from (
        select left(coalesce(error_reason, 'بلا سبب مسجّل'), 70) as reason, count(*) as n
        from s where status = 'Failed' or error_reason is not null
        group by 1 order by 2 desc limit 5
      ) f
    ), '[]'::jsonb),
    coalesce((
      select jsonb_agg(jsonb_build_object(
               'phone', phone, 'name', nm, 'at', ev, 'kind', kind) order by ev desc)
      from (
        select phone, name as nm,
               greatest(coalesce(replied_at, 'epoch'::timestamptz),
                        coalesce(auto_reply_at, 'epoch'::timestamptz),
                        coalesce(read_at, 'epoch'::timestamptz),
                        coalesce(delivered_at, 'epoch'::timestamptz)) as ev,
               case when replied_at is not null then 'ردّ'
                    when auto_reply_at is not null then 'ردّ آلي'
                    when read_at is not null then 'قُرئت'
                    else 'وصلت' end as kind
        from s
        where delivered_at is not null or read_at is not null
           or replied_at is not null or auto_reply_at is not null
        order by ev desc limit 8
      ) r
    ), '[]'::jsonb)
  from s;
$function$;
CREATE OR REPLACE FUNCTION public.whatsapp_campaign_status()
 RETURNS TABLE(phone text, name text, last_template text, last_campaign text, last_sent_at timestamp with time zone, last_status text, delivered boolean, read_flag boolean, replied boolean, reply_at timestamp with time zone, sends_count integer, paid_after boolean, paid_at timestamp with time zone, last_delivered_at timestamp with time zone, last_attempt_failed boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with latest as (
    select distinct on (phone)
      phone, name, template_name, campaign_name, sent_at, status,
      delivered_at, read_at, replied_at, error_reason
    from public.whatsapp_campaign_sends
    order by phone, sent_at desc
  ),
  delivered_latest as (
    select phone, max(sent_at) as last_ok
    from public.whatsapp_campaign_sends
    where delivered_at is not null or read_at is not null
    group by phone
  ),
  counts as (
    select phone, count(*)::int c from public.whatsapp_campaign_sends group by phone
  ),
  paid as (
    select l.phone,
           min(p.date) filter (where p.date >= l.sent_at::date) as first_paid
    from latest l
    join public.zoho_payments p
      on lower(regexp_replace(coalesce(p.customer_name,''),'\s+','','g'))
       = lower(regexp_replace(coalesce(l.name,''),'\s+','','g'))
     and coalesce(l.name,'') <> ''
    group by l.phone
  )
  select l.phone, l.name, l.template_name, l.campaign_name, l.sent_at, l.status,
         l.delivered_at is not null, l.read_at is not null,
         l.replied_at is not null, l.replied_at,
         coalesce(c.c,1),
         pd.first_paid is not null, pd.first_paid::timestamptz,
         dl.last_ok,
         (l.status = 'Failed' or l.error_reason is not null)
  from latest l
  left join counts c on c.phone = l.phone
  left join paid  pd on pd.phone = l.phone
  left join delivered_latest dl on dl.phone = l.phone;
$function$;
CREATE OR REPLACE FUNCTION public.whatsapp_delivery_health()
 RETURNS json
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select json_build_object(
    'total',     count(*),
    'delivered', count(*) filter (where delivered_at is not null),
    'read',      count(*) filter (where read_at is not null),
    'replied',   count(*) filter (where replied_at is not null),
    'auto',      count(*) filter (where reply_is_auto),
    'failed',    count(*) filter (where status='Failed' or error_reason is not null),
    'pending',   count(*) filter (where delivered_at is null and read_at is null
                     and replied_at is null and status <> 'Failed' and error_reason is null),
    'reasons', coalesce((
      select json_agg(r) from (
        select coalesce(nullif(error_reason,''), status) as reason, count(*) as n
        from whatsapp_campaign_sends
        where status='Failed' or error_reason is not null
        group by 1 order by count(*) desc limit 10
      ) r), '[]'::json)
  )
  from whatsapp_campaign_sends;
$function$;
CREATE OR REPLACE FUNCTION public.whatsapp_number_health()
 RETURNS TABLE(sent_14d bigint, delivered_pct numeric, reply_pct numeric, at_risk boolean, worst_campaign text, worst_reply_pct numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with base as (
    select coalesce(nullif(campaign_name,''),'(بلا اسم)') as c, delivered_at, replied_at, reply_is_auto
    from whatsapp_campaign_sends where sent_at > now() - interval '14 days'
  ),
  per as (
    select c, count(*) n,
      100.0*count(*) filter (where delivered_at is not null)/nullif(count(*),0) as dpct,
      100.0*count(*) filter (where replied_at is not null and coalesce(reply_is_auto,false)=false)/nullif(count(*),0) as rpct
    from base group by c
  ),
  tot as (
    select count(*) n,
      round(100.0*count(*) filter (where delivered_at is not null)/nullif(count(*),0),1) dpct,
      round(100.0*count(*) filter (where replied_at is not null and coalesce(reply_is_auto,false)=false)/nullif(count(*),0),1) rpct
    from base
  ),
  worst as (select c, round(rpct,1) rp from per where n >= 200 order by rpct asc limit 1)
  select tot.n, tot.dpct, tot.rpct,
    (coalesce(tot.dpct,100) < 60 or exists(select 1 from per where n > 500 and rpct < 1.5)) as at_risk,
    (select c from worst), (select rp from worst)
  from tot;
$function$;
CREATE OR REPLACE FUNCTION public.whatsapp_quality(p_dim text DEFAULT 'template'::text, p_days integer DEFAULT 30)
 RETURNS TABLE(label text, sent integer, delivered integer, read_n integer, replied integer, failed integer, ecosystem integer, undeliverable integer, experiment integer, other_fail integer, pending integer, delivery_rate numeric, reply_rate numeric, ecosystem_rate numeric, undeliverable_rate numeric, pending_rate numeric, first_sent timestamp with time zone, last_sent timestamp with time zone, verdict text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with base as (
    select
      case when p_dim = 'campaign' then coalesce(nullif(campaign_name,''), '(بلا اسم)')
           else coalesce(nullif(template_name,''), '(بلا قالب)') end as label,
      lower(coalesce(status,'')) st, coalesce(error_reason,'') err,
      delivered_at, read_at, replied_at, coalesce(reply_is_auto,false) auto, sent_at
    from whatsapp_campaign_sends
    where sent_at >= now() - make_interval(days => greatest(p_days,1))
  ),
  agg as (
    select label,
      count(*)::int sent,
      count(*) filter (where delivered_at is not null or read_at is not null or replied_at is not null)::int delivered,
      count(*) filter (where read_at is not null)::int read_n,
      count(*) filter (where replied_at is not null and not auto)::int replied,
      count(*) filter (where st = 'failed')::int failed,
      count(*) filter (where st = 'failed' and err ilike '%healthy ecosystem%')::int ecosystem,
      count(*) filter (where st = 'failed' and err ilike '%undeliverable%')::int undeliverable,
      count(*) filter (where st = 'failed' and err ilike '%experiment%')::int experiment,
      count(*) filter (where st = 'failed'
         and err not ilike '%healthy ecosystem%' and err not ilike '%undeliverable%'
         and err not ilike '%experiment%')::int other_fail,
      -- معلّقة: أُرسلت ولم تفشل ولم تصل حالتها النهائية (webhook ناقص)
      count(*) filter (where st <> 'failed'
         and delivered_at is null and read_at is null and replied_at is null)::int pending,
      min(sent_at) first_sent, max(sent_at) last_sent
    from base group by 1
  ),
  r as (
    select a.*,
      round(100.0 * a.delivered     / nullif(a.sent,0), 1) d_rate,
      round(100.0 * a.replied       / nullif(a.delivered,0), 1) rp_rate,
      round(100.0 * a.ecosystem     / nullif(a.sent,0), 1) eco_rate,
      round(100.0 * a.undeliverable / nullif(a.sent,0), 1) und_rate,
      round(100.0 * a.pending       / nullif(a.sent,0), 1) pnd_rate
    from agg a where a.sent > 0
  )
  select r.label, r.sent, r.delivered, r.read_n, r.replied,
    r.failed, r.ecosystem, r.undeliverable, r.experiment, r.other_fail, r.pending,
    r.d_rate, r.rp_rate, r.eco_rate, r.und_rate, r.pnd_rate,
    r.first_sent, r.last_sent,
    case
      when r.sent < 30            then 'عيّنة صغيرة'
      when r.eco_rate >= 25       then 'أوقفه — ميتا تخنقه'
      when r.eco_rate >= 10       then 'راجعه — خنق مرتفع'
      -- «أرقام رديئة» بدليل صريح فقط
      when r.und_rate >= 25       then 'أرقام رديئة'
      -- تسليم منخفض بلا فشل = حالات لم تصلنا، لا حكم على الجمهور
      when r.pnd_rate >= 40       then 'بيانات غير مكتملة'
      when r.d_rate   <  70       then 'متوسط'
      else 'جيد'
    end as verdict
  from r order by r.sent desc;
$function$;
CREATE OR REPLACE FUNCTION public.work_agent_overdue_candidates(p_min_days integer DEFAULT 30, p_min_balance numeric DEFAULT 0.5, p_limit integer DEFAULT 500)
 RETURNS TABLE(customer_name text, store_name text, phone text, owed numeric, invoice_count bigint, oldest_due date)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with latest_snapshot as (
    select snapshot_id from public.merchants order by snapshot_date desc,uploaded_at desc limit 1
  ), debts as (
    select l.contact_name customer_name,sum(l.collectible_amount)::numeric owed,
      count(*) filter(where l.line_kind='invoice')::bigint invoice_count,min(l.due_date) oldest_due
    from public.customer_collectible_lines l
    where l.collectible_amount>=greatest(p_min_balance,0.01)
      and l.due_date<current_date-greatest(p_min_days,0)
    group by l.contact_name
  )
  select d.customer_name,coalesce(m.store_name,d.customer_name),public.norm_sa_phone(m.phone),
    d.owed,d.invoice_count,d.oldest_due
  from debts d
  left join public.customer_merchant_links l on l.customer_name=d.customer_name
  left join public.merchants m on m.store_id=l.store_id and m.snapshot_id=(select snapshot_id from latest_snapshot)
  order by d.owed desc,d.oldest_due
  limit least(greatest(p_limit,1),2000);
$function$;
CREATE OR REPLACE FUNCTION public.working_capital_now()
 RETURNS TABLE(dso_days numeric, dpo_days numeric, ccc_days numeric, total_ar numeric, total_ap numeric, customers_with_debt integer, carriers_with_debt integer, top_slow_customers jsonb, top_slow_carriers jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with
  ar_lines as (
    select z.customer_name, z.balance::numeric as bal,
      greatest(0, (current_date - z.date))::numeric as age_days
    from zoho_invoices z where z.balance > 0.5 and z.date is not null
  ),
  ar_per_customer as (
    select customer_name, sum(bal) as bal_total,
      sum(bal * age_days) / nullif(sum(bal), 0) as weighted_days
    from ar_lines group by customer_name
  ),
  ar_totals as (
    select (select coalesce(sum(total_due),0) from customer_ar where total_due > 0.5) as ar_total,
      case when sum(bal_total) > 0 then sum(bal_total * weighted_days) / sum(bal_total) else 0 end as dso,
      (select count(*)::int from customer_ar where total_due > 0.5) as n_customers
    from ar_per_customer
  ),
  ap_lines as (
    select carrier_id, (amount_dr - amount_cr)::numeric as net,
      greatest(0, (current_date - doc_date))::numeric as age_days
    from carrier_operations where status is distinct from 'paid' and doc_date is not null
  ),
  ap_per_carrier as (
    select carrier_id, sum(net) as net_total,
      sum(net * age_days) / nullif(sum(net), 0) as weighted_days
    from ap_lines group by carrier_id having sum(net) > 0.5
  ),
  ap_totals as (
    select sum(net_total) as ap_total,
      case when sum(net_total) > 0 then sum(net_total * weighted_days) / sum(net_total) else 0 end as dpo,
      count(*)::int as n_carriers
    from ap_per_carrier
  ),
  top_cust as (
    select jsonb_agg(j order by (j->>'days')::numeric desc) as arr
    from (select jsonb_build_object('name', customer_name, 'total', round(bal_total, 2),
            'days', round(weighted_days, 1),
            'share_pct', round((bal_total / nullif((select ar_total from ar_totals), 0)) * 100, 1)) as j
          from ar_per_customer where bal_total > 0 order by weighted_days desc limit 5) sub
  ),
  top_carr as (
    select jsonb_agg(j order by (j->>'days')::numeric desc) as arr
    from (select jsonb_build_object('carrier_id', carrier_id, 'total', round(net_total, 2),
            'days', round(weighted_days, 1),
            'share_pct', round((net_total / nullif((select ap_total from ap_totals), 0)) * 100, 1)) as j
          from ap_per_carrier order by weighted_days desc limit 5) sub
  )
  select round(art.dso, 1), round(apt.dpo, 1), round(art.dso - apt.dpo, 1),
    coalesce(art.ar_total, 0)::numeric, coalesce(apt.ap_total, 0)::numeric,
    coalesce(art.n_customers, 0), coalesce(apt.n_carriers, 0),
    coalesce(top_cust.arr, '[]'::jsonb), coalesce(top_carr.arr, '[]'::jsonb)
  from ar_totals art, ap_totals apt, top_cust, top_carr;
$function$;
CREATE OR REPLACE FUNCTION public.zatca_pending_today()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with sd as (
    select (now() at time zone 'Asia/Riyadh')::date as d
  ), eligible as (
    select *
    from public.zoho_invoices
    where not (coalesce(invoice_number, '') ilike '%الرصيد الافتتاحي%')
  ), pending as (
    select *
    from eligible
    where lower(coalesce(einvoice_status, '')) = 'yet_to_be_pushed'
  ), verify as (
    select *
    from eligible
    where nullif(btrim(coalesce(einvoice_status, '')), '') is null
      and date between (select d - 1 from sd) and (select d from sd)
  )
  select jsonb_build_object(
    'saudi_date', (select d from sd),
    'today_count', (select count(*) from pending where date = (select d from sd)),
    'today_total', coalesce((select sum(total) from pending where date = (select d from sd)), 0),
    'overdue_count', (select count(*) from pending where date < (select d from sd)),
    'overdue_total', coalesce((select sum(total) from pending where date < (select d from sd)), 0),
    'needs_live_check_count', (select count(*) from verify),
    'invoices', coalesce((
      select jsonb_agg(x)
      from (
        select jsonb_build_object(
          'invoice_number', invoice_number,
          'customer', customer_name,
          'total', total,
          'date', date,
          'overdue', date < (select d from sd)
        ) as x
        from pending
        order by date desc, total desc
        limit 100
      ) s
    ), '[]'::jsonb)
  );
$function$;
CREATE OR REPLACE FUNCTION public.zoho_applicable_credits()
 RETURNS TABLE(zoho_id text, customer_name text, open_invoices numeric, available_credit numeric, applicable numeric, clears_fully boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH inv AS (
    SELECT customer_name, sum(balance) AS open_inv
    FROM zoho_invoices WHERE balance > 0.5 GROUP BY customer_name
  ),
  cred AS (
    SELECT customer_name, sum(bal) AS avail FROM (
      SELECT customer_name, balance AS bal FROM zoho_creditnotes WHERE balance > 0.5
      UNION ALL
      SELECT customer_name, unused_amount FROM zoho_payments WHERE unused_amount > 0.5
    ) x GROUP BY customer_name
  )
  SELECT ct.zoho_id, cred.customer_name,
    round(coalesce(inv.open_inv, 0)::numeric, 2) AS open_invoices,
    round(cred.avail::numeric, 2) AS available_credit,
    round(least(cred.avail, coalesce(inv.open_inv, 0))::numeric, 2) AS applicable,
    (coalesce(inv.open_inv, 0) > 0.5 AND coalesce(inv.open_inv, 0) <= cred.avail + 0.5) AS clears_fully
  FROM cred
  LEFT JOIN inv ON inv.customer_name = cred.customer_name
  LEFT JOIN zoho_contacts ct ON ct.contact_name = cred.customer_name
  WHERE cred.avail > 0.5
  ORDER BY least(cred.avail, coalesce(inv.open_inv, 0)) DESC, cred.avail DESC;
$function$;
CREATE OR REPLACE FUNCTION public.zoho_financial_control_dashboard()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_out jsonb;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if not (public.crm_has_permission('zoho.view') or public.crm_has_permission('money.pnl')) then
    raise exception 'not_allowed';
  end if;

  select jsonb_build_object(
    'banks', coalesce((
      select jsonb_agg(jsonb_build_object(
        'zoho_id', b.zoho_id,
        'account_name', b.account_name,
        'account_code', b.account_code,
        'account_type', b.account_type,
        'currency_code', b.currency_code,
        'book_balance', b.book_balance,
        'bank_balance', b.bank_balance,
        'feed_available', (b.feed_status is not null or b.last_refreshed_at is not null),
        'variance', case when b.feed_status is null and b.last_refreshed_at is null then null else round((b.bank_balance - b.book_balance)::numeric, 2) end,
        'uncategorized_count', b.uncategorized_count,
        'feed_status', b.feed_status,
        'last_refreshed_at', b.last_refreshed_at,
        'synced_at', b.synced_at,
        'display_kind', case
          when l.link_kind is not null then l.link_kind
          when b.account_name like 'خزينة%' then 'operating_treasury'
          when b.account_name ~* '(moyassar|ميسر)' then 'payment_gateway'
          when b.account_name ~* '(أموال غير مودعة|undeposited funds|حساب تسوية المتاجر|merchant settlement)' then 'clearing'
          else 'unclassified'
        end,
        'internal_bank_name', l.internal_bank_name,
        'internal_balance', ib.balance,
        'internal_source', ib.source,
        'internal_as_of', ib.as_of,
        'internal_vs_book', case when ib.balance is null then null else round((ib.balance - b.book_balance)::numeric, 2) end,
        'internal_vs_feed', case when ib.balance is null or b.bank_balance is null then null else round((ib.balance - b.bank_balance)::numeric, 2) end
      ) order by abs(b.book_balance) desc)
      from public.zoho_bank_accounts b
      left join public.zoho_financial_account_links l
        on l.source_type = 'bank_account' and l.zoho_account_id = b.zoho_id
      left join lateral (
        select x.balance, x.as_of, x.source
        from (
          select m.balance, m.recorded_at as as_of, 'manual'::text as source
          from public.bank_balance_log m where m.bank = l.internal_bank_name
          union all
          select s.closing_balance as balance, s.period_to::timestamptz as as_of, 'statement'::text as source
          from public.bank_statement_summaries s where s.bank = l.internal_bank_name
        ) x
        order by x.as_of desc nulls last
        limit 1
      ) ib on true
    ), '[]'::jsonb),
    'bank_summary', (
      select jsonb_build_object(
        'count', count(*),
        'linked_count', count(l.id),
        'linked_bank_count', count(*) filter (where l.link_kind = 'bank'),
        'expected_bank_count', greatest(
          count(*) filter (where l.link_kind = 'bank'),
          (select count(*) from (
            select distinct nullif(btrim(bank), '') as bank from public.bank_balance_log
            union
            select distinct nullif(btrim(bank), '') as bank from public.bank_statement_summaries
          ) expected where expected.bank is not null)
        ),
        'operating_treasury_count', count(*) filter (where b.account_name like 'خزينة%'),
        'unclassified_count', count(*) filter (
          where l.id is null
            and b.account_name not like 'خزينة%'
            and b.account_name !~* '(moyassar|ميسر)'
            and b.account_name !~* '(أموال غير مودعة|undeposited funds|حساب تسوية المتاجر|merchant settlement)'
        ),
        'feed_available_count', count(*) filter (where b.feed_status is not null or b.last_refreshed_at is not null),
        'book_balance', coalesce(round(sum(b.book_balance)::numeric, 2), 0),
        'bank_balance', case when count(*) filter (where b.feed_status is not null or b.last_refreshed_at is not null) = 0 then null
          else round((sum(b.bank_balance) filter (where b.feed_status is not null or b.last_refreshed_at is not null))::numeric, 2) end,
        'variance', case when count(*) filter (where b.feed_status is not null or b.last_refreshed_at is not null) = 0 then null
          else round((sum(b.bank_balance - b.book_balance) filter (where b.feed_status is not null or b.last_refreshed_at is not null))::numeric, 2) end,
        'internal_count', count(ib.balance),
        'internal_balance', case when count(ib.balance) = 0 then null else round(sum(ib.balance)::numeric, 2) end,
        'internal_vs_book', case when count(ib.balance) = 0 then null else round(sum(ib.balance - b.book_balance)::numeric, 2) end,
        'uncategorized_count', coalesce(sum(b.uncategorized_count), 0),
        'stale_count', count(*) filter (where b.synced_at < now() - interval '2 hours')
      )
      from public.zoho_bank_accounts b
      left join public.zoho_financial_account_links l
        on l.source_type = 'bank_account' and l.zoho_account_id = b.zoho_id
      left join lateral (
        select x.balance
        from (
          select m.balance, m.recorded_at as as_of
          from public.bank_balance_log m where m.bank = l.internal_bank_name
          union all
          select s.closing_balance as balance, s.period_to::timestamptz as as_of
          from public.bank_statement_summaries s where s.bank = l.internal_bank_name
        ) x
        order by x.as_of desc nulls last
        limit 1
      ) ib on true
    ),
    'treasuries', coalesce((
      select jsonb_agg(jsonb_build_object(
        'zoho_id', a.zoho_id,
        'account_name', a.account_name,
        'current_balance', a.current_balance,
        'carrier_id', l.carrier_id,
        'synced_at', a.synced_at
      ) order by abs(coalesce(a.current_balance, 0)) desc)
      from public.zoho_financial_account_links l
      join public.zoho_chart_accounts a on a.zoho_id = l.zoho_account_id
      where l.source_type = 'chart_account' and l.link_kind = 'cod_treasury'
    ), '[]'::jsonb),
    'links', coalesce((
      select jsonb_agg(to_jsonb(l) order by l.updated_at desc)
      from public.zoho_financial_account_links l
    ), '[]'::jsonb),
    'vendor_summary', (
      select jsonb_build_object(
        'vendors', count(*) filter (where contact_type = 'vendor'),
        'payable_vendors', count(*) filter (where outstanding_payable > 0.5),
        'credit_vendors', count(*) filter (where unused_credits_payable > 0.5),
        'outstanding_payable', coalesce(round(sum(outstanding_payable)::numeric, 2), 0),
        'unused_credits', coalesce(round(sum(unused_credits_payable)::numeric, 2), 0),
        'net_payable', coalesce(round(sum(outstanding_payable - unused_credits_payable)::numeric, 2), 0),
        'synced_at', max(synced_at)
      ) from public.zoho_contacts where contact_type = 'vendor'
    ),
    'vendor_positions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'zoho_id', v.zoho_id,
        'vendor_name', v.contact_name,
        'gross_payable', v.outstanding_payable,
        'credit_balance', v.unused_credits_payable,
        'net_payable', round((v.outstanding_payable - v.unused_credits_payable)::numeric, 2),
        'status', v.status,
        'synced_at', v.synced_at
      ) order by abs(v.outstanding_payable - v.unused_credits_payable) desc, v.outstanding_payable desc)
      from public.zoho_contacts v
      where v.contact_type = 'vendor'
        and (abs(v.outstanding_payable) > 0.01 or abs(v.unused_credits_payable) > 0.01)
    ), '[]'::jsonb),
    'bills_summary', (
      select jsonb_build_object(
        'open_count', count(*) filter (where balance > 0.5),
        'open_balance', coalesce(round((sum(balance) filter (where balance > 0.5))::numeric, 2), 0),
        'overdue_count', count(*) filter (where balance > 0.5 and due_date < current_date),
        'overdue_balance', coalesce(round((sum(balance) filter (where balance > 0.5 and due_date < current_date))::numeric, 2), 0),
        'oldest_due_date', min(due_date) filter (where balance > 0.5),
        'synced_at', max(synced_at)
      ) from public.zoho_bills
    ),
    'vendor_credits', (
      select jsonb_build_object(
        'open_count', count(*) filter (where balance > 0.5),
        'open_balance', coalesce(round((sum(balance) filter (where balance > 0.5))::numeric, 2), 0),
        'synced_at', max(synced_at)
      ) from public.zoho_vendor_credits
    ),
    'capabilities', coalesce((
      select jsonb_object_agg(capability, jsonb_build_object(
        'status', status,
        'required_scope', required_scope,
        'last_checked_at', last_checked_at,
        'last_success_at', last_success_at,
        'error_message', error_message
      )) from public.zoho_integration_capabilities
    ), '{}'::jsonb),
    'api_usage', (
      select to_jsonb(u) from public.zoho_api_daily_usage u
      where u.usage_date = current_date
      order by u.updated_at desc limit 1
    ),
    'internal_banks', coalesce((
      select jsonb_agg(x.bank order by x.bank) from (
        select distinct nullif(btrim(bank), '') as bank from public.bank_balance_log
        union
        select distinct nullif(btrim(bank), '') as bank from public.bank_statement_summaries
      ) x where x.bank is not null
    ), '[]'::jsonb),
    'carriers', coalesce((
      select jsonb_agg(jsonb_build_object('id', id, 'name', name) order by name)
      from public.carriers
    ), '[]'::jsonb),
    'generated_at', now()
  ) into v_out;
  return v_out;
end;
$function$;
comment on function "public"."zoho_financial_control_dashboard"() is 'Financial read model. Expected banks come from explicit internal sources/links; gateways and clearing accounts are not banks.';
CREATE OR REPLACE FUNCTION public.zoho_financial_health_summary()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
with cfg as (
  select * from public.zoho_api_monitor_config where id = true
), usage as (
  select coalesce(sum(api_calls),0)::integer calls,
         coalesce(sum(rate_limited_count),0)::integer rate_limited,
         max(last_call_at) last_call_at
  from public.zoho_api_daily_usage where usage_date = current_date
), vat as (
  select
    (select fetched_at from public.vat_snapshots order by fetched_at desc limit 1) as fetched_at,
    (select net_due from public.vat_snapshots order by fetched_at desc limit 1) as net_due,
    (select quarter from public.vat_snapshots order by fetched_at desc limit 1) as quarter
), ar as (
  select coalesce(sum(balance),0) total,
         coalesce(sum(days_over_90),0) over_90,
         count(*) customers from public.zoho_ar_aging_current
), ap as (
  select coalesce(sum(balance),0) total,
         coalesce(sum(days_over_90),0) over_90,
         count(*) vendors from public.zoho_ap_aging_current
)
select jsonb_build_object(
  'generated_at', now(),
  'ar', jsonb_build_object('total', ar.total, 'over_90', ar.over_90, 'customers', ar.customers),
  'ap', jsonb_build_object('total', ap.total, 'over_90', ap.over_90, 'vendors', ap.vendors),
  'vat', jsonb_build_object('quarter', vat.quarter, 'net_due', vat.net_due, 'fetched_at', vat.fetched_at,
    'age_minutes', case when vat.fetched_at is null then null else floor(extract(epoch from now()-vat.fetched_at)/60) end,
    'healthy', vat.fetched_at >= now() - make_interval(mins => cfg.vat_max_age_minutes)),
  'api', jsonb_build_object('calls', usage.calls, 'rate_limited', usage.rate_limited,
    'last_call_at', usage.last_call_at, 'warning_calls', cfg.warning_calls, 'critical_calls', cfg.critical_calls,
    'status', case when usage.calls >= cfg.critical_calls then 'critical' when usage.calls >= cfg.warning_calls then 'warning' else 'healthy' end)
)
from cfg, usage, vat, ar, ap;
$function$;
CREATE OR REPLACE FUNCTION public.zoho_invoice_dashboard()
 RETURNS json
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with base as (
    select to_char(date, 'YYYY-MM') as ym,
      coalesce(total,0)::numeric as total, coalesce(balance,0)::numeric as balance,
      lower(coalesce(status,'')) as st, nullif(trim(customer_name),'') as cust
    from zoho_invoices where date is not null
  ),
  monthly as (
    select ym, count(*) as cnt, sum(total) as total,
      sum(case when balance > 0.5 then balance else 0 end) as remaining,
      count(*) filter (where st = 'draft')   as draft_cnt,
      count(*) filter (where st = 'overdue') as overdue_cnt,
      count(*) filter (where balance > 0.5)  as open_cnt
    from base group by ym
  ),
  debtors as (
    select ar.contact_name as cust, ar.total_due as owed, ar.open_invoices as open_cnt
    from customer_ar ar where ar.total_due > 0.5
    order by ar.total_due desc limit 20
  )
  select json_build_object(
    'open_ar',      (select coalesce(sum(total_due),0) from customer_ar where total_due > 0.5),
    'open_cnt',     (select count(*) from base where balance > 0.5),
    'draft_cnt',    (select count(*) from base where st = 'draft'),
    'draft_total',  (select coalesce(sum(total),0) from base where st = 'draft'),
    'overdue_cnt',  (select count(*) from base where st = 'overdue'),
    'overdue_amt',  (select coalesce(sum(case when balance>0.5 then balance else 0 end),0) from base where st = 'overdue'),
    'total_cnt',    (select count(*) from base),
    'monthly',      (select coalesce(json_agg(row_to_json(m) order by m.ym desc),'[]') from monthly m),
    'debtors',      (select coalesce(json_agg(row_to_json(d)),'[]') from debtors d)
  );
$function$;
CREATE OR REPLACE FUNCTION public.zoho_overdue_campaign()
 RETURNS TABLE(customer_name text, phone text, store_name text, owed numeric, inv_count integer, oldest date, oldest_age_days integer, invoice_list text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with latest_merch as (select snapshot_id from merchants order by uploaded_at desc limit 1),
  merch as (
    select m.store_id,m.store_name,m.phone,normalize_arabic_name(m.store_name) norm
    from merchants m where m.snapshot_id=(select snapshot_id from latest_merch)
  ),
  links as (select customer_name,store_id from customer_merchant_links where store_id is not null),
  overdue as (
    select l.contact_name customer_name,
      sum(l.collectible_amount) owed,
      count(*) filter(where l.line_kind='invoice' and l.collectible_amount>0.5)::int cnt,
      min(l.due_date) oldest,
      string_agg(
        case when l.line_kind='opening_balance'
          then 'رصيد افتتاحي 10-01-2026 ('||round(l.collectible_amount,2)||')'
          else l.invoice_number||' ('||round(l.collectible_amount,2)||')' end,
        ' · ' order by l.due_date,l.line_id
      ) invs
    from customer_collectible_lines l
    where l.collectible_amount>0.5
      and (l.line_kind='opening_balance' or lower(coalesce(l.status,''))='overdue')
    group by l.contact_name
  )
  select o.customer_name,m.phone,m.store_name,round(o.owed,2),o.cnt,o.oldest,
    (current_date-o.oldest)::int,o.invs
  from overdue o
  left join links l on l.customer_name=o.customer_name
  left join merch m on m.store_id=l.store_id or (l.store_id is null and m.norm=normalize_arabic_name(o.customer_name))
  order by o.owed desc;
$function$;
CREATE OR REPLACE FUNCTION public.zoho_record_api_usage(p_org_id text, p_api_calls integer, p_rate_limited integer DEFAULT 0, p_budget integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if nullif(btrim(p_org_id), '') is null then return; end if;
  insert into public.zoho_api_daily_usage (
    usage_date, org_id, api_calls, rate_limited_count,
    configured_budget, last_call_at, updated_at
  ) values (
    current_date, p_org_id, greatest(coalesce(p_api_calls, 0), 0),
    greatest(coalesce(p_rate_limited, 0), 0), p_budget, now(), now()
  )
  on conflict (usage_date, org_id) do update set
    api_calls = public.zoho_api_daily_usage.api_calls + excluded.api_calls,
    rate_limited_count = public.zoho_api_daily_usage.rate_limited_count + excluded.rate_limited_count,
    configured_budget = coalesce(excluded.configured_budget, public.zoho_api_daily_usage.configured_budget),
    last_call_at = excluded.last_call_at,
    updated_at = now();
end;
$function$;
CREATE OR REPLACE FUNCTION public.zoho_set_financial_account_link(p_source_type text, p_zoho_account_id text, p_link_kind text DEFAULT NULL::text, p_internal_bank_name text DEFAULT NULL::text, p_carrier_id text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS zoho_financial_account_links
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row public.zoho_financial_account_links;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if not public.crm_has_permission('zoho.configure') then raise exception 'not_allowed'; end if;
  if p_source_type not in ('bank_account', 'chart_account') then raise exception 'invalid_source_type'; end if;
  if nullif(btrim(p_zoho_account_id), '') is null then raise exception 'account_required'; end if;

  if p_link_kind is null then
    delete from public.zoho_financial_account_links
    where source_type = p_source_type and zoho_account_id = p_zoho_account_id
    returning * into v_row;
    return v_row;
  end if;

  insert into public.zoho_financial_account_links (
    source_type, zoho_account_id, link_kind, internal_bank_name,
    carrier_id, notes, created_by, updated_by
  ) values (
    p_source_type, p_zoho_account_id, p_link_kind,
    nullif(btrim(p_internal_bank_name), ''), nullif(btrim(p_carrier_id), ''),
    nullif(btrim(p_notes), ''), auth.uid(), auth.uid()
  )
  on conflict (source_type, zoho_account_id) do update set
    link_kind = excluded.link_kind,
    internal_bank_name = excluded.internal_bank_name,
    carrier_id = excluded.carrier_id,
    notes = excluded.notes,
    updated_by = auth.uid(),
    updated_at = now()
  returning * into v_row;
  return v_row;
end;
$function$;
CREATE OR REPLACE FUNCTION public.zoho_webhook_health()
 RETURNS json
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT json_build_object(
    'webhook_last_at',   (SELECT webhook_last_at FROM zoho_auth WHERE id = 1),
    'webhook_last_kind', (SELECT webhook_last_kind FROM zoho_auth WHERE id = 1),
    'webhook_ready',     (SELECT webhook_key IS NOT NULL FROM zoho_auth WHERE id = 1),
    'last_sync_at',      (SELECT max(last_sync) FROM zoho_sync_state)
  );
$function$;
