create view "public"."crm_leads_campaign" with (security_invoker = true) as  SELECT id,
    name,
    name_normalized,
    phone,
    whatsapp,
    email,
    source,
    snapshot_id,
    city,
    notes,
    status,
    owner_id,
    converted_at,
    converted_customer,
    converted_store_id,
    created_by,
    created_at,
    updated_at,
    phone_normalized,
    whatsapp_normalized,
    name_en,
    category,
    address,
    website,
    platform,
    store_url,
    social_links,
    raw_payload,
    source_row_number,
    duplicate_key,
    duplicate_count,
    duplicate_names,
    matched_store_id,
    matched_store_name,
    matched_store_status,
    matched_store_billing_type,
    matched_store_shipments,
    matched_store_last_shipment_at,
    matched_store_wallet,
    last_campaign_at,
    last_campaign_status,
    last_campaign_template,
    last_campaign_replied_at,
    in_hatif,
    lead_kind,
    source_channel,
    campaign_name,
    campaign_meta,
    received_at,
    first_response_due_at,
    first_attempt_at,
    first_connected_at,
    last_touch_at,
    next_action_at,
    last_disposition,
    contact_attempts,
    loss_reason,
    loss_notes,
    won_at,
    activated_at,
    converted_by,
    status_changed_at
   FROM ( SELECT l.id,
            l.name,
            l.name_normalized,
            l.phone,
            l.whatsapp,
            l.email,
            l.source,
            l.snapshot_id,
            l.city,
            l.notes,
            l.status,
            l.owner_id,
            l.converted_at,
            l.converted_customer,
            l.converted_store_id,
            l.created_by,
            l.created_at,
            l.updated_at,
            l.phone_normalized,
            l.whatsapp_normalized,
            l.name_en,
            l.category,
            l.address,
            l.website,
            l.platform,
            l.store_url,
            l.social_links,
            l.raw_payload,
            l.source_row_number,
            l.duplicate_key,
            l.duplicate_count,
            l.duplicate_names,
            l.matched_store_id,
            l.matched_store_name,
            l.matched_store_status,
            l.matched_store_billing_type,
            l.matched_store_shipments,
            l.matched_store_last_shipment_at,
            l.matched_store_wallet,
            s.sent_at AS last_campaign_at,
            s.status AS last_campaign_status,
            s.template_name AS last_campaign_template,
            s.replied_at AS last_campaign_replied_at,
            (EXISTS ( SELECT 1
                   FROM hatif_unknown_contacts h
                  WHERE h.phone = l.phone_normalized)) AS in_hatif,
            l.lead_kind,
            l.source_channel,
            l.campaign_name,
            l.campaign_meta,
            l.received_at,
            l.first_response_due_at,
            l.first_attempt_at,
            l.first_connected_at,
            l.last_touch_at,
            l.next_action_at,
            l.last_disposition,
            l.contact_attempts,
            l.loss_reason,
            l.loss_notes,
            l.won_at,
            l.activated_at,
            l.converted_by,
            l.status_changed_at
           FROM crm_leads l
             LEFT JOIN LATERAL ( SELECT w.sent_at,
                    w.status,
                    w.template_name,
                    w.replied_at
                   FROM whatsapp_campaign_sends w
                  WHERE w.phone = l.phone_normalized
                  ORDER BY w.sent_at DESC
                 LIMIT 1) s ON true) guarded_view
  WHERE app_has_any_permission('{crm.view,sales.external_leads}'::text[]);
create view "public"."customer_ar" with (security_invoker = true) as  SELECT c.contact_name,
    c.zoho_id,
    COALESCE(c.outstanding_receivable, 0::numeric) AS total_due,
    COALESCE(inv.invoiced_due, 0::numeric) AS invoiced_due,
    round(LEAST(GREATEST(calc.balance_residual, 0::numeric), GREATEST(COALESCE(c.opening_balance_configured, 0::numeric), 0::numeric)), 2) AS opening_due,
    COALESCE(inv.open_count, 0::bigint) AS open_invoices,
    inv.oldest_invoice_date,
    COALESCE(inv.days_oldest, 0) AS days_oldest,
    COALESCE(c.unused_credits_receivable, 0::numeric) AS unused_credits,
    c.status,
    round(LEAST(GREATEST(COALESCE(c.outstanding_receivable, 0::numeric), 0::numeric), GREATEST(COALESCE(c.unused_credits_receivable, 0::numeric), 0::numeric)), 2) AS credit_offset,
    round(GREATEST(COALESCE(c.outstanding_receivable, 0::numeric) - GREATEST(COALESCE(c.unused_credits_receivable, 0::numeric), 0::numeric), 0::numeric), 2) AS collectible_due,
    round(GREATEST(COALESCE(c.unused_credits_receivable, 0::numeric) - GREATEST(COALESCE(c.outstanding_receivable, 0::numeric), 0::numeric), 0::numeric), 2) AS credit_surplus,
    COALESCE(c.outstanding_receivable, 0::numeric) > 0.5 AND COALESCE(c.unused_credits_receivable, 0::numeric) > 0.005 AS needs_zoho_settlement,
    c.opening_balance_configured,
    c.opening_balance_checked_at,
    calc.balance_residual,
    round(GREATEST(calc.balance_residual - GREATEST(COALESCE(c.opening_balance_configured, 0::numeric), 0::numeric), 0::numeric), 2) AS balance_sync_gap,
    round(GREATEST(- calc.balance_residual, 0::numeric), 2) AS balance_sync_overage,
        CASE
            WHEN abs(calc.balance_residual) <= 0.5 THEN 'valid'::text
            WHEN GREATEST(COALESCE(c.unused_credits_receivable, 0::numeric), 0::numeric) >= (GREATEST(COALESCE(c.outstanding_receivable, 0::numeric), 0::numeric) - 0.005) THEN 'valid'::text
            WHEN c.opening_balance_checked_at IS NULL THEN 'unchecked'::text
            WHEN (calc.balance_residual - GREATEST(COALESCE(c.opening_balance_configured, 0::numeric), 0::numeric)) > 0.5 THEN 'mismatch'::text
            WHEN (- calc.balance_residual) > 0.5 THEN 'mismatch'::text
            ELSE 'valid'::text
        END AS balance_integrity_status
   FROM zoho_contacts c
     LEFT JOIN LATERAL ( SELECT COALESCE(sum(i.balance), 0::numeric) AS invoiced_due,
            count(*) AS open_count,
            min(i.date) AS oldest_invoice_date,
            CURRENT_DATE - min(i.date) AS days_oldest
           FROM zoho_invoices i
          WHERE (i.customer_id = c.zoho_id OR i.customer_id IS NULL AND i.customer_name = c.contact_name) AND i.balance > 0.5) inv ON true
     CROSS JOIN LATERAL ( SELECT round(COALESCE(c.outstanding_receivable, 0::numeric) - COALESCE(inv.invoiced_due, 0::numeric), 2) AS balance_residual) calc
  WHERE c.contact_type = 'customer'::text;
comment on view "public"."customer_ar" is 'Zoho customer balance truth. Explicit opening balances remain separate; fully credit-covered contacts are safe from collection while retaining diagnostic residuals.';
create view "public"."customer_balance_integrity_issues" with (security_invoker = true) as  SELECT contact_name,
    zoho_id,
    total_due,
    invoiced_due,
    opening_balance_configured,
    balance_residual,
    balance_sync_gap,
    balance_sync_overage,
    balance_integrity_status,
    opening_balance_checked_at
   FROM customer_ar
  WHERE balance_integrity_status <> 'valid'::text;
comment on view "public"."customer_balance_integrity_issues" is 'Customers excluded from automated collection until Zoho contact and invoice balances reconcile.';
create view "public"."customer_collectible_lines" with (security_invoker = true) as  WITH balances AS (
         SELECT ar.contact_name,
            ar.zoho_id AS contact_id,
            GREATEST(COALESCE(ar.opening_due, 0::numeric), 0::numeric) AS opening_gross,
            GREATEST(COALESCE(ar.unused_credits, 0::numeric), 0::numeric) AS available_credit,
            LEAST(GREATEST(COALESCE(ar.opening_due, 0::numeric), 0::numeric), GREATEST(COALESCE(ar.unused_credits, 0::numeric), 0::numeric)) AS opening_credit,
            GREATEST(GREATEST(COALESCE(ar.unused_credits, 0::numeric), 0::numeric) - GREATEST(COALESCE(ar.opening_due, 0::numeric), 0::numeric), 0::numeric) AS invoice_credit
           FROM customer_ar ar
          WHERE ar.balance_integrity_status = 'valid'::text
        ), invoice_base AS (
         SELECT b.contact_name,
            b.contact_id,
            i.zoho_id AS line_id,
            i.invoice_number,
            i.date AS line_date,
            COALESCE(i.due_date, i.date) AS due_date,
            i.status,
            i.balance AS gross_amount,
            b.invoice_credit,
            COALESCE(sum(i.balance) OVER (PARTITION BY b.contact_id ORDER BY (COALESCE(i.due_date, i.date)), i.date, i.zoho_id ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), 0::numeric) AS prior_gross
           FROM balances b
             JOIN zoho_invoices i ON i.customer_id = b.contact_id OR i.customer_id IS NULL AND i.customer_name = b.contact_name
          WHERE i.balance > 0.5
        ), invoice_lines AS (
         SELECT invoice_base.contact_name,
            invoice_base.contact_id,
            'invoice'::text AS line_kind,
            invoice_base.line_id,
            invoice_base.invoice_number,
            invoice_base.line_date,
            invoice_base.due_date,
            invoice_base.status,
            invoice_base.gross_amount,
            LEAST(invoice_base.gross_amount, GREATEST(invoice_base.invoice_credit - invoice_base.prior_gross, 0::numeric)) AS allocated_credit
           FROM invoice_base
        ), opening_lines AS (
         SELECT balances.contact_name,
            balances.contact_id,
            'opening_balance'::text AS line_kind,
            NULL::text AS line_id,
            NULL::text AS invoice_number,
            '2026-01-10'::date AS line_date,
            '2026-01-10'::date AS due_date,
            'opening_balance'::text AS status,
            balances.opening_gross AS gross_amount,
            balances.opening_credit AS allocated_credit
           FROM balances
          WHERE balances.opening_gross > 0.005
        )
 SELECT contact_name,
    contact_id,
    line_kind,
    line_id,
    invoice_number,
    line_date,
    due_date,
    status,
    round(gross_amount, 2) AS gross_amount,
    round(allocated_credit, 2) AS allocated_credit,
    round(GREATEST(gross_amount - allocated_credit, 0::numeric), 2) AS collectible_amount,
    GREATEST(CURRENT_DATE - due_date, 0) AS age_days
   FROM ( SELECT opening_lines.contact_name,
            opening_lines.contact_id,
            opening_lines.line_kind,
            opening_lines.line_id,
            opening_lines.invoice_number,
            opening_lines.line_date,
            opening_lines.due_date,
            opening_lines.status,
            opening_lines.gross_amount,
            opening_lines.allocated_credit
           FROM opening_lines
        UNION ALL
         SELECT invoice_lines.contact_name,
            invoice_lines.contact_id,
            invoice_lines.line_kind,
            invoice_lines.line_id,
            invoice_lines.invoice_number,
            invoice_lines.line_date,
            invoice_lines.due_date,
            invoice_lines.status,
            invoice_lines.gross_amount,
            invoice_lines.allocated_credit
           FROM invoice_lines) lines;
comment on view "public"."customer_collectible_lines" is 'Read-only FIFO collection projection. It excludes unresolved Zoho balance gaps and applies unused credit to explicit opening balance first, then oldest invoices.';
create view "public"."merchant_by_name" with (security_invoker = true) as  SELECT nname,
    store_id,
    store_name,
    phone,
    billing_type,
    status,
    wallet_balance,
    shipment_count,
    last_shipment_at
   FROM ( SELECT DISTINCT ON ((normalize_arabic_name(merchants.store_name))) normalize_arabic_name(merchants.store_name) AS nname,
            merchants.store_id,
            merchants.store_name,
            merchants.phone,
            merchants.billing_type,
            merchants.status,
            merchants.wallet_balance,
            merchants.shipment_count,
            merchants.last_shipment_at
           FROM merchants
          WHERE merchants.snapshot_id = (( SELECT merchants_1.snapshot_id
                   FROM merchants merchants_1
                  ORDER BY merchants_1.uploaded_at DESC
                 LIMIT 1)) AND normalize_arabic_name(merchants.store_name) <> ''::text
          ORDER BY (normalize_arabic_name(merchants.store_name)), (COALESCE(merchants.shipment_count, 0)) DESC, merchants.last_shipment_at DESC NULLS LAST, (merchants.status = 'نشط'::text) DESC, merchants.store_id) guarded_view
  WHERE app_has_any_permission('{merchants.view,merchants.link}'::text[]);
create view "public"."v_collection_candidates" with (security_invoker = true) as  SELECT customer_name,
    debt,
    days_outstanding,
    prepaid,
    active,
    trigger,
    priority_score
   FROM ( WITH latest_snapshot AS (
                 SELECT merchants.snapshot_id
                   FROM merchants
                  ORDER BY merchants.uploaded_at DESC
                 LIMIT 1
                ), merchant_context AS (
                 SELECT l.customer_name,
                    bool_or(COALESCE(m.billing_type, ''::text) = 'دفع مسبق'::text) AS prepaid,
                    bool_or(lower(COALESCE(m.status, ''::text)) = ANY (ARRAY['active'::text, 'نشط'::text, 'enabled'::text])) AS active
                   FROM customer_merchant_links l
                     JOIN merchants m ON m.store_id = l.store_id AND m.snapshot_id = (( SELECT latest_snapshot.snapshot_id
                           FROM latest_snapshot))
                  GROUP BY l.customer_name
                ), base AS (
                 SELECT ar.contact_name AS customer_name,
                    round(ar.collectible_due, 2) AS debt,
                    GREATEST(COALESCE(( SELECT max(l.age_days) AS max
                           FROM customer_collectible_lines l
                          WHERE l.contact_name = ar.contact_name AND l.collectible_amount > 0.005), 0), 0) AS days_outstanding,
                    COALESCE(mc.prepaid, false) AS prepaid,
                    COALESCE(mc.active, false) AS active
                   FROM customer_ar ar
                     LEFT JOIN merchant_context mc ON mc.customer_name = ar.contact_name
                  WHERE ar.collectible_due > 0.5
                )
         SELECT base.customer_name,
            base.debt,
            base.days_outstanding,
            base.prepaid,
            base.active,
                CASE
                    WHEN base.prepaid THEN 'prepaid_with_debt'::text
                    WHEN base.debt > 10000::numeric THEN 'over_credit_limit'::text
                    WHEN base.days_outstanding > 90 THEN 'aged_90'::text
                    WHEN base.days_outstanding > 60 THEN 'aged_60'::text
                    WHEN base.days_outstanding > 30 THEN 'aged_30'::text
                    ELSE NULL::text
                END AS trigger,
                CASE
                    WHEN base.prepaid THEN 500
                    WHEN base.active AND base.debt > 10000::numeric THEN 450
                    WHEN base.days_outstanding > 90 THEN 400
                    WHEN base.debt > 10000::numeric THEN 350
                    WHEN base.days_outstanding > 60 THEN 300
                    WHEN base.days_outstanding > 30 THEN 200
                    ELSE 0
                END AS priority_score
           FROM base
          WHERE base.prepaid OR base.debt > 10000::numeric OR base.days_outstanding > 30) guarded_view
  WHERE app_has_any_permission('{collections.view,receivables.view}'::text[]);
create view "public"."v_crm_retargeting" with (security_invoker = true) as  SELECT phone,
    store_count,
    primary_store,
    store_names,
    total_shipments,
    last_shipment,
    wallet,
    last_topup,
    created_at,
    any_active,
    integration_type,
    billing_type,
    profile_done,
    verified,
    vat_reg,
    days_since_last,
    high_value,
    segment,
    priority,
    channel,
    zatca_done,
    compliance_pending,
    readiness_score,
    opportunity_score,
    team_route,
    next_step
   FROM ( WITH latest AS (
                 SELECT merchants.snapshot_id
                   FROM merchants
                  ORDER BY merchants.uploaded_at DESC
                 LIMIT 1
                ), m AS (
                 SELECT merchants.id,
                    merchants.snapshot_id,
                    merchants.snapshot_date,
                    merchants.store_id,
                    merchants.store_name,
                    merchants.phone,
                    merchants.shipment_count,
                    merchants.last_shipment_at,
                    merchants.integration_type,
                    merchants.billing_type,
                    merchants.status,
                    merchants.created_at_platform,
                    merchants.last_topup_at,
                    merchants.wallet_balance,
                    merchants.uploaded_by,
                    merchants.uploaded_at,
                    merchants.profile_status,
                    merchants.vat_registered,
                    merchants.zatca_completed,
                    merchants.verification_status
                   FROM merchants
                  WHERE merchants.snapshot_id = (( SELECT latest.snapshot_id
                           FROM latest)) AND merchants.phone IS NOT NULL AND btrim(merchants.phone) <> ''::text
                ), customer_rollup AS (
                 SELECT m.phone,
                    count(*)::integer AS store_count,
                    (array_agg(m.store_name ORDER BY (COALESCE(m.shipment_count, 0)) DESC, m.store_id))[1] AS primary_store,
                    array_agg(DISTINCT m.store_name ORDER BY m.store_name) AS store_names,
                    sum(COALESCE(m.shipment_count, 0)) AS total_shipments,
                    max(m.last_shipment_at) AS last_shipment,
                    round(sum(COALESCE(m.wallet_balance, 0::numeric)), 2) AS wallet,
                    max(m.last_topup_at) AS last_topup,
                    min(m.created_at_platform) AS created_at,
                    bool_or(m.status = 'نشط'::text) AS any_active,
                    (array_agg(m.integration_type ORDER BY (COALESCE(m.shipment_count, 0)) DESC, m.store_id) FILTER (WHERE m.integration_type IS NOT NULL))[1] AS integration_type,
                    (array_agg(m.billing_type ORDER BY (COALESCE(m.shipment_count, 0)) DESC, m.store_id) FILTER (WHERE m.billing_type IS NOT NULL))[1] AS billing_type,
                    bool_or(m.profile_status = 'مكتمل'::text) AS profile_done,
                    bool_or(m.verification_status = 'موثق'::text) AS verified,
                    bool_or(COALESCE(m.vat_registered, false)) AS vat_reg,
                    bool_or(COALESCE(m.zatca_completed, false)) AS zatca_done
                   FROM m
                  GROUP BY m.phone
                ), classified AS (
                 SELECT c.phone,
                    c.store_count,
                    c.primary_store,
                    c.store_names,
                    c.total_shipments,
                    c.last_shipment,
                    c.wallet,
                    c.last_topup,
                    c.created_at,
                    c.any_active,
                    c.integration_type,
                    c.billing_type,
                    c.profile_done,
                    c.verified,
                    c.vat_reg,
                    c.zatca_done,
                        CASE
                            WHEN c.last_shipment IS NOT NULL THEN CURRENT_DATE - c.last_shipment::date
                            ELSE NULL::integer
                        END AS days_since_last,
                    c.total_shipments >= 300 AS high_value,
                        CASE
                            WHEN c.profile_done THEN 20
                            ELSE 0
                        END +
                        CASE
                            WHEN c.verified THEN 20
                            ELSE 0
                        END +
                        CASE
                            WHEN c.integration_type IS NOT NULL THEN 25
                            ELSE 0
                        END +
                        CASE
                            WHEN c.last_topup IS NOT NULL THEN 25
                            ELSE 0
                        END +
                        CASE
                            WHEN c.any_active THEN 10
                            ELSE 0
                        END AS readiness_score,
                    c.vat_reg AND NOT c.zatca_done AS compliance_pending,
                        CASE
                            WHEN c.wallet < '-0.5'::numeric THEN 'negative_balance'::text
                            WHEN c.total_shipments = 0 THEN
                            CASE
                                WHEN c.last_topup IS NOT NULL THEN 'topped_no_ship'::text
                                WHEN c.integration_type IS NOT NULL THEN 'linked_no_ship'::text
                                WHEN c.any_active THEN 'new_active'::text
                                ELSE 'registered_no_ship'::text
                            END
                            WHEN c.any_active THEN 'active'::text
                            WHEN (CURRENT_DATE - c.last_shipment::date) <= 60 THEN 'stopped_recent'::text
                            ELSE 'stopped_long'::text
                        END AS segment
                   FROM customer_rollup c
                ), enriched AS (
                 SELECT c.phone,
                    c.store_count,
                    c.primary_store,
                    c.store_names,
                    c.total_shipments,
                    c.last_shipment,
                    c.wallet,
                    c.last_topup,
                    c.created_at,
                    c.any_active,
                    c.integration_type,
                    c.billing_type,
                    c.profile_done,
                    c.verified,
                    c.vat_reg,
                    c.zatca_done,
                    c.days_since_last,
                    c.high_value,
                    c.readiness_score,
                    c.compliance_pending,
                    c.segment,
                        CASE
                            WHEN c.segment = 'active'::text THEN NULL::text
                            WHEN c.segment = 'negative_balance'::text THEN 'FIN'::text
                            WHEN (c.segment = ANY (ARRAY['stopped_recent'::text, 'stopped_long'::text])) AND (c.high_value OR c.billing_type = 'دفع لاحق'::text) THEN 'A'::text
                            WHEN c.segment = 'stopped_recent'::text AND c.wallet > 0.5 THEN 'A'::text
                            WHEN c.segment = ANY (ARRAY['stopped_recent'::text, 'topped_no_ship'::text]) THEN 'B'::text
                            WHEN c.segment = 'stopped_long'::text AND c.total_shipments >= 50 THEN 'B'::text
                            WHEN c.segment = ANY (ARRAY['linked_no_ship'::text, 'new_active'::text, 'registered_no_ship'::text]) THEN 'C'::text
                            ELSE 'D'::text
                        END AS priority,
                        CASE
                            WHEN c.segment = 'active'::text THEN 'grow'::text
                            WHEN c.segment = 'negative_balance'::text THEN 'finance'::text
                            WHEN c.high_value THEN 'call'::text
                            WHEN c.wallet > 0.5 THEN 'whatsapp_balance'::text
                            WHEN c.segment = ANY (ARRAY['linked_no_ship'::text, 'new_active'::text, 'registered_no_ship'::text]) THEN 'activation'::text
                            ELSE 'whatsapp'::text
                        END AS channel,
                        CASE
                            WHEN c.segment = 'negative_balance'::text THEN 0
                            WHEN c.segment = 'topped_no_ship'::text THEN 100
                            WHEN c.total_shipments = 0 AND c.profile_done AND c.verified AND c.integration_type IS NOT NULL THEN 92
                            WHEN (c.segment = ANY (ARRAY['new_active'::text, 'linked_no_ship'::text, 'registered_no_ship'::text])) AND c.created_at >= (CURRENT_DATE - 7) THEN 88
                            WHEN c.segment = 'stopped_recent'::text AND c.high_value THEN 86
                            WHEN c.segment = 'stopped_recent'::text THEN 78
                            WHEN c.segment = 'stopped_long'::text AND c.high_value THEN 72
                            WHEN c.segment = 'linked_no_ship'::text THEN LEAST(80, 45 + c.readiness_score / 2)
                            WHEN c.segment = 'new_active'::text THEN 60
                            WHEN c.segment = 'registered_no_ship'::text THEN 40
                            WHEN c.segment = 'active'::text AND c.high_value THEN 65
                            ELSE 30
                        END AS opportunity_score,
                        CASE
                            WHEN c.segment = 'negative_balance'::text THEN 'collections'::text
                            WHEN c.total_shipments = 0 AND (NOT c.profile_done OR NOT c.verified) THEN 'onboarding'::text
                            WHEN c.total_shipments = 0 THEN 'sales_activation'::text
                            WHEN c.segment = ANY (ARRAY['stopped_recent'::text, 'stopped_long'::text]) THEN 'sales_recovery'::text
                            WHEN c.segment = 'active'::text AND c.high_value THEN 'account_management'::text
                            ELSE 'sales_growth'::text
                        END AS team_route,
                        CASE
                            WHEN c.segment = 'negative_balance'::text THEN 'تحويل للتحصيل قبل أي محاولة بيع'::text
                            WHEN c.total_shipments = 0 AND NOT c.profile_done THEN 'إكمال بيانات المتجر'::text
                            WHEN c.total_shipments = 0 AND NOT c.verified THEN 'إكمال توثيق المتجر'::text
                            WHEN c.total_shipments = 0 AND c.integration_type IS NULL THEN 'إكمال ربط المتجر'::text
                            WHEN c.total_shipments = 0 THEN 'مساعدته على تنفيذ أول شحنة'::text
                            WHEN c.segment = ANY (ARRAY['stopped_recent'::text, 'stopped_long'::text]) THEN 'فهم سبب التوقف وإعادة التفعيل'::text
                            WHEN c.compliance_pending THEN 'إكمال متطلبات زاتكا'::text
                            ELSE 'تنمية الحساب والمحافظة على نشاطه'::text
                        END AS next_step
                   FROM classified c
                )
         SELECT enriched.phone,
            enriched.store_count,
            enriched.primary_store,
            enriched.store_names,
            enriched.total_shipments,
            enriched.last_shipment,
            enriched.wallet,
            enriched.last_topup,
            enriched.created_at,
            enriched.any_active,
            enriched.integration_type,
            enriched.billing_type,
            enriched.profile_done,
            enriched.verified,
            enriched.vat_reg,
            enriched.days_since_last,
            enriched.high_value,
            enriched.segment,
            enriched.priority,
            enriched.channel,
            enriched.zatca_done,
            enriched.compliance_pending,
            enriched.readiness_score,
            enriched.opportunity_score,
            enriched.team_route,
            enriched.next_step
           FROM enriched) guarded_view
  WHERE app_has_any_permission('{sales.view,crm.view}'::text[]);
create view "public"."v_no_whatsapp" with (security_invoker = true) as  SELECT phone,
    name,
    last_attempt,
    attempts,
    campaigns
   FROM ( SELECT s.phone,
            max(s.name) AS name,
            max(s.sent_at) AS last_attempt,
            count(*) AS attempts,
            string_agg(DISTINCT s.campaign_name, ', '::text) AS campaigns
           FROM whatsapp_campaign_sends s
          WHERE s.error_reason ~~* '%undeliverable%'::text AND NOT (EXISTS ( SELECT 1
                   FROM whatsapp_campaign_sends d
                  WHERE d.phone = s.phone AND (d.delivered_at IS NOT NULL OR d.read_at IS NOT NULL OR d.replied_at IS NOT NULL)))
          GROUP BY s.phone) guarded_view
  WHERE app_has_any_permission('{campaigns.send,whatsapp.view_log}'::text[]);
create view "public"."v_platform_commercial_routing" with (security_invoker = true) as  SELECT phone,
    store_count,
    primary_store,
    store_names,
    total_shipments,
    last_shipment,
    wallet,
    last_topup,
    created_at,
    any_active,
    integration_type,
    billing_type,
    profile_done,
    verified,
    vat_reg,
    days_since_last,
    high_value,
    segment,
    priority,
    channel,
    zatca_done,
    compliance_pending,
    readiness_score,
    opportunity_score,
    team_route,
    next_step,
    direct_live,
    direct_live_inactive,
    manual_only,
    automated_integration,
    joined_5d,
    latest_created_at,
    positive_wallet,
    negative_wallet,
    has_negative_wallet,
    debt,
    financial_hold,
    hot_live_new,
    hot_live_topped,
    recent_stop,
    wallet_stranded,
    live_inactive,
    integration_class,
    financial_hold_reason,
    sales_eligible,
    commercial_signal,
    signal_score,
    signal_reason,
    assigned_team
   FROM ( WITH latest_id AS (
                 SELECT merchants.snapshot_id
                   FROM merchants
                  ORDER BY merchants.uploaded_at DESC
                 LIMIT 1
                ), latest_merchants AS (
                 SELECT merchant.id,
                    merchant.snapshot_id,
                    merchant.snapshot_date,
                    merchant.store_id,
                    merchant.store_name,
                    merchant.phone,
                    merchant.shipment_count,
                    merchant.last_shipment_at,
                    merchant.integration_type,
                    merchant.billing_type,
                    merchant.status,
                    merchant.created_at_platform,
                    merchant.last_topup_at,
                    merchant.wallet_balance,
                    merchant.uploaded_by,
                    merchant.uploaded_at,
                    merchant.profile_status,
                    merchant.vat_registered,
                    merchant.zatca_completed,
                    merchant.verification_status
                   FROM merchants merchant
                  WHERE merchant.snapshot_id = (( SELECT latest_id.snapshot_id
                           FROM latest_id)) AND merchant.phone IS NOT NULL AND btrim(merchant.phone) <> ''::text
                ), store_flags AS (
                 SELECT merchant.phone,
                    bool_or(lower(COALESCE(btrim(merchant.integration_type), ''::text)) ~~ 'live%'::text) AS direct_live,
                    bool_or(lower(COALESCE(btrim(merchant.integration_type), ''::text)) ~~ 'live%'::text AND merchant.status <> 'نشط'::text) AS direct_live_inactive,
                    bool_and(COALESCE(btrim(merchant.integration_type), ''::text) = ''::text) AS manual_only,
                    bool_or(lower(COALESCE(btrim(merchant.integration_type), ''::text)) = ANY (ARRAY['webhook'::text, 'zapier'::text])) AS automated_integration,
                    bool_or(merchant.created_at_platform::date >= (CURRENT_DATE - 5)) AS joined_5d,
                    max(merchant.created_at_platform) AS latest_created_at,
                    round(sum(GREATEST(COALESCE(merchant.wallet_balance, 0::numeric), 0::numeric)), 2) AS positive_wallet,
                    round(abs(sum(LEAST(COALESCE(merchant.wallet_balance, 0::numeric), 0::numeric))), 2) AS negative_wallet,
                    bool_or(COALESCE(merchant.wallet_balance, 0::numeric) < '-0.5'::numeric) AS has_negative_wallet
                   FROM latest_merchants merchant
                  GROUP BY merchant.phone
                ), open_ar AS (
                 SELECT invoice.customer_name,
                    round(sum(invoice.balance), 2) AS debt
                   FROM zoho_invoices invoice
                  WHERE invoice.balance > 0.5
                  GROUP BY invoice.customer_name
                ), phone_customers AS (
                 SELECT DISTINCT merchant.phone,
                    link.customer_name
                   FROM latest_merchants merchant
                     JOIN customer_merchant_links link ON link.store_id = merchant.store_id
                ), phone_debt AS (
                 SELECT phone_customer.phone,
                    round(sum(COALESCE(open_ar.debt, 0::numeric)), 2) AS debt
                   FROM phone_customers phone_customer
                     LEFT JOIN open_ar ON open_ar.customer_name = phone_customer.customer_name
                  GROUP BY phone_customer.phone
                ), base AS (
                 SELECT merchant_rollup.phone,
                    merchant_rollup.store_count,
                    merchant_rollup.primary_store,
                    merchant_rollup.store_names,
                    merchant_rollup.total_shipments,
                    merchant_rollup.last_shipment,
                    merchant_rollup.wallet,
                    merchant_rollup.last_topup,
                    merchant_rollup.created_at,
                    merchant_rollup.any_active,
                    merchant_rollup.integration_type,
                    merchant_rollup.billing_type,
                    merchant_rollup.profile_done,
                    merchant_rollup.verified,
                    merchant_rollup.vat_reg,
                    merchant_rollup.days_since_last,
                    merchant_rollup.high_value,
                    merchant_rollup.segment,
                    merchant_rollup.priority,
                    merchant_rollup.channel,
                    merchant_rollup.zatca_done,
                    merchant_rollup.compliance_pending,
                    merchant_rollup.readiness_score,
                    merchant_rollup.opportunity_score,
                    merchant_rollup.team_route,
                    merchant_rollup.next_step,
                    flags.direct_live,
                    flags.direct_live_inactive,
                    flags.manual_only,
                    flags.automated_integration,
                    flags.joined_5d,
                    flags.latest_created_at,
                    flags.positive_wallet,
                    flags.negative_wallet,
                    flags.has_negative_wallet,
                    COALESCE(phone_debt.debt, 0::numeric) AS debt,
                    flags.has_negative_wallet OR COALESCE(phone_debt.debt, 0::numeric) > 0.5 AS financial_hold,
                    flags.direct_live AND flags.joined_5d AND merchant_rollup.total_shipments = 0 AND merchant_rollup.last_topup IS NULL AS hot_live_new,
                    flags.direct_live AND flags.joined_5d AND merchant_rollup.total_shipments = 0 AND merchant_rollup.last_topup IS NOT NULL AS hot_live_topped,
                    merchant_rollup.total_shipments > 0 AND merchant_rollup.days_since_last > 5 AS recent_stop,
                    flags.positive_wallet > 0.5 AND (merchant_rollup.total_shipments = 0 OR merchant_rollup.days_since_last > 5 OR NOT merchant_rollup.any_active) AS wallet_stranded,
                    flags.direct_live_inactive AS live_inactive,
                        CASE
                            WHEN flags.direct_live THEN 'direct_live'::text
                            WHEN flags.automated_integration THEN 'automation'::text
                            WHEN flags.manual_only THEN 'manual'::text
                            ELSE 'other'::text
                        END AS integration_class,
                        CASE
                            WHEN flags.has_negative_wallet AND COALESCE(phone_debt.debt, 0::numeric) > 0.5 THEN 'مديونية زوهو ومحفظة سالبة'::text
                            WHEN flags.has_negative_wallet THEN 'محفظة سالبة'::text
                            WHEN COALESCE(phone_debt.debt, 0::numeric) > 0.5 THEN 'مديونية زوهو مفتوحة'::text
                            ELSE NULL::text
                        END AS financial_hold_reason
                   FROM v_crm_retargeting merchant_rollup
                     JOIN store_flags flags ON flags.phone = merchant_rollup.phone
                     LEFT JOIN phone_debt ON phone_debt.phone = merchant_rollup.phone
                ), classified AS (
                 SELECT base.phone,
                    base.store_count,
                    base.primary_store,
                    base.store_names,
                    base.total_shipments,
                    base.last_shipment,
                    base.wallet,
                    base.last_topup,
                    base.created_at,
                    base.any_active,
                    base.integration_type,
                    base.billing_type,
                    base.profile_done,
                    base.verified,
                    base.vat_reg,
                    base.days_since_last,
                    base.high_value,
                    base.segment,
                    base.priority,
                    base.channel,
                    base.zatca_done,
                    base.compliance_pending,
                    base.readiness_score,
                    base.opportunity_score,
                    base.team_route,
                    base.next_step,
                    base.direct_live,
                    base.direct_live_inactive,
                    base.manual_only,
                    base.automated_integration,
                    base.joined_5d,
                    base.latest_created_at,
                    base.positive_wallet,
                    base.negative_wallet,
                    base.has_negative_wallet,
                    base.debt,
                    base.financial_hold,
                    base.hot_live_new,
                    base.hot_live_topped,
                    base.recent_stop,
                    base.wallet_stranded,
                    base.live_inactive,
                    base.integration_class,
                    base.financial_hold_reason,
                    NOT base.financial_hold AS sales_eligible,
                        CASE
                            WHEN base.financial_hold THEN 'collections_hold'::text
                            WHEN base.hot_live_topped THEN 'hot_live_topped'::text
                            WHEN base.hot_live_new THEN 'hot_live_new'::text
                            WHEN base.recent_stop THEN 'recent_stop'::text
                            WHEN base.wallet_stranded THEN 'wallet_stranded'::text
                            WHEN base.live_inactive THEN 'live_inactive'::text
                            WHEN base.direct_live AND base.total_shipments = 0 THEN 'live_no_first_shipment'::text
                            WHEN base.manual_only AND base.joined_5d AND base.total_shipments = 0 THEN 'manual_trial'::text
                            WHEN base.segment = ANY (ARRAY['stopped_recent'::text, 'stopped_long'::text]) THEN 'recovery'::text
                            WHEN base.segment = 'active'::text THEN 'account_growth'::text
                            ELSE 'nurture'::text
                        END AS commercial_signal,
                        CASE
                            WHEN base.financial_hold THEN 0
                            WHEN base.hot_live_topped THEN 100
                            WHEN base.hot_live_new THEN 98
                            WHEN base.recent_stop THEN LEAST(99::bigint, 92 + LEAST(base.total_shipments / 250, 7::bigint))::integer
                            WHEN base.wallet_stranded THEN LEAST(96, 88 + LEAST(base.positive_wallet::integer / 500, 8))
                            WHEN base.live_inactive THEN LEAST(93::bigint, 82 + LEAST(base.total_shipments / 500, 11::bigint))::integer
                            WHEN base.direct_live AND base.total_shipments = 0 THEN 78
                            WHEN base.manual_only AND base.joined_5d AND base.total_shipments = 0 THEN 45
                            ELSE GREATEST(25, LEAST(COALESCE(base.opportunity_score, 30), 85))
                        END AS signal_score,
                        CASE
                            WHEN base.financial_hold THEN 'محوّل للتحصيل: '::text || base.financial_hold_reason
                            WHEN base.hot_live_topped THEN 'ربط متجره مباشرة خلال 5 أيام وشحن الرصيد؛ يحتاج تنفيذ أول شحنة'::text
                            WHEN base.hot_live_new THEN 'ربط متجره مباشرة خلال 5 أيام ولم يشحن رصيدًا أو ينفّذ أول شحنة'::text
                            WHEN base.recent_stop THEN ('كان يشحن وآخر شحنة قبل '::text || base.days_since_last::text) || ' أيام'::text
                            WHEN base.wallet_stranded THEN ('لديه '::text || base.positive_wallet::text) || ' ر.س في المحفظة بلا شحن حديث'::text
                            WHEN base.live_inactive AND base.total_shipments > 0 THEN ('ربط مباشر غير نشط بعد '::text || base.total_shipments::text) || ' شحنة'::text
                            WHEN base.live_inactive THEN 'ربط متجره مباشرة ثم أصبح غير نشط قبل أول شحنة'::text
                            WHEN base.direct_live AND base.total_shipments = 0 THEN 'ربط مباشر قائم لكنه لم ينفّذ أول شحنة'::text
                            WHEN base.manual_only AND base.joined_5d AND base.total_shipments = 0 THEN 'تسجيل يدوي حديث؛ نية أقل من العميل الذي ربط متجره'::text
                            WHEN base.segment = ANY (ARRAY['stopped_recent'::text, 'stopped_long'::text]) THEN 'له شحنات سابقة ويحتاج فهم سبب التوقف'::text
                            ELSE base.next_step
                        END AS signal_reason,
                        CASE
                            WHEN base.financial_hold THEN 'collections'::text
                            WHEN base.recent_stop OR base.live_inactive THEN 'sales_recovery'::text
                            WHEN base.wallet_stranded THEN 'customer_success'::text
                            WHEN base.total_shipments = 0 THEN 'sales_activation'::text
                            WHEN base.segment = 'active'::text THEN 'account_management'::text
                            ELSE base.team_route
                        END AS assigned_team
                   FROM base
                )
         SELECT classified.phone,
            classified.store_count,
            classified.primary_store,
            classified.store_names,
            classified.total_shipments,
            classified.last_shipment,
            classified.wallet,
            classified.last_topup,
            classified.created_at,
            classified.any_active,
            classified.integration_type,
            classified.billing_type,
            classified.profile_done,
            classified.verified,
            classified.vat_reg,
            classified.days_since_last,
            classified.high_value,
            classified.segment,
            classified.priority,
            classified.channel,
            classified.zatca_done,
            classified.compliance_pending,
            classified.readiness_score,
            classified.opportunity_score,
            classified.team_route,
            classified.next_step,
            classified.direct_live,
            classified.direct_live_inactive,
            classified.manual_only,
            classified.automated_integration,
            classified.joined_5d,
            classified.latest_created_at,
            classified.positive_wallet,
            classified.negative_wallet,
            classified.has_negative_wallet,
            classified.debt,
            classified.financial_hold,
            classified.hot_live_new,
            classified.hot_live_topped,
            classified.recent_stop,
            classified.wallet_stranded,
            classified.live_inactive,
            classified.integration_class,
            classified.financial_hold_reason,
            classified.sales_eligible,
            classified.commercial_signal,
            classified.signal_score,
            classified.signal_reason,
            classified.assigned_team
           FROM classified) guarded_view
  WHERE app_has_any_permission('{sales.view,sales.external_leads,crm.view}'::text[]);
comment on view "public"."v_platform_commercial_routing" is 'Commercial routing for platform merchants. Recovery becomes important only when the last shipment is older than five days.';
create view "public"."v_weak_whatsapp" with (security_invoker = true) as  SELECT phone
   FROM ( SELECT whatsapp_campaign_sends.phone
           FROM whatsapp_campaign_sends
          WHERE whatsapp_campaign_sends.phone IS NOT NULL
          GROUP BY whatsapp_campaign_sends.phone
         HAVING max(whatsapp_campaign_sends.sent_at) < (now() - '1 day'::interval) AND count(*) FILTER (WHERE whatsapp_campaign_sends.delivered_at IS NOT NULL OR whatsapp_campaign_sends.read_at IS NOT NULL OR whatsapp_campaign_sends.replied_at IS NOT NULL) = 0) guarded_view
  WHERE app_has_any_permission('{campaigns.send,whatsapp.view_log}'::text[]);
create view "public"."zoho_ap_aging_current" with (security_invoker = true) as  SELECT COALESCE(vendor_id, 'name:'::text || lower(btrim(COALESCE(vendor_name, ''::text)))) AS vendor_key,
    max(vendor_id) AS vendor_id,
    max(vendor_name) AS vendor_name,
    count(*)::integer AS bill_count,
    round(sum(balance), 2) AS balance,
    round(sum(balance) FILTER (WHERE due_date IS NULL OR due_date >= CURRENT_DATE), 2) AS current_amount,
    round(sum(balance) FILTER (WHERE (CURRENT_DATE - due_date) >= 1 AND (CURRENT_DATE - due_date) <= 30), 2) AS days_1_30,
    round(sum(balance) FILTER (WHERE (CURRENT_DATE - due_date) >= 31 AND (CURRENT_DATE - due_date) <= 60), 2) AS days_31_60,
    round(sum(balance) FILTER (WHERE (CURRENT_DATE - due_date) >= 61 AND (CURRENT_DATE - due_date) <= 90), 2) AS days_61_90,
    round(sum(balance) FILTER (WHERE (CURRENT_DATE - due_date) > 90), 2) AS days_over_90,
    min(due_date) FILTER (WHERE balance > 0.005) AS oldest_due_date
   FROM zoho_bills
  WHERE balance > 0.005
  GROUP BY (COALESCE(vendor_id, 'name:'::text || lower(btrim(COALESCE(vendor_name, ''::text)))));
create view "public"."zoho_ar_aging_current" with (security_invoker = true) as  SELECT COALESCE(customer_id, 'name:'::text || lower(btrim(COALESCE(customer_name, ''::text)))) AS customer_key,
    max(customer_id) AS customer_id,
    max(customer_name) AS customer_name,
    count(*)::integer AS invoice_count,
    round(sum(balance), 2) AS balance,
    round(sum(balance) FILTER (WHERE due_date IS NULL OR due_date >= CURRENT_DATE), 2) AS current_amount,
    round(sum(balance) FILTER (WHERE (CURRENT_DATE - due_date) >= 1 AND (CURRENT_DATE - due_date) <= 30), 2) AS days_1_30,
    round(sum(balance) FILTER (WHERE (CURRENT_DATE - due_date) >= 31 AND (CURRENT_DATE - due_date) <= 60), 2) AS days_31_60,
    round(sum(balance) FILTER (WHERE (CURRENT_DATE - due_date) >= 61 AND (CURRENT_DATE - due_date) <= 90), 2) AS days_61_90,
    round(sum(balance) FILTER (WHERE (CURRENT_DATE - due_date) > 90), 2) AS days_over_90,
    min(due_date) FILTER (WHERE balance > 0.005) AS oldest_due_date
   FROM zoho_invoices
  WHERE balance > 0.005
  GROUP BY (COALESCE(customer_id, 'name:'::text || lower(btrim(COALESCE(customer_name, ''::text)))));
